import React, { useState, useMemo, useRef } from 'react';
import {
  Users,
  Search,
  Phone,
  MapPin,
  ChevronDown,
  ChevronUp,
  UserCheck,
  UserX,
  RefreshCw,
  UploadCloud,
  FileSpreadsheet,
  Download,
  CheckCircle2,
  AlertCircle,
  X,
  FileCheck,
  UserPlus,
  Plus
} from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle } from './ui/card';
import { Badge } from './ui/badge';
import { Input } from './ui/input';
import { Button } from './ui/button';
import { cn } from '@/lib/utils';
import { Colaborador, Veiculo, StatusPresenca, Regional } from '../types';

export interface ColaboradorCompleto {
  id: string;
  nome: string;
  cargo: string;
  matricula: string;
  foto: string;
  telefone: string;
  status: StatusPresenca;
  motivoFalta?: string;
  substitutoNome?: string;
  equipeId: string;
  equipeNumero: 1 | 2;
  posicaoVeiculo: 'motorista' | 'frente_dir' | 'tras_esq' | 'tras_dir';
  veiculoPrefixo: string;
  veiculoPlaca: string;
  regional: 'ribas' | 'agua_clara';
}

interface CollaboratorsManagementProps {
  veiculos?: Veiculo[];
  colaboradoresReserva?: Colaborador[];
  onImportarColaboradores?: (novosColaboradores: ColaboradorCompleto[]) => void;
  onAdicionarColaborador?: (novoColaborador: ColaboradorCompleto) => void;
}

const posicaoLabel: Record<string, string> = {
  motorista: 'Motorista / Líder',
  frente_dir: 'Dianteiro Direito',
  tras_esq: 'Traseiro Esquerdo',
  tras_dir: 'Traseiro Direito',
};

const statusConfig: Record<StatusPresenca, { label: string; className: string }> = {
  presente: { label: 'Presente', className: 'bg-emerald-500/20 text-emerald-400 border-emerald-500/30' },
  falta: { label: 'Falta', className: 'bg-rose-500/20 text-rose-400 border-rose-500/30' },
  substituto: { label: 'Substituto', className: 'bg-amber-500/20 text-amber-400 border-amber-500/30' },
};

const regionalLabel: Record<string, string> = {
  ribas: 'Ribas do Rio Pardo',
  agua_clara: 'Água Clara',
};

interface RegistroImportado {
  nome: string;
  cargo: string;
  unidade: 'ribas' | 'agua_clara';
  matricula?: string;
  telefone?: string;
}

export const CollaboratorsManagement: React.FC<CollaboratorsManagementProps> = ({
  veiculos = [],
  colaboradoresReserva = [],
  onImportarColaboradores,
  onAdicionarColaborador,
}) => {
  const [search, setSearch] = useState('');
  const [filterStatus, setFilterStatus] = useState<StatusPresenca | 'todos'>('todos');
  const [filterRegional, setFilterRegional] = useState<Regional | 'todas'>('todas');
  const [expandedId, setExpandedId] = useState<string | null>(null);

  // Estados do Modal de Cadastro Manual de Colaborador
  const [modalNovoColaboradorAberto, setModalNovoColaboradorAberto] = useState(false);
  const [novoNome, setNovoNome] = useState('');
  const [novoCargo, setNovoCargo] = useState('');
  const [novaMatricula, setNovaMatricula] = useState('');
  const [novoTelefone, setNovoTelefone] = useState('');
  const [novaUnidade, setNovaUnidade] = useState<'ribas' | 'agua_clara'>('ribas');
  const [novoStatus, setNovoStatus] = useState<StatusPresenca>('presente');
  const [formErro, setFormErro] = useState<string | null>(null);

  // Estados do Modal de Importação Excel / CSV
  const [modalImportAberto, setModalImportAberto] = useState(false);
  const [arquivoNome, setArquivoNome] = useState('');
  const [registrosPrevia, setRegistrosPrevia] = useState<RegistroImportado[]>([]);
  const [erroImportacao, setErroImportacao] = useState<string | null>(null);
  const [sucessoMsg, setSucessoMsg] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Lista de colaboradores extraídos dos veículos e lista reserva
  const colaboradoresBase: ColaboradorCompleto[] = useMemo(() => {
    const lista: ColaboradorCompleto[] = [];
    (veiculos || []).forEach((v) => {
      if (!v || !v.assentos) return;
      const assentos: Array<{ colab?: Colaborador; pos: ColaboradorCompleto['posicaoVeiculo'] }> = [
        { colab: v.assentos.motorista, pos: 'motorista' },
        { colab: v.assentos.frenteDir, pos: 'frente_dir' },
        { colab: v.assentos.trasEsq, pos: 'tras_esq' },
        { colab: v.assentos.trasDir, pos: 'tras_dir' },
      ];
      assentos.forEach(({ colab, pos }) => {
        if (!colab) return;
        lista.push({
          id: colab.id,
          nome: colab.nome || 'Sem Nome',
          cargo: colab.cargo || 'Operador',
          matricula: colab.matricula ?? '',
          foto: colab.foto ?? '',
          telefone: colab.telefone ?? '',
          status: colab.status || 'presente',
          motivoFalta: colab.motivoFalta,
          substitutoNome: colab.substitutoNome,
          equipeId: colab.equipeId || '',
          equipeNumero: colab.equipeNumero || 1,
          posicaoVeiculo: pos,
          veiculoPrefixo: v.prefixo || '',
          veiculoPlaca: v.placa || '',
          regional: v.regional || 'ribas',
        });
      });
    });

    // Adiciona colaboradores reserva se houver
    (colaboradoresReserva || []).forEach((r, idx) => {
      if (!r) return;
      lista.push({
        id: r.id || `res-${idx}`,
        nome: r.nome || 'Colaborador Reserva',
        cargo: r.cargo || 'Reserva Operacional',
        matricula: r.matricula || '',
        foto: r.foto || '',
        telefone: r.telefone || '',
        status: r.status || 'presente',
        motivoFalta: r.motivoFalta,
        substitutoNome: r.substitutoNome,
        equipeId: 'reserva',
        equipeNumero: 1,
        posicaoVeiculo: 'motorista',
        veiculoPrefixo: 'Banco de Reserva',
        veiculoPlaca: '-',
        regional: 'ribas',
      });
    });

    return lista;
  }, [veiculos, colaboradoresReserva]);

  const [colaboradoresAdicionados, setColaboradoresAdicionados] = useState<ColaboradorCompleto[]>([]);

  const todosColaboradores = useMemo(() => {
    return [...colaboradoresBase, ...colaboradoresAdicionados];
  }, [colaboradoresBase, colaboradoresAdicionados]);

  const colaboradoresFiltrados = useMemo(() => {
    return todosColaboradores.filter((c) => {
      if (!c) return false;
      const matchSearch =
        !search ||
        (c.nome || '').toLowerCase().includes(search.toLowerCase()) ||
        (c.cargo || '').toLowerCase().includes(search.toLowerCase()) ||
        (c.matricula || '').toLowerCase().includes(search.toLowerCase()) ||
        (c.veiculoPlaca || '').toLowerCase().includes(search.toLowerCase()) ||
        (c.veiculoPrefixo || '').toLowerCase().includes(search.toLowerCase());

      const matchStatus = filterStatus === 'todos' || c.status === filterStatus;
      const matchRegional = filterRegional === 'todas' || c.regional === filterRegional;

      return matchSearch && matchStatus && matchRegional;
    });
  }, [todosColaboradores, search, filterStatus, filterRegional]);

  const stats = useMemo(() => {
    const presentes = todosColaboradores.filter((c) => c.status === 'presente').length;
    const faltas = todosColaboradores.filter((c) => c.status === 'falta').length;
    const substitutos = todosColaboradores.filter((c) => c.status === 'substituto').length;
    return { presentes, faltas, substitutos, total: todosColaboradores.length };
  }, [todosColaboradores]);

  // Handler para Adicionar Colaborador Manualmente
  const handleCadastrarNovoColaborador = (e: React.FormEvent) => {
    e.preventDefault();
    if (!novoNome.trim()) {
      setFormErro('Por favor, informe o nome do colaborador.');
      return;
    }
    if (!novoCargo.trim()) {
      setFormErro('Por favor, informe a função/cargo do colaborador.');
      return;
    }

    const novoColab: ColaboradorCompleto = {
      id: `col-novo-${Date.now()}`,
      nome: novoNome.trim(),
      cargo: novoCargo.trim(),
      matricula: novaMatricula.trim() || `MAT-${Math.floor(1000 + Math.random() * 9000)}`,
      foto: '',
      telefone: novoTelefone.trim() || '(67) 99999-0000',
      status: novoStatus,
      equipeId: 'reserva',
      equipeNumero: 1,
      posicaoVeiculo: 'motorista',
      veiculoPrefixo: 'Banco de Reserva',
      veiculoPlaca: '-',
      regional: novaUnidade,
    };

    setColaboradoresAdicionados((prev) => [novoColab, ...prev]);

    if (onAdicionarColaborador) {
      onAdicionarColaborador(novoColab);
    }

    setSucessoMsg(`Colaborador "${novoColab.nome}" cadastrado com sucesso!`);
    setTimeout(() => setSucessoMsg(null), 4000);

    // Limpar formulário e fechar
    setNovoNome('');
    setNovoCargo('');
    setNovaMatricula('');
    setNovoTelefone('');
    setNovaUnidade('ribas');
    setNovoStatus('presente');
    setFormErro(null);
    setModalNovoColaboradorAberto(false);
  };

  // Função para processar arquivo Excel / CSV importado
  const processarArquivo = (file: File) => {
    setErroImportacao(null);
    setArquivoNome(file.name);

    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const text = e.target?.result as string;
        if (!text) {
          setErroImportacao('O arquivo selecionado está vazio.');
          return;
        }

        const linhas = text.split(/\r?\n/).map((l) => l.trim()).filter(Boolean);
        if (linhas.length < 2) {
          setErroImportacao('O arquivo precisa conter cabeçalho e pelo menos 1 linha de dados.');
          return;
        }

        const headerLinha = linhas[0];
        const separador = headerLinha.includes(';') ? ';' : ',';
        const headers = headerLinha.split(separador).map((h) => h.trim().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, ''));

        const idxNome = headers.findIndex((h) => h.includes('nome') || h.includes('colaborador'));
        const idxCargo = headers.findIndex((h) => h.includes('cargo') || h.includes('funcao') || h.includes('ocupacao'));
        const idxUnidade = headers.findIndex((h) => h.includes('unidade') || h.includes('regional') || h.includes('polo') || h.includes('cidade'));
        const idxMatricula = headers.findIndex((h) => h.includes('matricula') || h.includes('registro') || h.includes('chapa'));
        const idxTelefone = headers.findIndex((h) => h.includes('telefone') || h.includes('celular') || h.includes('fone') || h.includes('contato'));

        if (idxNome === -1 || idxCargo === -1) {
          setErroImportacao('O arquivo deve conter obrigatoriamente as colunas "Nome" e "Função/Cargo".');
          return;
        }

        const listaExtraida: RegistroImportado[] = [];
        for (let i = 1; i < linhas.length; i++) {
          const colunas = linhas[i].split(separador).map((c) => c.trim().replace(/^["']|["']$/g, ''));
          const nome = colunas[idxNome] || '';
          const cargo = colunas[idxCargo] || '';
          const unidadeRaw = idxUnidade !== -1 ? (colunas[idxUnidade] || '').toLowerCase() : 'ribas';
          const matricula = idxMatricula !== -1 ? colunas[idxMatricula] : undefined;
          const telefone = idxTelefone !== -1 ? colunas[idxTelefone] : undefined;

          if (nome && cargo) {
            const unidade: 'ribas' | 'agua_clara' =
              unidadeRaw.includes('agua') || unidadeRaw.includes('clara') || unidadeRaw.includes('ac')
                ? 'agua_clara'
                : 'ribas';

            listaExtraida.push({
              nome,
              cargo,
              unidade,
              matricula,
              telefone,
            });
          }
        }

        if (listaExtraida.length === 0) {
          setErroImportacao('Nenhum registro válido foi encontrado no arquivo.');
          return;
        }

        setRegistrosPrevia(listaExtraida);
      } catch {
        setErroImportacao('Falha ao ler o arquivo. Verifique o formato CSV / Excel.');
      }
    };

    reader.onerror = () => {
      setErroImportacao('Erro ao abrir o arquivo.');
    };

    reader.readAsText(file);
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      processarArquivo(file);
    }
  };

  const handleConfirmarImportacao = () => {
    if (registrosPrevia.length === 0) return;

    const novos: ColaboradorCompleto[] = registrosPrevia.map((reg, idx) => ({
      id: `imp-${Date.now()}-${idx}`,
      nome: reg.nome,
      cargo: reg.cargo,
      matricula: reg.matricula || `MAT-IMP-${1000 + idx}`,
      foto: '',
      telefone: reg.telefone || '(67) 99999-0000',
      status: 'presente',
      equipeId: 'reserva',
      equipeNumero: 1,
      posicaoVeiculo: 'motorista',
      veiculoPrefixo: 'Banco de Reserva',
      veiculoPlaca: '-',
      regional: reg.unidade,
    }));

    setColaboradoresAdicionados((prev) => [...prev, ...novos]);

    if (onImportarColaboradores) {
      onImportarColaboradores(novos);
    }

    setSucessoMsg(`${novos.length} colaboradores importados com sucesso!`);
    setTimeout(() => setSucessoMsg(null), 5000);

    setModalImportAberto(false);
    setRegistrosPrevia([]);
    setArquivoNome('');
    if (fileInputRef.current) {
      fileInputRef.current.value = '';
    }
  };

  const baixarModeloCSV = () => {
    const conteudo = 'Nome;Funcao;Unidade;Matricula;Telefone\nJoão Pedro Silva;Motorista;Ribas do Rio Pardo;MAT-2031;(67) 99981-1001\nCarlos Alberto;Operador Florestal;Água Clara;MAT-2032;(67) 99981-1002\nMarcos Souza;Ajudante Geral;Ribas do Rio Pardo;MAT-2033;(67) 99981-1003';
    const blob = new Blob(['\uFEFF' + conteudo], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.setAttribute('href', url);
    link.setAttribute('download', 'modelo_importacao_colaboradores.csv');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="space-y-6">
      {/* Alerta de Sucesso */}
      {sucessoMsg && (
        <div className="flex items-center gap-3 p-4 rounded-2xl bg-emerald-500/15 border border-emerald-500/30 text-emerald-300 animate-in fade-in slide-in-from-top-2 duration-200 shadow-lg">
          <CheckCircle2 className="w-5 h-5 shrink-0 text-emerald-400" />
          <p className="text-sm font-semibold">{sucessoMsg}</p>
        </div>
      )}

      {/* Cabeçalho da Aba */}
      <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-foreground flex items-center gap-2">
            <Users className="w-6 h-6 text-primary" />
            Quadro Geral de Colaboradores
          </h2>
          <p className="text-sm text-muted-foreground mt-0.5">
            Gestão operacional, listagem de presença, cadastro e importação em lote
          </p>
        </div>

        {/* Botões de Ação: Adicionar Colaborador & Importar Excel */}
        <div className="flex items-center gap-2.5 flex-wrap">
          <Button
            onClick={() => {
              setFormErro(null);
              setModalNovoColaboradorAberto(true);
            }}
            className="gap-2 bg-primary hover:bg-primary/90 text-primary-foreground font-semibold shadow-md shadow-primary/20"
          >
            <UserPlus className="w-4 h-4" />
            ADICIONAR COLABORADOR
          </Button>

          <Button
            onClick={() => setModalImportAberto(true)}
            variant="outline"
            className="gap-2 border-emerald-500/40 text-emerald-400 hover:bg-emerald-500/10 hover:text-emerald-300 font-medium"
          >
            <FileSpreadsheet className="w-4 h-4 text-emerald-400" />
            Importar Excel / CSV
          </Button>
        </div>
      </div>

      {/* Cards de Métricas de Presença dos Colaboradores */}
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-3">
        <div className="p-4 rounded-2xl bg-card/60 border border-border flex items-center gap-3.5">
          <div className="w-10 h-10 rounded-xl bg-primary/10 border border-primary/20 flex items-center justify-center text-primary shrink-0">
            <Users className="w-5 h-5" />
          </div>
          <div>
            <p className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">Total</p>
            <p className="text-xl font-bold text-foreground">{stats.total}</p>
          </div>
        </div>

        <div className="p-4 rounded-2xl bg-card/60 border border-border flex items-center gap-3.5">
          <div className="w-10 h-10 rounded-xl bg-emerald-500/10 border border-emerald-500/20 flex items-center justify-center text-emerald-400 shrink-0">
            <UserCheck className="w-5 h-5" />
          </div>
          <div>
            <p className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">Presentes</p>
            <p className="text-xl font-bold text-emerald-400">{stats.presentes}</p>
          </div>
        </div>

        <div className="p-4 rounded-2xl bg-card/60 border border-border flex items-center gap-3.5">
          <div className="w-10 h-10 rounded-xl bg-rose-500/10 border border-rose-500/20 flex items-center justify-center text-rose-400 shrink-0">
            <UserX className="w-5 h-5" />
          </div>
          <div>
            <p className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">Faltas</p>
            <p className="text-xl font-bold text-rose-400">{stats.faltas}</p>
          </div>
        </div>

        <div className="p-4 rounded-2xl bg-card/60 border border-border flex items-center gap-3.5">
          <div className="w-10 h-10 rounded-xl bg-amber-500/10 border border-amber-500/20 flex items-center justify-center text-amber-400 shrink-0">
            <RefreshCw className="w-5 h-5" />
          </div>
          <div>
            <p className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">Substitutos</p>
            <p className="text-xl font-bold text-amber-400">{stats.substitutos}</p>
          </div>
        </div>
      </div>

      {/* Barra de Filtros */}
      <Card className="bg-card/40 border-border/70 backdrop-blur-sm">
        <CardContent className="p-4 space-y-3">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
            <div className="relative">
              <Search className="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground" />
              <Input
                placeholder="Buscar por nome, cargo, matrícula ou carro..."
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                className="pl-9 bg-background/50 border-border/60 text-sm"
              />
            </div>

            <div className="flex items-center gap-1.5 overflow-x-auto pb-1 md:pb-0">
              <span className="text-xs font-medium text-muted-foreground shrink-0 mr-1">Status:</span>
              {(['todos', 'presente', 'falta', 'substituto'] as const).map((st) => (
                <button
                  key={st}
                  onClick={() => setFilterStatus(st)}
                  className={cn(
                    'px-2.5 py-1 rounded-lg text-xs font-semibold transition-all shrink-0 capitalize',
                    filterStatus === st
                      ? 'bg-primary text-primary-foreground shadow-sm'
                      : 'bg-muted/40 text-muted-foreground hover:bg-muted hover:text-foreground'
                  )}
                >
                  {st}
                </button>
              ))}
            </div>

            <div className="flex items-center gap-1.5 overflow-x-auto pb-1 md:pb-0">
              <span className="text-xs font-medium text-muted-foreground shrink-0 mr-1">Unidade:</span>
              {(['todas', 'ribas', 'agua_clara'] as const).map((reg) => (
                <button
                  key={reg}
                  onClick={() => setFilterRegional(reg)}
                  className={cn(
                    'px-2.5 py-1 rounded-lg text-xs font-semibold transition-all shrink-0',
                    filterRegional === reg
                      ? 'bg-primary text-primary-foreground shadow-sm'
                      : 'bg-muted/40 text-muted-foreground hover:bg-muted hover:text-foreground'
                  )}
                >
                  {reg === 'todas' ? 'Todas' : reg === 'ribas' ? 'Ribas' : 'Água Clara'}
                </button>
              ))}
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Lista / Grid de Colaboradores */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {colaboradoresFiltrados.map((c) => {
          const isExpanded = expandedId === c.id;
          const statusInfo = statusConfig[c.status] || statusConfig.presente;

          return (
            <Card
              key={c.id}
              className={cn(
                'group hover:border-primary/50 transition-all bg-card/60 backdrop-blur-md overflow-hidden',
                c.status === 'falta' ? 'border-rose-500/30' : c.status === 'substituto' ? 'border-amber-500/30' : 'border-border/60'
              )}
            >
              <CardContent className="p-4 space-y-3">
                <div className="flex items-start gap-3">
                  <div className="relative shrink-0">
                    <div className="w-12 h-12 rounded-full overflow-hidden border-2 border-border/80 bg-muted flex items-center justify-center">
                      {c.foto ? (
                        <img src={c.foto} alt={c.nome} className="w-full h-full object-cover" />
                      ) : (
                        <div className="w-full h-full flex items-center justify-center font-bold text-muted-foreground text-sm">
                          {c.nome?.charAt(0) || 'C'}
                        </div>
                      )}
                    </div>
                    <div
                      className={cn(
                        'w-3.5 h-3.5 rounded-full absolute -bottom-0.5 -right-0.5 border-2 border-card',
                        c.status === 'presente' && 'bg-emerald-500',
                        c.status === 'falta' && 'bg-rose-500',
                        c.status === 'substituto' && 'bg-amber-500'
                      )}
                    />
                  </div>

                  <div className="flex-1 min-w-0">
                    <div className="flex items-center justify-between gap-1">
                      <h4 className="font-bold text-sm text-foreground truncate">{c.nome}</h4>
                      <Badge variant="outline" className={cn('text-[10px] uppercase font-bold shrink-0', statusInfo.className)}>
                        {statusInfo.label}
                      </Badge>
                    </div>
                    <p className="text-xs text-muted-foreground font-medium truncate">{c.cargo}</p>
                    <p className="text-[11px] text-muted-foreground/80 mt-0.5">Matrícula: {c.matricula || 'N/D'}</p>
                  </div>
                </div>

                <div className="pt-2 border-t border-border/40 grid grid-cols-2 gap-2 text-xs">
                  <div>
                    <span className="text-muted-foreground block text-[10px] font-medium">Veículo / Lotação:</span>
                    <span className="font-semibold text-foreground truncate block">{c.veiculoPrefixo}</span>
                  </div>
                  <div>
                    <span className="text-muted-foreground block text-[10px] font-medium">Unidade:</span>
                    <span className="font-semibold text-foreground flex items-center gap-1">
                      <MapPin className="w-3 h-3 text-primary shrink-0" />
                      {regionalLabel[c.regional] || 'Ribas do Rio Pardo'}
                    </span>
                  </div>
                </div>

                {/* Detalhes expansíveis */}
                {isExpanded && (
                  <div className="pt-2.5 border-t border-border/40 space-y-2 text-xs animate-in fade-in duration-150">
                    <div className="flex items-center gap-2 text-muted-foreground">
                      <Phone className="w-3.5 h-3.5 text-primary shrink-0" />
                      <span>{c.telefone || 'Não informado'}</span>
                    </div>

                    <div className="flex items-center justify-between text-muted-foreground">
                      <span>Posição Veículo:</span>
                      <span className="font-medium text-foreground">{posicaoLabel[c.posicaoVeiculo] || 'Assento'}</span>
                    </div>

                    {c.motivoFalta && (
                      <div className="p-2 rounded-lg bg-rose-500/10 border border-rose-500/20 text-rose-300">
                        <span className="font-bold block text-[10px] uppercase tracking-wider">Motivo da Falta:</span>
                        <p className="text-xs font-medium mt-0.5">{c.motivoFalta}</p>
                      </div>
                    )}

                    {c.substitutoNome && (
                      <div className="p-2 rounded-lg bg-amber-500/10 border border-amber-500/20 text-amber-300">
                        <span className="font-bold block text-[10px] uppercase tracking-wider">Substituto Designado:</span>
                        <p className="text-xs font-medium mt-0.5">{c.substitutoNome}</p>
                      </div>
                    )}
                  </div>
                )}

                <button
                  type="button"
                  onClick={() => setExpandedId(isExpanded ? null : c.id)}
                  className="w-full pt-1.5 flex items-center justify-center gap-1 text-[11px] font-semibold text-primary hover:text-primary/80 transition-colors"
                >
                  {isExpanded ? (
                    <>
                      Menos detalhes <ChevronUp className="w-3.5 h-3.5" />
                    </>
                  ) : (
                    <>
                      Mais detalhes <ChevronDown className="w-3.5 h-3.5" />
                    </>
                  )}
                </button>
              </CardContent>
            </Card>
          );
        })}
      </div>

      {colaboradoresFiltrados.length === 0 && (
        <div className="text-center py-12 px-4 rounded-2xl bg-card/30 border border-dashed border-border/80">
          <Users className="w-10 h-10 text-muted-foreground/60 mx-auto mb-3" />
          <h4 className="text-base font-semibold text-foreground">Nenhum colaborador encontrado</h4>
          <p className="text-xs text-muted-foreground mt-1 max-w-sm mx-auto">
            Não foram encontrados colaboradores correspondentes aos critérios de busca ou filtros selecionados.
          </p>
        </div>
      )}

      {/* ========================================================================= */}
      {/* MODAL 1: ADICIONAR COLABORADOR MANUALMENTE                               */}
      {/* ========================================================================= */}
      {modalNovoColaboradorAberto && (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/75 backdrop-blur-sm animate-in fade-in duration-150"
          onClick={() => setModalNovoColaboradorAberto(false)}
        >
          <div
            className="bg-card border border-border rounded-2xl shadow-2xl w-full max-w-lg overflow-hidden animate-in fade-in zoom-in-95 duration-150"
            onClick={(e) => e.stopPropagation()}
          >
            <div className="flex items-center justify-between px-6 py-4 border-b border-border bg-muted/20">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 rounded-xl bg-primary/10 border border-primary/20 flex items-center justify-center text-primary">
                  <UserPlus className="w-5 h-5" />
                </div>
                <div>
                  <h3 className="font-bold text-base text-foreground">Novo Colaborador</h3>
                  <p className="text-xs text-muted-foreground">Preencha os dados para cadastrar o colaborador</p>
                </div>
              </div>
              <button
                type="button"
                onClick={() => setModalNovoColaboradorAberto(false)}
                className="p-1.5 rounded-lg text-muted-foreground hover:text-foreground hover:bg-muted/60 transition-colors"
              >
                <X className="w-5 h-5" />
              </button>
            </div>

            <form onSubmit={handleCadastrarNovoColaborador} className="p-6 space-y-4">
              {formErro && (
                <div className="p-3 rounded-xl bg-rose-500/10 border border-rose-500/30 text-rose-400 text-xs flex items-center gap-2">
                  <AlertCircle className="w-4 h-4 shrink-0" />
                  <span>{formErro}</span>
                </div>
              )}

              <div className="space-y-1.5">
                <label className="text-xs font-semibold text-foreground flex items-center gap-1">
                  Nome Completo <span className="text-rose-400">*</span>
                </label>
                <Input
                  placeholder="Ex: Carlos Eduardo de Souza"
                  value={novoNome}
                  onChange={(e) => setNovoNome(e.target.value)}
                  className="bg-background/50 border-border/70"
                  required
                />
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                <div className="space-y-1.5">
                  <label className="text-xs font-semibold text-foreground flex items-center gap-1">
                    Função / Cargo <span className="text-rose-400">*</span>
                  </label>
                  <Input
                    placeholder="Ex: Operador Florestal"
                    value={novoCargo}
                    onChange={(e) => setNovoCargo(e.target.value)}
                    className="bg-background/50 border-border/70"
                    required
                  />
                </div>

                <div className="space-y-1.5">
                  <label className="text-xs font-semibold text-foreground">Matrícula</label>
                  <Input
                    placeholder="Ex: MAT-1088"
                    value={novaMatricula}
                    onChange={(e) => setNovaMatricula(e.target.value)}
                    className="bg-background/50 border-border/70"
                  />
                </div>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                <div className="space-y-1.5">
                  <label className="text-xs font-semibold text-foreground">Telefone / Contato</label>
                  <Input
                    placeholder="(67) 99999-0000"
                    value={novoTelefone}
                    onChange={(e) => setNovoTelefone(e.target.value)}
                    className="bg-background/50 border-border/70"
                  />
                </div>

                <div className="space-y-1.5">
                  <label className="text-xs font-semibold text-foreground">Unidade / Polo</label>
                  <select
                    value={novaUnidade}
                    onChange={(e) => setNovaUnidade(e.target.value as 'ribas' | 'agua_clara')}
                    className="w-full h-10 px-3 text-sm bg-card/50 border border-input rounded-xl focus:outline-none focus:ring-2 focus:ring-primary text-foreground"
                  >
                    <option value="ribas">Ribas do Rio Pardo</option>
                    <option value="agua_clara">Água Clara</option>
                  </select>
                </div>
              </div>

              <div className="space-y-1.5">
                <label className="text-xs font-semibold text-foreground">Status Inicial</label>
                <div className="grid grid-cols-3 gap-2">
                  {(['presente', 'falta', 'substituto'] as const).map((st) => (
                    <button
                      key={st}
                      type="button"
                      onClick={() => setNovoStatus(st)}
                      className={cn(
                        'py-2 px-3 rounded-xl border text-xs font-semibold capitalize transition-all',
                        novoStatus === st
                          ? 'border-primary bg-primary/10 text-primary ring-1 ring-primary/40'
                          : 'border-border/60 text-muted-foreground hover:bg-muted/40'
                      )}
                    >
                      {st}
                    </button>
                  ))}
                </div>
              </div>

              <div className="pt-3 flex items-center justify-end gap-2 border-t border-border">
                <Button
                  type="button"
                  variant="outline"
                  onClick={() => setModalNovoColaboradorAberto(false)}
                >
                  Cancelar
                </Button>
                <Button type="submit" className="gap-2 bg-primary hover:bg-primary/90 text-primary-foreground font-semibold">
                  <Plus className="w-4 h-4" />
                  Salvar Colaborador
                </Button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* ========================================================================= */}
      {/* MODAL 2: IMPORTAR ARQUIVO EXCEL / CSV                                    */}
      {/* ========================================================================= */}
      {modalImportAberto && (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/75 backdrop-blur-sm animate-in fade-in duration-150"
          onClick={() => setModalImportAberto(false)}
        >
          <div
            className="bg-card border border-border rounded-2xl shadow-2xl w-full max-w-2xl max-h-[90vh] flex flex-col overflow-hidden animate-in fade-in zoom-in-95 duration-150"
            onClick={(e) => e.stopPropagation()}
          >
            {/* Modal Header */}
            <div className="flex items-center justify-between px-6 py-4 border-b border-border bg-muted/20">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 rounded-xl bg-emerald-500/10 border border-emerald-500/20 flex items-center justify-center text-emerald-400">
                  <FileSpreadsheet className="w-5 h-5" />
                </div>
                <div>
                  <h3 className="font-bold text-base text-foreground">Importar Colaboradores via Excel / CSV</h3>
                  <p className="text-xs text-muted-foreground">Envie uma planilha com Nome, Função e Unidade</p>
                </div>
              </div>
              <button
                type="button"
                onClick={() => setModalImportAberto(false)}
                className="p-1.5 rounded-lg text-muted-foreground hover:text-foreground hover:bg-muted/60 transition-colors"
              >
                <X className="w-5 h-5" />
              </button>
            </div>

            {/* Modal Body */}
            <div className="p-6 space-y-4 overflow-y-auto flex-1">
              {/* Área de Drop / Seleção de Arquivo */}
              <div
                onClick={() => fileInputRef.current?.click()}
                className="border-2 border-dashed border-border/80 hover:border-emerald-500/60 bg-muted/20 hover:bg-emerald-500/5 rounded-2xl p-6 text-center cursor-pointer transition-all group"
              >
                <input
                  ref={fileInputRef}
                  type="file"
                  accept=".csv, .xlsx, .xls, text/csv, application/vnd.openxmlformats-officedocument.spreadsheetml.sheet, application/vnd.ms-excel"
                  className="hidden"
                  onChange={handleFileChange}
                />
                <div className="w-12 h-12 rounded-full bg-emerald-500/10 group-hover:bg-emerald-500/20 text-emerald-400 flex items-center justify-center mx-auto mb-3 transition-colors">
                  <UploadCloud className="w-6 h-6" />
                </div>
                <h4 className="font-bold text-sm text-foreground group-hover:text-emerald-300 transition-colors">
                  {arquivoNome ? arquivoNome : 'Clique aqui para carregar o arquivo CSV ou Excel'}
                </h4>
                <p className="text-xs text-muted-foreground mt-1">
                  Formatos suportados: CSV com separador ponto-e-vírgula ou vírgula
                </p>
              </div>

              {/* Botão Baixar Modelo */}
              <div className="flex items-center justify-between p-3 rounded-xl bg-muted/40 border border-border/60">
                <div className="flex items-center gap-2 text-xs text-muted-foreground">
                  <FileCheck className="w-4 h-4 text-primary" />
                  <span>Colunas esperadas: <strong>Nome, Função, Unidade</strong> (Matrícula e Telefone opcionais)</span>
                </div>
                <Button
                  type="button"
                  variant="ghost"
                  size="sm"
                  onClick={baixarModeloCSV}
                  className="text-xs font-semibold text-primary hover:text-primary/80 gap-1.5 h-8"
                >
                  <Download className="w-3.5 h-3.5" />
                  Baixar Modelo CSV
                </Button>
              </div>

              {/* Erro */}
              {erroImportacao && (
                <div className="p-3.5 rounded-xl bg-rose-500/15 border border-rose-500/30 text-rose-300 text-xs flex items-center gap-2.5">
                  <AlertCircle className="w-4 h-4 shrink-0 text-rose-400" />
                  <p>{erroImportacao}</p>
                </div>
              )}

              {/* Prévia dos Dados */}
              {registrosPrevia.length > 0 && (
                <div className="space-y-2">
                  <div className="flex items-center justify-between">
                    <p className="text-xs font-bold text-foreground uppercase tracking-wider">
                      Prévia dos Registros ({registrosPrevia.length} encontrados)
                    </p>
                    <Badge variant="outline" className="border-emerald-500/30 text-emerald-400 bg-emerald-500/10 text-[11px]">
                      Pronto para importação
                    </Badge>
                  </div>

                  <div className="border border-border rounded-xl overflow-hidden max-h-48 overflow-y-auto">
                    <table className="w-full text-left text-xs border-collapse">
                      <thead className="bg-muted/60 text-muted-foreground font-semibold sticky top-0">
                        <tr>
                          <th className="p-2.5">Nome</th>
                          <th className="p-2.5">Função</th>
                          <th className="p-2.5">Unidade</th>
                          <th className="p-2.5">Matrícula</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-border/40">
                        {registrosPrevia.map((reg, idx) => (
                          <tr key={idx} className="hover:bg-muted/20">
                            <td className="p-2.5 font-medium text-foreground">{reg.nome}</td>
                            <td className="p-2.5 text-muted-foreground">{reg.cargo}</td>
                            <td className="p-2.5">
                              <span className="capitalize">{reg.unidade === 'ribas' ? 'Ribas do Rio Pardo' : 'Água Clara'}</span>
                            </td>
                            <td className="p-2.5 text-muted-foreground">{reg.matricula || '-'}</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                </div>
              )}
            </div>

            {/* Modal Footer */}
            <div className="px-6 py-4 border-t border-border bg-muted/10 flex items-center justify-end gap-2.5">
              <Button
                type="button"
                variant="outline"
                onClick={() => setModalImportAberto(false)}
              >
                Cancelar
              </Button>
              <Button
                type="button"
                disabled={registrosPrevia.length === 0}
                onClick={handleConfirmarImportacao}
                className="gap-2 bg-emerald-600 hover:bg-emerald-500 text-white font-semibold disabled:opacity-50"
              >
                <CheckCircle2 className="w-4 h-4" />
                Confirmar e Importar {registrosPrevia.length > 0 ? `(${registrosPrevia.length})` : ''}
              </Button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

