                className="p-2 rounded-lg hover:bg-muted text-muted-foreground hover:text-foreground transition-colors"
              >
                <X className="w-4 h-4" />
              </button>
            </div>

            {/* Modal Form Body */}
            <form onSubmit={handleCadastrarNovoColaborador} className="p-6 space-y-4 overflow-y-auto">
              {formErro && (
                <div className="flex items-center gap-2 p-3 rounded-xl bg-rose-500/15 border border-rose-500/40 text-rose-300 text-xs">
                  <AlertCircle className="w-4 h-4 shrink-0 text-rose-400" />
                  <span>{formErro}</span>
                </div>
              )}

              {/* UPLOAD DA FOTO DO COLABORADOR */}
              <div className="p-4 rounded-2xl bg-muted/30 border border-border/70">
                <label className="block text-xs font-bold text-foreground uppercase tracking-wider mb-2.5">
                  Foto do Colaborador
                </label>

                <input
                  ref={fotoInputRef}
                  type="file"
                  accept="image/png, image/jpeg, image/jpg, image/webp"
                  className="hidden"
                  onChange={handleFotoUpload}
                />

                <div className="flex flex-col sm:flex-row items-center gap-4">
                  {/* Preview do Avatar */}
                  <div className="relative group shrink-0">
                    <div className="w-20 h-20 rounded-2xl overflow-hidden border-2 border-dashed border-primary/40 bg-card/80 flex items-center justify-center shadow-inner">
                      {novaFoto ? (
                        <img
                          src={novaFoto}
                          alt="Prévia da foto"
                          className="w-full h-full object-cover"
                        />
                      ) : (
                        <div className="flex flex-col items-center justify-center text-muted-foreground">
                          <ImageIcon className="w-7 h-7 text-muted-foreground/60 mb-1" />
                          <span className="text-[9px] font-medium text-center px-1">Sem foto</span>
                        </div>
                      )}
                    </div>

                    {/* Botão de câmera rápido sobre o avatar */}
                    <button
                      type="button"
                      onClick={() => fotoInputRef.current?.click()}
                      className="absolute -bottom-1.5 -right-1.5 w-7 h-7 rounded-xl bg-primary text-primary-foreground flex items-center justify-center shadow-lg hover:scale-105 transition-transform"
                      title="Selecionar foto do dispositivo"
                    >
                      <Camera className="w-3.5 h-3.5" />
                    </button>
                  </div>

                  {/* Instruções e Ações da Foto */}
                  <div className="flex-1 space-y-2 text-center sm:text-left">
                    <p className="text-xs text-foreground font-semibold">
                      {novaFoto ? 'Foto carregada com sucesso!' : 'Carregue uma foto de identificação'}
                    </p>
                    <p className="text-[11px] text-muted-foreground">
                      Formatos suportados: PNG, JPG ou WEBP (até 5MB). A foto será exibida nos cards dos veículos.
                    </p>

                    <div className="flex flex-wrap items-center justify-center sm:justify-start gap-2 pt-1">
                      <Button
                        type="button"
                        size="sm"
                        variant="outline"
                        onClick={() => fotoInputRef.current?.click()}
                        className="h-8 text-xs rounded-xl border-primary/40 text-primary hover:bg-primary/10 gap-1.5"
                      >
                        <UploadCloud className="w-3.5 h-3.5" />
                        {novaFoto ? 'Alterar Foto' : 'Escolher Foto do Computador'}
                      </Button>

                      {novaFoto && (
                        <Button
                          type="button"
                          size="sm"
                          variant="ghost"
                          onClick={handleRemoverFoto}
                          className="h-8 text-xs rounded-xl text-rose-400 hover:text-rose-300 hover:bg-rose-500/10 gap-1.5"
                        >
                          <Trash2 className="w-3.5 h-3.5" />
                          Remover Foto
                        </Button>
                      )}
                    </div>
                  </div>
                </div>
              </div>

              {/* Nome Completo */}
              <div>
                <label className="block text-xs font-semibold text-muted-foreground uppercase tracking-wider mb-1.5">
                  Nome Completo *
                </label>
                <Input
                  type="text"
                  placeholder="Ex: Carlos Eduardo de Oliveira"
                  value={novoNome}
                  onChange={(e) => setNovoNome(e.target.value)}
                  className="h-10 bg-muted/40 border-border rounded-xl"
                  required
                />
              </div>

              {/* Função / Cargo */}
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                <div>
                  <label className="block text-xs font-semibold text-muted-foreground uppercase tracking-wider mb-1.5">
                    Função / Cargo *
                  </label>
                  <Input
                    type="text"
                    placeholder="Ex: Operador Florestal"
                    value={novoCargo}
                    onChange={(e) => setNovoCargo(e.target.value)}
                    className="h-10 bg-muted/40 border-border rounded-xl"
                    required
                  />
                </div>

                {/* Matrícula */}
                <div>
                  <label className="block text-xs font-semibold text-muted-foreground uppercase tracking-wider mb-1.5">
                    Matrícula
                  </label>
                  <Input
                    type="text"
                    placeholder="Ex: MAT-5020 (opcional)"
                    value={novaMatricula}
                    onChange={(e) => setNovaMatricula(e.target.value)}
                    className="h-10 bg-muted/40 border-border rounded-xl"
                  />
                </div>
              </div>

              {/* Telefone e Unidade */}
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                <div>
                  <label className="block text-xs font-semibold text-muted-foreground uppercase tracking-wider mb-1.5">
                    Telefone / WhatsApp
                  </label>
                  <Input
                    type="text"
                    placeholder="Ex: (67) 99812-3344"
                    value={novoTelefone}
                    onChange={(e) => setNovoTelefone(e.target.value)}
                    className="h-10 bg-muted/40 border-border rounded-xl"
                  />
                </div>

                <div>
                  <label className="block text-xs font-semibold text-muted-foreground uppercase tracking-wider mb-1.5">
                    Unidade Regional *
                  </label>
                  <select
                    value={novaUnidade}
                    onChange={(e) => setNovaUnidade(e.target.value as 'ribas' | 'agua_clara')}
                    className="w-full h-10 px-3 rounded-xl bg-muted/40 border border-border text-foreground text-sm focus:outline-none focus:ring-2 focus:ring-primary cursor-pointer"
                  >
                    <option value="ribas">Ribas do Rio Pardo</option>
                    <option value="agua_clara">Água Clara</option>
                  </select>
                </div>
              </div>

              {/* Status Inicial */}
              <div>
                <label className="block text-xs font-semibold text-muted-foreground uppercase tracking-wider mb-1.5">
                  Status Inicial
                </label>
                <div className="grid grid-cols-3 gap-2">
                  <button
                    type="button"
                    onClick={() => setNovoStatus('presente')}
                    className={cn(
                      'p-2.5 rounded-xl border text-xs font-semibold transition-all flex items-center justify-center gap-1.5',
                      novoStatus === 'presente'
                        ? 'border-emerald-500 bg-emerald-500/20 text-emerald-300'
                        : 'border-border/60 text-muted-foreground hover:bg-muted/40'
                    )}
                  >
                    <UserCheck className="w-3.5 h-3.5" />
                    Presente
                  </button>
                  <button
                    type="button"
                    onClick={() => setNovoStatus('falta')}
                    className={cn(
                      'p-2.5 rounded-xl border text-xs font-semibold transition-all flex items-center justify-center gap-1.5',
                      novoStatus === 'falta'
                        ? 'border-rose-500 bg-rose-500/20 text-rose-300'
                        : 'border-border/60 text-muted-foreground hover:bg-muted/40'
                    )}
                  >
                    <UserX className="w-3.5 h-3.5" />
                    Falta
                  </button>
                  <button
                    type="button"
                    onClick={() => setNovoStatus('substituto')}
                    className={cn(
                      'p-2.5 rounded-xl border text-xs font-semibold transition-all flex items-center justify-center gap-1.5',
                      novoStatus === 'substituto'
                        ? 'border-amber-500 bg-amber-500/20 text-amber-300'
                        : 'border-border/60 text-muted-foreground hover:bg-muted/40'
                    )}
                  >
                    <RefreshCw className="w-3.5 h-3.5" />
                    Substituto
                  </button>
                </div>
              </div>

              {/* Botões do Rodapé */}
              <div className="pt-4 border-t border-border flex items-center justify-end gap-2.5">
                <Button
                  type="button"
                  variant="outline"
                  onClick={() => setModalNovoColaboradorAberto(false)}
                  className="h-10 px-4 rounded-xl"
                >
                  Cancelar
                </Button>
                <Button
                  type="submit"
                  className="h-10 px-5 rounded-xl bg-primary hover:bg-primary/90 text-primary-foreground font-semibold gap-2 shadow-md"
                >
                  <UserPlus className="w-4 h-4" />
                  Salvar Colaborador
                </Button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* ========================================================================= */}
      {/* MODAL: IMPORTAR ARQUIVO EXCEL / CSV                                       */}
      {/* ========================================================================= */}
      {modalImportAberto && (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/75 backdrop-blur-sm animate-in fade-in duration-150"
          onClick={() => setModalImportAberto(false)}
        >
          <div
            className="bg-card border border-border rounded-2xl shadow-2xl w-full max-w-2xl overflow-hidden animate-in zoom-in-95 duration-150 max-h-[90vh] flex flex-col"
            onClick={(e) => e.stopPropagation()}
          >
            {/* Header */}
            <div className="flex items-center justify-between px-6 py-4 border-b border-border bg-muted/20 shrink-0">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 rounded-xl bg-emerald-500/15 border border-emerald-500/30 flex items-center justify-center text-emerald-400">
                  <FileSpreadsheet className="w-5 h-5" />
                </div>
                <div>
                  <h3 className="text-base font-bold text-foreground">Importar Colaboradores via Excel / CSV</h3>
                  <p className="text-xs text-muted-foreground">Adicione colaboradores em massa com nome, função e unidade</p>
                </div>
              </div>
              <button
                type="button"
                onClick={() => setModalImportAberto(false)}
                className="p-2 rounded-lg hover:bg-muted text-muted-foreground hover:text-foreground transition-colors"
              >
                <X className="w-4 h-4" />
              </button>
            </div>

            {/* Conteúdo */}
            <div className="p-6 space-y-5 overflow-y-auto">
              {/* Área de Drop / Seleção de Arquivo */}
              <div
                onClick={() => fileInputRef.current?.click()}
                className="border-2 border-dashed border-border/80 hover:border-emerald-500/60 bg-muted/20 hover:bg-emerald-500/[0.03] rounded-2xl p-6 text-center cursor-pointer transition-all flex flex-col items-center justify-center gap-3 group"
              >
                <input
                  ref={fileInputRef}
                  type="file"
                  accept=".csv, .xlsx, .xls, text/csv, application/vnd.openxmlformats-officedocument.spreadsheetml.sheet, application/vnd.ms-excel"
                  className="hidden"
                  onChange={handleFileChange}
                />
                <div className="w-14 h-14 rounded-2xl bg-emerald-500/10 border border-emerald-500/20 flex items-center justify-center text-emerald-400 group-hover:scale-110 transition-transform">
                  <UploadCloud className="w-7 h-7" />
                </div>
                <div>
                  <p className="text-sm font-bold text-foreground">
                    {arquivoNome ? arquivoNome : 'Clique para selecionar a planilha Excel / CSV'}
                  </p>
                  <p className="text-xs text-muted-foreground mt-1">
                    Formato aceito: .csv ou exportação de Excel com as colunas <b>Nome</b>, <b>Função</b> e <b>Unidade</b>
                  </p>
                </div>
              </div>

              {/* Botão Baixar Modelo */}
              <div className="flex items-center justify-between p-3.5 rounded-xl bg-background/60 border border-border">
                <div className="flex items-center gap-2.5">
                  <FileCheck className="w-4 h-4 text-primary shrink-0" />
                  <span className="text-xs text-muted-foreground">
                    Precisa de uma referência? Baixe nossa planilha modelo pré-formatada.
                  </span>
                </div>
                <Button
                  type="button"
                  variant="outline"
                  size="sm"
                  onClick={downloadModeloCSV}
                  className="rounded-xl text-xs gap-1.5 border-border hover:bg-muted shrink-0"
                >
                  <Download className="w-3.5 h-3.5" />
                  Baixar Modelo CSV
                </Button>
              </div>

              {/* Erro de importação se houver */}
              {erroImportacao && (
                <div className="flex items-center gap-2 p-3 rounded-xl bg-rose-500/15 border border-rose-500/40 text-rose-300 text-xs">
                  <AlertCircle className="w-4 h-4 shrink-0 text-rose-400" />
                  <span>{erroImportacao}</span>
                </div>
              )}

              {/* Prévia dos Dados Identificados */}
              {registrosPrevia.length > 0 && (
                <div className="space-y-2.5">
                  <div className="flex items-center justify-between">
                    <span className="text-xs font-bold text-foreground uppercase tracking-wider">
                      Prévia dos Colaboradores Identificados ({registrosPrevia.length})
                    </span>
                    <Badge variant="success" className="text-[11px]">
                      {registrosPrevia.length} prontos para importar
                    </Badge>
                  </div>

                  <div className="max-h-52 overflow-y-auto rounded-xl border border-border/70 bg-card divide-y divide-border/40 text-xs">
                    {registrosPrevia.map((reg, idx) => (
                      <div key={idx} className="p-2.5 flex items-center justify-between gap-3">
                        <div className="min-w-0">
                          <p className="font-bold text-foreground truncate">{reg.nome}</p>
                          <p className="text-[11px] text-muted-foreground truncate">{reg.cargo}</p>
                        </div>
                        <div className="flex items-center gap-2 shrink-0">
                          <span className="text-[11px] px-2 py-0.5 rounded-md bg-muted text-muted-foreground border border-border/50">
                            {regionalLabel[reg.unidade]}
                          </span>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>

            {/* Footer do Modal */}
            <div className="px-6 py-4 border-t border-border bg-muted/20 flex items-center justify-end gap-2 shrink-0">
              <Button
                type="button"
                variant="outline"
                onClick={() => setModalImportAberto(false)}
                className="h-10 px-4 rounded-xl"
              >
                Cancelar
              </Button>
              <Button
                type="button"
                disabled={registrosPrevia.length === 0}
                onClick={handleConfirmarImportacao}
                className="h-10 px-5 rounded-xl bg-emerald-600 hover:bg-emerald-500 text-white font-semibold gap-2 disabled:opacity-50"
              >
                <CheckCircle2 className="w-4 h-4" />
                Confirmar Importação ({registrosPrevia.length})
              </Button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

