import React, { useState } from 'react';
import { Navbar } from './components/Navbar';
import { MetricsHeader } from './components/MetricsHeader';
import { VehicleCardGrid } from './components/VehicleCardGrid';
import { TeamsManagement } from './components/TeamsManagement';
import { CollaboratorsManagement } from './components/CollaboratorsManagement';
import { ExportReports } from './components/ExportReports';
import { NewTeamModal } from './components/NewTeamModal';
import { VEICULOS_INICIAIS, COLABORADORES_RESERVA } from './data/mockData';
import { Veiculo, Regional, Colaborador, StatusPresenca, MotivoFalta } from './types';

export default function App() {
  const [activeTab, setActiveTab] = useState<'veiculos' | 'equipes' | 'colaboradores' | 'relatorios'>('veiculos');
  const [selectedRegional, setSelectedRegional] = useState<Regional>('todas');
  const [selectedDate, setSelectedDate] = useState<Date>(new Date());
  const [veiculos, setVeiculos] = useState<Veiculo[]>(VEICULOS_INICIAIS);
  const [colaboradoresReserva, setColaboradoresReserva] = useState<Colaborador[]>(COLABORADORES_RESERVA);
  const [modalNovaEquipeAberto, setModalNovaEquipeAberto] = useState(false);

  // Manipulador para atualizar status de presença de colaboradores
  const handleUpdateStatus = (
    veiculoId: string,
    colaboradorId: string,
    novoStatus: StatusPresenca,
    motivoFalta?: MotivoFalta,
    substituto?: Colaborador
  ) => {
    setVeiculos((prevVeiculos) =>
      prevVeiculos.map((v) => {
        if (v.id !== veiculoId) return v;

        const assentosAtualizados = { ...v.assentos };
        (Object.keys(assentosAtualizados) as Array<keyof typeof assentosAtualizados>).forEach((chave) => {
          const colab = assentosAtualizados[chave];
          if (colab && colab.id === colaboradorId) {
            assentosAtualizados[chave] = {
              ...colab,
              status: novoStatus,
              motivoFalta: novoStatus === 'falta' ? motivoFalta : undefined,
              substitutoId: novoStatus === 'substituto' ? substituto?.id : undefined,
              substitutoNome: novoStatus === 'substituto' ? substituto?.nome : undefined,
            };
          }
        });

        return { ...v, assentos: assentosAtualizados };
      })
    );
  };

  // Manipulador para criar nova equipe
  const handleCriarNovaEquipe = (novaEquipe: {
    prefixo: string;
    placa: string;
    modelo: string;
    regional: 'ribas' | 'agua_clara';
    motoristaNome: string;
    frenteDirNome: string;
    trasEsqNome?: string;
    trasDirNome?: string;
  }) => {
    const novoVeiculo: Veiculo = {
      id: `vtr-${Date.now()}`,
      prefixo: novaEquipe.prefixo,
      placa: novaEquipe.placa,
      modelo: novaEquipe.modelo,
      ano: 2024,
      regional: novaEquipe.regional,
      statusOperacional: 'ativo',
      equipe1Codigo: `EQ-${novaEquipe.prefixo}-A`,
      equipe2Codigo: `EQ-${novaEquipe.prefixo}-B`,
      assentos: {
        motorista: {
          id: `col-${Date.now()}-1`,
          nome: novaEquipe.motoristaNome,
          cargo: 'Motorista / Líder',
          matricula: `MAT-${Math.floor(1000 + Math.random() * 9000)}`,
          foto: '',
          telefone: '(67) 99999-1111',
          status: 'presente',
          equipeId: `EQ-${novaEquipe.prefixo}-A`,
          equipeNumero: 1,
          posicaoVeiculo: 'motorista',
        },
        frenteDir: {
          id: `col-${Date.now()}-2`,
          nome: novaEquipe.frenteDirNome,
          cargo: 'Operador Florestal',
          matricula: `MAT-${Math.floor(1000 + Math.random() * 9000)}`,
          foto: '',
          telefone: '(67) 99999-2222',
          status: 'presente',
          equipeId: `EQ-${novaEquipe.prefixo}-A`,
          equipeNumero: 1,
          posicaoVeiculo: 'frente_dir',
        },
        trasEsq: {
          id: `col-${Date.now()}-3`,
          nome: novaEquipe.trasEsqNome || 'Operador de Campo',
          cargo: 'Operador de Máquinas',
          matricula: `MAT-${Math.floor(1000 + Math.random() * 9000)}`,
          foto: '',
          telefone: '(67) 99999-3333',
          status: 'presente',
          equipeId: `EQ-${novaEquipe.prefixo}-B`,
          equipeNumero: 2,
          posicaoVeiculo: 'tras_esq',
        },
        trasDir: {
          id: `col-${Date.now()}-4`,
          nome: novaEquipe.trasDirNome || 'Ajudante Geral',
          cargo: 'Auxiliar Operacional',
          matricula: `MAT-${Math.floor(1000 + Math.random() * 9000)}`,
          foto: '',
          telefone: '(67) 99999-4444',
          status: 'presente',
          equipeId: `EQ-${novaEquipe.prefixo}-B`,
          equipeNumero: 2,
          posicaoVeiculo: 'tras_dir',
        },
      },
    };

    setVeiculos((prev) => [novoVeiculo, ...prev]);
    setModalNovaEquipeAberto(false);
  };

  return (
    <div className="min-h-screen bg-background text-foreground flex flex-col selection:bg-primary/20">
      {/* Barra de Navegação Superior */}
      <Navbar
        activeTab={activeTab}
        onTabChange={setActiveTab}
        selectedRegional={selectedRegional}
        onRegionalChange={setSelectedRegional}
        selectedDate={selectedDate}
        onDateChange={setSelectedDate}
        onNewTeamClick={() => setModalNovaEquipeAberto(true)}
      />

      {/* Conteúdo Principal */}
      <main className="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-6 space-y-6">
        {/* Visualização de Veículos & Assentos */}
        {activeTab === 'veiculos' && (
          <div className="space-y-6">
            <MetricsHeader
              veiculos={veiculos}
              selectedRegional={selectedRegional}
              onFiltroRegionalChange={(reg) => setSelectedRegional(reg)}
              onNovaEquipe={() => setModalNovaEquipeAberto(true)}
            />
            <VehicleCardGrid
              veiculos={veiculos}
              selectedRegional={selectedRegional}
              onUpdateStatus={handleUpdateStatus}
              colaboradoresReserva={colaboradoresReserva}
            />
          </div>
        )}

        {/* Visualização de Composição de Equipes */}
        {activeTab === 'equipes' && (
          <TeamsManagement
            veiculos={veiculos}
            onNovaEquipe={() => setModalNovaEquipeAberto(true)}
          />
        )}

        {/* Visualização de Gestão de Colaboradores */}
        {activeTab === 'colaboradores' && (
          <CollaboratorsManagement
            veiculos={veiculos}
            colaboradoresReserva={colaboradoresReserva}
          />
        )}

        {/* Visualização de Relatórios & Histórico */}
        {activeTab === 'relatorios' && (
          <ExportReports
            veiculos={veiculos}
            selectedDate={selectedDate}
          />
        )}
      </main>

      {/* Modal de Cadastro de Nova Equipe */}
      {modalNovaEquipeAberto && (
        <NewTeamModal
          isOpen={modalNovaEquipeAberto}
          onClose={() => setModalNovaEquipeAberto(false)}
          onSave={handleCriarNovaEquipe}
        />
      )}
    </div>
  );
}

