import React, { useState, useMemo, useRef } from 'react';
import {
  Users,
  Search,
  Phone,
  MapPin,
  ChevronDown,
  ChevronUp,
  UserCheck,
  UserX,
  RefreshCw,
  UploadCloud,
  FileSpreadsheet,
  Download,
  CheckCircle2,
  AlertCircle,
  X,
  FileCheck,
  UserPlus,
  Plus,
  Camera,
  Image as ImageIcon,
  Trash2,
  IdCard,
  Building2
} from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle } from './ui/card';
import { Badge } from './ui/badge';
import { Input } from './ui/input';
import { Button } from './ui/button';
import { cn } from '@/lib/utils';
import { Colaborador, Veiculo, StatusPresenca, Regional } from '../types';

export interface ColaboradorCompleto {
  id: string;
  nome: string;
  cargo: string;
  matricula: string;
  foto: string;
  telefone: string;
  status: StatusPresenca;
  motivoFalta?: string;
  substitutoNome?: string;
  equipeId: string;
  equipeNumero: 1 | 2;
  posicaoVeiculo: 'motorista' | 'frente_dir' | 'tras_esq' | 'tras_dir';
  veiculoPrefixo: string;
  veiculoPlaca: string;
  regional: 'ribas' | 'agua_clara';
}

interface CollaboratorsManagementProps {
  veiculos?: Veiculo[];
  colaboradoresReserva?: Colaborador[];
  onImportarColaboradores?: (novosColaboradores: ColaboradorCompleto[]) => void;
  onAdicionarColaborador?: (novoColaborador: ColaboradorCompleto) => void;
}

const statusConfig: Record<StatusPresenca, { label: string; className: string }> = {
  presente: { label: 'Presente', className: 'bg-emerald-500/20 text-emerald-400 border-emerald-500/30' },
  falta: { label: 'Falta', className: 'bg-rose-500/20 text-rose-400 border-rose-500/30' },
  substituto: { label: 'Substituto', className: 'bg-amber-500/20 text-amber-400 border-amber-500/30' },
};

const regionalLabel: Record<string, string> = {
  ribas: 'Ribas do Rio Pardo',
  agua_clara: 'Água Clara',
};

interface RegistroImportado {
  nome: string;
  cargo: string;
  unidade: 'ribas' | 'agua_clara';
  matricula?: string;
  telefone?: string;
}

export const CollaboratorsManagement: React.FC<CollaboratorsManagementProps> = ({
  veiculos = [],
  colaboradoresReserva = [],
  onImportarColaboradores,
  onAdicionarColaborador,
}) => {
  const [search, setSearch] = useState('');
  const [filterStatus, setFilterStatus] = useState<StatusPresenca | 'todos'>('todos');
  const [filterRegional, setFilterRegional] = useState<Regional | 'todas'>('todas');
  const [expandedId, setExpandedId] = useState<string | null>(null);

  // Estados do Modal de Cadastro Manual de Colaborador
  const [modalNovoColaboradorAberto, setModalNovoColaboradorAberto] = useState(false);
  const [novoNome, setNovoNome] = useState('');
  const [novoCargo, setNovoCargo] = useState('');
  const [novaMatricula, setNovaMatricula] = useState('');
  const [novoTelefone, setNovoTelefone] = useState('');
  const [novaFoto, setNovaFoto] = useState<string>('');
  const [novaUnidade, setNovaUnidade] = useState<'ribas' | 'agua_clara'>('ribas');
  const [novoStatus, setNovoStatus] = useState<StatusPresenca>('presente');
  const [formErro, setFormErro] = useState<string | null>(null);
  const fotoInputRef = useRef<HTMLInputElement>(null);

  // Estados do Modal de Importação Excel / CSV
  const [modalImportAberto, setModalImportAberto] = useState(false);
  const [arquivoNome, setArquivoNome] = useState('');
  const [registrosPrevia, setRegistrosPrevia] = useState<RegistroImportado[]>([]);
  const [erroImportacao, setErroImportacao] = useState<string | null>(null);
  const [sucessoMsg, setSucessoMsg] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Lista de colaboradores extraídos dos veículos e lista reserva
  const colaboradoresBase: ColaboradorCompleto[] = useMemo(() => {
    const lista: ColaboradorCompleto[] = [];
    (veiculos || []).forEach((v) => {
      if (!v || !v.assentos) return;
      const assentos: Array<{ colab?: Colaborador; pos: ColaboradorCompleto['posicaoVeiculo'] }> = [
        { colab: v.assentos.motorista, pos: 'motorista' },
        { colab: v.assentos.frenteDir, pos: 'frente_dir' },
        { colab: v.assentos.trasEsq, pos: 'tras_esq' },
        { colab: v.assentos.trasDir, pos: 'tras_dir' },
      ];
      assentos.forEach(({ colab, pos }) => {
        if (!colab) return;
        lista.push({
          id: colab.id,
          nome: colab.nome || 'Sem Nome',
          cargo: colab.cargo || 'Operador',
          matricula: colab.matricula ?? '',
          foto: colab.foto ?? '',
          telefone: colab.telefone ?? '',
          status: colab.status || 'presente',
          motivoFalta: colab.motivoFalta,
          substitutoNome: colab.substitutoNome,
          equipeId: colab.equipeId || '',
          equipeNumero: colab.equipeNumero || 1,
          posicaoVeiculo: pos,
          veiculoPrefixo: v.prefixo || '',
          veiculoPlaca: v.placa || '',
          regional: v.regional || 'ribas',
        });
      });
    });

    // Adiciona colaboradores reserva se houver
    (colaboradoresReserva || []).forEach((r, idx) => {
      if (!r) return;
      lista.push({
        id: r.id || `res-${idx}`,
        nome: r.nome || 'Colaborador Reserva',
        cargo: r.cargo || 'Reserva Operacional',
        matricula: r.matricula || '',
        foto: r.foto || '',
        telefone: r.telefone || '',
        status: r.status || 'presente',
        motivoFalta: r.motivoFalta,
        substitutoNome: r.substitutoNome,
        equipeId: 'reserva',
        equipeNumero: 1,
        posicaoVeiculo: 'motorista',
        veiculoPrefixo: 'Banco de Reserva',
        veiculoPlaca: '-',
        regional: 'ribas',
      });
    });

    return lista;
  }, [veiculos, colaboradoresReserva]);

  const [colaboradoresAdicionados, setColaboradoresAdicionados] = useState<ColaboradorCompleto[]>([]);

  const todosColaboradores = useMemo(() => {
    return [...colaboradoresBase, ...colaboradoresAdicionados];
  }, [colaboradoresBase, colaboradoresAdicionados]);

  const colaboradoresFiltrados = useMemo(() => {
    return todosColaboradores.filter((c) => {
      if (!c) return false;
      const matchSearch =
        !search ||
        (c.nome || '').toLowerCase().includes(search.toLowerCase()) ||
        (c.cargo || '').toLowerCase().includes(search.toLowerCase()) ||
        (c.matricula || '').toLowerCase().includes(search.toLowerCase()) ||
        (c.veiculoPlaca || '').toLowerCase().includes(search.toLowerCase()) ||
        (c.veiculoPrefixo || '').toLowerCase().includes(search.toLowerCase());

      const matchStatus = filterStatus === 'todos' || c.status === filterStatus;
      const matchRegional = filterRegional === 'todas' || c.regional === filterRegional;

      return matchSearch && matchStatus && matchRegional;
    });
  }, [todosColaboradores, search, filterStatus, filterRegional]);

  const stats = useMemo(() => {
    const presentes = todosColaboradores.filter((c) => c.status === 'presente').length;
    const faltas = todosColaboradores.filter((c) => c.status === 'falta').length;
    const substitutos = todosColaboradores.filter((c) => c.status === 'substituto').length;
    return { presentes, faltas, substitutos, total: todosColaboradores.length };
  }, [todosColaboradores]);

  // Handler para Upload de Foto de Colaborador
  const handleFotoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (!file.type.startsWith('image/')) {
      setFormErro('Por favor, selecione um arquivo de imagem válido (PNG, JPG, JPEG, WEBP).');
      return;
    }

    if (file.size > 5 * 1024 * 1024) {
      setFormErro('A imagem selecionada deve ter no máximo 5MB.');
      return;
    }

    setFormErro(null);
    const reader = new FileReader();
    reader.onload = (event) => {
      if (event.target?.result) {
        setNovaFoto(event.target.result as string);
      }
    };
    reader.readAsDataURL(file);
  };

  const handleRemoverFoto = () => {
    setNovaFoto('');
    if (fotoInputRef.current) {
      fotoInputRef.current.value = '';
    }
  };

  // Salvar Novo Colaborador Manual
  const handleSalvarNovoColaborador = (e: React.FormEvent) => {
    e.preventDefault();
    if (!novoNome.trim()) {
      setFormErro('Informe o nome completo do colaborador.');
      return;
    }
    if (!novoCargo.trim()) {
      setFormErro('Informe a função/cargo do colaborador.');
      return;
    }

    const idGerado = `col-manual-${Date.now()}`;
    const fotoFinal = novaFoto.trim() || `https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?w=150&auto=format&fit=crop&q=80`;

    const novoItem: ColaboradorCompleto = {
      id: idGerado,
      nome: novoNome.trim(),
      cargo: novoCargo.trim(),
      matricula: novaMatricula.trim() || `MAT-${Math.floor(1000 + Math.random() * 9000)}`,
      foto: fotoFinal,
      telefone: novoTelefone.trim() || '(67) 99999-0000',
      status: novoStatus,
      equipeId: 'reserva',
      equipeNumero: 1,
      posicaoVeiculo: 'motorista',
      veiculoPrefixo: 'Banco de Reserva',
      veiculoPlaca: '-',
      regional: novaUnidade,
    };

    setColaboradoresAdicionados((prev) => [novoItem, ...prev]);

    if (onAdicionarColaborador) {
      onAdicionarColaborador(novoItem);
    }

    // Resetar formulário
    setNovoNome('');
    setNovoCargo('');
    setNovaMatricula('');
    setNovoTelefone('');
    setNovaFoto('');
    setNovaUnidade('ribas');
    setNovoStatus('presente');
    setFormErro(null);
    setModalNovoColaboradorAberto(false);
  };

  // Handler para Upload e Leitura do Arquivo Excel/CSV
  const handleArquivoChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setArquivoNome(file.name);
    setErroImportacao(null);
    setSucessoMsg(null);

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const text = event.target?.result as string;
        if (!text) {
          setErroImportacao('O arquivo selecionado está vazio.');
          return;
        }

        const linhas = text.split(/\r\n|\n/).filter((l) => l.trim().length > 0);
        if (linhas.length < 2) {
          setErroImportacao('O arquivo deve conter um cabeçalho e ao menos uma linha de dados.');
          return;
        }

        const separador = linhas[0].includes(';') ? ';' : linhas[0].includes('\t') ? '\t' : ',';
        const cabecalhos = linhas[0].split(separador).map((c) => c.trim().toLowerCase());

        const idxNome = cabecalhos.findIndex((c) => c.includes('nome') || c.includes('colaborador') || c.includes('funcionario'));
        const idxCargo = cabecalhos.findIndex((c) => c.includes('cargo') || c.includes('função') || c.includes('funcao') || c.includes('posto'));
        const idxUnidade = cabecalhos.findIndex((c) => c.includes('unidade') || c.includes('regional') || c.includes('polo') || c.includes('base') || c.includes('cidade'));
        const idxMatricula = cabecalhos.findIndex((c) => c.includes('matricula') || c.includes('matrícula') || c.includes('registro') || c.includes('id') || c.includes('re'));
        const idxTelefone = cabecalhos.findIndex((c) => c.includes('telefone') || c.includes('celular') || c.includes('contato') || c.includes('fone'));

        const parsed: RegistroImportado[] = [];

        for (let i = 1; i < linhas.length; i++) {
          const colunas = linhas[i].split(separador).map((val) => val.trim().replace(/^["']|["']$/g, ''));
          if (colunas.length === 0 || !colunas[0]) continue;

          const nomeVal = idxNome !== -1 ? colunas[idxNome] : colunas[0];
          const cargoVal = idxCargo !== -1 ? colunas[idxCargo] : (colunas[1] || 'Operador Florestal');
          const unidadeStr = (idxUnidade !== -1 ? colunas[idxUnidade] : (colunas[2] || 'ribas')).toLowerCase();

          let unidadeFinal: 'ribas' | 'agua_clara' = 'ribas';
          if (unidadeStr.includes('agua') || unidadeStr.includes('água') || unidadeStr.includes('clara') || unidadeStr.includes('agc')) {
            unidadeFinal = 'agua_clara';
          }

          const matriculaVal = idxMatricula !== -1 ? colunas[idxMatricula] : `MAT-${Math.floor(1000 + Math.random() * 9000)}`;
          const telefoneVal = idxTelefone !== -1 ? colunas[idxTelefone] : '(67) 99999-0000';

          if (nomeVal) {
            parsed.push({
              nome: nomeVal,
              cargo: cargoVal,
              unidade: unidadeFinal,
              matricula: matriculaVal,
              telefone: telefoneVal,
            });
          }
        }

        if (parsed.length === 0) {
          setErroImportacao('Não foi possível identificar registros válidos no arquivo enviado.');
          return;
        }

        setRegistrosPrevia(parsed);
      } catch (err) {
        setErroImportacao('Erro ao processar o arquivo. Certifique-se de que é um CSV ou arquivo formatado.');
      }
    };

    reader.readAsText(file);
  };

  const handleConfirmarImportacao = () => {
    if (registrosPrevia.length === 0) return;

    const novosColaboradoresConvertidos: ColaboradorCompleto[] = registrosPrevia.map((reg, idx) => {
      const randomAvatar = `https://images.unsplash.com/photo-${1535713875002 + (idx % 10)}?w=150&auto=format&fit=crop&q=80`;
      return {
        id: `import-${Date.now()}-${idx}`,
        nome: reg.nome,
        cargo: reg.cargo,
        matricula: reg.matricula || `MAT-${Math.floor(2000 + idx)}`,
        foto: randomAvatar,
        telefone: reg.telefone || '(67) 99888-0000',
        status: 'presente',
        equipeId: 'reserva',
        equipeNumero: 1,
        posicaoVeiculo: 'motorista',
        veiculoPrefixo: 'Banco de Reserva',
        veiculoPlaca: '-',
        regional: reg.unidade,
      };
    });

    setColaboradoresAdicionados((prev) => [...novosColaboradoresConvertidos, ...prev]);

    if (onImportarColaboradores) {
      onImportarColaboradores(novosColaboradoresConvertidos);
    }

    setSucessoMsg(`${registrosPrevia.length} colaboradores importados com sucesso!`);
    setTimeout(() => {
      setModalImportAberto(false);
      setRegistrosPrevia([]);
      setArquivoNome('');
      setSucessoMsg(null);
    }, 1200);
  };

  const handleBaixarModeloExemplo = () => {
    const csvContent = "Nome;Cargo;Unidade;Matricula;Telefone\n"
      + "Carlos Silva;Operador de Máquinas;Ribas do Rio Pardo;MAT-4010;(67) 99811-2233\n"
      + "Mariana Souza;Técnica de Campo;Água Clara;MAT-4011;(67) 99822-4455\n"
      + "João Ferreira;Ajudante Geral;Ribas do Rio Pardo;MAT-4012;(67) 99833-6677\n"
      + "Lucas Oliveira;Motorista Especializado;Água Clara;MAT-4013;(67) 99844-8899";

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.setAttribute('href', url);
    link.setAttribute('download', 'modelo_importacao_colaboradores.csv');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-300">
      {/* Header com Ações */}
      <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-4 bg-card/60 backdrop-blur-md p-5 rounded-2xl border border-border">
        <div>
          <div className="flex items-center gap-3 mb-1">
            <div className="p-2.5 rounded-xl bg-primary/10 text-primary border border-primary/20">
              <Users className="w-6 h-6" />
            </div>
            <div>
              <h1 className="text-xl font-bold text-foreground">Gestão de Colaboradores</h1>
              <p className="text-xs text-muted-foreground">
                Visualização do quadro de colaboradores, presença diária e cadastro de novos membros
              </p>
            </div>
          </div>
        </div>

        {/* Botões de Ação de Alto Nível */}
        <div className="flex flex-wrap items-center gap-2.5">
          <Button
            onClick={() => setModalNovoColaboradorAberto(true)}
            className="gap-2 bg-primary text-primary-foreground shadow-lg hover:bg-primary/90 font-semibold text-xs h-10 px-4 rounded-xl cursor-pointer"
          >
            <UserPlus className="w-4 h-4" />
            Adicionar Colaborador
          </Button>

          <Button
            onClick={() => setModalImportAberto(true)}
            variant="outline"
            className="gap-2 border-emerald-500/30 text-emerald-400 bg-emerald-500/10 hover:bg-emerald-500/20 text-xs h-10 px-4 rounded-xl cursor-pointer"
          >
            <UploadCloud className="w-4 h-4" />
            Importar Excel / CSV
          </Button>
        </div>
      </div>

      {/* Cards de Métricas Principais (Sem Composição de Equipe) */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
        <div className="bg-card/50 border border-border p-4 rounded-xl">
          <div className="flex items-center justify-between">
            <span className="text-xs text-muted-foreground font-medium">Total Colaboradores</span>
            <Users className="w-4 h-4 text-primary" />
          </div>
          <p className="text-2xl font-bold text-foreground mt-1">{stats.total}</p>
        </div>

        <div className="bg-card/50 border border-border p-4 rounded-xl">
          <div className="flex items-center justify-between">
            <span className="text-xs text-muted-foreground font-medium">Presentes</span>
            <UserCheck className="w-4 h-4 text-emerald-400" />
