    setNovoStatus('presente');
    setFormErro(null);
    setModalNovoColaboradorAberto(false);
  };

  // Handler para Upload e Leitura do Arquivo Excel/CSV
  const handleArquivoChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setArquivoNome(file.name);
    setErroImportacao(null);
    setSucessoMsg(null);

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const text = event.target?.result as string;
        if (!text) {
          setErroImportacao('O arquivo selecionado está vazio.');
          return;
        }

        const linhas = text.split(/\r\n|\n/).filter((l) => l.trim().length > 0);
        if (linhas.length < 2) {
          setErroImportacao('O arquivo deve conter um cabeçalho e ao menos uma linha de dados.');
          return;
        }

        const separador = linhas[0].includes(';') ? ';' : linhas[0].includes('\t') ? '\t' : ',';
        const cabecalhos = linhas[0].split(separador).map((c) => c.trim().toLowerCase());

        const idxNome = cabecalhos.findIndex((c) => c.includes('nome') || c.includes('colaborador') || c.includes('funcionario'));
        const idxCargo = cabecalhos.findIndex((c) => c.includes('cargo') || c.includes('função') || c.includes('funcao') || c.includes('posto'));
        const idxUnidade = cabecalhos.findIndex((c) => c.includes('unidade') || c.includes('regional') || c.includes('polo') || c.includes('base') || c.includes('cidade'));
        const idxMatricula = cabecalhos.findIndex((c) => c.includes('matricula') || c.includes('matrícula') || c.includes('registro') || c.includes('id') || c.includes('re'));
        const idxTelefone = cabecalhos.findIndex((c) => c.includes('telefone') || c.includes('celular') || c.includes('contato') || c.includes('fone'));

        const parsed: RegistroImportado[] = [];

        for (let i = 1; i < linhas.length; i++) {
          const colunas = linhas[i].split(separador).map((val) => val.trim().replace(/^["']|["']$/g, ''));
          if (colunas.length === 0 || !colunas[0]) continue;

          const nomeVal = idxNome !== -1 ? colunas[idxNome] : colunas[0];
          const cargoVal = idxCargo !== -1 ? colunas[idxCargo] : (colunas[1] || 'Operador Florestal');
          const unidadeStr = (idxUnidade !== -1 ? colunas[idxUnidade] : (colunas[2] || 'ribas')).toLowerCase();

          let unidadeFinal: 'ribas' | 'agua_clara' = 'ribas';
          if (unidadeStr.includes('agua') || unidadeStr.includes('água') || unidadeStr.includes('clara') || unidadeStr.includes('agc')) {
            unidadeFinal = 'agua_clara';
          }

          const matriculaVal = idxMatricula !== -1 ? colunas[idxMatricula] : `MAT-${Math.floor(1000 + Math.random() * 9000)}`;
          const telefoneVal = idxTelefone !== -1 ? colunas[idxTelefone] : '(67) 99999-0000';

          if (nomeVal) {
            parsed.push({
              nome: nomeVal,
              cargo: cargoVal,
              unidade: unidadeFinal,
              matricula: matriculaVal,
              telefone: telefoneVal,
            });
          }
        }

        if (parsed.length === 0) {
          setErroImportacao('Não foi possível identificar registros válidos no arquivo enviado.');
          return;
        }

        setRegistrosPrevia(parsed);
      } catch (err) {
        setErroImportacao('Erro ao processar o arquivo. Certifique-se de que é um CSV ou arquivo formatado.');
      }
    };

    reader.readAsText(file);
  };

  const handleConfirmarImportacao = () => {
    if (registrosPrevia.length === 0) return;

    const novosColaboradoresConvertidos: ColaboradorCompleto[] = registrosPrevia.map((reg, idx) => {
      const randomAvatar = `https://images.unsplash.com/photo-${1535713875002 + (idx % 10)}?w=150&auto=format&fit=crop&q=80`;
      return {
        id: `import-${Date.now()}-${idx}`,
        nome: reg.nome,
        cargo: reg.cargo,
        matricula: reg.matricula || `MAT-${Math.floor(2000 + idx)}`,
        foto: randomAvatar,
        telefone: reg.telefone || '(67) 99888-0000',
        status: 'presente',
        equipeId: 'reserva',
        equipeNumero: 1,
        posicaoVeiculo: 'motorista',
        veiculoPrefixo: 'Banco de Reserva',
        veiculoPlaca: '-',
        regional: reg.unidade,
      };
    });

    setColaboradoresAdicionados((prev) => [...novosColaboradoresConvertidos, ...prev]);

    if (onImportarColaboradores) {
      onImportarColaboradores(novosColaboradoresConvertidos);
    }

    setSucessoMsg(`${registrosPrevia.length} colaboradores importados com sucesso!`);
    setTimeout(() => {
      setModalImportAberto(false);
      setRegistrosPrevia([]);
      setArquivoNome('');
      setSucessoMsg(null);
    }, 1200);
  };

  const handleBaixarModeloExemplo = () => {
    const csvContent = "Nome;Cargo;Unidade;Matricula;Telefone\n"
      + "Carlos Silva;Operador de Máquinas;Ribas do Rio Pardo;MAT-4010;(67) 99811-2233\n"
      + "Mariana Souza;Técnica de Campo;Água Clara;MAT-4011;(67) 99822-4455\n"
      + "João Ferreira;Ajudante Geral;Ribas do Rio Pardo;MAT-4012;(67) 99833-6677\n"
      + "Lucas Oliveira;Motorista Especializado;Água Clara;MAT-4013;(67) 99844-8899";

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.setAttribute('href', url);
    link.setAttribute('download', 'modelo_importacao_colaboradores.csv');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-300">
      {/* Header com Ações */}
      <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-4 bg-card/60 backdrop-blur-md p-5 rounded-2xl border border-border">
        <div>
          <div className="flex items-center gap-3 mb-1">
            <div className="p-2.5 rounded-xl bg-primary/10 text-primary border border-primary/20">
              <Users className="w-6 h-6" />
            </div>
            <div>
              <h1 className="text-xl font-bold text-foreground">Gestão de Colaboradores</h1>
              <p className="text-xs text-muted-foreground">
                Visualização do quadro de colaboradores, presença diária e cadastro de novos membros
              </p>
            </div>
          </div>
        </div>

        {/* Botões de Ação de Alto Nível */}
        <div className="flex flex-wrap items-center gap-2.5">
          <Button
            onClick={() => setModalNovoColaboradorAberto(true)}
            className="gap-2 bg-primary text-primary-foreground shadow-lg hover:bg-primary/90 font-semibold text-xs h-10 px-4 rounded-xl cursor-pointer"
