import React, { useState, useMemo } from 'react';
import { Users, Search, Plus, MapPin, Car, Shield, UserCheck, UserX, RefreshCw } from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle } from './ui/card';
import { Button } from './ui/button';
import { Input } from './ui/input';
import { Badge } from './ui/badge';
import { Veiculo, Regional, StatusPresenca, Colaborador } from '../types';
import { cn } from '@/lib/utils';

export interface TeamsManagementProps {
  veiculos?: Veiculo[];
  filtroRegional?: Regional;
  selectedRegional?: Regional;
  onNovaEquipe?: () => void;
}

export const TeamsManagement: React.FC<TeamsManagementProps> = ({
  veiculos = [],
  filtroRegional = 'todas',
  selectedRegional,
  onNovaEquipe,
}) => {
  const [search, setSearch] = useState('');
  const regionalEfetiva = selectedRegional || filtroRegional || 'todas';

  const equipes = useMemo(() => {
    const lista: Array<{
      codigo: string;
      numero: 1 | 2;
      veiculoPrefixo: string;
      veiculoPlaca: string;
      regional: 'ribas' | 'agua_clara';
      membros: Colaborador[];
    }> = [];

    (veiculos || []).forEach((v) => {
      if (!v || !v.assentos) return;

      // Equipe 1
      const eq1Membros = [v.assentos.motorista, v.assentos.frenteDir].filter(Boolean) as Colaborador[];
      lista.push({
        codigo: v.equipe1Codigo || `${v.prefixo}-EQ1`,
        numero: 1,
        veiculoPrefixo: v.prefixo,
        veiculoPlaca: v.placa,
        regional: v.regional,
        membros: eq1Membros,
      });

      // Equipe 2
      const eq2Membros = [v.assentos.trasEsq, v.assentos.trasDir].filter(Boolean) as Colaborador[];
      lista.push({
        codigo: v.equipe2Codigo || `${v.prefixo}-EQ2`,
        numero: 2,
        veiculoPrefixo: v.prefixo,
        veiculoPlaca: v.placa,
        regional: v.regional,
        membros: eq2Membros,
      });
    });

    return lista;
  }, [veiculos]);

  const equipesFiltradas = useMemo(() => {
    return equipes.filter((eq) => {
      const matchRegional = regionalEfetiva === 'todas' || eq.regional === regionalEfetiva;
      const termo = search.toLowerCase();
      if (!termo) return matchRegional;

      const matchCodigo = eq.codigo.toLowerCase().includes(termo);
      const matchCarro = eq.veiculoPrefixo.toLowerCase().includes(termo) || eq.veiculoPlaca.toLowerCase().includes(termo);
      const matchMembro = eq.membros.some((m) => m.nome?.toLowerCase().includes(termo));

      return matchRegional && (matchCodigo || matchCarro || matchMembro);
    });
  }, [equipes, regionalEfetiva, search]);

  return (
    <div className="space-y-6">
      {/* Topo / Filtro e Ação */}
      <div className="flex flex-col sm:flex-row items-center justify-between gap-4">
        <div className="relative w-full sm:max-w-md">
          <Search className="absolute left-3.5 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
          <Input
            placeholder="Buscar por equipe, veículo ou colaborador..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="pl-10"
          />
        </div>

        {onNovaEquipe && (
          <Button onClick={onNovaEquipe} size="sm" className="w-full sm:w-auto gap-2">
            <Plus className="w-4 h-4" />
            Nova Equipe
          </Button>
        )}
      </div>

      {/* Grid de Equipes */}
      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-5">
        {equipesFiltradas.map((eq) => {
          const presentes = eq.membros.filter((m) => m.status === 'presente' || m.status === 'substituto').length;
          const total = eq.membros.length;
          const completa = presentes >= total && total > 0;

          return (
            <Card key={`${eq.veiculoPrefixo}-${eq.codigo}`} className="border-border/70 hover:border-border transition-all">
              <CardHeader className="pb-3 border-b border-border/40">
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-2">
                    <div className="w-8 h-8 rounded-lg bg-primary/10 border border-primary/20 flex items-center justify-center text-primary font-bold text-xs">
                      EQ{eq.numero}
                    </div>
                    <div>
                      <CardTitle className="text-sm font-bold">{eq.codigo}</CardTitle>
                      <p className="text-[11px] text-muted-foreground flex items-center gap-1 mt-0.5">
                        <Car className="w-3 h-3" />
                        {eq.veiculoPrefixo} • {eq.veiculoPlaca}
                      </p>
                    </div>
                  </div>

                  <Badge variant={completa ? 'success' : 'destructive'}>
                    {presentes}/{total} membros
                  </Badge>
                </div>
              </CardHeader>

              <CardContent className="p-4 space-y-3">
                <div className="space-y-2">
                  {eq.membros.map((m) => {
                    const isSubst = m.status === 'substituto' && m.substitutoNome;
                    const nome = isSubst ? m.substitutoNome : m.nome;

                    return (
                      <div
                        key={m.id}
                        className="flex items-center justify-between p-2 rounded-xl bg-muted/30 border border-border/40 text-xs"
                      >
                        <div className="flex items-center gap-2.5">
                          <div className="w-7 h-7 rounded-full overflow-hidden bg-muted border border-border/60 shrink-0">
                            {m.foto ? (
                              <img src={m.foto} alt={nome} className="w-full h-full object-cover" />
                            ) : (
                              <div className="w-full h-full flex items-center justify-center font-bold text-[10px]">
                                {nome?.charAt(0)}
                              </div>
                            )}
                          </div>
                          <div>
                            <p className="font-semibold text-foreground leading-tight">{nome}</p>
                            <p className="text-[10px] text-muted-foreground">{m.cargo}</p>
                          </div>
                        </div>

                        {m.status === 'presente' && (
                          <span className="flex items-center gap-1 text-[10px] font-semibold text-emerald-400">
                            <UserCheck className="w-3 h-3" /> Presente
                          </span>
                        )}
                        {m.status === 'falta' && (
