import React, { useState } from 'react';
import { Navbar } from './components/Navbar';
import { MetricsHeader } from './components/MetricsHeader';
import { VehicleCardGrid } from './components/VehicleCardGrid';
import { TeamsManagement } from './components/TeamsManagement';
import { CollaboratorsManagement, ColaboradorCompleto } from './components/CollaboratorsManagement';
import { ExportReports } from './components/ExportReports';
import { NewTeamModal } from './components/NewTeamModal';
import { VEICULOS_INICIAIS, COLABORADORES_RESERVA } from './data/mockData';
import { Veiculo, Colaborador, Regional, StatusPresenca, MotivoFalta } from './types';

export function App() {
  const [activeTab, setActiveTab] = useState<'veiculos' | 'equipes' | 'colaboradores' | 'relatorios'>('veiculos');
  const [selectedRegional, setSelectedRegional] = useState<Regional>('todas');
  const [selectedDate, setSelectedDate] = useState<Date>(new Date());
  const [isNewTeamModalOpen, setIsNewTeamModalOpen] = useState(false);

  const [veiculos, setVeiculos] = useState<Veiculo[]>(VEICULOS_INICIAIS);
  const [colaboradoresReserva, setColaboradoresReserva] = useState<Colaborador[]>(COLABORADORES_RESERVA);

  // Atualiza a presença/falta/substituto de um assento
  const handleUpdateStatus = (
    veiculoId: string,
    colaboradorId: string,
    novoStatus: StatusPresenca,
    motivoFalta?: MotivoFalta,
    substituto?: Colaborador
  ) => {
    setVeiculos((prev) =>
      prev.map((v) => {
        if (v.id !== veiculoId) return v;

        const atualizarAssento = (c: Colaborador): Colaborador => {
          if (c.id !== colaboradorId) return c;

          return {
            ...c,
            status: novoStatus,
            motivoFalta: novoStatus === 'falta' ? motivoFalta : undefined,
            substitutoId: novoStatus === 'substituto' && substituto ? substituto.id : undefined,
            substitutoNome: novoStatus === 'substituto' && substituto ? substituto.nome : undefined,
          };
        };

        return {
          ...v,
          assentos: {
            motorista: atualizarAssento(v.assentos.motorista),
            frenteDir: atualizarAssento(v.assentos.frenteDir),
            trasEsq: atualizarAssento(v.assentos.trasEsq),
            trasDir: atualizarAssento(v.assentos.trasDir),
          },
        };
      })
    );
  };

  // Criação de nova equipe / veículo
  const handleCreateTeam = (novoVeiculo: Veiculo) => {
    setVeiculos((prev) => [novoVeiculo, ...prev]);
    setIsNewTeamModalOpen(false);
  };

  // Importação em massa de colaboradores vindos da aba Colaboradores
  const handleImportarColaboradores = (novosColaboradores: ColaboradorCompleto[]) => {
    const convertidosParaReserva: Colaborador[] = novosColaboradores.map((c) => ({
      id: c.id,
      nome: c.nome,
      cargo: c.cargo,
      matricula: c.matricula,
      foto: c.foto,
      telefone: c.telefone,
      status: c.status,
      equipeId: 'reserva',
      equipeNumero: 1,
      posicaoVeiculo: 'motorista',
    }));

    setColaboradoresReserva((prev) => [...convertidosParaReserva, ...prev]);
  };

  // Cadastro manual de colaborador
  const handleAdicionarColaborador = (novoColab: ColaboradorCompleto) => {
    const convertidoParaReserva: Colaborador = {
      id: novoColab.id,
      nome: novoColab.nome,
      cargo: novoColab.cargo,
      matricula: novoColab.matricula,
      foto: novoColab.foto,
      telefone: novoColab.telefone,
      status: novoColab.status,
      equipeId: 'reserva',
      equipeNumero: 1,
      posicaoVeiculo: 'motorista',
    };

    setColaboradoresReserva((prev) => [convertidoParaReserva, ...prev]);
  };

  return (
    <div className="min-h-screen bg-background text-foreground flex flex-col selection:bg-primary/30 selection:text-primary">
      {/* Barra de Navegação Superior */}
      <Navbar
        activeTab={activeTab}
        onTabChange={setActiveTab}
        selectedRegional={selectedRegional}
        onRegionalChange={setSelectedRegional}
        selectedDate={selectedDate}
        onDateChange={setSelectedDate}
        onOpenNewTeamModal={() => setIsNewTeamModalOpen(true)}
      />

      {/* Conteúdo Principal */}
      <main className="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-6 space-y-6">
        {/* Cabeçalho de Métricas */}
        <MetricsHeader
          veiculos={veiculos}
          selectedRegional={selectedRegional}
          selectedDate={selectedDate}
        />

        {/* Visualização por Abas */}
        {activeTab === 'veiculos' && (
          <VehicleCardGrid
            veiculos={veiculos}
            selectedRegional={selectedRegional}
            onUpdateStatus={handleUpdateStatus}
            colaboradoresReserva={colaboradoresReserva}
            onOpenNewTeamModal={() => setIsNewTeamModalOpen(true)}
          />
        )}

        {activeTab === 'equipes' && (
          <TeamsManagement
            veiculos={veiculos}
            selectedRegional={selectedRegional}
            onOpenNewTeamModal={() => setIsNewTeamModalOpen(true)}
          />
        )}

        {activeTab === 'colaboradores' && (
          <CollaboratorsManagement
            veiculos={veiculos}
            colaboradoresReserva={colaboradoresReserva}
            onImportarColaboradores={handleImportarColaboradores}
            onAdicionarColaborador={handleAdicionarColaborador}
          />
        )}

        {activeTab === 'relatorios' && (
          <ExportReports
            veiculos={veiculos}
            selectedRegional={selectedRegional}
            selectedDate={selectedDate}
            colaboradoresReserva={colaboradoresReserva}
          />
        )}
      </main>

      {/* Modal de Criação de Nova Equipe */}
      <NewTeamModal
        isOpen={isNewTeamModalOpen}
        onClose={() => setIsNewTeamModalOpen(false)}
        onSave={handleCreateTeam}
        colaboradoresReserva={colaboradoresReserva}
      />
    </div>
  );
}

export default App;

