import React from 'react';
import {
  Car,
  Calendar,
  Layers,
  MapPin,
  Users,
  FileSpreadsheet,
} from 'lucide-react';
import { Regional } from '../types';
import { Badge } from './ui/badge';
import { cn } from '@/lib/utils';

export interface NavbarProps {
  activeTab?: 'veiculos' | 'equipes' | 'colaboradores' | 'relatorios';
  onTabChange?: (tab: 'veiculos' | 'equipes' | 'colaboradores' | 'relatorios') => void;
  selectedRegional?: Regional;
  onRegionalChange?: (regional: Regional) => void;
  selectedDate?: Date;
  onDateChange?: (date: Date) => void;
  onOpenNewTeamModal?: () => void;
  onNewTeamClick?: () => void;
  totalVeiculos?: number;
  taxaPresenca?: number;
}

export const Navbar: React.FC<NavbarProps> = ({
  activeTab = 'veiculos',
  onTabChange,
  selectedRegional = 'todas',
  onRegionalChange,
  selectedDate = new Date(),
  onDateChange,
}) => {
  const tabs = [
    { id: 'veiculos' as const, label: 'Veículos & Assentos', icon: Car },
    { id: 'equipes' as const, label: 'Composição de Equipes', icon: Layers },
    { id: 'colaboradores' as const, label: 'Colaboradores', icon: Users },
    { id: 'relatorios' as const, label: 'Relatórios & Histórico', icon: FileSpreadsheet },
  ];

  const formatDateInputValue = (date: Date) => {
    if (!(date instanceof Date) || isNaN(date.getTime())) {
      return new Date().toISOString().split('T')[0];
    }
    return date.toISOString().split('T')[0];
  };

  const handleDateInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = e.target.value;
    if (value) {
      const [year, month, day] = value.split('-').map(Number);
      const newDate = new Date(year, month - 1, day);
      onDateChange?.(newDate);
    }
  };

  const handleTabClick = (tabId: 'veiculos' | 'equipes' | 'colaboradores' | 'relatorios') => {
    if (typeof onTabChange === 'function') {
      onTabChange(tabId);
    }
  };

  return (
    <header className="sticky top-0 z-40 w-full border-b border-border/80 bg-background/95 backdrop-blur supports-[backdrop-filter]:bg-background/80 transition-colors">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex items-center justify-between h-16 sm:h-20 gap-4">
          {/* Logo e Identificação */}
          <div className="flex items-center gap-3 shrink-0">
            <div className="w-10 h-10 sm:w-11 sm:h-11 rounded-2xl bg-gradient-to-tr from-emerald-600 via-emerald-500 to-teal-400 flex items-center justify-center shadow-lg shadow-emerald-500/20 text-white ring-2 ring-emerald-500/30">
              <Car className="w-5 h-5 sm:w-6 sm:h-6" />
            </div>
            <div>
              <div className="flex items-center gap-2">
                <h1 className="text-base sm:text-lg font-black tracking-tight text-foreground">
                  Controle de Faltas
                </h1>
                <Badge variant="outline" className="hidden sm:inline-flex border-emerald-500/30 text-emerald-400 bg-emerald-500/10 text-[10px] font-semibold px-2 py-0.5">
                  Operação Florestal
                </Badge>
              </div>
              <p className="text-xs text-muted-foreground hidden sm:block">
                Gestão de Lotação, Presença e Escalas
              </p>
            </div>
          </div>

          {/* Navegação Principal (Tabs Centrais) */}
          <nav className="hidden md:flex items-center p-1 rounded-xl bg-muted/40 border border-border/60">
            {tabs.map((tab) => {
              const Icon = tab.icon;
              const isActive = activeTab === tab.id;
              return (
                <button
                  key={tab.id}
                  type="button"
                  onClick={() => handleTabClick(tab.id)}
                  className={cn(
                    'flex items-center gap-2 px-3.5 py-2 rounded-lg text-xs font-semibold transition-all cursor-pointer select-none',
                    isActive
                      ? 'bg-card text-foreground shadow-sm border border-border/60 text-primary font-bold'
                      : 'text-muted-foreground hover:text-foreground hover:bg-muted/60'
                  )}
                >
                  <Icon className={cn('w-4 h-4', isActive ? 'text-primary' : 'text-muted-foreground')} />
                  {tab.label}
                </button>
              );
            })}
          </nav>

          {/* Filtros e Seletores da Direita */}
          <div className="flex items-center gap-2 sm:gap-3">
            {/* Seletor de Regional */}
            <div className="flex items-center p-1 rounded-xl bg-muted/40 border border-border/60">
              <div className="flex items-center gap-1.5 px-2 text-xs text-muted-foreground">
                <MapPin className="w-3.5 h-3.5 text-emerald-400" />
                <span className="hidden xl:inline">Unidade:</span>
              </div>
              <select
                value={selectedRegional}
                onChange={(e) => onRegionalChange?.(e.target.value as Regional)}
                aria-label="Selecionar Unidade Regional"
                className="h-7 text-xs bg-transparent border-0 rounded-lg text-foreground font-semibold px-2 py-0 focus:outline-none focus:ring-1 focus:ring-primary cursor-pointer"
              >
                <option value="todas" className="bg-card text-foreground">Todas as Unidades</option>
                <option value="ribas" className="bg-card text-foreground">Ribas do Rio Pardo</option>
                <option value="agua_clara" className="bg-card text-foreground">Água Clara</option>
              </select>
            </div>

            {/* Seletor de Data */}
            <div className="flex items-center p-1 rounded-xl bg-muted/40 border border-border/60">
              <div className="flex items-center gap-1.5 px-2 text-xs text-muted-foreground">
                <Calendar className="w-3.5 h-3.5 text-primary" />
                <span className="hidden xl:inline">Data:</span>
              </div>
              <input
                type="date"
                value={formatDateInputValue(selectedDate)}
                onChange={handleDateInputChange}
                aria-label="Selecionar Data da Operação"
                className="h-7 text-xs bg-transparent border-0 rounded-lg text-foreground font-semibold px-1.5 py-0 focus:outline-none focus:ring-1 focus:ring-primary cursor-pointer"
              />
            </div>
          </div>
        </div>

        {/* Barra de Navegação Mobile */}
        <div className="flex md:hidden items-center justify-between overflow-x-auto py-2.5 border-t border-border/40 gap-1 scrollbar-none">
          {tabs.map((tab) => {
            const Icon = tab.icon;
            const isActive = activeTab === tab.id;
            return (
              <button
                key={tab.id}
                type="button"
                onClick={() => handleTabClick(tab.id)}
                className={cn(
                  'flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-semibold whitespace-nowrap transition-all shrink-0 cursor-pointer',
