                </h1>
              </div>
            </div>

            {/* Divisor vertical sutil */}
            <div className="hidden md:block h-8 w-px bg-border/80" />

            {/* SELETOR DE UNIDADES REFINADO / PREMIUM */}
            <div className="relative" ref={dropdownRef}>
              {/* Botão Gatilho do Seletor de Unidades */}
              <button
                type="button"
                onClick={() => setDropdownOpen(!dropdownOpen)}
                className={cn(
                  'group relative flex items-center gap-2.5 px-3.5 py-2 rounded-2xl border transition-all duration-200 cursor-pointer text-left',
                  'bg-gradient-to-r from-muted/60 via-muted/40 to-muted/60 hover:bg-muted/80',
                  'hover:shadow-md hover:border-primary/40 focus:outline-none focus:ring-2 focus:ring-primary/30',
                  dropdownOpen ? 'border-primary shadow-lg shadow-primary/10 ring-2 ring-primary/20' : 'border-border/80'
                )}
                title="Trocar Unidade Operacional"
              >
                {/* Indicador luminoso pulsante */}
                <div className="relative flex items-center justify-center shrink-0">
                  <span className={cn('w-2.5 h-2.5 rounded-full transition-all duration-300', currentRegionalConfig.dotColor)} />
                  <span
                    className={cn(
                      'absolute w-4 h-4 rounded-full opacity-40 animate-ping pointer-events-none',
                      currentRegionalConfig.dotColor
                    )}
                  />
                </div>

                {/* Textos da Unidade */}
                <div className="flex flex-col">
                  <span className="text-[10px] uppercase font-bold text-muted-foreground tracking-wider leading-none flex items-center gap-1">
                    <MapPin className="w-2.5 h-2.5 text-primary" />
                    Unidade Operacional
                  </span>
                  <div className="flex items-center gap-1.5 mt-0.5">
                    <span className="text-xs sm:text-sm font-black text-foreground tracking-tight group-hover:text-primary transition-colors whitespace-nowrap">
                      {currentRegionalConfig.label}
                    </span>
                    <span className="text-[10px] font-semibold px-1.5 py-0.2 rounded-md bg-background/80 border border-border/60 text-muted-foreground">
                      {currentRegionalConfig.badge}
                    </span>
                  </div>
                </div>

                {/* Seta seletora animada */}
                <ChevronDown
                  className={cn(
                    'w-4 h-4 text-muted-foreground transition-transform duration-200 ml-1 shrink-0 group-hover:text-foreground',
                    dropdownOpen && 'rotate-180 text-primary'
                  )}
                />
              </button>

              {/* Menu Dropdown de Seleção de Unidades */}
              {dropdownOpen && (
                <div className="absolute left-0 top-full mt-2 w-72 sm:w-80 p-2 rounded-2xl bg-card/95 backdrop-blur-2xl border border-border shadow-2xl shadow-black/40 z-50 animate-in fade-in zoom-in-95 duration-150">
                  <div className="px-3 py-2 border-b border-border/50 mb-1.5 flex items-center justify-between">
                    <div className="flex items-center gap-1.5 text-xs font-bold text-muted-foreground uppercase tracking-wider">
                      <Compass className="w-3.5 h-3.5 text-primary" />
                      Filtrar por Unidade
                    </div>
                    <span className="text-[11px] text-muted-foreground">3 opções</span>
                  </div>

                  <div className="space-y-1">
                    {REGIONAIS.map((regional) => {
                      const isSelected = selectedRegional === regional.id;
                      return (
                        <button
                          key={regional.id}
                          type="button"
                          onClick={() => handleSelectUnit(regional.id)}
                          className={cn(
                            'w-full flex items-center justify-between p-2.5 rounded-xl text-left transition-all duration-150 cursor-pointer group',
                            isSelected
                              ? regional.bgActive + ' border'
                              : 'hover:bg-muted/60 text-foreground/80 hover:text-foreground border border-transparent'
                          )}
                        >
                          <div className="flex items-center gap-3 min-w-0">
                            <div
                              className={cn(
                                'w-8 h-8 rounded-xl flex items-center justify-center shrink-0 transition-colors border',
                                isSelected
                                  ? 'bg-card border-border/60 shadow-sm'
                                  : 'bg-muted/80 border-border/40 group-hover:bg-card'
                              )}
                            >
                              {regional.id === 'todas' ? (
                                <Building2 className={cn('w-4 h-4', isSelected ? regional.accentColor : 'text-muted-foreground')} />
                              ) : (
                                <MapPin className={cn('w-4 h-4', isSelected ? regional.accentColor : 'text-muted-foreground')} />
                              )}
                            </div>

                            <div className="min-w-0">
                              <div className="flex items-center gap-1.5">
                                <p className="font-bold text-xs sm:text-sm truncate">
                                  {regional.label}
