  // Modal de Presença
  const [modalPresenca, setModalPresenca] = useState<{
    aberto: boolean;
    colaborador?: Colaborador;
    veiculoId?: string;
  }>({ aberto: false });

  // Modal de Nova Equipe
  const [isNewTeamModalOpen, setIsNewTeamModalOpen] = useState(false);

  // Veículos filtrados por Regional
  const veiculosFiltrados = useMemo(() => {
    return veiculos.filter((v) => {
      if (selectedRegional === 'todas') return true;
      return v.regional === selectedRegional;
    });
  }, [veiculos, selectedRegional]);

  // Atualizar status de presença de um colaborador dentro de um veículo
  const handleSaveAttendance = (
    veiculoId: string,
    colaboradorId: string,
    novoStatus: StatusPresenca,
    motivoFalta?: MotivoFalta,
    substituto?: Colaborador
  ) => {
    setVeiculos((prev) =>
      prev.map((v) => {
        if (v.id !== veiculoId) return v;

        const assentos = { ...v.assentos };
        const keys: Array<keyof typeof assentos> = ['motorista', 'frenteDir', 'trasEsq', 'trasDir'];

        keys.forEach((k) => {
          if (assentos[k] && assentos[k].id === colaboradorId) {
            assentos[k] = {
              ...assentos[k],
              status: novoStatus,
              motivoFalta: novoStatus === 'falta' ? motivoFalta : undefined,
              substitutoId: novoStatus === 'substituto' ? substituto?.id : undefined,
              substitutoNome: novoStatus === 'substituto' ? substituto?.nome : undefined,
            };
          }
        });

        return { ...v, assentos };
      })
    );

    setModalPresenca({ aberto: false });
  };

  // Abrir Modal de Presença ao clicar num colaborador no card
  const handleOpenAttendance = (colaborador: Colaborador, veiculoId: string) => {
    setModalPresenca({
      aberto: true,
      colaborador,
      veiculoId,
    });
  };

  // Criação de nova equipe / veículo
  const handleCreateTeam = (novoVeiculo: Partial<Veiculo>) => {
    const veiculoCompleto: Veiculo = {
      id: `vtr-${Date.now()}`,
      prefixo: novoVeiculo.prefixo || 'CARRO NOVO',
      placa: novoVeiculo.placa || 'BRA-0000',
      modelo: novoVeiculo.modelo || 'Caminhonete 4x4',
      ano: novoVeiculo.ano || 2024,
      regional: novoVeiculo.regional || (selectedRegional === 'todas' ? 'ribas' : selectedRegional),
      statusOperacional: novoVeiculo.statusOperacional || 'ativo',
      equipe1Codigo: novoVeiculo.equipe1Codigo || `EQ-${Math.floor(100 + Math.random() * 900)}A`,
      equipe2Codigo: novoVeiculo.equipe2Codigo || `EQ-${Math.floor(100 + Math.random() * 900)}B`,
      assentos: novoVeiculo.assentos || {
        motorista: {
          id: `col-${Date.now()}-1`,
          nome: 'Motorista Cadastrado',
          cargo: 'Motorista Operacional',
          matricula: `MAT-${Math.floor(1000 + Math.random() * 9000)}`,
          foto: 'https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?w=150&auto=format&fit=crop&q=80',
          telefone: '(67) 99999-0001',
          status: 'presente',
          equipeId: 'nova-eq1',
          equipeNumero: 1,
          posicaoVeiculo: 'motorista',
        },
        frenteDir: {
          id: `col-${Date.now()}-2`,
          nome: 'Ajudante Operacional',
          cargo: 'Ajudante Geral',
          matricula: `MAT-${Math.floor(1000 + Math.random() * 9000)}`,
          foto: 'https://images.unsplash.com/photo-1570295999919-56ceb5ecca61?w=150&auto=format&fit=crop&q=80',
          telefone: '(67) 99999-0002',
          status: 'presente',
          equipeId: 'nova-eq1',
          equipeNumero: 1,
          posicaoVeiculo: 'frente_dir',
        },
        trasEsq: {
          id: `col-${Date.now()}-3`,
          nome: 'Técnico de Campo',
          cargo: 'Técnico Florestal',
          matricula: `MAT-${Math.floor(1000 + Math.random() * 9000)}`,
          foto: 'https://images.unsplash.com/photo-1527980965255-d3b416303d12?w=150&auto=format&fit=crop&q=80',
          telefone: '(67) 99999-0003',
          status: 'presente',
          equipeId: 'nova-eq2',
          equipeNumero: 2,
          posicaoVeiculo: 'tras_esq',
        },
        trasDir: {
          id: `col-${Date.now()}-4`,
          nome: 'Operador Florestal',
          cargo: 'Operador',
          matricula: `MAT-${Math.floor(1000 + Math.random() * 9000)}`,
          foto: 'https://images.unsplash.com/photo-1580489944761-15a19d654956?w=150&auto=format&fit=crop&q=80',
          telefone: '(67) 99999-0004',
          status: 'presente',
          equipeId: 'nova-eq2',
          equipeNumero: 2,
          posicaoVeiculo: 'tras_dir',
        },
      },
    };

    setVeiculos((prev) => [veiculoCompleto, ...prev]);
    setIsNewTeamModalOpen(false);
  };

  // Importar colaboradores
  const handleImportarColaboradores = (novosColabs: ColaboradorCompleto[]) => {
    const novosReserva: Colaborador[] = novosColabs.map((c, index) => ({
      id: c.id || `imp-${Date.now()}-${index}`,
      nome: c.nome,
      cargo: c.cargo,
      matricula: c.matricula || `MAT-${1000 + index}`,
      foto: c.foto || `https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=150&auto=format&fit=crop&q=80`,
      telefone: c.telefone || '(67) 99999-9999',
      status: c.status || 'presente',
      equipeId: 'reserva',
      equipeNumero: 1,
      posicaoVeiculo: 'motorista',
    }));

    setColaboradoresReserva((prev) => [...novosReserva, ...prev]);
  };

  // Adicionar colaborador avulso
  const handleAdicionarColaborador = (novoColab: ColaboradorCompleto) => {
    const novo: Colaborador = {
      id: novoColab.id,
      nome: novoColab.nome,
      cargo: novoColab.cargo,
      matricula: novoColab.matricula,
      foto: novoColab.foto,
      telefone: novoColab.telefone,
      status: novoColab.status,
      equipeId: 'reserva',
      equipeNumero: 1,
      posicaoVeiculo: 'motorista',
    };
    setColaboradoresReserva((prev) => [novo, ...prev]);
  };

  return (
    <div className="min-h-screen bg-background text-foreground flex flex-col antialiased">
      {/* Navbar Superior com Seletor de Unidades Refinado */}
      <Navbar
        selectedRegional={selectedRegional}
        onSelectRegional={setSelectedRegional}
        selectedDate={selectedDate}
        onDateChange={setSelectedDate}
        activeTab={activeTab}
        onTabChange={setActiveTab}
        onOpenNewTeamModal={() => setIsNewTeamModalOpen(true)}
      />

      {/* Conteúdo Principal */}
      <main className="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-6 space-y-6">
        {/* Painel de Métricas Gerais */}
        <MetricsHeader
          veiculos={veiculosFiltrados}
          selectedRegional={selectedRegional}
          selectedDate={selectedDate}
        />

        {/* Renderização Condicional por Aba Ativa */}
        {activeTab === 'veiculos' && (
          <VehicleCardGrid
            veiculos={veiculosFiltrados}
            selectedRegional={selectedRegional}
            onOpenAttendance={handleOpenAttendance}
            onOpenNewTeamModal={() => setIsNewTeamModalOpen(true)}
          />
        )}

        {activeTab === 'equipes' && (
          <TeamsManagement
            veiculos={veiculosFiltrados}
            selectedRegional={selectedRegional}
            onOpenNewTeamModal={() => setIsNewTeamModalOpen(true)}
          />
        )}

        {activeTab === 'colaboradores' && (
          <CollaboratorsManagement
            veiculos={veiculosFiltrados}
            colaboradoresReserva={colaboradoresReserva}
            onImportarColaboradores={handleImportarColaboradores}
            onAdicionarColaborador={handleAdicionarColaborador}
          />
        )}

        {activeTab === 'relatorios' && (
          <ExportReports
            veiculos={veiculosFiltrados}
            colaboradoresReserva={colaboradoresReserva}
            selectedRegional={selectedRegional}
            selectedDate={selectedDate}
          />
        )}
      </main>

      {/* Modal de Presença e Registro de Falta / Substituto */}
      {modalPresenca.aberto && modalPresenca.colaborador && modalPresenca.veiculoId && (
        <AttendanceModal
          colaborador={modalPresenca.colaborador}
          veiculoId={modalPresenca.veiculoId}
          onClose={() => setModalPresenca({ aberto: false })}
          onSave={handleSaveAttendance}
          colaboradoresReserva={colaboradoresReserva}
        />
      )}

      {/* Modal de Nova Equipe */}
      <NewTeamModal
        isOpen={isNewTeamModalOpen}
        onClose={() => setIsNewTeamModalOpen(false)}
        onCreateTeam={handleCreateTeam}
        defaultRegional={selectedRegional === 'todas' ? 'ribas' : selectedRegional}
      />
    </div>
  );
}

export default App;

