import React, { useState, useRef, useEffect } from 'react';
import {
  Car,
  Calendar,
  Layers,
  MapPin,
  Users,
  FileSpreadsheet,
  Check,
  ChevronDown,
  Building2,
  Sparkles,
  Compass
} from 'lucide-react';
import { Regional } from '../types';
import { cn } from '@/lib/utils';

export interface NavbarProps {
  selectedRegional: Regional;
  onSelectRegional: (regional: Regional) => void;
  selectedDate: Date;
  onDateChange: (date: Date) => void;
  activeTab?: 'veiculos' | 'equipes' | 'colaboradores' | 'relatorios';
  onTabChange?: (tab: 'veiculos' | 'equipes' | 'colaboradores' | 'relatorios') => void;
  onOpenNewTeamModal?: () => void;
}

const REGIONAIS: Array<{
  id: Regional;
  label: string;
  shortLabel: string;
  badge: string;
  accentColor: string;
  bgActive: string;
  borderActive: string;
  dotColor: string;
  description: string;
}> = [
  {
    id: 'todas',
    label: 'Todas as Unidades',
    shortLabel: 'Todas',
    badge: 'Visão Geral',
    accentColor: 'text-indigo-400',
    bgActive: 'bg-indigo-500/20 text-indigo-200 border-indigo-500/50 shadow-indigo-500/10',
    borderActive: 'border-indigo-500/50',
    dotColor: 'bg-indigo-400 shadow-[0_0_8px_rgba(129,140,248,0.8)]',
    description: 'Painel integrado de todas as frentes operacionais',
  },
  {
    id: 'ribas',
    label: 'Ribas do Rio Pardo',
    shortLabel: 'Ribas',
    badge: 'MS',
    accentColor: 'text-emerald-400',
    bgActive: 'bg-emerald-500/20 text-emerald-200 border-emerald-500/50 shadow-emerald-500/10',
    borderActive: 'border-emerald-500/50',
    dotColor: 'bg-emerald-400 shadow-[0_0_8px_rgba(52,211,153,0.8)]',
    description: 'Polo Florestal Ribas do Rio Pardo',
  },
  {
    id: 'agua_clara',
    label: 'Água Clara',
    shortLabel: 'Água Clara',
    badge: 'MS',
    accentColor: 'text-sky-400',
    bgActive: 'bg-sky-500/20 text-sky-200 border-sky-500/50 shadow-sky-500/10',
    borderActive: 'border-sky-500/50',
    dotColor: 'bg-sky-400 shadow-[0_0_8px_rgba(56,189,248,0.8)]',
    description: 'Polo Operacional Água Clara',
  },
];

export const Navbar: React.FC<NavbarProps> = ({
  selectedRegional = 'todas',
  onSelectRegional,
  selectedDate = new Date(),
  onDateChange,
  activeTab = 'veiculos',
  onTabChange,
}) => {
  const [dropdownOpen, setDropdownOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  // Fecha o dropdown ao clicar fora
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setDropdownOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const currentRegionalConfig = REGIONAIS.find((r) => r.id === selectedRegional) || REGIONAIS[0];

  const handleSelectUnit = (id: Regional) => {
    onSelectRegional?.(id);
    setDropdownOpen(false);
  };

  const navTabs = [
    { id: 'veiculos', label: 'Veículos & Turmas', icon: Car },
    { id: 'equipes', label: 'Equipes', icon: Layers },
    { id: 'colaboradores', label: 'Colaboradores', icon: Users },
    { id: 'relatorios', label: 'Relatórios & Histórico', icon: FileSpreadsheet },
  ] as const;

  const formattedDate =
    selectedDate instanceof Date && !isNaN(selectedDate.getTime())
      ? selectedDate.toISOString().split('T')[0]
      : new Date().toISOString().split('T')[0];

  return (
    <header className="sticky top-0 z-40 w-full border-b border-border/60 bg-card/85 backdrop-blur-xl shadow-lg transition-all">
      {/* Barra Principal */}
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex items-center justify-between h-20 gap-4">
          {/* Lado Esquerdo: Logo, Título do Sistema e SELETOR DE UNIDADES PREMIUM */}
          <div className="flex items-center gap-3 sm:gap-5 min-w-0">
            {/* Ícone e Marca */}
            <div className="flex items-center gap-3 shrink-0">
              <div className="w-11 h-11 rounded-2xl bg-gradient-to-br from-primary via-primary/80 to-emerald-500 flex items-center justify-center shadow-lg shadow-primary/25 ring-2 ring-primary/20 transition-transform hover:scale-105">
                <Car className="w-6 h-6 text-white" />
              </div>
              <div className="hidden sm:block">
                <div className="flex items-center gap-1.5">
                  <span className="text-xs font-semibold tracking-wider text-primary uppercase">
                    Gestão Operacional
                  </span>
                  <span className="w-1 h-1 rounded-full bg-primary/60" />
                  <span className="text-[10px] font-medium text-muted-foreground">v2.4</span>
                </div>
                <h1 className="text-xl font-black tracking-tight text-foreground leading-none mt-0.5">
                  Controle de Faltas
                </h1>
              </div>
            </div>

            {/* Divisor vertical sutil */}
            <div className="hidden md:block h-8 w-px bg-border/80" />

            {/* SELETOR DE UNIDADES REFINADO / PREMIUM */}
            <div className="relative" ref={dropdownRef}>
              {/* Botão Gatilho do Seletor de Unidades */}
              <button
                type="button"
                onClick={() => setDropdownOpen(!dropdownOpen)}
                className={cn(
                  'group relative flex items-center gap-2.5 px-3.5 py-2 rounded-2xl border transition-all duration-200 cursor-pointer text-left',
                  'bg-gradient-to-r from-muted/60 via-muted/40 to-muted/60 hover:bg-muted/80',
                  'hover:shadow-md hover:border-primary/40 focus:outline-none focus:ring-2 focus:ring-primary/30',
                  dropdownOpen ? 'border-primary shadow-lg shadow-primary/10 ring-2 ring-primary/20' : 'border-border/80'
                )}
                title="Trocar Unidade Operacional"
              >
                {/* Indicador luminoso pulsante */}
                <div className="relative flex items-center justify-center shrink-0">
                  <span className={cn('w-2.5 h-2.5 rounded-full transition-all duration-300', currentRegionalConfig.dotColor)} />
                  <span
                    className={cn(
                      'absolute w-4 h-4 rounded-full opacity-40 animate-ping pointer-events-none',
                      currentRegionalConfig.dotColor
                    )}
                  />
                </div>

                {/* Textos da Unidade */}
                <div className="flex flex-col">
                  <span className="text-[10px] uppercase font-bold text-muted-foreground tracking-wider leading-none flex items-center gap-1">
                    <MapPin className="w-2.5 h-2.5 text-primary" />
                    Unidade Operacional
                  </span>
                  <div className="flex items-center gap-1.5 mt-0.5">
                    <span className="text-xs sm:text-sm font-black text-foreground tracking-tight group-hover:text-primary transition-colors whitespace-nowrap">
                      {currentRegionalConfig.label}
                    </span>
                    <span className="text-[10px] font-semibold px-1.5 py-0.2 rounded-md bg-background/80 border border-border/60 text-muted-foreground">
                      {currentRegionalConfig.badge}
                    </span>
                  </div>
                </div>

                {/* Seta seletora animada */}
                <ChevronDown
                  className={cn(
                    'w-4 h-4 text-muted-foreground transition-transform duration-200 ml-1 shrink-0 group-hover:text-foreground',
                    dropdownOpen && 'rotate-180 text-primary'
                  )}
                />
              </button>

              {/* Menu Dropdown de Seleção de Unidades */}
              {dropdownOpen && (
                <div className="absolute left-0 top-full mt-2 w-72 sm:w-80 p-2 rounded-2xl bg-card/95 backdrop-blur-2xl border border-border shadow-2xl shadow-black/40 z-50 animate-in fade-in zoom-in-95 duration-150">
                  <div className="px-3 py-2 border-b border-border/50 mb-1.5 flex items-center justify-between">
                    <div className="flex items-center gap-1.5 text-xs font-bold text-muted-foreground uppercase tracking-wider">
                      <Compass className="w-3.5 h-3.5 text-primary" />
                      Filtrar por Unidade
                    </div>
                    <span className="text-[11px] text-muted-foreground">3 opções</span>
                  </div>

                  <div className="space-y-1">
                    {REGIONAIS.map((regional) => {
                      const isSelected = selectedRegional === regional.id;
                      return (
                        <button
                          key={regional.id}
                          type="button"
                          onClick={() => handleSelectUnit(regional.id)}
                          className={cn(
                            'w-full flex items-center justify-between p-2.5 rounded-xl text-left transition-all duration-150 cursor-pointer group',
                            isSelected
                              ? regional.bgActive + ' border'
                              : 'hover:bg-muted/60 text-foreground/80 hover:text-foreground border border-transparent'
                          )}
                        >
                          <div className="flex items-center gap-3 min-w-0">
                            <div
                              className={cn(
                                'w-8 h-8 rounded-xl flex items-center justify-center shrink-0 transition-colors border',
                                isSelected
                                  ? 'bg-card border-border/60 shadow-sm'
                                  : 'bg-muted/80 border-border/40 group-hover:bg-card'
                              )}
                            >
                              {regional.id === 'todas' ? (
                                <Building2 className={cn('w-4 h-4', isSelected ? regional.accentColor : 'text-muted-foreground')} />
                              ) : (
                                <MapPin className={cn('w-4 h-4', isSelected ? regional.accentColor : 'text-muted-foreground')} />
                              )}
                            </div>

                            <div className="min-w-0">
                              <div className="flex items-center gap-1.5">
                                <p className="font-bold text-xs sm:text-sm truncate">
                                  {regional.label}
                                </p>
                                <span className="text-[9px] px-1.5 py-0.2 rounded font-bold bg-muted border border-border/50 text-muted-foreground uppercase">
                                  {regional.badge}
                                </span>
                              </div>
                              <p className="text-[11px] text-muted-foreground truncate">
                                {regional.description}
                              </p>
                            </div>
                          </div>

                          {isSelected ? (
                            <div className="w-5 h-5 rounded-full bg-primary/20 border border-primary/40 flex items-center justify-center shrink-0 ml-2">
                              <Check className="w-3 h-3 text-primary" />
                            </div>
                          ) : (
                            <div className="w-2 h-2 rounded-full bg-border group-hover:bg-primary/50 transition-colors shrink-0 ml-2" />
                          )}
                        </button>
                      );
                    })}
                  </div>

                  {/* Rodapé informativo do dropdown */}
                  <div className="mt-2 pt-2 border-t border-border/50 px-3 py-1.5 flex items-center justify-between text-[11px] text-muted-foreground">
                    <span className="flex items-center gap-1">
                      <Sparkles className="w-3 h-3 text-amber-400" />
                      Filtro dinâmico instantâneo
                    </span>
                    <span className="font-medium text-foreground">{currentRegionalConfig.shortLabel} ativo</span>
                  </div>
                </div>
              )}
            </div>
          </div>

          {/* Lado Direito: Seletor de Data & Atendimentos */}
          <div className="flex items-center gap-2 sm:gap-3">
            {/* Seletor de Data */}
            <div className="relative flex items-center">
              <div className="flex items-center gap-2 px-3 py-2 bg-muted/40 border border-border/80 rounded-2xl hover:border-primary/40 transition-all shadow-sm">
                <Calendar className="w-4 h-4 text-primary shrink-0" />
                <input
                  type="date"
                  value={formattedDate}
                  onChange={(e) => {
                    if (e.target.value) {
                      const [ano, mes, dia] = e.target.value.split('-').map(Number);
                      onDateChange?.(new Date(ano, mes - 1, dia));
                    }
                  }}
                  className="bg-transparent text-xs sm:text-sm font-semibold text-foreground focus:outline-none cursor-pointer"
                />
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Barra de Navegação das Abas Principais */}
      <div className="border-t border-border/40 bg-card/40">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <nav className="flex items-center gap-1 sm:gap-2 overflow-x-auto py-2.5 no-scrollbar">
            {navTabs.map(({ id, label, icon: Icon }) => {
              const isActive = activeTab === id;
              return (
                <button
                  key={id}
                  type="button"
                  onClick={() => onTabChange?.(id)}
                  className={cn(
                    'flex items-center gap-2 px-3.5 py-2 rounded-xl text-xs sm:text-sm font-bold transition-all whitespace-nowrap cursor-pointer',
                    isActive
                      ? 'bg-primary text-primary-foreground shadow-md shadow-primary/20 scale-[1.01]'
                      : 'text-muted-foreground hover:text-foreground hover:bg-muted/60'
                  )}
                >
                  <Icon className={cn('w-4 h-4 shrink-0', isActive ? 'text-primary-foreground' : 'text-muted-foreground')} />
                  <span>{label}</span>
                </button>
              );
            })}
          </nav>
        </div>
      </div>
    </header>
  );
};

