                        <p className="text-[11px] text-muted-foreground truncate">{substitutoSelecionado.cargo}</p>
                      </div>
                    </div>
                  )}

                  <div className="max-h-40 overflow-y-auto space-y-1.5 pr-1">
                    {reservaFiltrada.map((item) => (
                      <button
                        key={item.id}
