interface FaltaDoDia {
  id: string;
  nome: string;
  matricula: string;
  cargo: string;
  veiculoPrefixo: string;
  veiculoPlaca: string;
  regional: 'ribas' | 'agua_clara';
  regionalNome: string;
  equipeNumero: number;
  motivoFalta: string;
  substitutoNome?: string;
  observacao?: string;
}

export const ExportReports: React.FC<ExportReportsProps> = ({
  veiculos = [],
  selectedRegional = 'todas',
  selectedDate = new Date(),
}) => {
  const [mesSelecionado, setMesSelecionado] = useState<number>(selectedDate.getMonth());
  const [filtroGraficoRegional, setFiltroGraficoRegional] = useState<Regional>(selectedRegional);
  const [downloadSucesso, setDownloadSucesso] = useState<string | null>(null);

  // Formatação da data atual para exibição e relatórios
  const dataFormatada = useMemo(() => {
    return selectedDate.toLocaleDateString('pt-BR', {
      day: '2-digit',
      month: '2-digit',
      year: 'numeric',
    });
  }, [selectedDate]);

  const dataNomeAmigavel = useMemo(() => {
    return selectedDate.toLocaleDateString('pt-BR', {
      weekday: 'long',
      day: '2-digit',
      month: 'long',
      year: 'numeric',
    });
  }, [selectedDate]);

  // Lista de faltas exclusivamente do dia selecionado e conforme a unidade selecionada
  const faltasDoDiaFiltradas: FaltaDoDia[] = useMemo(() => {
    const faltas: FaltaDoDia[] = [];

    (veiculos || []).forEach((veic) => {
      if (!veic) return;

      // Filtro de regional
      if (selectedRegional !== 'todas' && veic.regional !== selectedRegional) {
        return;
      }

      const regionalTexto = veic.regional === 'ribas' ? 'Ribas do Rio Pardo' : 'Água Clara';
      const assentos = [
        { colab: veic.assentos?.motorista, eq: 1 },
        { colab: veic.assentos?.frenteDir, eq: 1 },
        { colab: veic.assentos?.trasEsq, eq: 2 },
        { colab: veic.assentos?.trasDir, eq: 2 },
      ];

      assentos.forEach(({ colab, eq }) => {
        if (!colab) return;
        if (colab.status === 'falta') {
          faltas.push({
            id: colab.id,
            nome: colab.nome || 'Não informado',
            matricula: colab.matricula || 'S/N',
            cargo: colab.cargo || 'Operador',
            veiculoPrefixo: veic.prefixo || 'N/A',
            veiculoPlaca: veic.placa || 'N/A',
            regional: veic.regional,
            regionalNome: regionalTexto,
            equipeNumero: colab.equipeNumero || eq,
            motivoFalta: colab.motivoFalta || 'Falta Injustificada',
            substitutoNome: colab.substitutoNome,
            observacao: colab.observacao,
          });
        }
      });
    });

    return faltas;
  }, [veiculos, selectedRegional]);

  // Dados consolidados do gráfico: Ranking de quem mais faltou no mês selecionado
  const dadosGraficoFaltas = useMemo(() => {
    const mesObj = HISTORICO_MENSAL_FALTAS.find((m) => m.mesIndex === mesSelecionado) || HISTORICO_MENSAL_FALTAS[0];
    let lista = mesObj.faltas;

    if (filtroGraficoRegional !== 'todas') {
      lista = lista.filter((f) => f.regionalKey === filtroGraficoRegional);
    }

    // Ordena decrescente pelo número de faltas
    return [...lista].sort((a, b) => b.totalFaltas - a.totalFaltas);
  }, [mesSelecionado, filtroGraficoRegional]);

  const maxFaltasMes = useMemo(() => {
    if (!dadosGraficoFaltas.length) return 1;
    return Math.max(...dadosGraficoFaltas.map((d) => d.totalFaltas), 1);
  }, [dadosGraficoFaltas]);

  // Função para exportar EXCLUSIVAMENTE as faltas do dia filtradas em formato CSV compatível com Excel
  const exportarFaltasDoDiaCSV = () => {
    if (faltasDoDiaFiltradas.length === 0) {
      alert(`Nenhuma falta registrada no dia ${dataFormatada} para o filtro "${regionalLabel[selectedRegional]}".`);
      return;
    }

    const separador = ';';
    const cabecalho = [
      'Data',
      'Unidade',
      'Nome do Colaborador',
      'Matrícula',
      'Cargo / Função',
      'Veículo',
      'Placa',
      'Equipe',
      'Motivo da Ausência',
      'Substituto Alocado',
      'Observação',
    ].join(separador);

    const linhas = faltasDoDiaFiltradas.map((f) => {
      const escape = (str?: string) => `"${(str || '').replace(/"/g, '""')}"`;
      return [
        escape(dataFormatada),
        escape(f.regionalNome),
        escape(f.nome),
        escape(f.matricula),
        escape(f.cargo),
        escape(f.veiculoPrefixo),
        escape(f.veiculoPlaca),
        escape(`Equipe ${f.equipeNumero}`),
        escape(f.motivoFalta),
        escape(f.substitutoNome || 'Sem substituto'),
        escape(f.observacao || '-'),
      ].join(separador);
    });

    // Adiciona BOM UTF-8 (\uFEFF) para que o Excel brasileiro abra sem problemas de acentuação
    const conteudoCompleto = '\uFEFF' + [cabecalho, ...linhas].join('\r\n');
    const blob = new Blob([conteudoCompleto], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');

    const regionalTag = selectedRegional === 'todas' ? 'TODAS_UNIDADES' : selectedRegional.toUpperCase();
    const dataSlug = dataFormatada.replace(/\//g, '-');
    link.href = url;
    link.setAttribute('download', `RELATORIO_FALTAS_${regionalTag}_${dataSlug}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);

    setDownloadSucesso(`Arquivo gerado com sucesso! (${faltasDoDiaFiltradas.length} faltas exportadas)`);
    setTimeout(() => setDownloadSucesso(null), 4000);
  };

  // Função para imprimir/gerar PDF limpo com apenas os colaboradores faltosos
  const imprimirRelatorioFaltas = () => {
    window.print();
  };

  return (
    <div className="space-y-6">
      {/* Banner / Card Principal de Exportação de Faltas do Dia */}
      <Card className="border-border/60 bg-gradient-to-br from-card via-card/90 to-card/60 shadow-xl overflow-hidden">
        <div className="p-6 border-b border-border/40 bg-gradient-to-r from-rose-500/10 via-amber-500/5 to-transparent">
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
            <div className="space-y-1">
              <div className="flex items-center gap-2">
                <Badge variant="outline" className="border-rose-500/40 text-rose-400 bg-rose-500/10 font-bold px-2.5 py-0.5">
                  <UserX className="w-3.5 h-3.5 mr-1" />
                  RELATÓRIO DE FALTAS DO DIA
                </Badge>
                <Badge variant="outline" className="border-border/60 text-muted-foreground text-xs">
                  {regionalLabel[selectedRegional]}
                </Badge>
              </div>
              <h2 className="text-xl sm:text-2xl font-black text-foreground tracking-tight">
                Exportar Apenas Faltas do Dia
              </h2>
              <p className="text-xs sm:text-sm text-muted-foreground">
                Gere o arquivo consolidado contendo <strong className="text-foreground">apenas os colaboradores ausentes</strong> na data <strong className="text-foreground">{dataFormatada}</strong> ({dataNomeAmigavel}) e conforme o filtro de unidade ativo.
              </p>
            </div>

            <div className="flex flex-wrap items-center gap-2.5">
              <Button
                type="button"
                onClick={exportarFaltasDoDiaCSV}
                className="bg-emerald-600 hover:bg-emerald-500 text-white font-bold gap-2 px-5 py-2.5 rounded-xl shadow-lg shadow-emerald-900/30 hover:scale-[1.02] transition-all cursor-pointer"
              >
                <FileSpreadsheet className="w-4 h-4" />
                Baixar Faltas (Excel / CSV)
              </Button>
              <Button
                type="button"
                variant="outline"
                onClick={imprimirRelatorioFaltas}
                className="border-border/80 hover:bg-muted/60 text-foreground font-semibold gap-2 px-4 py-2.5 rounded-xl cursor-pointer"
              >
                <Printer className="w-4 h-4" />
                Imprimir Lista
              </Button>
            </div>
          </div>

          {downloadSucesso && (
            <div className="mt-4 p-3 rounded-xl bg-emerald-500/15 border border-emerald-500/30 text-emerald-300 text-xs font-semibold flex items-center gap-2 animate-in fade-in slide-in-from-top-2 duration-300">
              <CheckCircle2 className="w-4 h-4 text-emerald-400 shrink-0" />
              <span>{downloadSucesso}</span>
            </div>
          )}
        </div>

        {/* Resumo Dinâmico e Lista de Colaboradores Ausentes */}
        <CardContent className="p-6 space-y-6">
          <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
            <div className="p-4 rounded-xl border border-rose-500/25 bg-rose-500/5 flex items-center justify-between">
              <div>
                <p className="text-xs text-muted-foreground font-medium">Total de Faltas no Dia</p>
                <p className="text-2xl font-black text-rose-400 mt-0.5">{faltasDoDiaFiltradas.length}</p>
                <p className="text-[11px] text-muted-foreground mt-1">Colaboradores ausentes</p>
              </div>
              <div className="w-10 h-10 rounded-xl bg-rose-500/15 border border-rose-500/30 flex items-center justify-center text-rose-400">
                <UserX className="w-5 h-5" />
              </div>
            </div>

            <div className="p-4 rounded-xl border border-border/50 bg-card/40 flex items-center justify-between">
              <div>
                <p className="text-xs text-muted-foreground font-medium">Filtro de Unidade</p>
                <p className="text-base font-bold text-foreground mt-0.5">{regionalLabel[selectedRegional]}</p>
                <p className="text-[11px] text-muted-foreground mt-1">
                  {selectedRegional === 'todas' ? 'Ribas e Água Clara unificadas' : 'Apenas esta unidade'}
                </p>
              </div>
              <div className="w-10 h-10 rounded-xl bg-primary/10 border border-primary/20 flex items-center justify-center text-primary">
                <MapPin className="w-5 h-5" />
              </div>
            </div>

            <div className="p-4 rounded-xl border border-border/50 bg-card/40 flex items-center justify-between">
              <div>
                <p className="text-xs text-muted-foreground font-medium">Data Selecionada</p>
                <p className="text-base font-bold text-foreground mt-0.5">{dataFormatada}</p>
                <p className="text-[11px] text-muted-foreground mt-1 capitalize">{dataNomeAmigavel.split(',')[0]}</p>
              </div>
              <div className="w-10 h-10 rounded-xl bg-sky-500/10 border border-sky-500/20 flex items-center justify-center text-sky-400">
                <Calendar className="w-5 h-5" />
              </div>
            </div>
          </div>

          {/* Prévia da Tabela de Faltosos */}
          <div className="space-y-3">
            <div className="flex items-center justify-between">
              <h3 className="text-sm font-bold text-foreground flex items-center gap-2">
                <Info className="w-4 h-4 text-emerald-400" />
                Prévia dos Colaboradores que Faltaram em {dataFormatada} ({faltasDoDiaFiltradas.length})
              </h3>
              <span className="text-xs text-muted-foreground">
                Estes dados serão incluídos no arquivo baixado
              </span>
            </div>

            {faltasDoDiaFiltradas.length === 0 ? (
              <div className="p-8 rounded-2xl border border-dashed border-emerald-500/30 bg-emerald-500/5 text-center space-y-2">
                <CheckCircle2 className="w-10 h-10 text-emerald-400 mx-auto" />
                <h4 className="text-sm font-bold text-foreground">Nenhuma falta registrada nesta data!</h4>
                <p className="text-xs text-muted-foreground max-w-md mx-auto">
                  Excelente! Todas as equipes e colaboradores da unidade {regionalLabel[selectedRegional]} constam como presentes no dia {dataFormatada}.
                </p>
              </div>
            ) : (
              <div className="overflow-x-auto rounded-xl border border-border/60 bg-card/30">
                <table className="w-full text-left text-xs">
                  <thead className="bg-muted/40 text-muted-foreground border-b border-border/40 font-semibold uppercase tracking-wider">
                    <tr>
                      <th className="py-3 px-4">Colaborador</th>
                      <th className="py-3 px-4">Função / Matrícula</th>
                      <th className="py-3 px-4">Unidade</th>
                      <th className="py-3 px-4">Veículo / Equipe</th>
                      <th className="py-3 px-4">Motivo da Falta</th>
                      <th className="py-3 px-4">Substituto</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-border/30">
                    {faltasDoDiaFiltradas.map((f) => (
                      <tr key={f.id} className="hover:bg-rose-500/5 transition-colors">
                        <td className="py-3 px-4 font-bold text-foreground flex items-center gap-2">
                          <span className="w-2 h-2 rounded-full bg-rose-500 shrink-0" />
                          {f.nome}
                        </td>
                        <td className="py-3 px-4">
                          <span className="text-foreground font-medium">{f.cargo}</span>
                          <span className="block text-[10px] text-muted-foreground font-mono">{f.matricula}</span>
                        </td>
                        <td className="py-3 px-4">
                          <Badge variant="outline" className={cn(
                            'text-[10px] py-0',
                            f.regional === 'ribas'
                              ? 'border-sky-500/30 text-sky-400 bg-sky-500/10'
                              : 'border-teal-500/30 text-teal-400 bg-teal-500/10'
                          )}>
                            {f.regionalNome}
                          </Badge>
                        </td>
                        <td className="py-3 px-4">
                          <span className="font-semibold text-foreground">{f.veiculoPrefixo}</span>
                          <span className="block text-[10px] text-muted-foreground">Equipe {f.equipeNumero} ({f.veiculoPlaca})</span>
                        </td>
                        <td className="py-3 px-4">
                          <span className="px-2 py-0.5 rounded-md bg-rose-500/15 border border-rose-500/30 text-rose-300 font-semibold text-[11px] inline-block">
                            {f.motivoFalta}
                          </span>
                        </td>
                        <td className="py-3 px-4">
                          {f.substitutoNome ? (
                            <span className="text-amber-400 font-medium flex items-center gap-1">
                              <UserCheck className="w-3 h-3 text-amber-400" />
                              {f.substitutoNome}
                            </span>
                          ) : (
                            <span className="text-muted-foreground italic text-[11px]">Nenhum</span>
                          )}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </div>
        </CardContent>
      </Card>

      {/* Seção Gráfica: Ranking de Quem Faltou Mais no Mês */}
      <Card className="border-border/60 bg-card/60 backdrop-blur-md shadow-xl">
        <CardHeader className="border-b border-border/40 pb-4">
          <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
            <div className="space-y-1">
              <div className="flex items-center gap-2">
                <Badge variant="outline" className="border-amber-500/30 text-amber-400 bg-amber-500/10 font-bold px-2 py-0.5">
