import React, { useState } from 'react';
import {
  X,
  UserCheck,
  UserX,
  RefreshCw,
  AlertCircle,
  FileText,
  UserPlus,
  Car,
  CheckCircle2,
} from 'lucide-react';
import { Colaborador, Veiculo, StatusPresenca, MotivoFalta } from '../types';
import { Button } from './ui/button';
import { Badge } from './ui/badge';
import { cn } from '@/lib/utils';

export interface AttendanceModalProps {
  isOpen?: boolean;
  onClose: () => void;
  colaborador: Colaborador;
  veiculo: Veiculo;
  posicao: 'motorista' | 'frenteDir' | 'trasEsq' | 'trasDir';
  colaboradoresReserva: Colaborador[];
  onSalvarStatus: (
    novoStatus: StatusPresenca,
    motivoFalta?: MotivoFalta,
    observacao?: string,
    substitutoId?: string
  ) => void;
}

const MOTIVOS_FALTA: MotivoFalta[] = [
  'Atestado Médico',
  'Falta Injustificada',
  'Folga Compensatória',
  'Treinamento / Integração',
  'Problema de Transporte',
  'Licença Especial',
];

export const AttendanceModal: React.FC<AttendanceModalProps> = ({
  isOpen = true,
  onClose,
  colaborador,
  veiculo,
  posicao,
  colaboradoresReserva = [],
  onSalvarStatus,
}) => {
  if (isOpen === false) {
    return null;
  }

  const [novoStatus, setNovoStatus] = useState<StatusPresenca>(colaborador?.status || 'presente');
  const [motivoFalta, setMotivoFalta] = useState<MotivoFalta | undefined>(colaborador?.motivoFalta);
  const [observacao, setObservacao] = useState<string>(colaborador?.observacao || '');
  const [substitutoId, setSubstitutoId] = useState<string | undefined>(colaborador?.substitutoId);

  const posicaoLabel: Record<string, string> = {
    motorista: 'Motorista (Equipe 1)',
    frenteDir: 'Frente Direita (Equipe 1)',
    trasEsq: 'Traseiro Esquerdo (Equipe 2)',
    trasDir: 'Traseiro Direito (Equipe 2)',
  };

  const handleSalvar = () => {
    onSalvarStatus(
      novoStatus,
      novoStatus === 'falta' ? motivoFalta : undefined,
      observacao,
      novoStatus === 'falta' || novoStatus === 'substituto' ? substitutoId : undefined
    );
    onClose();
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/75 backdrop-blur-sm animate-in fade-in duration-200">
      <div className="relative w-full max-w-lg rounded-2xl border border-border/80 bg-card text-card-foreground shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200">
        <div className="flex items-center justify-between border-b border-border/60 px-6 py-4 bg-muted/20">
          <div>
            <h2 className="text-lg font-bold text-foreground">Registro de Frequência</h2>
            <p className="text-xs text-muted-foreground mt-0.5">
              {veiculo?.prefixo || 'Veículo'} · {posicaoLabel[posicao] || posicao}
            </p>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="rounded-lg p-1.5 text-muted-foreground hover:bg-muted hover:text-foreground transition-colors cursor-pointer"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        <div className="p-6 space-y-5 max-h-[80vh] overflow-y-auto">
          <div className="flex items-center gap-3 p-3 rounded-xl border border-border/60 bg-muted/30">
            {colaborador?.foto ? (
              <img
                src={colaborador.foto}
                alt={colaborador.nome}
                className="w-12 h-12 rounded-full object-cover border border-border"
              />
            ) : (
              <div className="w-12 h-12 rounded-full bg-muted flex items-center justify-center border border-border">
                <Car className="w-5 h-5 text-muted-foreground" />
              </div>
            )}
            <div className="flex-1 min-w-0">
              <p className="text-sm font-bold text-foreground truncate">{colaborador?.nome || 'Não definido'}</p>
              <p className="text-xs text-muted-foreground">{colaborador?.cargo || 'Operador'}</p>
              <div className="flex items-center gap-2 mt-1">
                <Badge variant="outline" className="text-[10px] py-0 px-1.5 font-medium">
                  {colaborador?.matricula || 'Sem matrícula'}
                </Badge>
              </div>
            </div>
          </div>

          <div className="space-y-2">
            <label className="text-xs font-semibold text-foreground">Status da Presença</label>
            <div className="grid grid-cols-3 gap-2">
              <button
                type="button"
                onClick={() => setNovoStatus('presente')}
                className={cn(
                  'flex flex-col items-center justify-center gap-1.5 p-3 rounded-xl border text-xs font-semibold transition-all cursor-pointer',
                  novoStatus === 'presente'
                    ? 'border-emerald-500 bg-emerald-500/15 text-emerald-400 shadow-sm'
                    : 'border-border/60 bg-card/60 text-muted-foreground hover:border-border hover:bg-muted/40'
                )}
              >
                <UserCheck className="w-4 h-4 text-emerald-400" />
                Presente
              </button>

              <button
                type="button"
                onClick={() => setNovoStatus('falta')}
                className={cn(
                  'flex flex-col items-center justify-center gap-1.5 p-3 rounded-xl border text-xs font-semibold transition-all cursor-pointer',
                  novoStatus === 'falta'
                    ? 'border-rose-500 bg-rose-500/15 text-rose-400 shadow-sm'
                    : 'border-border/60 bg-card/60 text-muted-foreground hover:border-border hover:bg-muted/40'
                )}
              >
                <UserX className="w-4 h-4 text-rose-400" />
                Falta
              </button>

              <button
                type="button"
                onClick={() => setNovoStatus('substituto')}
                className={cn(
                  'flex flex-col items-center justify-center gap-1.5 p-3 rounded-xl border text-xs font-semibold transition-all cursor-pointer',
                  novoStatus === 'substituto'
                    ? 'border-amber-500 bg-amber-500/15 text-amber-400 shadow-sm'
                    : 'border-border/60 bg-card/60 text-muted-foreground hover:border-border hover:bg-muted/40'
                )}
              >
                <RefreshCw className="w-4 h-4 text-amber-400" />
                Substituto
              </button>
            </div>
          </div>

          {novoStatus === 'falta' && (
            <div className="space-y-4 pt-1 border-t border-border/40 animate-in fade-in duration-150">
              <div className="space-y-1.5">
                <label className="text-xs font-semibold text-foreground flex items-center gap-1.5">
                  <AlertCircle className="w-3.5 h-3.5 text-rose-400" />
                  Motivo da Falta
                </label>
                <select
                  value={motivoFalta || ''}
                  onChange={(e) => setMotivoFalta(e.target.value as MotivoFalta)}
                  className="w-full rounded-xl border border-input bg-card px-3 py-2 text-xs text-foreground focus:outline-none focus:ring-2 focus:ring-ring"
                >
                  <option value="">Selecione o motivo...</option>
                  {MOTIVOS_FALTA.map((m) => (
                    <option key={m} value={m}>
                      {m}
                    </option>
                  ))}
                </select>
              </div>

              <div className="space-y-1.5">
                <label className="text-xs font-semibold text-foreground flex items-center gap-1.5">
                  <UserPlus className="w-3.5 h-3.5 text-amber-400" />
                  Alocar Substituto do Banco de Reservas (Opcional)
                </label>
                <select
                  value={substitutoId || ''}
                  onChange={(e) => setSubstitutoId(e.target.value || undefined)}
                  className="w-full rounded-xl border border-input bg-card px-3 py-2 text-xs text-foreground focus:outline-none focus:ring-2 focus:ring-ring"
                >
                  <option value="">Nenhum substituto alocado (Vaga aberta)</option>
                  {colaboradoresReserva.map((res) => (
                    <option key={res.id} value={res.id}>
                      {res.nome} ({res.cargo})
                    </option>
                  ))}
                </select>
              </div>
            </div>
          )}

          <div className="space-y-1.5">
            <label className="text-xs font-semibold text-foreground flex items-center gap-1.5">
              <FileText className="w-3.5 h-3.5 text-muted-foreground" />
              Observações Adicionais
            </label>
            <textarea
              rows={2}
              value={observacao}
              onChange={(e) => setObservacao(e.target.value)}
              placeholder="Ex: Avisou com antecedência às 05:30h..."
              className="w-full rounded-xl border border-input bg-card px-3 py-2 text-xs text-foreground placeholder:text-muted-foreground focus:outline-none focus:ring-2 focus:ring-ring resize-none"
            />
          </div>
        </div>

        <div className="flex items-center justify-end gap-2 border-t border-border/60 px-6 py-4 bg-muted/20">
          <Button type="button" variant="outline" size="sm" onClick={onClose} className="rounded-xl">
            Cancelar
          </Button>
          <Button
            type="button"
            size="sm"
            onClick={handleSalvar}
            className="rounded-xl gap-1.5 bg-emerald-600 hover:bg-emerald-500 text-white shadow"
          >
            <CheckCircle2 className="w-4 h-4" />
            Salvar Registro
          </Button>
        </div>
      </div>
    </div>
  );
};

