                  <Building2 className="w-3.5 h-3.5 text-emerald-400" />
                  <span className="text-muted-foreground font-normal">Unidade:</span>
                  <span className="text-foreground font-bold">{unidadeAtual.label}</span>
                </div>
                <span className={cn('w-2 h-2 rounded-full ring-2 ring-background shrink-0', unidadeAtual.dotColor)} />
                <ChevronDown
                  className={cn(
                    'w-3.5 h-3.5 text-muted-foreground transition-transform duration-200 ml-0.5',
                    dropdownUnidadeAberto && 'rotate-180 text-emerald-400'
                  )}
                />
              </button>

              {dropdownUnidadeAberto && (
                <div className="absolute left-0 mt-2 w-72 rounded-2xl border border-border/80 bg-popover/95 backdrop-blur-xl p-2 shadow-2xl z-50 animate-in fade-in-50 zoom-in-95">
                  <div className="px-3 py-2 text-[11px] font-semibold text-muted-foreground border-b border-border/40">
                    Selecione a Unidade Operacional
                  </div>
                  <div className="mt-1 space-y-1">
                    {REGIONAIS.map((reg) => (
                      <button
                        key={reg.id}
                        type="button"
                        onClick={() => {
                          onRegionalChange(reg.id);
                          setDropdownUnidadeAberto(false);
                        }}
                        className={cn(
                          'w-full flex items-center justify-between p-2.5 rounded-xl text-left text-xs font-medium transition-all cursor-pointer',
                          selectedRegional === reg.id
                            ? 'bg-primary/10 text-primary border border-primary/20'
                            : 'hover:bg-muted/60 text-foreground'
                        )}
                      >
                        <div className="flex items-center gap-2">
                          <span className={cn('w-2 h-2 rounded-full', reg.dotColor)} />
                          <div>
                            <p className="font-semibold">{reg.label}</p>
                            <p className="text-[10px] text-muted-foreground">{reg.description}</p>
                          </div>
                        </div>
                        {selectedRegional === reg.id && <Check className="w-4 h-4 text-primary shrink-0" />}
                      </button>
                    ))}
                  </div>
                </div>
              )}
            </div>

            {/* Seletor de Data */}
            <div className="relative" ref={dropdownDataRef}>
              <button
                type="button"
                onClick={() => {
                  setDropdownDataAberto(!dropdownDataAberto);
                  setDropdownUnidadeAberto(false);
                }}
                className={cn(
                  'flex items-center gap-2 px-3 py-1.5 rounded-xl border text-xs font-semibold transition-all duration-200 shadow-sm cursor-pointer',
                  'bg-card/90 hover:bg-card hover:border-emerald-500/50 focus:outline-none focus:ring-2 focus:ring-emerald-500/30 border-border/80',
                  dropdownDataAberto && 'border-emerald-500 ring-2 ring-emerald-500/20 bg-emerald-500/5'
                )}
              >
                <Calendar className="w-3.5 h-3.5 text-emerald-400" />
                <span className="text-foreground capitalize">{formatarDataExibicao(selectedDate)}</span>
                <ChevronDown
                  className={cn(
                    'w-3.5 h-3.5 text-muted-foreground transition-transform duration-200',
                    dropdownDataAberto && 'rotate-180 text-emerald-400'
                  )}
                />
              </button>

              {dropdownDataAberto && (
                <div className="absolute left-0 mt-2 p-3 rounded-2xl border border-border/80 bg-popover/95 backdrop-blur-xl shadow-2xl z-50 animate-in fade-in-50 zoom-in-95 w-64">
                  <label className="text-[11px] font-semibold text-muted-foreground block mb-1.5">
                    Data da Operação
                  </label>
                  <input
                    type="date"
                    value={formatarDataInput(selectedDate)}
                    onChange={handleDataChangeFromInput}
                    className="w-full px-3 py-2 rounded-xl border border-border bg-card text-foreground text-xs focus:outline-none focus:ring-2 focus:ring-emerald-500/30"
                  />
                  <div className="flex items-center justify-between mt-2 pt-2 border-t border-border/40">
                    <button
                      type="button"
                      onClick={() => {
                        onDateChange(new Date());
                        setDropdownDataAberto(false);
                      }}
                      className="text-[11px] text-emerald-400 font-semibold hover:underline cursor-pointer"
                    >
                      Voltar para Hoje
                    </button>
                  </div>
                </div>
              )}
            </div>
          </div>
        </div>

        {/* Abas de Navegação */}
        <nav className="flex items-center gap-1 overflow-x-auto py-2.5 scrollbar-none" aria-label="Navegação Principal">
          {navItems.map((item) => {
            const Icon = item.icon;
            const ativo = activeTab === item.id;
            return (
              <button
                key={item.id}
                type="button"
                onClick={() => handleTabSelect(item.id)}
                className={cn(
                  'flex items-center gap-2 px-3.5 py-2 rounded-xl text-xs font-semibold whitespace-nowrap transition-all duration-150 cursor-pointer',
                  ativo
                    ? 'bg-emerald-500/15 text-emerald-300 border border-emerald-500/30 shadow-sm'
                    : 'text-muted-foreground hover:text-foreground hover:bg-muted/40 border border-transparent'
                )}
              >
                <Icon className={cn('w-4 h-4', ativo ? 'text-emerald-400' : 'text-muted-foreground')} />
                <span>{item.label}</span>
              </button>
            );
          })}
        </nav>
      </div>
    </header>
  );
};

