                    </Badge>
                  </div>
                </div>

                {/* Sub-barra com status das duas equipes */}
                <div className="mt-3 pt-2.5 border-t border-border/30 flex items-center justify-between text-[11px] text-muted-foreground">
                  <div className="flex items-center gap-3">
                    <span className="flex items-center gap-1">
                      <span className="w-1.5 h-1.5 rounded-full bg-emerald-400" />
                      {veiculo.equipe1Codigo}
                    </span>
                    <span className="flex items-center gap-1">
                      <span className="w-1.5 h-1.5 rounded-full bg-teal-400" />
                      {veiculo.equipe2Codigo}
                    </span>
                  </div>

                  <div className="flex items-center gap-2">
                    {totalFaltas > 0 ? (
                      <span className="flex items-center gap-1 text-rose-400 font-semibold">
                        <AlertTriangle className="w-3 h-3" />
                        {totalFaltas} {totalFaltas === 1 ? 'falta' : 'faltas'}
                      </span>
                    ) : (
                      <span className="text-emerald-400 font-semibold">Completo</span>
                    )}
                  </div>
                </div>
              </CardHeader>

              {/* Lista dos 4 assentos */}
              <CardContent className="p-3 space-y-2">
                {assentosArray.map(({ colab, posKey }) => {
                  const statusInfo = statusBadgeConfig[colab.status] || statusBadgeConfig.presente;
                  const StatusIcon = statusInfo.icon;

                  return (
                    <div
                      key={colab.id || posKey}
                      onClick={() => abrirModalChamada(veiculo, colab, posKey)}
                      className={cn(
                        'flex items-center justify-between p-2.5 rounded-xl border border-border/40 bg-card/60 hover:bg-card/90 transition-all cursor-pointer group/row',
                        colab.status === 'falta' && 'border-rose-500/30 bg-rose-500/5',
                        colab.status === 'substituto' && 'border-amber-500/30 bg-amber-500/5'
                      )}
                    >
                      <div className="flex items-center gap-2.5 min-w-0">
                        <div className="relative shrink-0">
                          {colab.foto ? (
                            <img
                              src={colab.foto}
                              alt={colab.nome}
                              className="w-8 h-8 rounded-full object-cover border border-border/60"
                              onError={(e) => {
                                (e.target as HTMLImageElement).style.display = 'none';
                              }}
                            />
                          ) : (
                            <div className="w-8 h-8 rounded-full bg-muted flex items-center justify-center text-xs font-bold text-muted-foreground border border-border">
                              {colab.nome?.slice(0, 2).toUpperCase()}
                            </div>
                          )}
                          <span
                            className={cn(
                              'absolute -bottom-0.5 -right-0.5 w-2.5 h-2.5 rounded-full ring-2 ring-card',
                              colab.status === 'presente' && 'bg-emerald-400',
                              colab.status === 'falta' && 'bg-rose-400',
                              colab.status === 'substituto' && 'bg-amber-400'
                            )}
                          />
                        </div>

                        <div className="min-w-0">
                          <p className="text-xs font-semibold text-foreground truncate group-hover/row:text-primary transition-colors">
                            {colab.nome}
                          </p>
                          <p className="text-[10px] text-muted-foreground truncate">
                            {posicaoLabel[posKey]} · {colab.cargo}
                          </p>
                          {colab.status === 'falta' && colab.motivoFalta && (
                            <p className="text-[10px] text-rose-400 font-medium truncate mt-0.5">
                              {colab.motivoFalta}
                            </p>
                          )}
                          {colab.status === 'substituto' && colab.substitutoNome && (
                            <p className="text-[10px] text-amber-400 font-medium truncate mt-0.5">
                              Subst: {colab.substitutoNome}
                            </p>
                          )}
                        </div>
                      </div>

                      <div className="flex items-center gap-1.5 shrink-0 ml-2">
                        <span
                          className={cn(
                            'inline-flex items-center gap-1 px-2 py-0.5 rounded-md text-[10px] font-semibold border',
                            statusInfo.className
                          )}
                        >
                          <StatusIcon className="w-3 h-3" />
                          <span>{statusInfo.label}</span>
                        </span>
                        <ChevronRight className="w-3.5 h-3.5 text-muted-foreground/60 group-hover/row:text-foreground transition-colors" />
                      </div>
                    </div>
                  );
                })}
              </CardContent>
            </Card>
          );
        })}
      </div>

      {modalAberto && colaboradorSelecionado && veiculoSelecionado && (
        <AttendanceModal
          isOpen={modalAberto}
          onClose={() => setModalAberto(false)}
          colaborador={colaboradorSelecionado}
          veiculoPrefixo={veiculoSelecionado.prefixo}
          colaboradoresReserva={colaboradoresReserva}
          onSave={handleSalvarStatus}
        />
      )}
    </>
  );
};

