          <p className="text-[11px] text-muted-foreground mt-0.5">{veiculosFiltrados.length} veículos ativos</p>
        </div>

        <div className="p-4 rounded-2xl border border-emerald-500/20 bg-emerald-500/5 backdrop-blur-md shadow-sm">
