            <VehicleCardGrid
              veiculos={veiculos}
              colaboradoresReserva={reservas}
              selectedRegional={selectedRegional}
              onStatusChange={handleStatusChange}
            />
          </div>
        )}

        {activeTab === 'colaboradores' && (
          <CollaboratorsManagement
            veiculos={veiculos}
            colaboradoresReserva={reservas}
            selectedRegional={selectedRegional}
            onUpdateColaboradorStatus={(colabId, novoStatus, motivo, obs) => {
              setVeiculos((prev) =>
                prev.map((v) => {
                  const updatedAssentos = { ...v.assentos };
                  let changed = false;
                  (['motorista', 'frenteDir', 'trasEsq', 'trasDir'] as const).forEach((pos) => {
                    if (updatedAssentos[pos]?.id === colabId) {
                      updatedAssentos[pos] = {
                        ...updatedAssentos[pos],
                        status: novoStatus,
                        motivoFalta: motivo,
                        observacao: obs,
                      };
                      changed = true;
                    }
                  });
                  return changed ? { ...v, assentos: updatedAssentos } : v;
                })
              );
            }}
          />
        )}

        {activeTab === 'equipes' && (
          <TeamsManagement
            veiculos={veiculos}
            colaboradoresReserva={reservas}
            selectedRegional={selectedRegional}
            onNovaEquipeClick={() => setIsNewTeamModalOpen(true)}
          />
        )}

        {activeTab === 'relatorios' && (
          <ExportReports
            veiculos={veiculos}
            selectedDate={selectedDate}
            selectedRegional={selectedRegional}
          />
        )}
      </main>

      <NewTeamModal
        isOpen={isNewTeamModalOpen}
        onClose={() => setIsNewTeamModalOpen(false)}
        onSave={handleSalvarNovaEquipe}
        colaboradoresReserva={reservas}
      />
    </div>
  );
}

export default App;

