export const ExportReports: React.FC<ExportReportsProps> = ({
  veiculos = [],
  selectedRegional = 'todas',
  selectedDate = new Date(),
}) => {
  const [mesSelecionado, setMesSelecionado] = useState<number>(selectedDate?.getMonth?.() ?? 0);
  const [regionalFiltro, setRegionalFiltro] = useState<Regional>(selectedRegional);

  // Lista de faltas do dia
  const faltasDoDia = useMemo(() => {
    const faltas: Array<{
      colaborador: Colaborador;
      prefixo: string;
      placa: string;
      regional: string;
    }> = [];

    (veiculos || []).forEach((v) => {
      if (!v || !v.assentos) return;
      if (regionalFiltro !== 'todas' && v.regional !== regionalFiltro) return;

      const assentos = [v.assentos.motorista, v.assentos.frenteDir, v.assentos.trasEsq, v.assentos.trasDir];
      assentos.forEach((colab) => {
        if (colab && colab.status === 'falta') {
          faltas.push({
            colaborador: colab,
            prefixo: v.prefixo,
            placa: v.placa,
            regional: v.regional === 'ribas' ? 'Ribas do Rio Pardo' : 'Água Clara',
          });
        }
      });
    });

    return faltas;
  }, [veiculos, regionalFiltro]);

  // Ranking do mês selecionado
  const rankingMes = useMemo(() => {
    const dadosMes = HISTORICO_MENSAL_FALTAS.find((h) => h.mesIndex === mesSelecionado);
    if (!dadosMes) return [];

    let lista = dadosMes.faltas;
    if (regionalFiltro !== 'todas') {
      lista = lista.filter((item) => item.regionalKey === regionalFiltro);
    }
    return lista.sort((a, b) => b.totalFaltas - a.totalFaltas);
  }, [mesSelecionado, regionalFiltro]);

  const maxFaltas = useMemo(() => {
    if (rankingMes.length === 0) return 5;
    return Math.max(...rankingMes.map((r) => r.totalFaltas), 5);
  }, [rankingMes]);

  const exportarCSVFaltas = () => {
    const dataFormatada = selectedDate ? selectedDate.toLocaleDateString('pt-BR') : 'Hoje';
    const nomeUnidade = regionalLabel[regionalFiltro];

    let csvContent = 'data:text/csv;charset=utf-8,';
    csvContent += `Relatorio de Faltas - ${nomeUnidade} - Data: ${dataFormatada}\n\n`;
    csvContent += 'Nome,Cargo,Matricula,Veiculo,Placa,Unidade,Motivo da Falta,Observacoes\n';

    faltasDoDia.forEach((f) => {
      const c = f.colaborador;
      const linha = [
        `"${c.nome}"`,
        `"${c.cargo}"`,
        `"${c.matricula || '-'}"`,
        `"${f.prefixo}"`,
        `"${f.placa}"`,
        `"${f.regional}"`,
        `"${c.motivoFalta || 'Não Informado'}"`,
        `"${c.observacao || '-'}"`,
      ].join(',');
      csvContent += linha + '\n';
    });

    const encodedUri = encodeURI(csvContent);
    const link = document.createElement('a');
    link.setAttribute('href', encodedUri);
    link.setAttribute('download', `relatorio_faltas_${regionalFiltro}_${selectedDate.toISOString().split('T')[0]}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="w-full space-y-6">
      {/* Top Banner */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 p-5 rounded-2xl border border-border/80 bg-card/60 backdrop-blur-md shadow-lg">
        <div>
          <div className="flex items-center gap-2">
            <BarChart3 className="w-5 h-5 text-emerald-400" />
            <h2 className="text-xl font-black text-foreground tracking-tight">Relatórios Operacionais e Absenteísmo</h2>
          </div>
          <p className="text-xs text-muted-foreground mt-1">
            Análise detalhada de faltas por colaborador, unidade e histórico consolidado
          </p>
        </div>

        <div className="flex items-center gap-2 flex-wrap">
          <select
            value={regionalFiltro}
            onChange={(e) => setRegionalFiltro(e.target.value as any)}
            className="h-9 px-3 rounded-xl border border-border bg-card text-xs text-foreground focus:outline-none focus:ring-2 focus:ring-emerald-500/30"
          >
            <option value="todas">Todas as Unidades</option>
            <option value="ribas">Ribas do Rio Pardo</option>
            <option value="agua_clara">Água Clara</option>
          </select>

          <Button
            type="button"
            onClick={exportarCSVFaltas}
            className="h-9 text-xs gap-1.5 bg-emerald-600 hover:bg-emerald-500 text-white shadow-md shadow-emerald-600/20"
          >
            <Download className="w-3.5 h-3.5" />
            Exportar Faltas do Dia (CSV)
          </Button>
        </div>
      </div>

      {/* Gráfico de Ranking de Faltas */}
      <Card className="border-border/80 bg-card/60 backdrop-blur-md shadow-lg overflow-hidden">
        <CardHeader className="border-b border-border/40 pb-4">
          <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3">
            <div>
              <CardTitle className="flex items-center gap-2 text-base font-bold">
                <Flame className="w-5 h-5 text-rose-400" />
                Ranking de Faltas — Colaboradores com Maior Absenteísmo
              </CardTitle>
              <CardDescription className="text-xs">
                Mês de referência: <strong>{MESES[mesSelecionado]}</strong> | Polo:{' '}
                <strong>{regionalLabel[regionalFiltro]}</strong>
              </CardDescription>
            </div>

            <div className="flex items-center gap-1.5 flex-wrap">
              {MESES.map((mes, idx) => (
                <button
                  key={mes}
                  type="button"
                  onClick={() => setMesSelecionado(idx)}
                  className={cn(
                    'px-2.5 py-1 rounded-lg text-[11px] font-semibold transition-all',
                    mesSelecionado === idx
                      ? 'bg-rose-500/20 text-rose-300 border border-rose-500/40 font-bold'
                      : 'text-muted-foreground hover:bg-muted/40 hover:text-foreground'
                  )}
                >
                  {mes.slice(0, 3)}
                </button>
              ))}
            </div>
          </div>
        </CardHeader>

        <CardContent className="p-6">
          {rankingMes.length === 0 ? (
            <div className="p-8 text-center text-muted-foreground text-xs">
              Nenhuma falta registrada nesta regional durante o mês de {MESES[mesSelecionado]}.
            </div>
          ) : (
            <div className="space-y-4">
              {rankingMes.map((item, idx) => {
                const percent = Math.round((item.totalFaltas / maxFaltas) * 100);
                return (
                  <div key={idx} className="space-y-1.5">
                    <div className="flex items-center justify-between text-xs">
                      <div className="flex items-center gap-2">
                        <span className="w-5 h-5 rounded-md bg-muted/60 border border-border/60 flex items-center justify-center font-bold text-[10px] tabular-nums text-muted-foreground">
                          {idx + 1}º
                        </span>
                        <span className="font-bold text-foreground">{item.nome}</span>
                        <span className="text-[11px] text-muted-foreground">({item.cargo})</span>
                        <Badge variant="outline" className="text-[10px] py-0 px-1.5 hidden sm:inline-flex">
                          {item.regional}
                        </Badge>
                      </div>
                      <span className="font-extrabold text-rose-400 tabular-nums text-sm">
                        {item.totalFaltas} {item.totalFaltas === 1 ? 'falta' : 'faltas'}
                      </span>
                    </div>

                    <div className="w-full h-3 rounded-full bg-muted/40 overflow-hidden border border-border/40">
                      <div
                        className="h-full bg-gradient-to-r from-rose-500 to-amber-500 rounded-full transition-all duration-500"
                        style={{ width: `${percent}%` }}
                      />
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </CardContent>
      </Card>

      {/* Tabela de Faltas do Dia Selecionado */}
      <Card className="border-border/80 bg-card/60 backdrop-blur-md shadow-lg overflow-hidden">
        <CardHeader className="border-b border-border/40 pb-4">
          <div className="flex items-center justify-between">
            <div>
              <CardTitle className="text-base font-bold flex items-center gap-2">
                <UserX className="w-4 h-4 text-rose-400" />
                Colaboradores Ausentes no Dia Selecionado
              </CardTitle>
              <CardDescription className="text-xs">
                Data: <strong>{selectedDate ? selectedDate.toLocaleDateString('pt-BR') : 'Hoje'}</strong> | Total de faltas:{' '}
                <strong className="text-rose-400">{faltasDoDia.length}</strong>
              </CardDescription>
            </div>

            <Button
              type="button"
              variant="outline"
              size="sm"
              onClick={exportarCSVFaltas}
              disabled={faltasDoDia.length === 0}
              className="text-xs gap-1.5"
            >
              <FileDown className="w-3.5 h-3.5" />
              Baixar Lista Filtrada
            </Button>
          </div>
        </CardHeader>

        <CardContent className="p-0">
          {faltasDoDia.length === 0 ? (
            <div className="p-10 text-center text-muted-foreground text-xs">
              <CheckCircle2 className="w-8 h-8 text-emerald-400 mx-auto mb-2" />
              <p className="font-bold text-foreground">Nenhuma falta registrada no dia!</p>
              <p className="text-[11px] text-muted-foreground mt-0.5">Todas as equipes escaladas compareceram ao turno.</p>
            </div>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full text-xs text-left">
                <thead className="bg-muted/40 border-b border-border/40 text-muted-foreground uppercase text-[10px]">
                  <tr>
                    <th className="px-4 py-3 font-semibold">Colaborador</th>
                    <th className="px-4 py-3 font-semibold">Função</th>
                    <th className="px-4 py-3 font-semibold">Unidade</th>
                    <th className="px-4 py-3 font-semibold">Veículo</th>
                    <th className="px-4 py-3 font-semibold">Motivo Informado</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-border/30">
                  {faltasDoDia.map((item, idx) => (
                    <tr key={idx} className="hover:bg-muted/20 transition-colors">
                      <td className="px-4 py-3 font-bold text-foreground">{item.colaborador.nome}</td>
                      <td className="px-4 py-3 text-muted-foreground">{item.colaborador.cargo}</td>
                      <td className="px-4 py-3 text-muted-foreground">{item.regional}</td>
                      <td className="px-4 py-3 font-mono text-[11px]">
                        {item.prefixo} <span className="text-muted-foreground">({item.placa})</span>
                      </td>
                      <td className="px-4 py-3">
                        <Badge variant="outline" className="border-rose-500/30 text-rose-400 bg-rose-500/10 text-[10px]">
                          {item.colaborador.motivoFalta || 'Falta Injustificada'}
                        </Badge>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
};

