import React, { useState, useEffect } from 'react';
import { Navbar } from './components/Navbar';
import { MetricsHeader } from './components/MetricsHeader';
import { VehicleCardGrid } from './components/VehicleCardGrid';
import { CollaboratorsManagement, ColaboradorCompleto } from './components/CollaboratorsManagement';
import { TeamsManagement } from './components/TeamsManagement';
import { ExportReports } from './components/ExportReports';
import { NewTeamModal } from './components/NewTeamModal';
import { VEICULOS_INICIAIS, COLABORADORES_RESERVA } from './data/mockData';
import { Veiculo, Colaborador, Regional, StatusPresenca, MotivoFalta } from './types';

export function App() {
  const [activeTab, setActiveTab] = useState<'veiculos' | 'colaboradores' | 'equipes' | 'relatorios'>('veiculos');
  const [selectedRegional, setSelectedRegional] = useState<Regional>('todas');
  const [selectedDate, setSelectedDate] = useState<Date>(new Date());
  const [veiculos, setVeiculos] = useState<Veiculo[]>(VEICULOS_INICIAIS);
  const [colaboradoresReserva, setColaboradoresReserva] = useState<Colaborador[]>(COLABORADORES_RESERVA);
  const [isNewTeamModalOpen, setIsNewTeamModalOpen] = useState(false);

  // Manipulador para atualizar presença de um colaborador em um assento de veículo
  const handleUpdateAssentoStatus = (
    veiculoId: string,
    posicao: 'motorista' | 'frenteDir' | 'trasEsq' | 'trasDir',
    novoStatus: StatusPresenca,
    motivo?: MotivoFalta,
    observacao?: string,
    substituto?: { id: string; nome: string }
  ) => {
    setVeiculos((prev) =>
      prev.map((v) => {
        if (v.id !== veiculoId) return v;
        const assentoAtual = v.assentos[posicao];
        if (!assentoAtual) return v;

        return {
          ...v,
          assentos: {
            ...v.assentos,
            [posicao]: {
              ...assentoAtual,
              status: novoStatus,
              motivoFalta: novoStatus === 'falta' ? motivo : undefined,
              observacao: novoStatus === 'falta' ? observacao : undefined,
              substitutoId: novoStatus === 'substituto' ? substituto?.id : undefined,
              substitutoNome: novoStatus === 'substituto' ? substituto?.nome : undefined,
            },
          },
        };
      })
    );
  };

  // Manipulador para atualizar status direto a partir da tela de colaboradores
  const handleUpdateColaboradorStatus = (
    colabId: string,
    novoStatus: StatusPresenca,
    motivo?: MotivoFalta,
    obs?: string
  ) => {
    setVeiculos((prev) =>
      prev.map((v) => {
        let mudou = false;
        const novosAssentos = { ...v.assentos };

        (['motorista', 'frenteDir', 'trasEsq', 'trasDir'] as const).forEach((pos) => {
          if (novosAssentos[pos] && novosAssentos[pos].id === colabId) {
            mudou = true;
            novosAssentos[pos] = {
              ...novosAssentos[pos],
              status: novoStatus,
              motivoFalta: novoStatus === 'falta' ? motivo : undefined,
              observacao: novoStatus === 'falta' ? obs : undefined,
            };
          }
        });

        return mudou ? { ...v, assentos: novosAssentos } : v;
      })
    );
  };

  // Manipulador para criar novo veículo / equipe
  const handleSalvarNovoVeiculo = (novo: any) => {
    const novoVeiculo: Veiculo = {
      id: `veic-${Date.now()}`,
      prefixo: novo.prefixo || 'CARRO NOVO',
      placa: novo.placa || 'BRA2E19',
      modelo: novo.modelo || 'Caminhonete 4x4',
      ano: 2024,
      regional: novo.regional || 'ribas',
      statusOperacional: 'ativo',
      equipe1Codigo: `${novo.prefixo || 'CARRO'} - EQ 1`,
      equipe2Codigo: `${novo.prefixo || 'CARRO'} - EQ 2`,
      assentos: {
        motorista: {
          id: `c-${Date.now()}-1`,
          nome: 'Operador Motorista',
          cargo: 'Motorista Operacional',
          matricula: `MAT-${Math.floor(1000 + Math.random() * 9000)}`,
          foto: 'https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?w=150',
          telefone: '(67) 99999-0000',
          status: 'presente',
          equipeId: `${novo.prefixo}-1`,
          equipeNumero: 1,
          posicaoVeiculo: 'motorista',
        },
        frenteDir: {
          id: `c-${Date.now()}-2`,
          nome: 'Operador Ajudante',
          cargo: 'Ajudante Geral',
          matricula: `MAT-${Math.floor(1000 + Math.random() * 9000)}`,
          foto: 'https://images.unsplash.com/photo-1570295999919-56ceb5ecca61?w=150',
          telefone: '(67) 99999-0000',
          status: 'presente',
          equipeId: `${novo.prefixo}-1`,
          equipeNumero: 1,
          posicaoVeiculo: 'frente_dir',
        },
        trasEsq: {
          id: `c-${Date.now()}-3`,
          nome: 'Operador Motosserra',
          cargo: 'Operador de Motosserra',
          matricula: `MAT-${Math.floor(1000 + Math.random() * 9000)}`,
          foto: 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=150',
          telefone: '(67) 99999-0000',
          status: 'presente',
          equipeId: `${novo.prefixo}-2`,
          equipeNumero: 2,
          posicaoVeiculo: 'tras_esq',
        },
        trasDir: {
          id: `c-${Date.now()}-4`,
          nome: 'Operador Apoio',
          cargo: 'Ajudante Florestal',
          matricula: `MAT-${Math.floor(1000 + Math.random() * 9000)}`,
          foto: 'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?w=150',
          telefone: '(67) 99999-0000',
          status: 'presente',
          equipeId: `${novo.prefixo}-2`,
          equipeNumero: 2,
          posicaoVeiculo: 'tras_dir',
        },
      },
    };

    setVeiculos((prev) => [novoVeiculo, ...prev]);
  };

  return (
    <div className="min-h-screen bg-background text-foreground flex flex-col selection:bg-emerald-500/30 selection:text-emerald-200">
      <Navbar
        activeTab={activeTab}
        onTabChange={setActiveTab}
        selectedRegional={selectedRegional}
        onRegionalChange={setSelectedRegional}
        selectedDate={selectedDate}
        onDateChange={setSelectedDate}
        onNovaEquipeClick={() => setIsNewTeamModalOpen(true)}
      />

      <main className="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-6 space-y-6">
        {activeTab === 'veiculos' && (
          <div className="space-y-6">
            <MetricsHeader
              veiculos={veiculos}
              selectedRegional={selectedRegional}
              selectedDate={selectedDate}
              onFiltroRegionalChange={(reg) => setSelectedRegional(reg)}
              onNovaEquipe={() => setIsNewTeamModalOpen(true)}
            />

            <VehicleCardGrid
              veiculos={veiculos}
              colaboradoresReserva={colaboradoresReserva}
              selectedRegional={selectedRegional}
              onUpdateAssentoStatus={handleUpdateAssentoStatus}
              onNovaEquipe={() => setIsNewTeamModalOpen(true)}
            />
          </div>
        )}

        {activeTab === 'colaboradores' && (
          <CollaboratorsManagement
            veiculos={veiculos}
            colaboradoresReserva={colaboradoresReserva}
            selectedRegional={selectedRegional}
            onUpdateColaboradorStatus={handleUpdateColaboradorStatus}
          />
        )}

        {activeTab === 'equipes' && (
          <TeamsManagement
