                    {isExpanded ? (
                      <ChevronUp className="w-4 h-4 text-muted-foreground" />
                    ) : (
                      <ChevronDown className="w-4 h-4 text-muted-foreground" />
                    )}
                  </div>
                </div>

                {/* Detalhes Expandidos */}
                {isExpanded && (
                  <div className="px-4 pb-4 pt-2 border-t border-border/40 bg-muted/20 space-y-3 animate-in fade-in-50 duration-150">
                    <div className="grid grid-cols-1 sm:grid-cols-3 gap-3 text-xs">
                      <div>
                        <span className="text-muted-foreground block text-[11px]">Unidade Operacional:</span>
                        <span className="font-semibold text-foreground flex items-center gap-1 mt-0.5">
                          <MapPin className="w-3.5 h-3.5 text-emerald-400" />
                          {regionalLabel[c.regional]}
                        </span>
                      </div>

                      <div>
                        <span className="text-muted-foreground block text-[11px]">Contato:</span>
                        <span className="font-semibold text-foreground flex items-center gap-1 mt-0.5">
                          <Phone className="w-3.5 h-3.5 text-muted-foreground" />
                          {c.telefone || 'Não informado'}
                        </span>
                      </div>

                      <div>
                        <span className="text-muted-foreground block text-[11px]">Lotação / Veículo:</span>
                        <span className="font-semibold text-foreground mt-0.5 block">
                          {c.veiculoPrefixo} ({c.veiculoPlaca})
                        </span>
                      </div>
                    </div>

                    {c.status === 'falta' && (
                      <div className="p-2.5 rounded-xl bg-rose-500/10 border border-rose-500/25 text-xs text-rose-300">
                        <span className="font-bold">Motivo do Desfalque:</span>{' '}
                        {c.motivoFalta || 'Não especificado'}
                        {c.observacao && <p className="mt-1 text-rose-200/90 text-[11px]">{c.observacao}</p>}
                      </div>
                    )}

                    {c.status === 'substituto' && c.substitutoNome && (
                      <div className="p-2.5 rounded-xl bg-amber-500/10 border border-amber-500/25 text-xs text-amber-300">
                        <span className="font-bold">Substituído por:</span> {c.substitutoNome}
                      </div>
                    )}
                  </div>
                )}
              </Card>
            );
          })
        )}
      </div>

      {/* Modal Adicionar Novo Colaborador */}
      {modalNovoColaboradorAberto && (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-background/80 backdrop-blur-md animate-in fade-in"
          onClick={() => setModalNovoColaboradorAberto(false)}
        >
          <div
            className="w-full max-w-lg bg-card border border-border rounded-3xl shadow-2xl overflow-hidden animate-in zoom-in-95"
            onClick={(e) => e.stopPropagation()}
          >
            <div className="px-6 py-4 border-b border-border/80 flex items-center justify-between">
              <div className="flex items-center gap-2.5">
                <div className="w-8 h-8 rounded-xl bg-emerald-500/15 border border-emerald-500/30 flex items-center justify-center text-emerald-400">
