                      alt="Prévia da Foto"
                      className="w-16 h-16 rounded-full object-cover border-2 border-emerald-500/50 shadow-md"
                    />
                  ) : (
                    <div className="w-16 h-16 rounded-full bg-card border-2 border-dashed border-border/80 flex items-center justify-center text-muted-foreground">
                      <Camera className="w-6 h-6" />
                    </div>
                  )}
                </div>

                <div className="space-y-1.5 flex-1">
                  <p className="text-xs font-semibold text-foreground">Foto do Perfil</p>
                  <p className="text-[11px] text-muted-foreground">PNG, JPG ou WEBP até 5MB</p>
                  <div className="flex items-center gap-2">
                    <Button
                      type="button"
                      size="sm"
                      variant="outline"
                      onClick={() => fotoInputRef.current?.click()}
                      className="h-7 text-xs border-emerald-500/30 text-emerald-400"
                    >
                      Escolher Foto
                    </Button>
                    {novaFoto && (
                      <Button
                        type="button"
                        size="sm"
                        variant="ghost"
                        onClick={() => setNovaFoto('')}
                        className="h-7 text-xs text-rose-400 hover:text-rose-300"
