        {equipesFiltradas.length === 0 ? (
          <div className="col-span-full py-12 text-center rounded-2xl border border-dashed border-border/70 bg-card/20">
            <Layers className="w-8 h-8 text-muted-foreground mx-auto mb-2 opacity-50" />
            <p className="text-sm font-semibold text-foreground">Nenhuma equipe encontrada</p>
            <p className="text-xs text-muted-foreground mt-1">Ajuste os filtros de busca para visualizar os registros.</p>
          </div>
        ) : (
          equipesFiltradas.map((eq) => {
            const isExpanded = expandedTeamId === eq.id;
            const isIncompleta = eq.faltas > 0;

            return (
              <Card
                key={eq.id}
                className={cn(
                  'border transition-all duration-200 overflow-hidden',
                  isIncompleta ? 'border-amber-500/30 bg-card/70' : 'border-border/60 bg-card/40'
                )}
              >
                <div
                  className="p-4 flex items-center justify-between gap-3 cursor-pointer select-none"
                  onClick={() => setExpandedTeamId(isExpanded ? null : eq.id)}
                >
                  <div className="space-y-1 min-w-0">
                    <div className="flex items-center gap-2 flex-wrap">
                      <span className="font-bold text-sm text-foreground">{eq.codigo}</span>
                      <Badge
                        variant="outline"
                        className={cn(
                          'text-[10px] py-0 px-2 font-semibold',
                          isIncompleta
                            ? 'bg-amber-500/10 text-amber-400 border-amber-500/30'
                            : 'bg-emerald-500/10 text-emerald-400 border-emerald-500/30'
                        )}
                      >
                        {isIncompleta ? 'Com Desfalque' : 'Completa'}
                      </Badge>
                    </div>

                    <div className="flex items-center gap-3 text-xs text-muted-foreground">
                      <span className="flex items-center gap-1">
                        <Car className="w-3.5 h-3.5 text-muted-foreground" />
                        {eq.veiculoPrefixo}
                      </span>
                      <span className="flex items-center gap-1">
                        <MapPin className="w-3.5 h-3.5 text-emerald-400" />
                        {regionalLabel[eq.regional]}
                      </span>
                    </div>
                  </div>

                  <div className="flex items-center gap-3">
                    {/* Avatares agrupados dos integrantes */}
                    <div className="flex -space-x-2">
                      {eq.membros.map((m) => (
                        <div key={m.id} className="relative">
                          {m.foto ? (
                            <img
                              src={m.foto}
                              alt={m.nome}
                              className="w-7 h-7 rounded-full object-cover border-2 border-card ring-1 ring-border/40"
                              onError={(e) => {
                                (e.target as HTMLImageElement).style.display = 'none';
                                const fallback = (e.target as HTMLElement).nextElementSibling;
                                if (fallback) fallback.classList.remove('hidden');
                              }}
                            />
                          ) : null}
                          <div
                            className={cn(
                              'w-7 h-7 rounded-full bg-muted border-2 border-card flex items-center justify-center text-[10px] font-bold text-foreground',
                              m.foto ? 'hidden' : 'flex'
                            )}
                          >
                            {getIniciais(m.nome)}
                          </div>
                        </div>
                      ))}
                    </div>

                    <div className="text-right text-xs">
                      <p className="font-bold text-foreground tabular-nums">
                        {eq.presentes} / {eq.totalMembros}
                      </p>
                      <p className="text-[10px] text-muted-foreground">operadores</p>
                    </div>

                    {isExpanded ? (
                      <ChevronUp className="w-4 h-4 text-muted-foreground" />
                    ) : (
                      <ChevronDown className="w-4 h-4 text-muted-foreground" />
                    )}
                  </div>
                </div>

                {isExpanded && (
                  <div className="px-4 pb-4 pt-2 border-t border-border/40 bg-muted/20 space-y-2">
                    <p className="text-[11px] font-bold text-muted-foreground uppercase tracking-wider">
                      Integrantes do Posto
                    </p>
                    <div className="space-y-1.5">
                      {eq.membros.map((m) => (
                        <div
                          key={m.id}
                          className="flex items-center justify-between p-2 rounded-xl bg-card/60 border border-border/50 text-xs"
                        >
                          <div className="flex items-center gap-2.5">
                            {/* Foto do Colaborador na Equipe */}
                            <div className="relative shrink-0">
                              {m.foto ? (
                                <img
                                  src={m.foto}
                                  alt={m.nome}
                                  className="w-8 h-8 rounded-full object-cover border border-border/80 ring-1 ring-border/40"
                                  onError={(e) => {
                                    (e.target as HTMLImageElement).style.display = 'none';
                                    const fallback = (e.target as HTMLElement).nextElementSibling;
                                    if (fallback) fallback.classList.remove('hidden');
                                  }}
                                />
                              ) : null}
                              <div
                                className={cn(
                                  'w-8 h-8 rounded-full bg-muted/90 border border-border/80 flex items-center justify-center text-[11px] font-bold text-foreground',
                                  m.foto ? 'hidden' : 'flex'
                                )}
                              >
                                {getIniciais(m.nome)}
                              </div>
                            </div>

                            <div>
                              <p className="font-semibold text-foreground">{m.nome}</p>
                              <p className="text-[11px] text-muted-foreground">{m.cargo}</p>
                            </div>
                          </div>

                          <Badge
                            variant="outline"
                            className={cn(
                              'text-[10px] px-2 py-0.5',
                              m.status === 'presente'
                                ? 'bg-emerald-500/10 text-emerald-400 border-emerald-500/30'
                                : m.status === 'falta'
                                ? 'bg-rose-500/10 text-rose-400 border-rose-500/30'
                                : 'bg-amber-500/10 text-amber-400 border-amber-500/30'
                            )}
                          >
                            {m.status === 'presente'
                              ? 'Presente'
                              : m.status === 'falta'
                              ? 'Falta'
                              : 'Substituto'}
                          </Badge>
                        </div>
                      ))}
                    </div>
                  </div>
                )}
              </Card>
            );
          })
        )}
      </div>
    </div>
  );
};

