import React, { useState } from 'react';
import {
  X,
  CheckCircle2,
  XCircle,
  Users,
  AlertCircle,
  FileText,
  UserCheck,
  UserX,
  ShieldCheck,
} from 'lucide-react';
import { Button } from './ui/button';
import { Badge } from './ui/badge';
import { Colaborador, StatusPresenca, MotivoFalta } from '../types';
import { cn } from '@/lib/utils';

export interface AttendanceModalProps {
  isOpen: boolean;
  onClose: () => void;
  colaborador: Colaborador;
  colaboradoresReserva?: Colaborador[];
  onSaveStatus?: (
    novoStatus: StatusPresenca,
    motivo?: MotivoFalta,
    obs?: string,
    substitutoId?: string
  ) => void;
  onSubstituir?: (substituto: Colaborador) => void;
}

const MOTIVOS_FALTA: MotivoFalta[] = [
  'Atestado Médico',
  'Falta Injustificada',
  'Folga Compensatória',
  'Treinamento / Integração',
  'Problema de Transporte',
  'Licença Especial',
];

const getIniciais = (nome?: string) => {
  if (!nome) return 'OP';
  const partes = nome.trim().split(' ');
  if (partes.length === 1) return partes[0].substring(0, 2).toUpperCase();
  return (partes[0][0] + partes[partes.length - 1][0]).toUpperCase();
};

export const AttendanceModal: React.FC<AttendanceModalProps> = ({
  isOpen,
  onClose,
  colaborador,
  colaboradoresReserva = [],
  onSaveStatus,
  onSubstituir,
}) => {
  if (!isOpen || !colaborador) return null;

  const [status, setStatus] = useState<StatusPresenca>(colaborador.status || 'presente');
  const [motivo, setMotivo] = useState<MotivoFalta | undefined>(colaborador.motivoFalta);
  const [observacao, setObservacao] = useState(colaborador.observacao || '');
  const [substitutoId, setSubstitutoId] = useState<string>(colaborador.substitutoId || '');

  const handleSalvar = () => {
    if (onSaveStatus) {
      onSaveStatus(status, status === 'falta' ? motivo : undefined, observacao, substitutoId);
    }

    if (status === 'substituto' && substitutoId && onSubstituir) {
      const sub = colaboradoresReserva.find((c) => c.id === substitutoId);
      if (sub) {
        onSubstituir(sub);
      }
    }

    onClose();
  };

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-background/80 backdrop-blur-md animate-in fade-in duration-150"
      onClick={onClose}
    >
      <div
        className="relative w-full max-w-lg bg-card border border-border/80 rounded-3xl shadow-2xl overflow-hidden animate-in zoom-in-95"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Header com Foto em Destaque e Nome do Colaborador */}
        <div className="px-6 py-5 border-b border-border/80 flex items-center justify-between bg-muted/20">
          <div className="flex items-center gap-3.5">
            <div className="relative shrink-0">
              {colaborador.foto ? (
                <img
                  src={colaborador.foto}
                  alt={colaborador.nome}
                  className="w-12 h-12 rounded-full object-cover border-2 border-emerald-500/40 shadow-md ring-1 ring-border/50"
                  onError={(e) => {
                    (e.target as HTMLImageElement).style.display = 'none';
                    const fallback = (e.target as HTMLElement).nextElementSibling;
                    if (fallback) fallback.classList.remove('hidden');
                  }}
                />
              ) : null}
              <div
                className={cn(
                  'w-12 h-12 rounded-full bg-muted/90 border-2 border-border/80 flex items-center justify-center text-sm font-bold text-foreground ring-1 ring-border/40',
                  colaborador.foto ? 'hidden' : 'flex'
                )}
              >
                {getIniciais(colaborador.nome)}
              </div>
            </div>

            <div>
              <h3 className="text-base font-bold text-foreground leading-tight">{colaborador.nome}</h3>
              <p className="text-xs text-muted-foreground mt-0.5">
                {colaborador.cargo} {colaborador.matricula && `· Matrícula: ${colaborador.matricula}`}
              </p>
            </div>
          </div>

          <button
            type="button"
            onClick={onClose}
            className="p-1.5 rounded-lg text-muted-foreground hover:text-foreground hover:bg-muted transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Corpo do Modal */}
        <div className="p-6 space-y-5">
          {/* Seleção de Status */}
          <div>
            <label className="text-xs font-semibold text-muted-foreground uppercase tracking-wider block mb-2">
              Status Operacional do Dia
            </label>
            <div className="grid grid-cols-3 gap-2.5">
              <button
                type="button"
                onClick={() => setStatus('presente')}
                className={cn(
                  'flex flex-col items-center justify-center gap-1.5 p-3 rounded-2xl border text-xs font-semibold transition-all',
                  status === 'presente'
                    ? 'bg-emerald-500/15 border-emerald-500 text-emerald-400 shadow-sm'
                    : 'border-border/60 text-muted-foreground hover:bg-muted/40'
                )}
              >
                <CheckCircle2 className="w-5 h-5 text-emerald-400" />
                <span>Presente</span>
              </button>

              <button
                type="button"
                onClick={() => setStatus('falta')}
                className={cn(
                  'flex flex-col items-center justify-center gap-1.5 p-3 rounded-2xl border text-xs font-semibold transition-all',
                  status === 'falta'
                    ? 'bg-rose-500/15 border-rose-500 text-rose-400 shadow-sm'
                    : 'border-border/60 text-muted-foreground hover:bg-muted/40'
                )}
              >
                <XCircle className="w-5 h-5 text-rose-400" />
                <span>Falta</span>
              </button>

              <button
                type="button"
                onClick={() => setStatus('substituto')}
                className={cn(
                  'flex flex-col items-center justify-center gap-1.5 p-3 rounded-2xl border text-xs font-semibold transition-all',
                  status === 'substituto'
                    ? 'bg-amber-500/15 border-amber-500 text-amber-400 shadow-sm'
                    : 'border-border/60 text-muted-foreground hover:bg-muted/40'
                )}
              >
                <Users className="w-5 h-5 text-amber-400" />
                <span>Substituto</span>
              </button>
            </div>
          </div>

          {/* Motivo da Falta (se falta) */}
          {status === 'falta' && (
            <div className="space-y-2 animate-in fade-in-50 duration-150">
              <label className="text-xs font-semibold text-muted-foreground uppercase tracking-wider block">
                Motivo do Desfalque *
              </label>
              <div className="grid grid-cols-2 gap-2">
                {MOTIVOS_FALTA.map((m) => (
                  <button
                    key={m}
                    type="button"
                    onClick={() => setMotivo(m)}
                    className={cn(
                      'p-2.5 rounded-xl border text-left text-xs font-medium transition-all',
                      motivo === m
                        ? 'bg-rose-500/15 border-rose-500 text-rose-300 shadow-sm'
                        : 'border-border/60 text-muted-foreground hover:bg-muted/40'
                    )}
                  >
                    {m}
                  </button>
                ))}
              </div>
            </div>
          )}

          {/* Selecionar Substituto do Banco de Reserva */}
          {status === 'substituto' && (
            <div className="space-y-2 animate-in fade-in-50 duration-150">
              <label className="text-xs font-semibold text-muted-foreground uppercase tracking-wider block">
                Selecionar Substituto (Banco de Reserva)
              </label>
              <select
                value={substitutoId}
                onChange={(e) => setSubstitutoId(e.target.value)}
                className="w-full h-10 px-3 rounded-xl border border-border/80 bg-background text-xs font-medium text-foreground focus:outline-none focus:ring-2 focus:ring-amber-500/30"
              >
                <option value="">Selecione um colaborador do banco...</option>
                {colaboradoresReserva.map((r) => (
                  <option key={r.id} value={r.id}>
                    {r.nome} - {r.cargo}
                  </option>
                ))}
              </select>
            </div>
          )}

          {/* Campo de Observação */}
          <div className="space-y-1.5">
            <label className="text-xs font-semibold text-muted-foreground uppercase tracking-wider block">
              Observações Adicionais
            </label>
            <textarea
              rows={2}
              value={observacao}
              onChange={(e) => setObservacao(e.target.value)}
              placeholder="Ex: Justificativa enviada pelo supervisor, previsão de retorno..."
              className="w-full rounded-xl border border-input bg-card/50 p-3 text-xs text-foreground placeholder:text-muted-foreground focus:outline-none focus:ring-2 focus:ring-emerald-500/30 resize-none"
            />
          </div>

          {/* Botões de Ação */}
          <div className="flex items-center justify-end gap-3 pt-3 border-t border-border/80">
            <Button type="button" variant="outline" onClick={onClose}>
              Cancelar
            </Button>
            <Button
              type="button"
              onClick={handleSalvar}
              className="bg-emerald-600 hover:bg-emerald-500 text-white font-bold"
            >
              Salvar Registro
            </Button>
          </div>
        </div>
      </div>
    </div>
  );
