    colaborador: Colaborador;
  } | null>(null);

  const veiculosFiltrados = (veiculos || []).filter((v) => {
    if (!v) return false;
    if (selectedRegional !== 'todas' && v.regional !== selectedRegional) return false;

    if (busca.trim()) {
      const q = busca.toLowerCase();
      const matchPrefixo = (v.prefixo || '').toLowerCase().includes(q);
      const matchPlaca = (v.placa || '').toLowerCase().includes(q);
      const matchColaboradores = [
        v.assentos?.motorista?.nome,
        v.assentos?.frenteDir?.nome,
        v.assentos?.trasEsq?.nome,
        v.assentos?.trasDir?.nome,
      ].some((nome) => (nome || '').toLowerCase().includes(q));

      if (!matchPrefixo && !matchPlaca && !matchColaboradores) return false;
    }

    if (filtroStatus === 'com_falta') {
      const temFalta = [
        v.assentos?.motorista?.status,
        v.assentos?.frenteDir?.status,
        v.assentos?.trasEsq?.status,
        v.assentos?.trasDir?.status,
      ].some((s) => s === 'falta');
      if (!temFalta) return false;
    }

    if (filtroStatus === 'completo') {
      const temFalta = [
        v.assentos?.motorista?.status,
        v.assentos?.frenteDir?.status,
        v.assentos?.trasEsq?.status,
        v.assentos?.trasDir?.status,
      ].some((s) => s === 'falta');
      if (temFalta) return false;
    }

    return true;
  });

  const abrirModalPresenca = (
    veiculoId: string,
    posicao: 'motorista' | 'frenteDir' | 'trasEsq' | 'trasDir',
    colaborador: Colaborador
  ) => {
    setColaboradorSelecionado({ veiculoId, posicao, colaborador });
    setModalAberto(true);
  };

  const renderAssento = (
    veiculoId: string,
    posicao: 'motorista' | 'frenteDir' | 'trasEsq' | 'trasDir',
    colaborador?: Colaborador,
    labelPosicao?: string
  ) => {
    if (!colaborador) {
      return (
        <div className="flex items-center justify-between p-2.5 rounded-xl border border-dashed border-border/60 bg-muted/20 text-xs text-muted-foreground">
          <span>Vago</span>
        </div>
      );
    }

    const st = statusConfig[colaborador.status] || statusConfig.presente;

    return (
      <button
        type="button"
        onClick={() => abrirModalPresenca(veiculoId, posicao, colaborador)}
        className={cn(
          'w-full text-left p-2.5 rounded-xl border transition-all duration-150 flex items-center justify-between gap-3 group relative overflow-hidden',
          colaborador.status === 'falta'
            ? 'border-rose-500/40 bg-rose-500/5 hover:bg-rose-500/10 hover:border-rose-500/60'
            : colaborador.status === 'substituto'
            ? 'border-amber-500/40 bg-amber-500/5 hover:bg-amber-500/10 hover:border-amber-500/60'
            : 'border-border/60 bg-card/60 hover:bg-card hover:border-emerald-500/40'
        )}
      >
        <div className="flex items-center gap-2.5 min-w-0">
          {/* Avatar com foto real do colaborador ou fallback elegante */}
          <div className="relative shrink-0">
            {colaborador.foto ? (
              <img
                src={colaborador.foto}
                alt={colaborador.nome}
                className="w-9 h-9 rounded-full object-cover border border-border/80 shadow-sm ring-1 ring-border/40"
                onError={(e) => {
                  (e.target as HTMLImageElement).style.display = 'none';
                  const fallback = (e.target as HTMLElement).nextElementSibling;
                  if (fallback) fallback.classList.remove('hidden');
                }}
              />
            ) : null}
            <div
              className={cn(
                'w-9 h-9 rounded-full bg-muted/80 border border-border/80 flex items-center justify-center text-xs font-bold text-foreground ring-1 ring-border/40',
                colaborador.foto ? 'hidden' : 'flex'
              )}
            >
              {getIniciais(colaborador.nome)}
            </div>
            <span
              className={cn(
                'absolute -bottom-0.5 -right-0.5 w-3 h-3 rounded-full border-2 border-background',
                st.dot
              )}
            />
          </div>

          <div className="min-w-0 flex-1">
            <div className="flex items-center gap-1.5">
              <p className="text-xs font-semibold text-foreground truncate group-hover:text-emerald-300 transition-colors">
                {colaborador.nome}
              </p>
            </div>
            <p className="text-[11px] text-muted-foreground truncate">
              {colaborador.cargo || 'Operador'}
            </p>
            {labelPosicao && (
              <span className="text-[10px] text-muted-foreground/80 font-medium">
                {labelPosicao}
              </span>
            )}
          </div>
        </div>

        <div className="flex flex-col items-end gap-1 shrink-0">
          <Badge
            variant="outline"
            className={cn('text-[10px] px-2 py-0.5 font-medium border', st.bg, st.text)}
          >
            {st.label}
          </Badge>
          {colaborador.motivoFalta && colaborador.status === 'falta' && (
            <span className="text-[10px] text-rose-400 font-medium max-w-[90px] truncate text-right">
              {colaborador.motivoFalta}
            </span>
          )}
          {colaborador.substitutoNome && colaborador.status === 'substituto' && (
            <span className="text-[10px] text-amber-400 font-medium max-w-[90px] truncate text-right">
              Sub: {colaborador.substitutoNome}
            </span>
          )}
        </div>
      </button>
    );
  };

  return (
    <div className="space-y-4">
      {/* Barra de Filtros e Busca */}
      <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3 bg-card/60 p-3 rounded-2xl border border-border/60 backdrop-blur-md">
        <div className="relative flex-1">
          <Search className="w-4 h-4 text-muted-foreground absolute left-3 top-1/2 -translate-y-1/2" />
          <Input
            placeholder="Buscar veículo, placa ou colaborador pelo nome..."
            value={busca}
            onChange={(e) => setBusca(e.target.value)}
            className="pl-9 h-9 text-xs bg-background/50 border-border/60"
          />
        </div>

        <div className="flex items-center gap-2">
          <button
            type="button"
            onClick={() => setFiltroStatus('todos')}
            className={cn(
              'px-3 py-1.5 rounded-xl text-xs font-semibold border transition-all',
              filtroStatus === 'todos'
                ? 'bg-primary text-primary-foreground border-primary shadow-sm'
                : 'border-border/60 text-muted-foreground hover:bg-muted/40'
            )}
          >
            Todos ({veiculos.length})
          </button>
          <button
            type="button"
            onClick={() => setFiltroStatus('com_falta')}
            className={cn(
              'px-3 py-1.5 rounded-xl text-xs font-semibold border transition-all flex items-center gap-1.5',
              filtroStatus === 'com_falta'
                ? 'bg-rose-600 text-white border-rose-500 shadow-sm'
                : 'border-border/60 text-rose-400 hover:bg-rose-500/10'
            )}
          >
            <UserX className="w-3.5 h-3.5" />
            Com Faltas
          </button>
          <button
            type="button"
            onClick={() => setFiltroStatus('completo')}
            className={cn(
              'px-3 py-1.5 rounded-xl text-xs font-semibold border transition-all flex items-center gap-1.5',
              filtroStatus === 'completo'
                ? 'bg-emerald-600 text-white border-emerald-500 shadow-sm'
                : 'border-border/60 text-emerald-400 hover:bg-emerald-500/10'
            )}
          >
            <UserCheck className="w-3.5 h-3.5" />
            Completos
          </button>
        </div>
      </div>

      {/* Grid de Veículos */}
      {veiculosFiltrados.length === 0 ? (
        <div className="py-16 text-center rounded-2xl border border-dashed border-border/60 bg-card/20">
          <Car className="w-10 h-10 text-muted-foreground mx-auto mb-2 opacity-50" />
          <p className="text-sm font-semibold text-foreground">Nenhum veículo encontrado</p>
          <p className="text-xs text-muted-foreground mt-1">
            Tente ajustar os termos de pesquisa ou selecionar outra unidade.
          </p>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {veiculosFiltrados.map((veiculo) => {
            const faltasNoVeiculo = [
              veiculo.assentos?.motorista?.status,
              veiculo.assentos?.frenteDir?.status,
              veiculo.assentos?.trasEsq?.status,
              veiculo.assentos?.trasDir?.status,
            ].filter((s) => s === 'falta').length;

            return (
              <Card
                key={veiculo.id}
                className={cn(
                  'border transition-all duration-200 overflow-hidden shadow-md flex flex-col',
                  faltasNoVeiculo > 0
                    ? 'border-rose-500/30 bg-card/70'
                    : 'border-border/60 bg-card/50 hover:border-emerald-500/30'
                )}
              >
                {/* Header do Card com Prefixo e Placa */}
                <div className="px-4 py-3 border-b border-border/40 bg-muted/20 flex items-center justify-between">
                  <div className="flex items-center gap-2.5">
                    <div className="w-8 h-8 rounded-xl bg-emerald-500/15 border border-emerald-500/30 flex items-center justify-center shrink-0">
                      <Car className="w-4 h-4 text-emerald-400" />
                    </div>
                    <div>
                      <h4 className="text-sm font-bold text-foreground flex items-center gap-2">
                        {veiculo.prefixo}
                        <span className="text-[11px] font-mono font-medium text-muted-foreground px-1.5 py-0.5 rounded bg-muted border border-border/50">
                          {veiculo.placa}
                        </span>
                      </h4>
                      <p className="text-[11px] text-muted-foreground">
                        {veiculo.modelo} · {veiculo.regional === 'ribas' ? 'Ribas' : 'Água Clara'}
                      </p>
                    </div>
                  </div>

                  {faltasNoVeiculo > 0 ? (
                    <Badge variant="destructive" className="text-[10px] px-2 py-0.5 font-bold">
                      {faltasNoVeiculo} {faltasNoVeiculo === 1 ? 'Falta' : 'Faltas'}
                    </Badge>
                  ) : (
                    <Badge variant="success" className="text-[10px] px-2 py-0.5 font-bold">
                      Completo
                    </Badge>
                  )}
                </div>

                {/* Conteúdo com Assentos e Equipes */}
                <div className="p-4 space-y-3 flex-1 flex flex-col justify-between">
                  {/* Equipe 1: Dianteira */}
                  <div className="space-y-1.5">
                    <div className="flex items-center justify-between text-[11px] font-bold text-emerald-400/90 uppercase tracking-wider px-1">
                      <span>Equipe 1 · Frente</span>
                      <span className="text-muted-foreground font-normal lowercase">
                        {veiculo.equipe1Codigo || 'eq. 1'}
                      </span>
                    </div>
                    <div className="space-y-1.5">
                      {renderAssento(
                        veiculo.id,
                        'motorista',
                        veiculo.assentos?.motorista,
                        'Motorista'
                      )}
                      {renderAssento(
                        veiculo.id,
                        'frenteDir',
                        veiculo.assentos?.frenteDir,
                        'Passageiro Dianteiro'
                      )}
                    </div>
                  </div>

                  {/* Divisória sutil */}
                  <div className="border-t border-border/40 my-1" />

                  {/* Equipe 2: Traseira */}
                  <div className="space-y-1.5">
                    <div className="flex items-center justify-between text-[11px] font-bold text-teal-400/90 uppercase tracking-wider px-1">
                      <span>Equipe 2 · Traseira</span>
                      <span className="text-muted-foreground font-normal lowercase">
                        {veiculo.equipe2Codigo || 'eq. 2'}
                      </span>
                    </div>
                    <div className="space-y-1.5">
                      {renderAssento(
                        veiculo.id,
                        'trasEsq',
                        veiculo.assentos?.trasEsq,
                        'Traseiro Esquerdo'
                      )}
                      {renderAssento(
                        veiculo.id,
                        'trasDir',
                        veiculo.assentos?.trasDir,
                        'Traseiro Direito'
                      )}
                    </div>
                  </div>
                </div>
              </Card>
            );
          })}
        </div>
      )}

      {/* Modal de Gestão de Presença com Foto e Dados */}
      {modalAberto && colaboradorSelecionado && (
        <AttendanceModal
          isOpen={modalAberto}
          onClose={() => {
            setModalAberto(false);
            setColaboradorSelecionado(null);
          }}
          colaborador={colaboradorSelecionado.colaborador}
          colaboradoresReserva={colaboradoresReserva}
          onSaveStatus={(novoStatus, motivo, obs, substitutoId) => {
            if (onUpdateStatus) {
              onUpdateStatus(
                colaboradorSelecionado.veiculoId,
                colaboradorSelecionado.posicao,
                novoStatus,
                motivo,
                obs,
                substitutoId
              );
            }
            setModalAberto(false);
            setColaboradorSelecionado(null);
          }}
          onSubstituir={(substituto) => {
            if (onSubstituirColaborador) {
              onSubstituirColaborador(
                colaboradorSelecionado.veiculoId,
                colaboradorSelecionado.posicao,
                substituto
              );
            }
            setModalAberto(false);
            setColaboradorSelecionado(null);
          }}
        />
      )}
    </div>
  );
};

