import React, { useState } from 'react';
import {
  X,
  User,
  CheckCircle2,
  XCircle,
  HelpCircle,
  AlertTriangle,
  UserCheck,
  Calendar,
  Phone,
  Briefcase,
  IdCard,
} from 'lucide-react';
import { Button } from './ui/button';
import { Badge } from './ui/badge';
import { Colaborador, StatusPresenca, MotivoFalta } from '../types';
import { cn } from '@/lib/utils';

export interface AttendanceModalProps {
  isOpen: boolean;
  onClose: () => void;
  colaborador?: Colaborador | null;
  veiculoPrefixo?: string;
  onSave?: (status: StatusPresenca, motivo?: MotivoFalta, obs?: string, substitutoId?: string) => void;
  onSalvar?: (status: StatusPresenca, motivo?: MotivoFalta, obs?: string, substitutoId?: string) => void;
  colaboradoresReserva?: Colaborador[];
}

const MOTIVOS_FALTA: MotivoFalta[] = [
  'Atestado Médico',
  'Falta Injustificada',
  'Folga Compensatória',
  'Treinamento / Integração',
  'Problema de Transporte',
  'Licença Especial',
];

const getIniciais = (nome?: string) => {
  if (!nome) return 'CO';
  const partes = nome.trim().split(' ');
  if (partes.length === 1) return partes[0].substring(0, 2).toUpperCase();
  return (partes[0][0] + partes[partes.length - 1][0]).toUpperCase();
};

export const AttendanceModal: React.FC<AttendanceModalProps> = ({
  isOpen,
  onClose,
  colaborador,
  veiculoPrefixo,
  onSave,
  onSalvar,
  colaboradoresReserva = [],
}) => {
  const [status, setStatus] = useState<StatusPresenca>(colaborador?.status || 'presente');
  const [motivo, setMotivo] = useState<MotivoFalta | undefined>(colaborador?.motivoFalta);
  const [observacao, setObservacao] = useState(colaborador?.observacao || '');
  const [substitutoId, setSubstitutoId] = useState(colaborador?.substitutoId || '');

  React.useEffect(() => {
    if (colaborador) {
      setStatus(colaborador.status || 'presente');
      setMotivo(colaborador.motivoFalta);
      setObservacao(colaborador.observacao || '');
      setSubstitutoId(colaborador.substitutoId || '');
    }
  }, [colaborador]);

  if (!isOpen || !colaborador) return null;

  const handleSalvar = () => {
    const fn = onSave || onSalvar;
    if (fn) {
      fn(status, status === 'falta' ? motivo : undefined, observacao, status === 'substituto' ? substitutoId : undefined);
    }
    onClose();
  };

  const getStatusBorderColor = () => {
    if (status === 'presente') return 'ring-emerald-500 shadow-emerald-500/20';
    if (status === 'falta') return 'ring-rose-500 shadow-rose-500/20';
    return 'ring-amber-500 shadow-amber-500/20';
  };

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-background/80 backdrop-blur-md animate-in fade-in duration-200"
      onClick={onClose}
    >
      <div
        className="relative w-full max-w-lg bg-card border border-border/80 rounded-3xl shadow-2xl overflow-hidden"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="flex items-center justify-between px-6 py-4 border-b border-border/60 bg-muted/20">
          <div>
            <h3 className="text-base font-bold text-foreground">Registro de Frequência do Colaborador</h3>
            <p className="text-xs text-muted-foreground">Posto no {veiculoPrefixo || 'Veículo da Frente'}</p>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="p-1.5 rounded-xl text-muted-foreground hover:text-foreground hover:bg-muted transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Ênfase especial na Foto do Colaborador com Card de Perfil */}
        <div className="px-6 pt-6 pb-4 bg-gradient-to-b from-muted/30 to-transparent">
          <div className="flex flex-col sm:flex-row items-center gap-5 p-4 rounded-2xl border border-border/70 bg-card/90 shadow-md">
            <div className="relative group shrink-0">
              <div
                className={cn(
                  'w-24 h-24 rounded-2xl overflow-hidden border-2 ring-4 transition-all duration-300 shadow-xl flex items-center justify-center bg-gradient-to-br from-muted to-muted/40',
                  getStatusBorderColor()
                )}
              >
                {colaborador.foto ? (
                  <img
                    src={colaborador.foto}
                    alt={colaborador.nome}
                    className="w-full h-full object-cover object-center group-hover:scale-105 transition-transform duration-300"
                  />
                ) : (
                  <div className="w-full h-full flex flex-col items-center justify-center bg-emerald-950/40 text-emerald-300">
                    <span className="text-2xl font-black tracking-tight">{getIniciais(colaborador.nome)}</span>
                  </div>
                )}
              </div>

              {/* Status Badge flutuante na foto */}
              <div className="absolute -bottom-2 -right-2">
                {status === 'presente' && (
                  <span className="inline-flex items-center justify-center w-7 h-7 rounded-full bg-emerald-500 text-white shadow-md ring-2 ring-background">
                    <CheckCircle2 className="w-4 h-4" />
                  </span>
                )}
                {status === 'falta' && (
                  <span className="inline-flex items-center justify-center w-7 h-7 rounded-full bg-rose-500 text-white shadow-md ring-2 ring-background">
                    <XCircle className="w-4 h-4" />
                  </span>
                )}
                {status === 'substituto' && (
                  <span className="inline-flex items-center justify-center w-7 h-7 rounded-full bg-amber-500 text-white shadow-md ring-2 ring-background">
                    <UserCheck className="w-4 h-4" />
                  </span>
                )}
              </div>
            </div>

            <div className="flex-1 text-center sm:text-left space-y-1">
              <h4 className="text-lg font-extrabold text-foreground tracking-tight">{colaborador.nome}</h4>
              <div className="flex items-center justify-center sm:justify-start gap-2 text-xs text-muted-foreground flex-wrap">
                <span className="flex items-center gap-1 font-medium">
                  <Briefcase className="w-3.5 h-3.5 text-emerald-400" />
                  {colaborador.cargo}
                </span>
                <span>•</span>
                <span className="flex items-center gap-1 font-medium tabular-nums">
                  <IdCard className="w-3.5 h-3.5 text-muted-foreground" />
                  Matrícula: {colaborador.matricula || '---'}
                </span>
              </div>
              {colaborador.telefone && (
                <p className="text-xs text-muted-foreground/80 flex items-center justify-center sm:justify-start gap-1">
                  <Phone className="w-3 h-3 text-muted-foreground" />
                  {colaborador.telefone}
                </p>
              )}
            </div>
          </div>
        </div>

        {/* Seleção de Status */}
        <div className="p-6 pt-2 space-y-5">
          <div>
            <label className="text-xs font-bold text-muted-foreground uppercase tracking-wider block mb-2">
              Status do Dia
            </label>
            <div className="grid grid-cols-3 gap-2">
              <button
                type="button"
                onClick={() => setStatus('presente')}
                className={cn(
                  'flex flex-col items-center justify-center p-3 rounded-2xl border text-xs font-bold transition-all',
                  status === 'presente'
                    ? 'bg-emerald-500/15 border-emerald-500 text-emerald-400 shadow-sm ring-1 ring-emerald-500/30'
                    : 'border-border/70 text-muted-foreground hover:bg-muted/50'
                )}
              >
                <CheckCircle2 className="w-5 h-5 mb-1 text-emerald-400" />
                Presente
              </button>

              <button
                type="button"
                onClick={() => setStatus('falta')}
                className={cn(
                  'flex flex-col items-center justify-center p-3 rounded-2xl border text-xs font-bold transition-all',
                  status === 'falta'
                    ? 'bg-rose-500/15 border-rose-500 text-rose-400 shadow-sm ring-1 ring-rose-500/30'
                    : 'border-border/70 text-muted-foreground hover:bg-muted/50'
                )}
              >
                <XCircle className="w-5 h-5 mb-1 text-rose-400" />
                Falta
              </button>

              <button
                type="button"
                onClick={() => setStatus('substituto')}
                className={cn(
                  'flex flex-col items-center justify-center p-3 rounded-2xl border text-xs font-bold transition-all',
                  status === 'substituto'
                    ? 'bg-amber-500/15 border-amber-500 text-amber-400 shadow-sm ring-1 ring-amber-500/30'
                    : 'border-border/70 text-muted-foreground hover:bg-muted/50'
                )}
              >
                <UserCheck className="w-5 h-5 mb-1 text-amber-400" />
                Substituto
              </button>
            </div>
          </div>

          {status === 'falta' && (
            <div className="space-y-2 animate-in fade-in duration-150">
              <label className="text-xs font-bold text-muted-foreground uppercase tracking-wider block">
                Motivo da Ausência / Falta
              </label>
              <select
                value={motivo || ''}
                onChange={(e) => setMotivo(e.target.value as MotivoFalta)}
                className="w-full h-10 px-3 rounded-xl border border-border/80 bg-background text-sm text-foreground focus:outline-none focus:ring-2 focus:ring-emerald-500/30"
              >
                <option value="">Selecione o motivo...</option>
                {MOTIVOS_FALTA.map((m) => (
                  <option key={m} value={m}>
                    {m}
                  </option>
                ))}
              </select>
            </div>
          )}

          {status === 'substituto' && (
            <div className="space-y-2 animate-in fade-in duration-150">
              <label className="text-xs font-bold text-muted-foreground uppercase tracking-wider block">
                Selecione o Colaborador Reserva para Assumir o Posto
              </label>
              <select
                value={substitutoId}
                onChange={(e) => setSubstitutoId(e.target.value)}
                className="w-full h-10 px-3 rounded-xl border border-border/80 bg-background text-sm text-foreground focus:outline-none focus:ring-2 focus:ring-emerald-500/30"
              >
                <option value="">Escolha um operador do banco de reserva...</option>
                {colaboradoresReserva.map((res) => (
                  <option key={res.id} value={res.id}>
                    {res.nome} — {res.cargo}
                  </option>
                ))}
              </select>
            </div>
          )}

          <div className="space-y-2">
            <label className="text-xs font-bold text-muted-foreground uppercase tracking-wider block">
              Observações Operacionais
            </label>
            <textarea
              value={observacao}
              onChange={(e) => setObservacao(e.target.value)}
              placeholder="Descreva observações, horário de aviso, justificativas ou detalhes da frente..."
              className="w-full min-h-[75px] p-3 rounded-xl border border-border/80 bg-background text-sm text-foreground placeholder:text-muted-foreground focus:outline-none focus:ring-2 focus:ring-emerald-500/30"
            />
          </div>

          <div className="flex items-center justify-end gap-3 pt-3 border-t border-border/60">
            <Button type="button" variant="outline" onClick={onClose} className="rounded-xl">
              Cancelar
            </Button>
            <Button
              type="button"
              onClick={handleSalvar}
              className="rounded-xl bg-emerald-600 hover:bg-emerald-500 text-white font-bold px-5"
            >
              Confirmar e Salvar
            </Button>
          </div>
        </div>
      </div>
    </div>
  );
};

