import React, { useState } from 'react';
import {
  Car,
  AlertTriangle,
  CheckCircle2,
  XCircle,
  HelpCircle,
  Search,
  Filter,
  Eye,
  Disc,
  Users,
  Compass,
  Sparkles,
} from 'lucide-react';
import { Veiculo, Colaborador, StatusPresenca, MotivoFalta, Regional } from '../types';
import { AttendanceModal } from './AttendanceModal';
import { Badge } from './ui/badge';
import { Input } from './ui/input';
import { cn } from '@/lib/utils';

export interface VehicleCardGridProps {
  veiculos?: Veiculo[];
  colaboradoresReserva?: Colaborador[];
  selectedRegional?: Regional;
  onUpdateColaboradorStatus?: (
    colaboradorId: string,
    novoStatus: StatusPresenca,
    motivo?: MotivoFalta,
    observacao?: string,
    substitutoId?: string,
    substitutoNome?: string
  ) => void;
}

const statusBadgeConfig: Record<StatusPresenca, { label: string; bg: string; text: string; border: string; ring: string }> = {
  presente: {
    label: 'Presente',
    bg: 'bg-emerald-500/20',
    text: 'text-emerald-400',
    border: 'border-emerald-500/40',
    ring: 'ring-emerald-500/40',
  },
  falta: {
    label: 'Falta',
    bg: 'bg-rose-500/20',
    text: 'text-rose-400',
    border: 'border-rose-500/40',
    ring: 'ring-rose-500/40',
  },
  substituto: {
    label: 'Substituto',
    bg: 'bg-amber-500/20',
    text: 'text-amber-400',
    border: 'border-amber-500/40',
    ring: 'ring-amber-500/40',
  },
};

const getIniciais = (nome?: string) => {
  if (!nome) return 'OP';
  const partes = nome.trim().split(' ');
  if (partes.length === 1) return partes[0].substring(0, 2).toUpperCase();
  return (partes[0][0] + partes[partes.length - 1][0]).toUpperCase();
};

export const VehicleCardGrid: React.FC<VehicleCardGridProps> = ({
  veiculos = [],
  colaboradoresReserva = [],
  selectedRegional = 'todas',
  onUpdateColaboradorStatus,
}) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [filtroStatus, setFiltroStatus] = useState<string>('todos');
  const [filtroRegional, setFiltroRegional] = useState<Regional | 'todas'>(selectedRegional);
  const [modalOpen, setModalOpen] = useState(false);
  const [selectedColaborador, setSelectedColaborador] = useState<Colaborador | null>(null);
  const [fotoZoom, setFotoZoom] = useState<{ url: string; nome: string; cargo: string } | null>(null);

  const veiculosSeguros = veiculos || [];

  const veiculosFiltrados = veiculosSeguros.filter((veiculo) => {
    if (!veiculo) return false;

    const termo = searchTerm.toLowerCase();
    const matchTermo =
      !termo ||
      veiculo.prefixo.toLowerCase().includes(termo) ||
      veiculo.placa.toLowerCase().includes(termo) ||
      veiculo.modelo.toLowerCase().includes(termo) ||
      veiculo.equipe1Codigo.toLowerCase().includes(termo) ||
      veiculo.equipe2Codigo.toLowerCase().includes(termo) ||
      [
        veiculo.assentos?.motorista?.nome,
        veiculo.assentos?.frenteDir?.nome,
        veiculo.assentos?.trasEsq?.nome,
        veiculo.assentos?.trasDir?.nome,
      ].some((nome) => (nome || '').toLowerCase().includes(termo));

    const matchRegional = filtroRegional === 'todas' || veiculo.regional === filtroRegional;

    let matchStatus = true;
    if (filtroStatus === 'incompletos') {
      const temFalta = [
        veiculo.assentos?.motorista?.status,
        veiculo.assentos?.frenteDir?.status,
        veiculo.assentos?.trasEsq?.status,
        veiculo.assentos?.trasDir?.status,
      ].some((st) => st === 'falta');
      matchStatus = temFalta;
    } else if (filtroStatus === 'completos') {
      const todosPresentes = [
        veiculo.assentos?.motorista?.status,
        veiculo.assentos?.frenteDir?.status,
        veiculo.assentos?.trasEsq?.status,
        veiculo.assentos?.trasDir?.status,
      ].every((st) => st === 'presente' || st === 'substituto');
      matchStatus = todosPresentes;
    }

    return matchTermo && matchRegional && matchStatus;
  });

  const handleCardClick = (colaborador: Colaborador) => {
    if (!colaborador) return;
    setSelectedColaborador(colaborador);
    setModalOpen(true);
  };

  const handleSaveAttendance = (
    colaboradorId: string,
    novoStatus: StatusPresenca,
    motivo?: MotivoFalta,
    observacao?: string,
    substitutoId?: string,
    substitutoNome?: string
  ) => {
    if (onUpdateColaboradorStatus) {
      onUpdateColaboradorStatus(colaboradorId, novoStatus, motivo, observacao, substitutoId, substitutoNome);
    }
  };

  // Renderizador do assento do carro com ocupante
  const renderAssentoCarro = (
    colaborador: Colaborador | undefined,
    posicaoTitulo: string,
    posicaoTipo: 'motorista' | 'passageiro' | 'traseira_esq' | 'traseira_dir',
    equipeRotulo: string,
    equipeNumero: 1 | 2
  ) => {
    if (!colaborador) {
      return (
        <div className="relative rounded-2xl border-2 border-dashed border-border/50 bg-background/40 p-4 flex flex-col items-center justify-center min-h-[170px] text-center">
          <div className="w-12 h-12 rounded-full border border-border/40 bg-muted/20 flex items-center justify-center text-muted-foreground/50 mb-2">
            <HelpCircle className="w-5 h-5" />
          </div>
          <span className="text-xs font-semibold text-muted-foreground">Assento Vago</span>
          <span className="text-[10px] text-muted-foreground/70 mt-0.5">{posicaoTitulo}</span>
        </div>
      );
    }

    const cfg = statusBadgeConfig[colaborador.status || 'presente'];
    const isMotorista = posicaoTipo === 'motorista';
    const isFalta = colaborador.status === 'falta';

    return (
      <div
        onClick={() => handleCardClick(colaborador)}
        className={cn(
          'group relative flex flex-col items-center justify-between p-3.5 rounded-2xl border transition-all duration-200 cursor-pointer select-none',
          'bg-gradient-to-b from-card/90 via-card/60 to-background/90 hover:shadow-xl hover:-translate-y-0.5',
          isFalta
            ? 'border-rose-500/40 hover:border-rose-400/80 shadow-rose-950/20'
            : colaborador.status === 'substituto'
            ? 'border-amber-500/40 hover:border-amber-400/80 shadow-amber-950/20'
            : 'border-border/70 hover:border-emerald-500/50 shadow-black/20'
        )}
      >
        {/* Encosto do Banco de Carro (Simulação de Assento Automotivo) */}
        <div className="absolute top-2 inset-x-5 h-2 rounded-t-lg bg-border/40 pointer-events-none opacity-60 group-hover:bg-primary/30 transition-colors" />

        {/* Indicador de Posição & Volante se for motorista */}
        <div className="w-full flex items-center justify-between gap-1 mb-2">
          <div className="flex items-center gap-1.5">
            {isMotorista ? (
              <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-md bg-emerald-500/15 border border-emerald-500/30 text-[10px] font-bold text-emerald-400">
                <Disc className="w-3 h-3 text-emerald-400 animate-pulse" />
                Motorista
              </span>
            ) : (
              <span className="text-[10px] font-semibold text-muted-foreground px-2 py-0.5 rounded-md bg-muted/40 border border-border/40">
                {posicaoTitulo}
              </span>
            )}
          </div>

          <span
            className={cn(
              'text-[9px] font-extrabold uppercase px-1.5 py-0.5 rounded border',
              equipeNumero === 1
                ? 'bg-sky-500/10 text-sky-400 border-sky-500/25'
                : 'bg-emerald-500/10 text-emerald-400 border-emerald-500/25'
            )}
          >
            EQ {equipeNumero}
          </span>
        </div>

        {/* Foto em Máximo Destaque sentada no Assento */}
        <div className="relative my-1">
          {/* Silhueta do Assento com encosto de cabeça */}
          <div className="absolute -top-3 left-1/2 -translate-x-1/2 w-14 h-4 rounded-t-xl bg-muted/70 border border-border/60 pointer-events-none" />

          <div
            className={cn(
              'relative w-20 h-20 sm:w-22 sm:h-22 rounded-2xl p-1 bg-background shadow-md border-2 transition-all duration-200 group-hover:scale-105',
              isFalta
                ? 'border-rose-500 ring-4 ring-rose-500/20'
                : colaborador.status === 'substituto'
                ? 'border-amber-500 ring-4 ring-amber-500/20'
                : 'border-emerald-500 ring-4 ring-emerald-500/20'
            )}
          >
            {colaborador.foto ? (
              <img
                src={colaborador.foto}
                alt={colaborador.nome}
                className="w-full h-full object-cover rounded-xl"
                onError={(e) => {
                  (e.target as HTMLImageElement).style.display = 'none';
                }}
              />
            ) : (
              <div className="w-full h-full rounded-xl bg-gradient-to-br from-muted to-muted/60 flex items-center justify-center font-black text-sm text-foreground">
                {getIniciais(colaborador.nome)}
              </div>
            )}

            {/* Ícone de status sobreposto no assento */}
            <div
              className={cn(
                'absolute -bottom-1.5 -right-1.5 w-6 h-6 rounded-full flex items-center justify-center shadow-md border-2 border-background',
                isFalta
                  ? 'bg-rose-500 text-white'
                  : colaborador.status === 'substituto'
                  ? 'bg-amber-500 text-black'
                  : 'bg-emerald-500 text-white'
              )}
            >
              {isFalta ? (
                <XCircle className="w-3.5 h-3.5" />
              ) : colaborador.status === 'substituto' ? (
                <AlertTriangle className="w-3.5 h-3.5" />
              ) : (
                <CheckCircle2 className="w-3.5 h-3.5" />
              )}
            </div>

            {/* Botão sutil de zoom da foto */}
            {colaborador.foto && (
              <button
                type="button"
                onClick={(e) => {
                  e.stopPropagation();
                  setFotoZoom({
                    url: colaborador.foto,
                    nome: colaborador.nome,
                    cargo: colaborador.cargo,
                  });
                }}
                className="absolute -top-1.5 -right-1.5 w-6 h-6 rounded-full bg-card/90 border border-border/80 text-foreground flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity shadow-sm hover:scale-110"
                title="Ampliar foto"
              >
                <Eye className="w-3 h-3 text-emerald-400" />
              </button>
            )}
          </div>
        </div>

        {/* Informações do Tripulante */}
        <div className="w-full text-center mt-2 space-y-1">
          <p className="text-xs font-bold text-foreground truncate group-hover:text-emerald-400 transition-colors">
            {colaborador.nome}
          </p>
          <p className="text-[11px] text-muted-foreground truncate">{colaborador.cargo}</p>

          {/* Badge de Presença */}
          <div className="pt-1 flex items-center justify-center">
            <span
              className={cn(
                'inline-flex items-center gap-1 px-2.5 py-0.5 rounded-full border text-[10px] font-bold uppercase tracking-wider',
                cfg.bg,
                cfg.text,
                cfg.border
              )}
            >
              <span className={cn('w-1.5 h-1.5 rounded-full', isFalta ? 'bg-rose-400' : colaborador.status === 'substituto' ? 'bg-amber-400' : 'bg-emerald-400')} />
              {cfg.label}
            </span>
          </div>

          {isFalta && colaborador.motivoFalta && (
            <p className="text-[10px] text-rose-400 font-medium truncate bg-rose-500/10 px-2 py-0.5 rounded-md border border-rose-500/20">
              {colaborador.motivoFalta}
            </p>
          )}

          {colaborador.status === 'substituto' && colaborador.substitutoNome && (
            <p className="text-[10px] text-amber-400 font-medium truncate bg-amber-500/10 px-2 py-0.5 rounded-md border border-amber-500/20">
              Subst: {colaborador.substitutoNome}
            </p>
          )}
        </div>
      </div>
    );
  };

  return (
    <div className="space-y-6">
      {/* Barra de Filtros e Busca Rápida */}
      <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3 bg-card/60 p-4 rounded-3xl border border-border/60 backdrop-blur-md shadow-lg">
        <div className="relative flex-1">
          <Search className="w-4 h-4 text-muted-foreground absolute left-3.5 top-1/2 -translate-y-1/2" />
          <Input
            placeholder="Buscar veículo, placa, equipe ou operador sentado..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="pl-9 h-10 text-xs bg-background/60 border-border/60 rounded-2xl"
          />
        </div>

        <div className="flex items-center gap-2 flex-wrap">
          <div className="flex items-center gap-1 bg-background/50 p-1 rounded-2xl border border-border/60">
            <button
              type="button"
              onClick={() => setFiltroStatus('todos')}
              className={cn(
                'px-3 py-1.5 text-xs font-semibold rounded-xl transition-all',
                filtroStatus === 'todos' ? 'bg-primary text-primary-foreground shadow-sm' : 'text-muted-foreground hover:text-foreground'
              )}
            >
              Todos ({veiculosSeguros.length})
            </button>
            <button
              type="button"
              onClick={() => setFiltroStatus('completos')}
              className={cn(
                'px-3 py-1.5 text-xs font-semibold rounded-xl transition-all',
                filtroStatus === 'completos' ? 'bg-emerald-600 text-white shadow-sm' : 'text-muted-foreground hover:text-foreground'
              )}
            >
              Cheios
            </button>
            <button
              type="button"
              onClick={() => setFiltroStatus('incompletos')}
              className={cn(
                'px-3 py-1.5 text-xs font-semibold rounded-xl transition-all',
                filtroStatus === 'incompletos' ? 'bg-rose-600 text-white shadow-sm' : 'text-muted-foreground hover:text-foreground'
              )}
            >
              Com Falta
            </button>
          </div>

          <select
            value={filtroRegional}
            onChange={(e) => setFiltroRegional(e.target.value as any)}
            className="h-10 px-3 rounded-2xl border border-border/60 bg-background/50 text-xs font-semibold text-foreground focus:outline-none focus:ring-2 focus:ring-emerald-500/30"
          >
            <option value="todas">Todas Unidades</option>
            <option value="ribas">Ribas do Rio Pardo</option>
            <option value="agua_clara">Água Clara</option>
          </select>
        </div>
      </div>

      {/* Grid de Veículos Estilo Interior de Carro 4x4 */}
      {veiculosFiltrados.length === 0 ? (
        <div className="py-16 text-center rounded-3xl border border-dashed border-border/70 bg-card/20 space-y-3">
          <Car className="w-10 h-10 text-muted-foreground mx-auto opacity-50" />
          <h3 className="text-base font-bold text-foreground">Nenhum veículo encontrado</h3>
          <p className="text-xs text-muted-foreground max-w-sm mx-auto">
            Não encontramos nenhum veículo ou tripulante com os critérios selecionados. Ajuste a busca ou os filtros.
          </p>
        </div>
      ) : (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          {veiculosFiltrados.map((veiculo) => {
            const assentos = veiculo.assentos;
            const motorista = assentos?.motorista;
            const frenteDir = assentos?.frenteDir;
            const trasEsq = assentos?.trasEsq;
            const trasDir = assentos?.trasDir;

            const ocupantes = [motorista, frenteDir, trasEsq, trasDir].filter(Boolean) as Colaborador[];
            const faltasNoVeiculo = ocupantes.filter((c) => c.status === 'falta').length;
            const presentesNoVeiculo = ocupantes.filter((c) => c.status === 'presente' || c.status === 'substituto').length;

            return (
              <div
                key={veiculo.id}
                className={cn(
                  'relative rounded-3xl border bg-card/60 backdrop-blur-xl p-5 shadow-2xl transition-all duration-300',
                  faltasNoVeiculo > 0 ? 'border-amber-500/30' : 'border-border/70'
                )}
              >
                {/* Cabeçalho do Veículo */}
                <div className="flex items-center justify-between gap-3 pb-4 border-b border-border/50">
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 rounded-2xl bg-emerald-500/10 border border-emerald-500/30 flex items-center justify-center text-emerald-400">
                      <Car className="w-5 h-5" />
                    </div>
                    <div>
                      <div className="flex items-center gap-2">
                        <h3 className="text-base font-extrabold text-foreground tracking-tight">{veiculo.prefixo}</h3>
                        <span className="text-xs font-mono font-bold px-2 py-0.5 rounded-md bg-muted/60 border border-border/50 text-foreground">
                          {veiculo.placa}
                        </span>
                      </div>
                      <p className="text-xs text-muted-foreground">
                        {veiculo.modelo} · {veiculo.regional === 'ribas' ? 'Ribas do Rio Pardo' : 'Água Clara'}
                      </p>
                    </div>
                  </div>

                  <div className="flex items-center gap-2">
                    <Badge
                      variant="outline"
                      className={cn(
                        'text-xs font-bold py-1 px-3',
                        faltasNoVeiculo > 0
                          ? 'bg-amber-500/15 text-amber-400 border-amber-500/40'
                          : 'bg-emerald-500/15 text-emerald-400 border-emerald-500/40'
                      )}
                    >
                      {presentesNoVeiculo}/4 a bordo
                    </Badge>
                  </div>
                </div>

                {/* ESTRUTURA VISUAL DA CABINE DO CARRO (COCKPIT / BANCOS) */}
                <div className="mt-5 relative p-4 rounded-3xl bg-gradient-to-b from-muted/30 via-background/40 to-muted/20 border border-border/60 shadow-inner">
                  {/* Para-brisa Dianteiro do Carro */}
                  <div className="relative mb-3 flex items-center justify-center">
                    <div className="w-full max-w-[280px] h-3.5 rounded-t-full border-t-2 border-x-2 border-emerald-500/40 bg-gradient-to-b from-emerald-500/10 to-transparent flex items-center justify-center">
                      <span className="text-[9px] uppercase tracking-widest text-emerald-400 font-extrabold flex items-center gap-1">
                        <Compass className="w-3 h-3" /> Frente do Veículo / Para-brisa
                      </span>
                    </div>
                  </div>

                  {/* FIEL DA FRENTE: EQUIPE 1 (Motorista à esquerda + Frente Direita) */}
                  <div className="mb-4">
                    <div className="flex items-center justify-between mb-2 px-1">
                      <span className="text-[11px] font-bold text-sky-400 flex items-center gap-1.5">
                        <Users className="w-3.5 h-3.5" />
                        Bancos Dianteiros · {veiculo.equipe1Codigo || 'Equipe 1'}
                      </span>
                      <span className="text-[10px] text-muted-foreground">Posições 1 & 2</span>
                    </div>

                    <div className="grid grid-cols-2 gap-3 relative">
                      {/* Assento do Condutor / Motorista */}
                      {renderAssentoCarro(motorista, 'Motorista', 'motorista', veiculo.equipe1Codigo, 1)}

                      {/* Assento Passageiro Frente Direita */}
                      {renderAssentoCarro(frenteDir, 'Passageiro Dianteiro', 'passageiro', veiculo.equipe1Codigo, 1)}

                      {/* Console Central do Carro */}
                      <div className="absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 w-4 h-16 rounded-full bg-border/40 border border-border/50 pointer-events-none hidden sm:block" />
                    </div>
                  </div>

                  {/* Divisória do Interior do Carro */}
                  <div className="relative my-3 flex items-center justify-center">
                    <div className="h-[1px] w-full bg-border/50" />
                    <span className="absolute px-3 bg-card text-[9px] font-bold tracking-wider uppercase text-muted-foreground border border-border/50 rounded-full">
                      Corredor Central
                    </span>
                  </div>

                  {/* FILA DE TRÁS: EQUIPE 2 (Traseira Esquerda + Traseira Direita) */}
                  <div>
                    <div className="flex items-center justify-between mb-2 px-1">
                      <span className="text-[11px] font-bold text-emerald-400 flex items-center gap-1.5">
                        <Users className="w-3.5 h-3.5" />
                        Bancos Traseiros · {veiculo.equipe2Codigo || 'Equipe 2'}
                      </span>
                      <span className="text-[10px] text-muted-foreground">Posições 3 & 4</span>
                    </div>

                    <div className="grid grid-cols-2 gap-3">
                      {/* Assento Traseiro Esquerdo */}
                      {renderAssentoCarro(trasEsq, 'Traseiro Esquerdo', 'traseira_esq', veiculo.equipe2Codigo, 2)}

                      {/* Assento Traseiro Direito */}
                      {renderAssentoCarro(trasDir, 'Traseiro Direito', 'traseira_dir', veiculo.equipe2Codigo, 2)}
                    </div>
                  </div>

                  {/* Traseira do Carro / Caçamba */}
                  <div className="mt-4 pt-2 border-t border-border/40 flex items-center justify-center text-[10px] font-medium text-muted-foreground/80">
                    <span>Traseira / Compartimento de Ferramental Florestal</span>
                  </div>
                </div>

                {/* Rodapé com Dica de Ação */}
                <div className="mt-3 flex items-center justify-between text-[11px] text-muted-foreground px-1">
                  <span className="flex items-center gap-1">
                    <Sparkles className="w-3.5 h-3.5 text-emerald-400" />
                    Clique em qualquer tripulante para registrar falta ou substituição
                  </span>
                </div>
              </div>
            );
          })}
        </div>
      )}

      {/* Modal de Presença e Registro de Falta/Substituto */}
      <AttendanceModal
        isOpen={modalOpen}
        onClose={() => setModalOpen(false)}
        colaborador={selectedColaborador}
        colaboradoresReserva={colaboradoresReserva}
        onSaveAttendance={handleSaveAttendance}
      />

      {/* Modal de Ampliação de Foto */}
      {fotoZoom && (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-background/80 backdrop-blur-md animate-in fade-in duration-150"
          onClick={() => setFotoZoom(null)}
        >
          <div
            className="relative max-w-sm w-full bg-card border border-border rounded-3xl p-6 shadow-2xl text-center space-y-4"
            onClick={(e) => e.stopPropagation()}
          >
            <div className="relative w-48 h-48 mx-auto rounded-3xl overflow-hidden border-4 border-emerald-500 shadow-xl">
              <img src={fotoZoom.url} alt={fotoZoom.nome} className="w-full h-full object-cover" />
            </div>
            <div>
              <h3 className="text-lg font-bold text-foreground">{fotoZoom.nome}</h3>
              <p className="text-xs text-muted-foreground">{fotoZoom.cargo}</p>
            </div>
            <button
              type="button"
              onClick={() => setFotoZoom(null)}
              className="w-full py-2.5 rounded-xl bg-muted hover:bg-muted/80 text-foreground text-xs font-bold transition-colors"
            >
              Fechar Visualização
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

