import React, { useState } from 'react';
import {
  Car,
  AlertTriangle,
  CheckCircle2,
  XCircle,
  HelpCircle,
  Search,
  Filter,
  Eye,
  Disc,
  Users,
  ShieldAlert,
  ChevronRight,
  UserCheck,
} from 'lucide-react';
import { Veiculo, Colaborador, StatusPresenca, Regional } from '../types';
import { AttendanceModal } from './AttendanceModal';
import { Badge } from './ui/badge';
import { Button } from './ui/button';
import { Card, CardContent } from './ui/card';
import { cn } from '@/lib/utils';

export interface VehicleCardGridProps {
  veiculos: Veiculo[];
  colaboradoresReserva?: Colaborador[];
  selectedRegional: Regional;
  onUpdateColaboradorStatus: (
    colaboradorId: string,
    status: StatusPresenca,
    motivoFalta?: any,
    observacao?: string,
    substitutoId?: string,
    substitutoNome?: string
  ) => void;
  onSave?: (veiculo: Veiculo) => void;
}

const statusBadgeConfig: Record<StatusPresenca, { label: string; dot: string; ring: string; badge: string }> = {
  presente: {
    label: 'Presente',
    dot: 'bg-emerald-400 ring-2 ring-emerald-500/20',
    ring: 'border-emerald-500/30',
    badge: 'bg-emerald-500/10 text-emerald-400 border-emerald-500/20',
  },
  falta: {
    label: 'Falta',
    dot: 'bg-rose-500 ring-2 ring-rose-500/20',
    ring: 'border-rose-500/40 shadow-rose-950/30',
    badge: 'bg-rose-500/10 text-rose-400 border-rose-500/20',
  },
  substituto: {
    label: 'Substituto',
    dot: 'bg-amber-400 ring-2 ring-amber-500/20',
    ring: 'border-amber-500/30 shadow-amber-950/30',
    badge: 'bg-amber-500/10 text-amber-400 border-amber-500/20',
  },
};

const getIniciais = (nome?: string) => {
  if (!nome) return 'OP';
  const partes = nome.trim().split(' ');
  if (partes.length === 1) return partes[0].substring(0, 2).toUpperCase();
  return (partes[0][0] + partes[partes.length - 1][0]).toUpperCase();
};

export const VehicleCardGrid: React.FC<VehicleCardGridProps> = ({
  veiculos = [],
  colaboradoresReserva = [],
  selectedRegional = 'todas',
  onUpdateColaboradorStatus,
}) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState<'todos' | 'completos' | 'incompletos'>('todos');
  const [selectedVehicle, setSelectedVehicle] = useState<Veiculo | null>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);

  const getColaboradoresVeiculo = (v: Veiculo): Colaborador[] => {
    if (!v?.assentos) return [];
    return [
      v.assentos.motorista,
      v.assentos.frenteDir,
      v.assentos.trasEsq,
      v.assentos.trasDir,
    ].filter(Boolean);
  };

  const hasFaltas = (v: Veiculo) => {
    const list = getColaboradoresVeiculo(v);
    return list.some((c) => c.status === 'falta');
  };

  const veiculosFiltrados = (veiculos || []).filter((v) => {
    if (!v) return false;
    const matchRegional = selectedRegional === 'todas' || v.regional === selectedRegional;
    const colabs = getColaboradoresVeiculo(v);
    const matchSearch =
      !searchTerm ||
      v.prefixo.toLowerCase().includes(searchTerm.toLowerCase()) ||
      v.placa.toLowerCase().includes(searchTerm.toLowerCase()) ||
      v.modelo.toLowerCase().includes(searchTerm.toLowerCase()) ||
      colabs.some((c) => c.nome.toLowerCase().includes(searchTerm.toLowerCase()));

    const comFalta = hasFaltas(v);
    const matchStatus =
      statusFilter === 'todos' ||
      (statusFilter === 'incompletos' && comFalta) ||
      (statusFilter === 'completos' && !comFalta);

    return matchRegional && matchSearch && matchStatus;
  });

  const handleOpenAttendance = (veiculo: Veiculo) => {
    setSelectedVehicle(veiculo);
    setIsModalOpen(true);
  };

  // Renderizador limpo e minimalista de assento do veículo
  const renderAssentoClean = (
    colab: Colaborador | undefined,
    seatRole: string,
    isDriver: boolean = false
  ) => {
    if (!colab) {
      return (
        <div className="flex items-center gap-2.5 p-2 rounded-xl bg-card/40 border border-dashed border-border/60">
          <div className="w-10 h-10 rounded-full border border-dashed border-border/80 flex items-center justify-center bg-muted/20 text-muted-foreground text-xs font-semibold">
            -
          </div>
          <div className="min-w-0">
            <span className="text-[11px] font-medium text-muted-foreground block">
              Vago
            </span>
            <span className="text-[10px] text-muted-foreground/60 block">
              {seatRole}
            </span>
          </div>
        </div>
      );
    }

    const st = statusBadgeConfig[colab.status] || statusBadgeConfig.presente;
    const isFalta = colab.status === 'falta';

    return (
      <div
        className={cn(
          'group relative flex items-center gap-2.5 p-2 rounded-xl transition-all duration-200 border',
          isFalta
            ? 'bg-rose-500/[0.04] border-rose-500/25 hover:border-rose-500/40'
            : 'bg-card/40 border-border/50 hover:bg-card/70 hover:border-border/80'
        )}
      >
        {/* Avatar com badge sutil de status */}
        <div className="relative shrink-0">
          <div
            className={cn(
              'w-10 h-10 rounded-full overflow-hidden border transition-all duration-200 bg-muted/30 shadow-sm flex items-center justify-center',
              st.ring,
              isFalta && 'opacity-70 grayscale-[30%]'
            )}
          >
            {colab.foto ? (
              <img
                src={colab.foto}
                alt={colab.nome}
                className="w-full h-full object-cover"
                onError={(e) => {
                  (e.target as HTMLImageElement).style.display = 'none';
                }}
              />
            ) : (
              <span className="text-xs font-bold text-foreground/80 tracking-tight">
                {getIniciais(colab.nome)}
              </span>
            )}
          </div>

          {/* Micro status indicator */}
          <span
            className={cn(
              'absolute -bottom-0.5 -right-0.5 w-3 h-3 rounded-full border-2 border-background',
              st.dot
            )}
            title={st.label}
          />
        </div>

        {/* Informações textuais compactas */}
        <div className="min-w-0 flex-1">
          <div className="flex items-center gap-1.5 leading-tight">
            <p
              className={cn(
                'text-xs font-medium truncate',
                isFalta ? 'text-rose-300 font-semibold line-through decoration-rose-500/50' : 'text-foreground'
              )}
              title={colab.nome}
            >
              {colab.nome}
            </p>
            {isDriver && (
              <span className="text-[9px] px-1 py-0.5 rounded bg-muted/60 text-muted-foreground font-semibold leading-none shrink-0">
                Condutor
              </span>
            )}
          </div>

          <div className="flex items-center justify-between gap-1 mt-0.5 text-[10px] text-muted-foreground">
            <span className="truncate">{seatRole}</span>
            {colab.status !== 'presente' && (
              <span className={cn('font-semibold uppercase tracking-wider text-[9px]', isFalta ? 'text-rose-400' : 'text-amber-400')}>
                {colab.status === 'substituto' ? 'Subst.' : 'Falta'}
              </span>
            )}
          </div>
        </div>
      </div>
    );
  };

  return (
    <div className="space-y-5">
      {/* Barra de Busca e Filtros Limpa */}
      <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3 p-3 rounded-2xl bg-card/40 border border-border/50 backdrop-blur-sm">
        <div className="relative flex-1">
          <Search className="w-4 h-4 text-muted-foreground absolute left-3 top-1/2 -translate-y-1/2" />
          <input
            type="text"
            placeholder="Buscar por veículo, placa ou operador..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full pl-9 pr-4 py-2 rounded-xl bg-background/50 border border-border/50 text-xs text-foreground placeholder:text-muted-foreground focus:outline-none focus:ring-2 focus:ring-emerald-500/30 transition-all"
          />
        </div>

        <div className="flex items-center gap-1.5 shrink-0">
          {(['todos', 'completos', 'incompletos'] as const).map((filter) => (
            <button
              key={filter}
              type="button"
              onClick={() => setStatusFilter(filter)}
              className={cn(
                'px-3 py-1.5 rounded-xl text-xs font-medium transition-all duration-150',
                statusFilter === filter
                  ? 'bg-primary text-primary-foreground font-semibold shadow-sm'
                  : 'text-muted-foreground hover:text-foreground hover:bg-muted/40'
              )}
            >
              {filter === 'todos' && 'Todos'}
              {filter === 'completos' && '100% Presentes'}
              {filter === 'incompletos' && 'Com Faltas'}
            </button>
          ))}
        </div>
      </div>

      {/* Grid de Veículos */}
      {veiculosFiltrados.length === 0 ? (
        <div className="py-16 text-center rounded-2xl border border-dashed border-border/60 bg-card/20">
          <Car className="w-10 h-10 text-muted-foreground mx-auto mb-2 opacity-40" />
          <p className="text-sm font-semibold text-foreground">Nenhum veículo encontrado</p>
          <p className="text-xs text-muted-foreground mt-1">
            Tente redefinir a busca ou selecione outra regional no topo.
          </p>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {veiculosFiltrados.map((veiculo) => {
            const faltas = hasFaltas(veiculo);
            const todosColabs = getColaboradoresVeiculo(veiculo);
            const totalPresentes = todosColabs.filter(
              (c) => c.status === 'presente' || c.status === 'substituto'
            ).length;

            return (
              <div
                key={veiculo.id}
                className={cn(
                  'rounded-2xl border transition-all duration-200 bg-card/50 hover:bg-card/75 backdrop-blur-sm overflow-hidden flex flex-col',
                  faltas ? 'border-rose-500/30 shadow-sm' : 'border-border/60 hover:border-border'
                )}
              >
                {/* Cabeçalho do Card */}
                <div className="p-4 pb-3 border-b border-border/40 flex items-center justify-between gap-3 bg-muted/10">
                  <div className="flex items-center gap-2.5">
                    <div
                      className={cn(
                        'w-8 h-8 rounded-lg flex items-center justify-center shrink-0 border',
                        faltas
                          ? 'bg-rose-500/10 border-rose-500/25 text-rose-400'
                          : 'bg-emerald-500/10 border-emerald-500/25 text-emerald-400'
                      )}
                    >
                      <Car className="w-4 h-4" />
                    </div>
                    <div>
                      <div className="flex items-center gap-1.5">
                        <span className="font-bold text-sm tracking-tight text-foreground">
                          {veiculo.prefixo}
                        </span>
                        <span className="text-[10px] px-1.5 py-0.5 rounded bg-muted/60 text-muted-foreground font-mono">
                          {veiculo.placa}
                        </span>
                      </div>
                      <span className="text-[11px] text-muted-foreground">
                        {veiculo.modelo}
                      </span>
                    </div>
                  </div>

                  <div className="text-right">
                    <span
                      className={cn(
                        'inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[11px] font-semibold border',
                        faltas
                          ? 'bg-rose-500/10 text-rose-400 border-rose-500/20'
                          : 'bg-emerald-500/10 text-emerald-400 border-emerald-500/20'
                      )}
                    >
                      <span
                        className={cn(
                          'w-1.5 h-1.5 rounded-full',
                          faltas ? 'bg-rose-400' : 'bg-emerald-400'
                        )}
                      />
                      <span className="tabular-nums">{totalPresentes}/4</span>
                    </span>
                  </div>
                </div>

                {/* Disposição dos Assentos — Cabine Clean & Despoluída */}
                <div className="p-3.5 space-y-3 flex-1 flex flex-col justify-between">
                  {/* Fila Dianteira (Cabine) */}
                  <div className="space-y-1.5">
                    <div className="flex items-center justify-between px-1">
                      <span className="text-[10px] font-semibold text-muted-foreground uppercase tracking-wider">
                        Cabine Dianteira
                      </span>
                      <span className="text-[10px] text-muted-foreground/60 font-medium">
                        {veiculo.equipe1Codigo || 'Frente 1'}
                      </span>
                    </div>
                    <div className="grid grid-cols-2 gap-2">
                      {renderAssentoClean(veiculo.assentos?.motorista, 'Motorista', true)}
                      {renderAssentoClean(veiculo.assentos?.frenteDir, 'Carona')}
                    </div>
                  </div>

                  {/* Fila Traseira */}
                  <div className="space-y-1.5">
                    <div className="flex items-center justify-between px-1">
                      <span className="text-[10px] font-semibold text-muted-foreground uppercase tracking-wider">
                        Assentos Traseiros
                      </span>
                      <span className="text-[10px] text-muted-foreground/60 font-medium">
                        {veiculo.equipe2Codigo || 'Frente 2'}
                      </span>
                    </div>
                    <div className="grid grid-cols-2 gap-2">
                      {renderAssentoClean(veiculo.assentos?.trasEsq, 'Apoio')}
                      {renderAssentoClean(veiculo.assentos?.trasDir, 'Apoio')}
                    </div>
                  </div>

                  {/* Ação do Card */}
                  <div className="pt-2 border-t border-border/30">
                    <Button
                      type="button"
                      variant="outline"
                      size="sm"
                      onClick={() => handleOpenAttendance(veiculo)}
                      className={cn(
                        'w-full justify-between h-8 text-xs font-medium rounded-xl transition-all border-border/60 hover:bg-accent',
                        faltas && 'border-rose-500/30 text-rose-300 hover:bg-rose-500/10'
                      )}
                    >
                      <span className="flex items-center gap-1.5">
                        <UserCheck className="w-3.5 h-3.5 opacity-70" />
                        {faltas ? 'Gerenciar faltas & substitutos' : 'Conferir chamada'}
                      </span>
                      <ChevronRight className="w-3.5 h-3.5 opacity-50" />
                    </Button>
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      )}

      {/* Modal de Presença e Escala */}
      {selectedVehicle && (
        <AttendanceModal
          isOpen={isModalOpen}
          onClose={() => {
            setIsModalOpen(false);
            setSelectedVehicle(null);
          }}
          veiculo={selectedVehicle}
          colaboradoresReserva={colaboradoresReserva}
          onUpdateColaboradorStatus={onUpdateColaboradorStatus}
        />
      )}
    </div>
  );
};

files.oldContent:
import React, { useState, useEffect } from 'react';
import {
  X,
  User,
  Calendar,
  AlertTriangle,
  CheckCircle2,
  XCircle,
  HelpCircle,
  UserCheck,
  Disc,
  Compass,
} from 'lucide-react';
import { Colaborador, StatusPresenca, MotivoFalta } from '../types';
import { Button } from './ui/button';
import { Badge } from './ui/badge';
import { cn } from '@/lib/utils';

export interface AttendanceModalProps {
  isOpen: boolean;
  onClose: () => void;
  colaborador?: Colaborador | null;
  colaboradoresReserva?: Colaborador[];
  onSaveAttendance?: (
    colaboradorId: string,
    novoStatus: StatusPresenca,
    motivo?: MotivoFalta,
    observacao?: string,
    substitutoId?: string,
    substitutoNome?: string
  ) => void;
}

const MOTIVOS_FALTA: MotivoFalta[] = [
  'Atestado Médico',
  'Falta Injustificada',
  'Folga Compensatória',
  'Treinamento / Integração',
  'Problema de Transporte',
  'Licença Especial',
];

const getIniciais = (nome?: string) => {
  if (!nome) return 'OP';
  const partes = nome.trim().split(' ');
  if (partes.length === 1) return partes[0].substring(0, 2).toUpperCase();
  return (partes[0][0] + partes[partes.length - 1][0]).toUpperCase();
};

export const AttendanceModal: React.FC<AttendanceModalProps> = ({
  isOpen,
  onClose,
  colaborador,
  colaboradoresReserva = [],
  onSaveAttendance,
}) => {
  const [status, setStatus] = useState<StatusPresenca>('presente');
  const [motivo, setMotivo] = useState<MotivoFalta>('Atestado Médico');
  const [observacao, setObservacao] = useState('');
  const [substitutoId, setSubstitutoId] = useState('');

  useEffect(() => {
    if (colaborador) {
      setStatus(colaborador.status || 'presente');
      setMotivo(colaborador.motivoFalta || 'Atestado Médico');
      setObservacao(colaborador.observacao || '');
      setSubstitutoId(colaborador.substitutoId || '');
    }
  }, [colaborador]);

  if (!isOpen || !colaborador) return null;

  const handleSave = () => {
    const subSelecionado = colaboradoresReserva.find((r) => r.id === substitutoId);
    if (onSaveAttendance) {
      onSaveAttendance(
        colaborador.id,
        status,
        status === 'falta' ? motivo : undefined,
        observacao,
        status === 'substituto' ? substitutoId : undefined,
        status === 'substituto' ? subSelecionado?.nome : undefined
      );
    }
    onClose();
  };

  const getPosicaoNome = (pos?: string) => {
    switch (pos) {
      case 'motorista':
        return 'Condutor / Motorista (Frente Esquerda)';
      case 'frente_dir':
        return 'Passageiro Dianteiro (Frente Direita)';
      case 'tras_esq':
        return 'Banco Traseiro Esquerdo';
      case 'tras_dir':
        return 'Banco Traseiro Direito';
      default:
        return 'Assento Operacional';
    }
  };

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-background/85 backdrop-blur-md animate-in fade-in duration-200"
      onClick={onClose}
    >
      <div
        className="relative w-full max-w-lg bg-card border border-border/80 rounded-3xl shadow-2xl overflow-hidden"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Header com simulação do carro */}
        <div className="px-6 py-4 border-b border-border/60 bg-muted/30 flex items-center justify-between">
          <div className="flex items-center gap-2 text-xs font-bold text-emerald-400 uppercase tracking-wider">
            <Compass className="w-4 h-4" />
            <span>Assento no Veículo: {getPosicaoNome(colaborador.posicaoVeiculo)}</span>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="p-1 rounded-lg text-muted-foreground hover:text-foreground hover:bg-muted transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        <div className="p-6 space-y-5">
          {/* Box estilizado do Colaborador no Assento */}
          <div className="flex items-center gap-4 p-4 rounded-2xl border border-border/70 bg-gradient-to-r from-card to-background shadow-md">
            <div className="relative">
              {/* Encosto do banco atrás da foto */}
              <div className="absolute -top-2 inset-x-2 h-3 rounded-t-lg bg-border/50" />
              <div className="relative w-20 h-20 rounded-2xl p-1 bg-background border-2 border-emerald-500 shadow-lg overflow-hidden">
                {colaborador.foto ? (
                  <img
                    src={colaborador.foto}
                    alt={colaborador.nome}
                    className="w-full h-full object-cover rounded-xl"
                  />
                ) : (
                  <div className="w-full h-full rounded-xl bg-muted flex items-center justify-center font-bold text-base text-foreground">
                    {getIniciais(colaborador.nome)}
                  </div>
                )}
              </div>
            </div>

            <div className="flex-1 min-w-0">
              <div className="flex items-center gap-2">
                <h3 className="font-bold text-base text-foreground truncate">{colaborador.nome}</h3>
              </div>
              <p className="text-xs text-muted-foreground">{colaborador.cargo}</p>
              <div className="flex items-center gap-2 mt-2">
                <span className="text-[10px] font-mono px-2 py-0.5 rounded bg-muted/60 border border-border/50 text-muted-foreground">
                  Matrícula: {colaborador.matricula || '---'}
                </span>
                <span className="text-[10px] font-bold px-2 py-0.5 rounded bg-emerald-500/10 text-emerald-400 border border-emerald-500/20">
                  Equipe {colaborador.equipeNumero}
                </span>
              </div>
            </div>
          </div>

          {/* Seleção do Status de Presença */}
          <div className="space-y-2">
            <label className="text-xs font-bold text-muted-foreground uppercase tracking-wider">
              Status de Presença no Posto
            </label>
            <div className="grid grid-cols-3 gap-2">
              <button
                type="button"
                onClick={() => setStatus('presente')}
                className={cn(
                  'flex flex-col items-center justify-center gap-1.5 p-3 rounded-2xl border text-xs font-bold transition-all',
                  status === 'presente'
                    ? 'bg-emerald-500/20 border-emerald-500 text-emerald-300 shadow-md ring-2 ring-emerald-500/20'
                    : 'border-border/60 text-muted-foreground hover:bg-muted/40'
                )}
              >
                <CheckCircle2 className="w-5 h-5 text-emerald-400" />
                <span>Presente</span>
              </button>

              <button
                type="button"
                onClick={() => setStatus('falta')}
                className={cn(
                  'flex flex-col items-center justify-center gap-1.5 p-3 rounded-2xl border text-xs font-bold transition-all',
                  status === 'falta'
                    ? 'bg-rose-500/20 border-rose-500 text-rose-300 shadow-md ring-2 ring-rose-500/20'
                    : 'border-border/60 text-muted-foreground hover:bg-muted/40'
                )}
              >
                <XCircle className="w-5 h-5 text-rose-400" />
                <span>Registrar Falta</span>
              </button>

              <button
                type="button"
                onClick={() => setStatus('substituto')}
                className={cn(
                  'flex flex-col items-center justify-center gap-1.5 p-3 rounded-2xl border text-xs font-bold transition-all',
                  status === 'substituto'
                    ? 'bg-amber-500/20 border-amber-500 text-amber-300 shadow-md ring-2 ring-amber-500/20'
                    : 'border-border/60 text-muted-foreground hover:bg-muted/40'
                )}
              >
                <UserCheck className="w-5 h-5 text-amber-400" />
                <span>Substituto</span>
              </button>
            </div>
          </div>

          {/* Opções condicionais para Falta */}
          {status === 'falta' && (
            <div className="p-4 rounded-2xl border border-rose-500/30 bg-rose-500/5 space-y-3 animate-in fade-in">
              <label className="text-xs font-bold text-rose-400 block">Motivo da Ausência</label>
              <select
                value={motivo}
                onChange={(e) => setMotivo(e.target.value as MotivoFalta)}
                className="w-full h-10 px-3 rounded-xl border border-rose-500/30 bg-background text-xs font-semibold text-foreground focus:outline-none focus:ring-2 focus:ring-rose-500/30"
              >
                {MOTIVOS_FALTA.map((m) => (
                  <option key={m} value={m}>
                    {m}
                  </option>
                ))}
              </select>
            </div>
          )}

          {/* Opções condicionais para Substituto */}
          {status === 'substituto' && (
            <div className="p-4 rounded-2xl border border-amber-500/30 bg-amber-500/5 space-y-3 animate-in fade-in">
              <label className="text-xs font-bold text-amber-400 block">
                Selecione o Colaborador Reserva para este Assento
              </label>
              <select
                value={substitutoId}
                onChange={(e) => setSubstitutoId(e.target.value)}
                className="w-full h-10 px-3 rounded-xl border border-amber-500/30 bg-background text-xs font-semibold text-foreground focus:outline-none focus:ring-2 focus:ring-amber-500/30"
              >
                <option value="">Selecione um reserva...</option>
                {colaboradoresReserva.map((res) => (
                  <option key={res.id} value={res.id}>
                    {res.nome} — {res.cargo}
                  </option>
                ))}
              </select>
            </div>
          )}

          {/* Observações adicionais */}
          <div className="space-y-1.5">
            <label className="text-xs font-bold text-muted-foreground">Observações de Campo</label>
            <input
              type="text"
              placeholder="Ex: Liberado para consulta médica matutina..."
              value={observacao}
              onChange={(e) => setObservacao(e.target.value)}
              className="w-full h-10 px-3 rounded-xl border border-border/60 bg-background/50 text-xs text-foreground focus:outline-none focus:ring-2 focus:ring-emerald-500/30"
            />
          </div>

          <div className="flex items-center justify-end gap-3 pt-3 border-t border-border/60">
            <Button type="button" variant="outline" onClick={onClose} className="rounded-xl">
              Cancelar
            </Button>
            <Button
              type="button"
              onClick={handleSave}
              className="rounded-xl bg-emerald-600 hover:bg-emerald-500 text-white font-bold px-5"
            >
              Confirmar Assento
            </Button>
          </div>
        </div>
      </div>
    </div>
  );
};

