import React, { useState } from 'react';
import {
  Car,
  AlertTriangle,
  CheckCircle2,
  XCircle,
  HelpCircle,
  Search,
  Filter,
  Eye,
  Disc,
  Users,
  ShieldAlert,
  ArrowRightLeft,
  Calendar,
  Sparkles,
} from 'lucide-react';
import { Veiculo, Colaborador, StatusPresenca, Regional } from '../types';
import { Card, CardHeader, CardTitle, CardContent } from './ui/card';
import { Badge } from './ui/badge';
import { Button } from './ui/button';
import { AttendanceModal } from './AttendanceModal';
import { cn } from '@/lib/utils';

export interface VehicleCardGridProps {
  veiculos: Veiculo[];
  colaboradoresReserva: Colaborador[];
  onUpdateColaboradorStatus: (
    colaboradorId: string,
    novoStatus: StatusPresenca,
    motivoFalta?: any,
    observacao?: string,
    substitutoId?: string
  ) => void;
  selectedRegional: Regional;
  selectedDate: Date;
}

const statusConfig: Record<StatusPresenca, { label: string; bg: string; text: string; border: string; ring: string }> = {
  presente: {
    label: 'Presente',
    bg: 'bg-emerald-500/20',
    text: 'text-emerald-400',
    border: 'border-emerald-500/30',
    ring: 'ring-emerald-500/40',
  },
  falta: {
    label: 'Falta',
    bg: 'bg-rose-500/20',
    text: 'text-rose-400',
    border: 'border-rose-500/30',
    ring: 'ring-rose-500/40',
  },
  substituto: {
    label: 'Substituto',
    bg: 'bg-amber-500/20',
    text: 'text-amber-400',
    border: 'border-amber-500/30',
    ring: 'ring-amber-500/40',
  },
};

const getIniciais = (nome?: string) => {
  if (!nome) return 'OP';
  const partes = nome.trim().split(' ');
  if (partes.length === 1) return partes[0].substring(0, 2).toUpperCase();
  return (partes[0][0] + partes[partes.length - 1][0]).toUpperCase();
};

export const VehicleCardGrid: React.FC<VehicleCardGridProps> = ({
  veiculos = [],
  colaboradoresReserva = [],
  onUpdateColaboradorStatus,
  selectedRegional,
  selectedDate,
}) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState<'todos' | 'completos' | 'incompletos'>('todos');
  const [veiculoSelecionado, setVeiculoSelecionado] = useState<Veiculo | null>(null);
  const [modalOpen, setModalOpen] = useState(false);

  const veiculosFiltrados = (veiculos || []).filter((v) => {
    if (!v) return false;
    const matchRegional =
      selectedRegional === 'todas' || v.regional === selectedRegional;

    const assentosLista = [
      v.assentos?.motorista?.nome,
      v.assentos?.frenteDir?.nome,
      v.assentos?.trasEsq?.nome,
      v.assentos?.trasDir?.nome,
    ].filter(Boolean);

    const matchSearch =
      v.prefixo?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      v.placa?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      assentosLista.some((nome) => nome?.toLowerCase().includes(searchTerm.toLowerCase()));

    const temFalta = [
      v.assentos?.motorista?.status,
      v.assentos?.frenteDir?.status,
      v.assentos?.trasEsq?.status,
      v.assentos?.trasDir?.status,
    ].some((s) => s === 'falta');

    const matchStatus =
      statusFilter === 'todos' ||
      (statusFilter === 'incompletos' && temFalta) ||
      (statusFilter === 'completos' && !temFalta);

    return matchRegional && matchSearch && matchStatus;
  });

  const handleOpenAttendance = (veiculo: Veiculo) => {
    setVeiculoSelecionado(veiculo);
    setModalOpen(true);
  };

  const renderAssentoCarro = (
    colaborador?: Colaborador,
    posicaoTitulo: string = '',
    isDriver: boolean = false,
    veiculo?: Veiculo
  ) => {
    if (!colaborador) {
      return (
        <div className="relative flex flex-col items-center justify-center p-3 rounded-2xl border-2 border-dashed border-border/50 bg-card/30 min-h-[145px]">
          <span className="text-[11px] text-muted-foreground font-semibold">Vago</span>
          <span className="text-[9px] text-muted-foreground/60">{posicaoTitulo}</span>
        </div>
      );
    }

    const st = statusConfig[colaborador.status] || statusConfig.presente;

    return (
      <div
        onClick={() => veiculo && handleOpenAttendance(veiculo)}
        className={cn(
          'group relative flex flex-col items-center text-center p-3 rounded-2xl border transition-all duration-200 cursor-pointer overflow-hidden',
          'bg-gradient-to-b from-card/90 via-card/60 to-card/40 backdrop-blur-sm',
          'hover:border-primary/50 hover:shadow-lg hover:-translate-y-0.5',
          colaborador.status === 'falta'
            ? 'border-rose-500/40 shadow-rose-950/20'
            : colaborador.status === 'substituto'
            ? 'border-amber-500/40 shadow-amber-950/20'
            : 'border-border/70 hover:border-emerald-500/40'
        )}
      >
        {/* Marcador de posição no veículo */}
        <div className="w-full flex items-center justify-between gap-1 mb-2">
          <div className="flex items-center gap-1">
            {isDriver ? (
              <span className="flex items-center gap-1 text-[10px] font-bold text-amber-400 bg-amber-500/10 px-1.5 py-0.5 rounded-md border border-amber-500/20">
                <Disc className="w-3 h-3 animate-spin text-amber-400" />
                Motorista
              </span>
            ) : (
              <span className="text-[10px] font-semibold text-muted-foreground px-1.5 py-0.5 bg-muted/40 rounded-md">
                {posicaoTitulo}
              </span>
            )}
          </div>

          <Badge
            variant="outline"
            className={cn('text-[10px] py-0 px-1.5 font-bold border shadow-xs', st.bg, st.text, st.border)}
          >
            {st.label}
          </Badge>
        </div>

        {/* Foto de Destaque no Assento */}
        <div className="relative mb-2">
          <div
            className={cn(
              'w-16 h-16 rounded-full overflow-hidden border-2 shadow-md transition-transform duration-200 group-hover:scale-105 shrink-0 bg-muted/60',
              colaborador.status === 'falta'
                ? 'border-rose-500 ring-4 ring-rose-500/20 grayscale'
                : colaborador.status === 'substituto'
                ? 'border-amber-500 ring-4 ring-amber-500/20'
                : 'border-emerald-500/80 ring-4 ring-emerald-500/15'
            )}
          >
            {colaborador.foto ? (
              <img
                src={colaborador.foto}
                alt={colaborador.nome}
                className="w-full h-full object-cover object-top"
                onError={(e) => {
                  (e.target as HTMLImageElement).style.display = 'none';
                }}
              />
            ) : (
              <div className="w-full h-full flex items-center justify-center font-black text-sm bg-muted text-muted-foreground">
                {getIniciais(colaborador.nome)}
              </div>
            )}
          </div>

          {/* Ícone Indicador de Status */}
          <div className="absolute -bottom-1 -right-1">
            {colaborador.status === 'presente' && (
              <CheckCircle2 className="w-5 h-5 text-emerald-400 bg-background rounded-full p-0.5 shadow-sm" />
            )}
            {colaborador.status === 'falta' && (
              <XCircle className="w-5 h-5 text-rose-400 bg-background rounded-full p-0.5 shadow-sm" />
            )}
            {colaborador.status === 'substituto' && (
              <HelpCircle className="w-5 h-5 text-amber-400 bg-background rounded-full p-0.5 shadow-sm" />
            )}
          </div>
        </div>

        {/* Nome e Cargo */}
        <h4 className="text-xs font-bold text-foreground line-clamp-1 group-hover:text-primary transition-colors">
          {colaborador.nome}
        </h4>
        <p className="text-[10px] text-muted-foreground line-clamp-1 font-medium mt-0.5">
          {colaborador.cargo}
        </p>

        {/* Substituto ou Motivo da Falta */}
        {colaborador.status === 'substituto' && colaborador.substitutoNome && (
          <div className="mt-1.5 flex items-center gap-1 text-[9px] text-amber-300 bg-amber-500/15 px-1.5 py-0.5 rounded-md font-semibold border border-amber-500/20">
            <ArrowRightLeft className="w-2.5 h-2.5" />
            Subst: {colaborador.substitutoNome.split(' ')[0]}
          </div>
        )}

        {colaborador.status === 'falta' && colaborador.motivoFalta && (
          <div className="mt-1.5 text-[9px] text-rose-300 bg-rose-500/15 px-1.5 py-0.5 rounded-md font-semibold border border-rose-500/20 line-clamp-1">
            {colaborador.motivoFalta}
          </div>
        )}
      </div>
    );
  };

  return (
    <div className="space-y-6">
      {/* Barra de Filtros e Busca */}
      <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3 bg-card/60 backdrop-blur-md p-3.5 rounded-2xl border border-border/80 shadow-md">
        <div className="relative flex-1">
          <Search className="w-4 h-4 text-muted-foreground absolute left-3 top-1/2 -translate-y-1/2" />
          <input
            type="text"
            placeholder="Buscar por prefixo, placa ou nome do operador..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full pl-9 pr-4 py-2 bg-background/50 border border-border/70 rounded-xl text-xs font-medium text-foreground placeholder:text-muted-foreground focus:outline-none focus:ring-2 focus:ring-primary/40"
          />
        </div>

        <div className="flex items-center gap-2">
          <button
            onClick={() => setStatusFilter('todos')}
            className={cn(
              'px-3 py-1.5 rounded-xl text-xs font-semibold border transition-all cursor-pointer',
              statusFilter === 'todos'
                ? 'bg-primary text-primary-foreground border-primary shadow-sm'
                : 'border-border/70 text-muted-foreground hover:bg-muted/40'
            )}
          >
            Todos ({veiculos.length})
          </button>
          <button
            onClick={() => setStatusFilter('completos')}
            className={cn(
              'px-3 py-1.5 rounded-xl text-xs font-semibold border transition-all cursor-pointer',
              statusFilter === 'completos'
                ? 'bg-emerald-600 text-white border-emerald-500 shadow-sm'
                : 'border-border/70 text-muted-foreground hover:bg-muted/40'
            )}
          >
            Completos
          </button>
          <button
            onClick={() => setStatusFilter('incompletos')}
            className={cn(
              'px-3 py-1.5 rounded-xl text-xs font-semibold border transition-all cursor-pointer',
              statusFilter === 'incompletos'
                ? 'bg-rose-600 text-white border-rose-500 shadow-sm'
                : 'border-border/70 text-muted-foreground hover:bg-muted/40'
            )}
          >
            Com Faltas
          </button>
        </div>
      </div>

      {/* Grid de Veículos com Habitáculo / Cabine Sentada */}
      {veiculosFiltrados.length === 0 ? (
        <div className="py-16 text-center rounded-3xl border-2 border-dashed border-border/70 bg-card/20 p-8">
          <Car className="w-12 h-12 text-muted-foreground/40 mx-auto mb-3" />
          <h3 className="text-base font-bold text-foreground">Nenhum veículo encontrado</h3>
          <p className="text-xs text-muted-foreground max-w-sm mx-auto mt-1">
            Nenhum carro corresponde aos filtros de regional ou pesquisa selecionados.
          </p>
        </div>
      ) : (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          {veiculosFiltrados.map((veiculo) => {
            const assentos = [
              veiculo.assentos?.motorista,
              veiculo.assentos?.frenteDir,
              veiculo.assentos?.trasEsq,
              veiculo.assentos?.trasDir,
            ].filter(Boolean) as Colaborador[];

            const faltasCount = assentos.filter((a) => a.status === 'falta').length;
            const subsCount = assentos.filter((a) => a.status === 'substituto').length;
            const presentesCount = assentos.filter((a) => a.status === 'presente').length;

            return (
              <Card
                key={veiculo.id}
                className={cn(
                  'rounded-3xl border transition-all duration-300 overflow-hidden shadow-xl hover:shadow-2xl',
                  faltasCount > 0
                    ? 'border-rose-500/40 bg-card/80'
                    : 'border-border/80 bg-card/60 hover:border-emerald-500/40'
                )}
              >
                {/* Header do Veículo */}
                <CardHeader className="p-4 sm:p-5 border-b border-border/50 bg-gradient-to-r from-muted/30 via-transparent to-muted/10">
                  <div className="flex items-center justify-between gap-3 flex-wrap">
                    <div className="flex items-center gap-3">
                      <div className="w-10 h-10 rounded-2xl bg-emerald-500/15 border border-emerald-500/25 flex items-center justify-center shrink-0 shadow-inner">
                        <Car className="w-5 h-5 text-emerald-400" />
                      </div>
                      <div>
                        <div className="flex items-center gap-2">
                          <CardTitle className="text-base font-extrabold tracking-tight">
                            {veiculo.prefixo}
                          </CardTitle>
                          <Badge
                            variant="outline"
                            className="text-[11px] font-mono px-2 py-0 border-border/80 bg-background/50 font-semibold"
                          >
                            {veiculo.placa}
                          </Badge>
                        </div>
                        <p className="text-xs text-muted-foreground flex items-center gap-2 mt-0.5 font-medium">
                          <span>{veiculo.modelo}</span>
                          <span>•</span>
                          <span className="capitalize">
                            {veiculo.regional === 'ribas' ? 'Ribas do Rio Pardo' : 'Água Clara'}
                          </span>
                        </p>
                      </div>
                    </div>

                    <div className="flex items-center gap-2">
                      <Button
                        size="sm"
                        onClick={() => handleOpenAttendance(veiculo)}
                        className="h-8 px-3 rounded-xl bg-primary hover:bg-primary/90 text-primary-foreground text-xs font-semibold gap-1.5 shadow-sm"
                      >
                        <Eye className="w-3.5 h-3.5" />
                        <span>Gerenciar Presenças</span>
                      </Button>
                    </div>
                  </div>

                  {/* Resumo Rápido de Status */}
                  <div className="flex items-center gap-3 mt-3 pt-3 border-t border-border/30 text-xs">
                    <div className="flex items-center gap-1.5 text-emerald-400 font-semibold">
                      <span className="w-2 h-2 rounded-full bg-emerald-400" />
                      <span>{presentesCount} Presentes</span>
                    </div>
                    {subsCount > 0 && (
                      <div className="flex items-center gap-1.5 text-amber-400 font-semibold">
                        <span className="w-2 h-2 rounded-full bg-amber-400" />
                        <span>{subsCount} Substitutos</span>
                      </div>
                    )}
                    {faltasCount > 0 ? (
                      <div className="flex items-center gap-1.5 text-rose-400 font-bold ml-auto bg-rose-500/10 px-2 py-0.5 rounded-full border border-rose-500/20">
                        <AlertTriangle className="w-3.5 h-3.5 text-rose-400" />
                        <span>{faltasCount} Falta(s)</span>
                      </div>
                    ) : (
                      <div className="flex items-center gap-1.5 text-emerald-400 font-semibold ml-auto">
                        <CheckCircle2 className="w-3.5 h-3.5 text-emerald-400" />
                        <span>Veículo Operacional</span>
                      </div>
                    )}
                  </div>
                </CardHeader>

                {/* Conteúdo: Habitáculo do Carro (Layout Sentado em 4 Posições) */}
                <CardContent className="p-4 sm:p-5">
                  <div className="relative rounded-2xl border-2 border-border/60 bg-muted/15 p-4 shadow-inner">
                    {/* Representação do Vidro Frontal / Para-brisa */}
                    <div className="relative w-full h-5 rounded-t-xl bg-gradient-to-b from-sky-500/15 to-transparent border-t-2 border-x-2 border-sky-400/30 mb-3 flex items-center justify-center">
                      <span className="text-[9px] uppercase tracking-widest font-black text-sky-400/80">
                        FRENTE DO VEÍCULO (PARA-BRISA)
                      </span>
                    </div>

                    {/* Fileira da Frente: Motorista & Carona */}
                    <div className="space-y-1 mb-4">
                      <div className="flex items-center justify-between text-[10px] font-bold text-muted-foreground uppercase tracking-wider px-1">
                        <span>Equipe 1 • Fila Dianteira</span>
                        <span className="text-[9px] font-mono opacity-60">Eq: {veiculo.equipe1Codigo || 'EQ-1'}</span>
                      </div>
                      <div className="grid grid-cols-2 gap-3">
                        {renderAssentoCarro(veiculo.assentos?.motorista, 'Frente Esquerda', true, veiculo)}
                        {renderAssentoCarro(veiculo.assentos?.frenteDir, 'Frente Direita', false, veiculo)}
                      </div>
                    </div>

                    {/* Divisória Central de Habitáculo */}
                    <div className="relative flex items-center justify-center py-1">
                      <div className="w-full border-t border-dashed border-border/60" />
                      <span className="absolute bg-card px-2 text-[9px] font-bold text-muted-foreground uppercase">
                        Corredor Interno
                      </span>
                    </div>

                    {/* Fileira de Trás: Traseiro Esquerdo & Traseiro Direito */}
                    <div className="space-y-1 mt-3">
                      <div className="flex items-center justify-between text-[10px] font-bold text-muted-foreground uppercase tracking-wider px-1">
                        <span>Equipe 2 • Fila Traseira</span>
                        <span className="text-[9px] font-mono opacity-60">Eq: {veiculo.equipe2Codigo || 'EQ-2'}</span>
                      </div>
                      <div className="grid grid-cols-2 gap-3">
                        {renderAssentoCarro(veiculo.assentos?.trasEsq, 'Trás Esquerda', false, veiculo)}
                        {renderAssentoCarro(veiculo.assentos?.trasDir, 'Trás Direita', false, veiculo)}
                      </div>
                    </div>

                    {/* Traseira do Veículo */}
                    <div className="relative w-full h-3 rounded-b-xl bg-muted/30 border-b border-x border-border/40 mt-3 flex items-center justify-center">
                      <span className="text-[8px] uppercase tracking-wider font-semibold text-muted-foreground/60">
                        Porta-malas / Traseira
                      </span>
                    </div>
                  </div>
                </CardContent>
              </Card>
            );
          })}
        </div>
      )}

      {/* Modal de Gestão de Frequência */}
      {modalOpen && veiculoSelecionado && (
        <AttendanceModal
          isOpen={modalOpen}
          onClose={() => {
            setModalOpen(false);
            setVeiculoSelecionado(null);
          }}
          veiculo={veiculoSelecionado}
          colaboradoresReserva={colaboradoresReserva}
          onSalvarStatus={(colabId, status, motivo, obs, subId) => {
            onUpdateColaboradorStatus(colabId, status, motivo, obs, subId);
            setModalOpen(false);
            setVeiculoSelecionado(null);
          }}
        />
      )}
    </div>
  );
};

files.oldContent:
import React, { useState } from 'react';
import {
  X,
  CheckCircle2,
  XCircle,
  HelpCircle,
  Car,
  AlertTriangle,
  UserCheck,
  MapPin,
  Clock,
  ArrowRightLeft,
  ChevronDown,
} from 'lucide-react';
import { Veiculo, Colaborador, StatusPresenca, MotivoFalta } from '../types';
import { Button } from './ui/button';
import { Badge } from './ui/badge';
import { cn } from '@/lib/utils';

export interface AttendanceModalProps {
  isOpen: boolean;
  onClose: () => void;
  veiculo: Veiculo;
  colaboradoresReserva?: Colaborador[];
  onUpdateColaboradorStatus: (
    colaboradorId: string,
    status: StatusPresenca,
    motivoFalta?: MotivoFalta,
    observacao?: string,
    substitutoId?: string,
    substitutoNome?: string
  ) => void;
}

const MOTIVOS_FALTA: MotivoFalta[] = [
  'Atestado Médico',
  'Falta Injustificada',
  'Folga Compensatória',
  'Treinamento / Integração',
  'Problema de Transporte',
  'Licença Especial',
];

const getIniciais = (nome?: string) => {
  if (!nome) return 'OP';
  const partes = nome.trim().split(' ');
  if (partes.length === 1) return partes[0].substring(0, 2).toUpperCase();
  return (partes[0][0] + partes[partes.length - 1][0]).toUpperCase();
};

export const AttendanceModal: React.FC<AttendanceModalProps> = ({
  isOpen,
  onClose,
  veiculo,
  colaboradoresReserva = [],
  onUpdateColaboradorStatus,
}) => {
  const [editingColabId, setEditingColabId] = useState<string | null>(null);
  const [selectedStatus, setSelectedStatus] = useState<StatusPresenca>('presente');
  const [selectedMotivo, setSelectedMotivo] = useState<MotivoFalta>('Atestado Médico');
  const [observacao, setObservacao] = useState('');
  const [selectedSubstitutoId, setSelectedSubstitutoId] = useState<string>('');

  if (!isOpen || !veiculo) return null;

  const assentosConfig = [
    { key: 'motorista', label: 'Motorista', colab: veiculo.assentos?.motorista, isDriver: true, equipe: veiculo.equipe1Codigo || 'Equipe 1' },
    { key: 'frenteDir', label: 'Carona Dianteiro', colab: veiculo.assentos?.frenteDir, isDriver: false, equipe: veiculo.equipe1Codigo || 'Equipe 1' },
    { key: 'trasEsq', label: 'Traseiro Esquerdo', colab: veiculo.assentos?.trasEsq, isDriver: false, equipe: veiculo.equipe2Codigo || 'Equipe 2' },
    { key: 'trasDir', label: 'Traseiro Direito', colab: veiculo.assentos?.trasDir, isDriver: false, equipe: veiculo.equipe2Codigo || 'Equipe 2' },
  ];

  const handleStartEdit = (colab: Colaborador) => {
    setEditingColabId(colab.id);
    setSelectedStatus(colab.status || 'presente');
    setSelectedMotivo(colab.motivoFalta || 'Atestado Médico');
    setObservacao(colab.observacao || '');
    setSelectedSubstitutoId(colab.substitutoId || '');
  };

  const handleSaveAttendance = (colabId: string) => {
    let substNome: string | undefined;
    if (selectedStatus === 'substituto' && selectedSubstitutoId) {
      const achado = colaboradoresReserva.find((r) => r.id === selectedSubstitutoId);
      substNome = achado?.nome;
    }

    onUpdateColaboradorStatus(
      colabId,
      selectedStatus,
      selectedStatus === 'falta' ? selectedMotivo : undefined,
      observacao,
      selectedStatus === 'substituto' ? selectedSubstitutoId : undefined,
      substNome
    );

    setEditingColabId(null);
  };

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-background/80 backdrop-blur-md animate-in fade-in duration-150"
      onClick={onClose}
    >
      <div
        className="relative w-full max-w-2xl bg-card border border-border/80 rounded-3xl shadow-2xl overflow-hidden flex flex-col max-h-[90vh]"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Header Elegante */}
        <div className="flex items-center justify-between px-6 py-4 border-b border-border/60 bg-muted/20">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-2xl bg-primary/10 border border-primary/20 flex items-center justify-center shrink-0">
              <Car className="w-5 h-5 text-primary" />
            </div>
            <div>
              <div className="flex items-center gap-2">
                <h2 className="text-base font-bold text-foreground tracking-tight">
                  {veiculo.prefixo}
                </h2>
                <Badge variant="outline" className="text-[10px] font-mono px-2 py-0 border-border">
                  {veiculo.placa}
                </Badge>
                <Badge variant="outline" className="text-[10px] border-emerald-500/30 text-emerald-400 bg-emerald-500/10">
                  {veiculo.regional === 'ribas' ? 'Ribas do Rio Pardo' : 'Água Clara'}
                </Badge>
              </div>
              <p className="text-xs text-muted-foreground mt-0.5">
                Controle de presença e escalação da cabine
              </p>
            </div>
          </div>

          <button
            type="button"
            onClick={onClose}
            className="p-1.5 rounded-xl text-muted-foreground hover:text-foreground hover:bg-muted/60 transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Lista Despoluída de Assentos */}
        <div className="p-6 space-y-3 overflow-y-auto flex-1">
          {assentosConfig.map(({ key, label, colab, isDriver, equipe }) => {
            if (!colab) return null;
            const isEditing = editingColabId === colab.id;
            const isFalta = colab.status === 'falta';

            return (
              <div
                key={key}
                className={cn(
                  'rounded-2xl border transition-all duration-200 p-3.5',
                  isEditing
                    ? 'border-primary/50 bg-primary/[0.02] ring-1 ring-primary/20'
                    : isFalta
                    ? 'border-rose-500/30 bg-rose-500/[0.03]'
                    : 'border-border/50 bg-card/40 hover:bg-card/70'
                )}
              >
                {/* Visualização Normal */}
                <div className="flex items-center justify-between gap-3 flex-wrap sm:flex-nowrap">
                  <div className="flex items-center gap-3 min-w-0">
                    {/* Foto Limpa */}
                    <div className="relative shrink-0">
                      <div className="w-12 h-12 rounded-full overflow-hidden border border-border/80 bg-muted/40 shadow-sm flex items-center justify-center">
                        {colab.foto ? (
                          <img
                            src={colab.foto}
                            alt={colab.nome}
                            className="w-full h-full object-cover"
                            onError={(e) => {
                              (e.target as HTMLImageElement).style.display = 'none';
                            }}
                          />
                        ) : (
                          <span className="text-sm font-bold text-foreground/80">
                            {getIniciais(colab.nome)}
                          </span>
                        )}
                      </div>
                      <span
                        className={cn(
                          'absolute -bottom-0.5 -right-0.5 w-3.5 h-3.5 rounded-full border-2 border-background',
                          colab.status === 'presente'
                            ? 'bg-emerald-400'
                            : colab.status === 'falta'
                            ? 'bg-rose-500'
                            : 'bg-amber-400'
                        )}
                      />
                    </div>

                    {/* Dados */}
                    <div className="min-w-0">
                      <div className="flex items-center gap-1.5">
                        <span className="text-sm font-semibold text-foreground truncate">
                          {colab.nome}
                        </span>
                        {isDriver && (
                          <span className="text-[10px] px-1.5 py-0.2 rounded bg-muted/70 text-muted-foreground font-medium">
                            Motorista
                          </span>
                        )}
                      </div>
                      <div className="flex items-center gap-2 text-xs text-muted-foreground mt-0.5">
                        <span>{label}</span>
                        <span>•</span>
                        <span>{colab.cargo}</span>
                      </div>

                      {colab.status === 'falta' && colab.motivoFalta && (
                        <p className="text-xs text-rose-400 mt-1 flex items-center gap-1">
                          <AlertTriangle className="w-3 h-3" />
                          Motivo: {colab.motivoFalta}
                        </p>
                      )}

                      {colab.status === 'substituto' && colab.substitutoNome && (
                        <p className="text-xs text-amber-400 mt-1 flex items-center gap-1">
                          <ArrowRightLeft className="w-3 h-3" />
                          Substituto em campo: {colab.substitutoNome}
                        </p>
                      )}
                    </div>
                  </div>

                  {/* Status / Ação */}
                  <div className="flex items-center gap-2 shrink-0">
                    <span
                      className={cn(
                        'px-2.5 py-1 rounded-full text-xs font-semibold border',
                        colab.status === 'presente'
                          ? 'bg-emerald-500/10 text-emerald-400 border-emerald-500/25'
                          : colab.status === 'falta'
                          ? 'bg-rose-500/10 text-rose-400 border-rose-500/25'
                          : 'bg-amber-500/10 text-amber-400 border-amber-500/25'
                      )}
                    >
                      {colab.status === 'presente' && 'Presente'}
                      {colab.status === 'falta' && 'Falta Registrada'}
                      {colab.status === 'substituto' && 'Substituído'}
                    </span>

                    <Button
                      type="button"
                      variant="outline"
                      size="sm"
                      onClick={() => (isEditing ? setEditingColabId(null) : handleStartEdit(colab))}
                      className="h-8 text-xs rounded-xl"
                    >
                      {isEditing ? 'Fechar' : 'Alterar'}
                    </Button>
                  </div>
                </div>

                {/* Painel de Edição Discreto */}
                {isEditing && (
                  <div className="mt-4 pt-3.5 border-t border-border/40 space-y-3 animate-in fade-in-50 duration-150">
                    <div className="flex items-center gap-2">
                      <span className="text-xs font-semibold text-muted-foreground">
                        Definir presença:
                      </span>
                      <div className="flex items-center gap-1.5">
                        <button
                          type="button"
                          onClick={() => setSelectedStatus('presente')}
                          className={cn(
                            'px-3 py-1 rounded-lg text-xs font-medium border transition-all',
                            selectedStatus === 'presente'
                              ? 'bg-emerald-500/15 border-emerald-500/40 text-emerald-300 font-semibold'
                              : 'border-border/60 text-muted-foreground hover:bg-muted/40'
                          )}
                        >
                          Presente
                        </button>
                        <button
                          type="button"
                          onClick={() => setSelectedStatus('falta')}
                          className={cn(
                            'px-3 py-1 rounded-lg text-xs font-medium border transition-all',
                            selectedStatus === 'falta'
                              ? 'bg-rose-500/15 border-rose-500/40 text-rose-300 font-semibold'
                              : 'border-border/60 text-muted-foreground hover:bg-muted/40'
                          )}
                        >
                          Falta
                        </button>
                        <button
                          type="button"
                          onClick={() => setSelectedStatus('substituto')}
                          className={cn(
                            'px-3 py-1 rounded-lg text-xs font-medium border transition-all',
                            selectedStatus === 'substituto'
                              ? 'bg-amber-500/15 border-amber-500/40 text-amber-300 font-semibold'
                              : 'border-border/60 text-muted-foreground hover:bg-muted/40'
                          )}
                        >
                          Substituto
                        </button>
                      </div>
                    </div>

                    {selectedStatus === 'falta' && (
                      <div className="space-y-1.5">
                        <label className="text-[11px] font-semibold text-muted-foreground block">
                          Motivo da Ausência:
                        </label>
                        <select
                          value={selectedMotivo}
                          onChange={(e) => setSelectedMotivo(e.target.value as MotivoFalta)}
                          className="w-full h-8 px-2.5 rounded-lg border border-border/70 bg-background/60 text-xs text-foreground focus:outline-none focus:ring-1 focus:ring-emerald-500"
                        >
                          {MOTIVOS_FALTA.map((m) => (
                            <option key={m} value={m}>
                              {m}
                            </option>
                          ))}
                        </select>
                      </div>
                    )}

                    {selectedStatus === 'substituto' && (
                      <div className="space-y-1.5">
                        <label className="text-[11px] font-semibold text-muted-foreground block">
                          Selecionar do Banco de Reserva:
                        </label>
                        <select
                          value={selectedSubstitutoId}
                          onChange={(e) => setSelectedSubstitutoId(e.target.value)}
                          className="w-full h-8 px-2.5 rounded-lg border border-border/70 bg-background/60 text-xs text-foreground focus:outline-none focus:ring-1 focus:ring-emerald-500"
                        >
                          <option value="">Selecione um substituto disponível...</option>
                          {colaboradoresReserva.map((res) => (
                            <option key={res.id} value={res.id}>
                              {res.nome} — {res.cargo}
                            </option>
                          ))}
                        </select>
                      </div>
                    )}

                    <div className="flex items-center justify-end gap-2 pt-2">
                      <Button
                        type="button"
                        variant="ghost"
                        size="sm"
                        onClick={() => setEditingColabId(null)}
                        className="h-7 text-xs"
                      >
                        Cancelar
                      </Button>
                      <Button
                        type="button"
                        size="sm"
                        onClick={() => handleSaveAttendance(colab.id)}
                        className="h-7 text-xs bg-emerald-600 hover:bg-emerald-500 text-white"
                      >
                        Salvar Status
                      </Button>
                    </div>
                  </div>
                )}
              </div>
            );
          })}
        </div>

        {/* Rodapé */}
        <div className="px-6 py-3 border-t border-border/40 bg-muted/10 flex items-center justify-end">
          <Button type="button" variant="outline" size="sm" onClick={onClose} className="rounded-xl">
            Fechar
          </Button>
        </div>
      </div>
    </div>
  );
};

