import React, { useState } from 'react';
import {
  X,
  UserCheck,
  UserX,
  ArrowRightLeft,
  Disc,
  Check,
  AlertCircle,
  Car,
  ShieldCheck,
  Info,
} from 'lucide-react';
import {
  Veiculo,
  Colaborador,
  StatusPresenca,
  MotivoFalta,
} from '../types';
import { Button } from './ui/button';
import { Badge } from './ui/badge';
import { cn } from '@/lib/utils';

export interface AttendanceModalProps {
  isOpen: boolean;
  onClose: () => void;
  veiculo: Veiculo;
  colaboradoresReserva: Colaborador[];
  onSalvarStatus: (
    colaboradorId: string,
    novoStatus: StatusPresenca,
    motivoFalta?: MotivoFalta,
    observacao?: string,
    substitutoId?: string
  ) => void;
}

const MOTIVOS_FALTA: MotivoFalta[] = [
  'Atestado Médico',
  'Falta Injustificada',
  'Folga Compensatória',
  'Treinamento / Integração',
  'Problema de Transporte',
  'Licença Especial',
];

const getIniciais = (nome?: string) => {
  if (!nome) return 'OP';
  const partes = nome.trim().split(' ');
  if (partes.length === 1) return partes[0].substring(0, 2).toUpperCase();
  return (partes[0][0] + partes[partes.length - 1][0]).toUpperCase();
};

export const AttendanceModal: React.FC<AttendanceModalProps> = ({
  isOpen,
  onClose,
  veiculo,
  colaboradoresReserva = [],
  onSalvarStatus,
}) => {
  if (!isOpen || !veiculo) return null;

  const assentos = [
    { key: 'motorista', label: 'Motorista (Frente Esq.)', colab: veiculo.assentos?.motorista, isDriver: true },
    { key: 'frenteDir', label: 'Carona (Frente Dir.)', colab: veiculo.assentos?.frenteDir, isDriver: false },
    { key: 'trasEsq', label: 'Traseiro Esquerdo', colab: veiculo.assentos?.trasEsq, isDriver: false },
    { key: 'trasDir', label: 'Traseiro Direito', colab: veiculo.assentos?.trasDir, isDriver: false },
  ];

  const [assentoAtivoKey, setAssentoAtivoKey] = useState<string>('motorista');
  const assentoSelecionado = assentos.find((a) => a.key === assentoAtivoKey) || assentos[0];
  const colabAtual = assentoSelecionado.colab;

  const [statusTemp, setStatusTemp] = useState<StatusPresenca>(colabAtual?.status || 'presente');
  const [motivoTemp, setMotivoTemp] = useState<MotivoFalta | undefined>(colabAtual?.motivoFalta);
  const [obsTemp, setObsTemp] = useState<string>(colabAtual?.observacao || '');
  const [substitutoIdTemp, setSubstitutoIdTemp] = useState<string>(colabAtual?.substitutoId || '');

  const handleSelectAssento = (key: string) => {
    setAssentoAtivoKey(key);
    const item = assentos.find((a) => a.key === key);
    if (item?.colab) {
      setStatusTemp(item.colab.status || 'presente');
      setMotivoTemp(item.colab.motivoFalta);
      setObsTemp(item.colab.observacao || '');
      setSubstitutoIdTemp(item.colab.substitutoId || '');
    }
  };

  const handleSalvar = () => {
    if (!colabAtual) return;
    onSalvarStatus(
      colabAtual.id,
      statusTemp,
      statusTemp === 'falta' ? motivoTemp : undefined,
      obsTemp,
      statusTemp === 'substituto' ? substitutoIdTemp : undefined
    );
  };

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-background/80 backdrop-blur-md animate-in fade-in duration-150"
      onClick={onClose}
    >
      <div
        className="relative w-full max-w-2xl bg-card border border-border/80 rounded-3xl shadow-2xl overflow-hidden flex flex-col max-h-[92vh]"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Header do Modal */}
        <div className="flex items-center justify-between px-6 py-4 border-b border-border/60 bg-muted/20">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-2xl bg-emerald-500/15 border border-emerald-500/25 flex items-center justify-center">
              <Car className="w-5 h-5 text-emerald-400" />
            </div>
            <div>
              <div className="flex items-center gap-2">
                <h3 className="text-base font-bold text-foreground">{veiculo.prefixo}</h3>
                <Badge variant="outline" className="text-[10px] font-mono px-2 py-0 border-border">
                  {veiculo.placa}
                </Badge>
              </div>
              <p className="text-xs text-muted-foreground">
                Selecione o assento e ajuste a frequência do operador
              </p>
            </div>
          </div>

          <button
            onClick={onClose}
            className="p-1.5 rounded-xl text-muted-foreground hover:text-foreground hover:bg-muted transition-colors cursor-pointer"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Corpo com Habitáculo e Painel de Edição */}
        <div className="p-6 overflow-y-auto space-y-6">
          {/* Visual do Carro com os 4 Assentos Selecionáveis */}
          <div>
            <div className="flex items-center justify-between mb-2">
              <span className="text-xs font-bold text-foreground">
                Cabine do Veículo (Selecione o Assento)
              </span>
              <span className="text-[10px] text-muted-foreground font-medium">
                Clique para alterar status
              </span>
            </div>

            <div className="p-4 rounded-2xl border-2 border-border/70 bg-muted/20 space-y-3">
              {/* Para-brisa */}
              <div className="w-full py-1 text-center bg-sky-500/10 rounded-lg border border-sky-500/20 text-[9px] font-bold text-sky-400 tracking-wider">
                FRENTE DO VEÍCULO (PAINEL & VOLANTE)
              </div>

              {/* Grid 2x2 dos Assentos */}
              <div className="grid grid-cols-2 gap-3">
                {assentos.map((item) => {
                  const isSelected = item.key === assentoAtivoKey;
                  const c = item.colab;

                  return (
                    <button
                      key={item.key}
                      type="button"
                      onClick={() => handleSelectAssento(item.key)}
                      className={cn(
                        'relative flex items-center gap-3 p-3 rounded-xl border text-left transition-all duration-200 cursor-pointer',
                        isSelected
                          ? 'border-primary ring-2 ring-primary/30 bg-primary/10 shadow-md'
                          : 'border-border/70 bg-card/60 hover:border-border hover:bg-card'
                      )}
                    >
                      <div className="relative">
                        <div className="w-12 h-12 rounded-full overflow-hidden border-2 border-border/80 bg-muted/40 shrink-0">
                          {c?.foto ? (
                            <img
                              src={c.foto}
                              alt={c.nome}
                              className="w-full h-full object-cover object-top"
                              onError={(e) => {
                                (e.target as HTMLImageElement).style.display = 'none';
                              }}
                            />
                          ) : (
                            <div className="w-full h-full flex items-center justify-center text-xs font-bold text-muted-foreground">
                              {getIniciais(c?.nome)}
                            </div>
                          )}
                        </div>
                        {item.isDriver && (
                          <div className="absolute -top-1 -right-1 w-4 h-4 rounded-full bg-amber-500 text-black flex items-center justify-center">
                            <Disc className="w-3 h-3" />
                          </div>
                        )}
                      </div>

                      <div className="min-w-0 flex-1">
                        <div className="flex items-center gap-1.5">
                          <span className="text-[10px] font-semibold text-muted-foreground line-clamp-1">
                            {item.label}
                          </span>
                        </div>
                        <p className="text-xs font-bold text-foreground truncate mt-0.5">
                          {c?.nome || 'Assento Vago'}
                        </p>
                        <div className="mt-1">
                          {c?.status === 'presente' && (
                            <span className="text-[9px] font-bold text-emerald-400 bg-emerald-500/10 px-1.5 py-0.5 rounded border border-emerald-500/20">
                              Presente
                            </span>
                          )}
                          {c?.status === 'falta' && (
                            <span className="text-[9px] font-bold text-rose-400 bg-rose-500/10 px-1.5 py-0.5 rounded border border-rose-500/20">
                              Falta
                            </span>
                          )}
                          {c?.status === 'substituto' && (
                            <span className="text-[9px] font-bold text-amber-400 bg-amber-500/10 px-1.5 py-0.5 rounded border border-amber-500/20">
                              Substituto
                            </span>
                          )}
                        </div>
                      </div>
                    </button>
                  );
                })}
              </div>
            </div>
          </div>

          {/* Área de Modificação do Colaborador Selecionado */}
          {colabAtual ? (
            <div className="p-4 rounded-2xl border border-border/70 bg-card/60 space-y-4">
              <div className="flex items-center gap-3 pb-3 border-b border-border/50">
                <div className="w-14 h-14 rounded-full overflow-hidden border-2 border-primary/40 shrink-0">
                  {colabAtual.foto ? (
                    <img
                      src={colabAtual.foto}
                      alt={colabAtual.nome}
                      className="w-full h-full object-cover object-top"
                    />
                  ) : (
                    <div className="w-full h-full flex items-center justify-center font-bold text-base text-muted-foreground bg-muted">
                      {getIniciais(colabAtual.nome)}
                    </div>
                  )}
                </div>
                <div>
                  <h4 className="text-sm font-bold text-foreground">{colabAtual.nome}</h4>
                  <p className="text-xs text-muted-foreground">{colabAtual.cargo}</p>
                  <p className="text-[11px] text-muted-foreground/70 font-mono mt-0.5">
                    Matrícula: {colabAtual.matricula || '---'}
                  </p>
                </div>
              </div>

              {/* Seletor de Status */}
              <div>
                <label className="text-xs font-bold text-foreground block mb-2">
                  Status de Presença
                </label>
                <div className="grid grid-cols-3 gap-2">
                  <button
                    type="button"
                    onClick={() => setStatusTemp('presente')}
                    className={cn(
                      'flex items-center justify-center gap-1.5 p-2.5 rounded-xl border text-xs font-bold transition-all cursor-pointer',
                      statusTemp === 'presente'
                        ? 'bg-emerald-600 text-white border-emerald-500 shadow-md ring-2 ring-emerald-500/30'
                        : 'border-border/70 text-muted-foreground hover:bg-muted/40'
                    )}
                  >
                    <UserCheck className="w-4 h-4" />
                    Presente
                  </button>

                  <button
                    type="button"
                    onClick={() => setStatusTemp('falta')}
                    className={cn(
                      'flex items-center justify-center gap-1.5 p-2.5 rounded-xl border text-xs font-bold transition-all cursor-pointer',
                      statusTemp === 'falta'
                        ? 'bg-rose-600 text-white border-rose-500 shadow-md ring-2 ring-rose-500/30'
                        : 'border-border/70 text-muted-foreground hover:bg-muted/40'
                    )}
                  >
                    <UserX className="w-4 h-4" />
                    Falta
                  </button>

                  <button
                    type="button"
                    onClick={() => setStatusTemp('substituto')}
                    className={cn(
                      'flex items-center justify-center gap-1.5 p-2.5 rounded-xl border text-xs font-bold transition-all cursor-pointer',
                      statusTemp === 'substituto'
                        ? 'bg-amber-600 text-white border-amber-500 shadow-md ring-2 ring-amber-500/30'
                        : 'border-border/70 text-muted-foreground hover:bg-muted/40'
                    )}
                  >
                    <ArrowRightLeft className="w-4 h-4" />
                    Substituto
                  </button>
                </div>
              </div>

              {/* Se Falta: Motivo */}
              {statusTemp === 'falta' && (
                <div className="space-y-2 animate-in fade-in duration-150">
                  <label className="text-xs font-bold text-foreground block">
                    Motivo da Falta
                  </label>
                  <select
                    value={motivoTemp || ''}
                    onChange={(e) => setMotivoTemp(e.target.value as MotivoFalta)}
                    className="w-full h-10 px-3 rounded-xl border border-border/80 bg-background text-xs font-medium text-foreground focus:outline-none focus:ring-2 focus:ring-rose-500/30"
                  >
                    <option value="">Selecione o motivo da ausência...</option>
                    {MOTIVOS_FALTA.map((m) => (
                      <option key={m} value={m}>
                        {m}
                      </option>
                    ))}
                  </select>
                </div>
              )}

              {/* Se Substituto: Seleção da Reserva */}
              {statusTemp === 'substituto' && (
                <div className="space-y-2 animate-in fade-in duration-150">
                  <label className="text-xs font-bold text-foreground block">
                    Selecione o Colaborador Reserva
                  </label>
                  <select
                    value={substitutoIdTemp}
                    onChange={(e) => setSubstitutoIdTemp(e.target.value)}
                    className="w-full h-10 px-3 rounded-xl border border-border/80 bg-background text-xs font-medium text-foreground focus:outline-none focus:ring-2 focus:ring-amber-500/30"
                  >
                    <option value="">Selecione um operador do banco de reserva...</option>
                    {(colaboradoresReserva || []).map((res) => (
                      <option key={res.id} value={res.id}>
                        {res.nome} — {res.cargo}
                      </option>
                    ))}
                  </select>
                </div>
              )}

              {/* Observação */}
              <div className="space-y-1.5">
                <label className="text-xs font-semibold text-muted-foreground block">
                  Observações Operacionais (Opcional)
                </label>
                <input
                  type="text"
                  placeholder="Ex: Atestado entregue, retorno previsto para amanhã..."
                  value={obsTemp}
                  onChange={(e) => setObsTemp(e.target.value)}
                  className="w-full px-3 py-2 rounded-xl border border-border/70 bg-background text-xs font-medium text-foreground placeholder:text-muted-foreground focus:outline-none focus:ring-2 focus:ring-primary/30"
                />
              </div>
            </div>
          ) : (
            <div className="p-4 text-center text-xs text-muted-foreground border border-dashed rounded-xl">
              Nenhum colaborador alocado neste assento.
            </div>
          )}
        </div>

        {/* Rodapé com Ações */}
        <div className="flex items-center justify-end gap-3 px-6 py-4 border-t border-border/60 bg-muted/20">
          <Button variant="outline" size="sm" onClick={onClose} className="rounded-xl">
            Cancelar
          </Button>
          <Button
            size="sm"
            onClick={handleSalvar}
            className="rounded-xl bg-primary hover:bg-primary/90 text-primary-foreground gap-1.5 font-bold shadow-md"
          >
            <Check className="w-4 h-4" />
            Salvar Alteração
          </Button>
        </div>
      </div>
    </div>
  );
};

