import React, { useState } from 'react';
import {
  X,
  UserCheck,
  UserX,
  ArrowRightLeft,
  Calendar,
  AlertCircle,
  Car,
  Check,
  CheckCircle2,
  XCircle,
  HelpCircle,
  ShieldAlert,
} from 'lucide-react';
import { Button } from './ui/button';
import { Badge } from './ui/badge';
import { Veiculo, Colaborador, StatusPresenca, MotivoFalta } from '../types';
import { cn } from '@/lib/utils';

export interface AttendanceModalProps {
  isOpen: boolean;
  onClose: () => void;
  veiculo: Veiculo | null;
  colaboradoresReserva?: Colaborador[];
  onSalvarPresenca?: (dadosPresenca: Record<string, {
    status: StatusPresenca;
    motivo?: MotivoFalta;
    observacao?: string;
    substituto?: Colaborador;
  }>) => void;
}

const MOTIVOS_FALTA: MotivoFalta[] = [
  'Atestado Médico',
  'Falta Injustificada',
  'Folga Compensatória',
  'Treinamento / Integração',
  'Problema de Transporte',
  'Licença Especial',
];

const getIniciais = (nome?: string) => {
  if (!nome) return 'OP';
  const partes = nome.trim().split(' ');
  if (partes.length === 1) return partes[0].substring(0, 2).toUpperCase();
  return (partes[0][0] + partes[partes.length - 1][0]).toUpperCase();
};

export const AttendanceModal: React.FC<AttendanceModalProps> = ({
  isOpen,
  onClose,
  veiculo,
  colaboradoresReserva = [],
  onSalvarPresenca,
}) => {
  if (!isOpen || !veiculo) return null;

  const [presencas, setPresencas] = useState<Record<string, {
    status: StatusPresenca;
    motivo?: MotivoFalta;
    observacao?: string;
    substitutoId?: string;
  }>>(() => {
    const initial: Record<string, any> = {};
    const assentos = ['motorista', 'frenteDir', 'trasEsq', 'trasDir'] as const;
    assentos.forEach((seat) => {
      const c = veiculo.assentos?.[seat];
      if (c) {
        initial[seat] = {
          status: c.status || 'presente',
          motivo: c.motivoFalta,
          observacao: c.observacao || '',
          substitutoId: c.substitutoId || '',
        };
      }
    });
    return initial;
  });

  const handleToggleStatus = (seatKey: string) => {
    setPresencas((prev) => {
      const current = prev[seatKey];
      const novoStatus: StatusPresenca = current?.status === 'falta' ? 'presente' : 'falta';
      return {
        ...prev,
        [seatKey]: {
          ...current,
          status: novoStatus,
          motivo: novoStatus === 'falta' ? current?.motivo || 'Falta Injustificada' : undefined,
        },
      };
    });
  };

  const handleSetStatus = (seatKey: string, status: StatusPresenca) => {
    setPresencas((prev) => ({
      ...prev,
      [seatKey]: {
        ...prev[seatKey],
        status,
        motivo: status === 'falta' ? prev[seatKey]?.motivo || 'Falta Injustificada' : undefined,
      },
    }));
  };

  const handleSetMotivo = (seatKey: string, motivo: MotivoFalta) => {
    setPresencas((prev) => ({
      ...prev,
      [seatKey]: {
        ...prev[seatKey],
        motivo,
      },
    }));
  };

  const handleSetSubstituto = (seatKey: string, substitutoId: string) => {
    setPresencas((prev) => ({
      ...prev,
      [seatKey]: {
        ...prev[seatKey],
        substitutoId,
      },
    }));
  };

  const handleSalvar = () => {
    if (!onSalvarPresenca) {
      onClose();
      return;
    }

    const payload: Record<string, any> = {};
    Object.entries(presencas).forEach(([seat, val]) => {
      const sub = colaboradoresReserva.find((r) => r.id === val.substitutoId);
      payload[seat] = {
        status: val.status,
        motivo: val.motivo,
        observacao: val.observacao,
        substituto: sub,
      };
    });

    onSalvarPresenca(payload);
    onClose();
  };

  const seatsList: Array<{ key: 'motorista' | 'frenteDir' | 'trasEsq' | 'trasDir'; label: string; equipe: string }> = [
    { key: 'motorista', label: 'Motorista (Dianteiro Esq.)', equipe: veiculo.equipe1Codigo || 'Equipe 1' },
    { key: 'frenteDir', label: 'Operador (Dianteiro Dir.)', equipe: veiculo.equipe1Codigo || 'Equipe 1' },
    { key: 'trasEsq', label: 'Operador (Traseiro Esq.)', equipe: veiculo.equipe2Codigo || 'Equipe 2' },
    { key: 'trasDir', label: 'Operador (Traseiro Dir.)', equipe: veiculo.equipe2Codigo || 'Equipe 2' },
  ];

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-background/80 backdrop-blur-md animate-in fade-in duration-200 overflow-y-auto"
      onClick={onClose}
    >
      <div
        className="relative w-full max-w-2xl bg-card border border-border/80 rounded-3xl shadow-2xl overflow-hidden my-8"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Header Modal */}
        <div className="flex items-center justify-between px-6 py-4 border-b border-border/60 bg-muted/20">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-2xl bg-primary/10 border border-primary/20 text-primary flex items-center justify-center">
              <Car className="w-5 h-5" />
            </div>
            <div>
              <div className="flex items-center gap-2">
                <h3 className="text-base font-bold text-foreground">{veiculo.prefixo}</h3>
                <Badge variant="outline" className="text-[10px] font-mono py-0 px-1.5">
                  {veiculo.placa}
                </Badge>
              </div>
              <p className="text-xs text-muted-foreground">
                Toque na foto ou nos botões para marcar presença ou registrar falta
              </p>
            </div>
          </div>

          <button
            type="button"
            onClick={onClose}
            className="p-2 rounded-xl text-muted-foreground hover:text-foreground hover:bg-muted transition-colors cursor-pointer"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Lista de Colaboradores nos Assentos */}
        <div className="p-6 space-y-4 max-h-[70vh] overflow-y-auto">
          {seatsList.map(({ key, label, equipe }) => {
            const colab = veiculo.assentos?.[key];
            if (!colab) return null;

            const dados = presencas[key] || { status: 'presente' };
            const isFalta = dados.status === 'falta';
            const isSub = dados.status === 'substituto';

            return (
              <div
                key={key}
                className={cn(
                  'p-4 rounded-2xl border transition-all duration-150',
                  isFalta
                    ? 'border-rose-500/40 bg-rose-500/5'
                    : isSub
                    ? 'border-amber-500/40 bg-amber-500/5'
                    : 'border-border/60 bg-card/40'
                )}
              >
                <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-3">
                  <div className="flex items-center gap-3 min-w-0">
                    {/* Foto clicável para alternar status falta/presente */}
                    <button
                      type="button"
                      onClick={() => handleToggleStatus(key)}
                      title={isFalta ? 'Clique para marcar como Presente' : 'Clique para marcar como Falta'}
                      className="relative group shrink-0 focus:outline-none focus:ring-2 focus:ring-emerald-500/40 rounded-full cursor-pointer"
                    >
                      <div
                        className={cn(
                          'w-14 h-14 rounded-full overflow-hidden border-2 shadow-sm transition-all flex items-center justify-center',
                          isFalta
                            ? 'border-rose-500 ring-2 ring-rose-500/30 grayscale'
                            : 'border-emerald-500 ring-2 ring-emerald-500/20 group-hover:scale-105'
                        )}
                      >
                        {colab.foto ? (
                          <img
                            src={colab.foto}
                            alt={colab.nome}
                            className="w-full h-full object-cover"
                            onError={(e) => {
                              (e.target as HTMLImageElement).style.display = 'none';
                            }}
                          />
                        ) : (
                          <div className="w-full h-full bg-muted flex items-center justify-center font-bold text-xs text-foreground">
                            {getIniciais(colab.nome)}
                          </div>
                        )}
                      </div>
                      <span
                        className={cn(
                          'absolute -bottom-0.5 -right-0.5 p-0.5 rounded-full text-white shadow',
                          isFalta ? 'bg-rose-600' : 'bg-emerald-600'
                        )}
                      >
                        {isFalta ? <XCircle className="w-3.5 h-3.5" /> : <CheckCircle2 className="w-3.5 h-3.5" />}
                      </span>
                    </button>

                    <div className="min-w-0">
                      <div className="flex items-center gap-1.5 flex-wrap">
                        <span
                          className={cn(
                            'text-sm font-bold truncate',
                            isFalta ? 'text-rose-400 line-through' : 'text-foreground'
                          )}
                        >
                          {colab.nome}
                        </span>
                        <span className="text-[10px] text-muted-foreground font-mono">
                          ({colab.matricula || label})
                        </span>
                      </div>
                      <p className="text-xs text-muted-foreground">{colab.cargo} · {equipe}</p>
                    </div>
                  </div>

                  {/* Botões de Ação de Presença */}
                  <div className="flex items-center gap-1.5 self-end sm:self-center">
                    <button
                      type="button"
                      onClick={() => handleSetStatus(key, 'presente')}
                      className={cn(
                        'flex items-center gap-1 px-3 py-1.5 rounded-xl text-xs font-semibold border transition-all cursor-pointer',
                        dados.status === 'presente'
                          ? 'bg-emerald-600 text-white border-emerald-500 shadow-sm'
                          : 'border-border/60 text-muted-foreground hover:bg-muted/40'
                      )}
                    >
                      <UserCheck className="w-3.5 h-3.5" />
                      Presente
                    </button>

                    <button
                      type="button"
                      onClick={() => handleSetStatus(key, 'falta')}
                      className={cn(
                        'flex items-center gap-1 px-3 py-1.5 rounded-xl text-xs font-semibold border transition-all cursor-pointer',
                        dados.status === 'falta'
                          ? 'bg-rose-600 text-white border-rose-500 shadow-sm'
                          : 'border-border/60 text-muted-foreground hover:bg-muted/40'
                      )}
                    >
                      <UserX className="w-3.5 h-3.5" />
                      Falta
                    </button>

                    <button
                      type="button"
                      onClick={() => handleSetStatus(key, 'substituto')}
                      className={cn(
                        'flex items-center gap-1 px-3 py-1.5 rounded-xl text-xs font-semibold border transition-all cursor-pointer',
                        dados.status === 'substituto'
                          ? 'bg-amber-600 text-white border-amber-500 shadow-sm'
                          : 'border-border/60 text-muted-foreground hover:bg-muted/40'
                      )}
                    >
                      <ArrowRightLeft className="w-3.5 h-3.5" />
                      Substituto
                    </button>
                  </div>
                </div>

                {/* Se for FALTA, exibir seletor de motivo */}
                {isFalta && (
                  <div className="mt-3 pt-3 border-t border-rose-500/20 grid grid-cols-1 sm:grid-cols-2 gap-2">
                    <div>
                      <label className="text-[10px] font-bold uppercase tracking-wider text-rose-400 block mb-1">
                        Motivo da Ausência:
                      </label>
                      <select
                        value={dados.motivo || 'Falta Injustificada'}
                        onChange={(e) => handleSetMotivo(key, e.target.value as MotivoFalta)}
                        className="w-full h-8 px-2.5 rounded-lg border border-rose-500/30 bg-background text-xs font-medium text-foreground focus:outline-none focus:ring-2 focus:ring-rose-500/40"
                      >
                        {MOTIVOS_FALTA.map((m) => (
                          <option key={m} value={m}>
                            {m}
                          </option>
                        ))}
                      </select>
                    </div>
                  </div>
                )}

                {/* Se for SUBSTITUTO, exibir seleção de quem substitui */}
                {isSub && (
                  <div className="mt-3 pt-3 border-t border-amber-500/20">
                    <label className="text-[10px] font-bold uppercase tracking-wider text-amber-400 block mb-1">
                      Selecione o Colaborador Reserva:
                    </label>
                    <select
                      value={dados.substitutoId || ''}
                      onChange={(e) => handleSetSubstituto(key, e.target.value)}
                      className="w-full h-8 px-2.5 rounded-lg border border-amber-500/30 bg-background text-xs font-medium text-foreground focus:outline-none focus:ring-2 focus:ring-amber-500/40"
                    >
                      <option value="">Selecione da lista de reservas...</option>
                      {colaboradoresReserva.map((r) => (
                        <option key={r.id} value={r.id}>
                          {r.nome} — {r.cargo}
                        </option>
                      ))}
                    </select>
                  </div>
                )}
              </div>
            );
          })}
        </div>

        {/* Rodapé de Ações */}
        <div className="flex items-center justify-between px-6 py-4 border-t border-border/60 bg-muted/20">
          <span className="text-xs text-muted-foreground">
            As alterações atualizam a escala em tempo real
          </span>
          <div className="flex items-center gap-2">
            <Button variant="outline" size="sm" onClick={onClose}>
              Cancelar
            </Button>
            <Button
              size="sm"
              onClick={handleSalvar}
              className="bg-emerald-600 hover:bg-emerald-500 text-white gap-1.5"
            >
              <Check className="w-4 h-4" />
              Salvar Presenças
            </Button>
          </div>
        </div>
      </div>
    </div>
  );
};

