import React, { useState } from 'react';
import {
  Car,
  AlertTriangle,
  CheckCircle2,
  XCircle,
  HelpCircle,
  Search,
  Filter,
  Eye,
  Disc,
  Users,
  Building2,
  Calendar,
  Sparkles,
  ArrowRightLeft,
  UserCheck,
  UserX,
  FileText,
} from 'lucide-react';
import { Card, CardContent } from './ui/card';
import { Badge } from './ui/badge';
import { Button } from './ui/button';
import { Input } from './ui/input';
import { Veiculo, Colaborador, StatusPresenca, MotivoFalta, Regional } from '../types';
import { AttendanceModal } from './AttendanceModal';
import { cn } from '@/lib/utils';

export interface VehicleCardGridProps {
  veiculos?: Veiculo[];
  colaboradoresReserva?: Colaborador[];
  selectedRegional?: Regional;
  selectedDate?: Date;
  onUpdateStatus?: (
    veiculoId: string,
    colabId: string,
    status: StatusPresenca,
    motivo?: MotivoFalta,
    obs?: string,
    substituto?: Colaborador
  ) => void;
  onUpdateColaboradorStatus?: (
    colabId: string,
    novoStatus: StatusPresenca,
    motivo?: MotivoFalta,
    obs?: string
  ) => void;
  onNovaEquipeClick?: () => void;
}

const statusConfig: Record<
  StatusPresenca,
  { label: string; badgeClass: string; borderClass: string; bgClass: string; icon: any }
> = {
  presente: {
    label: 'Presente',
    badgeClass: 'bg-emerald-500/15 text-emerald-400 border-emerald-500/30',
    borderClass: 'border-emerald-500/30 group-hover:border-emerald-400',
    bgClass: 'bg-emerald-500/5',
    icon: CheckCircle2,
  },
  falta: {
    label: 'Falta',
    badgeClass: 'bg-rose-500/15 text-rose-400 border-rose-500/30',
    borderClass: 'border-rose-500/40 group-hover:border-rose-400 ring-1 ring-rose-500/20',
    bgClass: 'bg-rose-500/10',
    icon: XCircle,
  },
  substituto: {
    label: 'Substituto',
    badgeClass: 'bg-amber-500/15 text-amber-400 border-amber-500/30',
    borderClass: 'border-amber-500/30 group-hover:border-amber-400',
    bgClass: 'bg-amber-500/5',
    icon: AlertTriangle,
  },
};

const getIniciais = (nome?: string) => {
  if (!nome) return 'OP';
  const partes = nome.trim().split(' ');
  if (partes.length === 1) return partes[0].substring(0, 2).toUpperCase();
  return (partes[0][0] + partes[partes.length - 1][0]).toUpperCase();
};

export const VehicleCardGrid: React.FC<VehicleCardGridProps> = ({
  veiculos = [],
  colaboradoresReserva = [],
  selectedRegional = 'todas',
  selectedDate = new Date(),
  onUpdateStatus,
  onUpdateColaboradorStatus,
  onNovaEquipeClick,
}) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState<'todos' | 'completos' | 'incompletos'>('todos');
  const [selectedVehicleForModal, setSelectedVehicleForModal] = useState<Veiculo | null>(null);
  const [toastMessage, setToastMessage] = useState<string | null>(null);

  const showToast = (msg: string) => {
    setToastMessage(msg);
    setTimeout(() => {
      setToastMessage(null);
    }, 2800);
  };

  const veiculosFiltrados = (veiculos || []).filter((v) => {
    if (!v) return false;
    const matchRegional =
      selectedRegional === 'todas' || v.regional === selectedRegional;

    const term = searchTerm.toLowerCase();
    const matchSearch =
      !searchTerm ||
      v.prefixo?.toLowerCase().includes(term) ||
      v.placa?.toLowerCase().includes(term) ||
      v.modelo?.toLowerCase().includes(term) ||
      Object.values(v.assentos || {}).some((c) =>
        c?.nome?.toLowerCase().includes(term) || c?.matricula?.toLowerCase().includes(term)
      );

    const assentosArr = [
      v.assentos?.motorista,
      v.assentos?.frenteDir,
      v.assentos?.trasEsq,
      v.assentos?.trasDir,
    ].filter(Boolean) as Colaborador[];

    const hasFaltas = assentosArr.some((c) => c?.status === 'falta');
    const matchStatus =
      statusFilter === 'todos' ||
      (statusFilter === 'completos' && !hasFaltas) ||
      (statusFilter === 'incompletos' && hasFaltas);

    return matchRegional && matchSearch && matchStatus;
  });

  const handleToggleColaboradorStatus = (
    e: React.MouseEvent,
    veiculo: Veiculo,
    colaborador: Colaborador
  ) => {
    e.stopPropagation();
    if (!colaborador) return;

    const novoStatus: StatusPresenca = colaborador.status === 'falta' ? 'presente' : 'falta';
    const motivoPadrao: MotivoFalta | undefined =
      novoStatus === 'falta' ? 'Falta Injustificada' : undefined;

    if (onUpdateStatus) {
      onUpdateStatus(veiculo.id, colaborador.id, novoStatus, motivoPadrao);
    } else if (onUpdateColaboradorStatus) {
      onUpdateColaboradorStatus(colaborador.id, novoStatus, motivoPadrao);
    }

    showToast(
      novoStatus === 'falta'
        ? `⚠️ ${colaborador.nome} marcado como FALTA`
        : `✅ ${colaborador.nome} marcado como PRESENTE`
    );
  };

  return (
    <div className="space-y-6">
      {/* Toast Feedback */}
      {toastMessage && (
        <div className="fixed bottom-6 right-6 z-50 flex items-center gap-2.5 px-4 py-3 rounded-2xl bg-foreground text-background shadow-2xl animate-in slide-in-from-bottom-3 duration-200 text-xs font-semibold">
          <span>{toastMessage}</span>
        </div>
      )}

      {/* Barra de Filtros */}
      <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3 bg-card/60 backdrop-blur-md p-3.5 rounded-2xl border border-border/70 shadow-sm">
        <div className="relative flex-1">
          <Search className="w-4 h-4 text-muted-foreground absolute left-3 top-1/2 -translate-y-1/2" />
          <Input
            placeholder="Buscar por veículo, placa ou nome do operador..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="pl-9 h-10 text-xs bg-background/50 border-border/60 rounded-xl focus-visible:ring-emerald-500/20"
          />
        </div>

        <div className="flex items-center gap-2 overflow-x-auto pb-1 sm:pb-0">
          <button
            type="button"
            onClick={() => setStatusFilter('todos')}
            className={cn(
              'px-3.5 py-2 rounded-xl text-xs font-semibold transition-all border shrink-0 cursor-pointer',
              statusFilter === 'todos'
                ? 'bg-primary text-primary-foreground border-primary shadow-sm'
                : 'border-border/60 text-muted-foreground hover:bg-muted/40'
            )}
          >
            Todos ({veiculosFiltrados.length})
          </button>
          <button
            type="button"
            onClick={() => setStatusFilter('completos')}
            className={cn(
              'flex items-center gap-1.5 px-3.5 py-2 rounded-xl text-xs font-semibold transition-all border shrink-0 cursor-pointer',
              statusFilter === 'completos'
                ? 'bg-emerald-600 text-white border-emerald-500 shadow-sm'
                : 'border-border/60 text-muted-foreground hover:bg-muted/40'
            )}
          >
            <CheckCircle2 className="w-3.5 h-3.5 text-emerald-400" />
            100% Presentes
          </button>
          <button
            type="button"
            onClick={() => setStatusFilter('incompletos')}
            className={cn(
              'flex items-center gap-1.5 px-3.5 py-2 rounded-xl text-xs font-semibold transition-all border shrink-0 cursor-pointer',
              statusFilter === 'incompletos'
                ? 'bg-rose-600 text-white border-rose-500 shadow-sm'
                : 'border-border/60 text-muted-foreground hover:bg-muted/40'
            )}
          >
            <AlertTriangle className="w-3.5 h-3.5 text-rose-300" />
            Com Faltas
          </button>
        </div>
      </div>

      {/* Grade de Veículos */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-5">
        {veiculosFiltrados.map((veiculo) => {
          const assentosArr = [
            veiculo.assentos?.motorista,
            veiculo.assentos?.frenteDir,
            veiculo.assentos?.trasEsq,
            veiculo.assentos?.trasDir,
          ].filter(Boolean) as Colaborador[];

          const faltasCount = assentosArr.filter((c) => c?.status === 'falta').length;
          const presentesCount = assentosArr.filter(
            (c) => c?.status === 'presente' || c?.status === 'substituto'
          ).length;

          const renderSeat = (
            colab: Colaborador | undefined,
            cargoPos: string,
            seatLabel: string,
            lado: 'esq' | 'dir'
          ) => {
            if (!colab) {
              return (
                <div className="flex flex-col items-center justify-center p-3 rounded-2xl border border-dashed border-border/60 bg-muted/20 min-h-[148px]">
                  <Disc className="w-5 h-5 text-muted-foreground/40 mb-1" />
                  <span className="text-[11px] font-semibold text-muted-foreground/60">Vago</span>
                  <span className="text-[9px] text-muted-foreground/40">{seatLabel}</span>
                </div>
              );
            }

            const cfg = statusConfig[colab.status] || statusConfig.presente;
            const StatusIcon = cfg.icon;
            const isFalta = colab.status === 'falta';

            return (
              <div
                className={cn(
                  'group relative flex flex-col items-center text-center p-3 rounded-2xl border transition-all duration-200 min-h-[154px]',
                  cfg.bgClass,
                  cfg.borderClass,
                  'hover:shadow-md'
                )}
              >
                {/* Botão de Troca Rápida de Presença / Falta ao Clicar na Foto */}
                <button
                  type="button"
                  title={
                    isFalta
                      ? 'Clique para marcar como PRESENTE'
                      : 'Clique para marcar como FALTA'
                  }
                  onClick={(e) => handleToggleColaboradorStatus(e, veiculo, colab)}
                  className="relative group/photo focus:outline-none focus:ring-2 focus:ring-emerald-500/40 rounded-full transition-transform active:scale-95 cursor-pointer"
                >
                  <div
                    className={cn(
                      'w-16 h-16 rounded-full overflow-hidden border-2 shadow-md transition-all flex items-center justify-center',
                      isFalta
                        ? 'border-rose-500 ring-4 ring-rose-500/20 grayscale contrast-125'
                        : 'border-emerald-500 ring-2 ring-emerald-500/20 group-hover/photo:ring-4 group-hover/photo:ring-emerald-500/30'
                    )}
                  >
                    {colab.foto ? (
                      <img
                        src={colab.foto}
                        alt={colab.nome}
                        className="w-full h-full object-cover"
                        onError={(e) => {
                          (e.target as HTMLImageElement).style.display = 'none';
                        }}
                      />
                    ) : (
                      <div className="w-full h-full flex items-center justify-center bg-muted text-foreground font-black text-sm">
                        {getIniciais(colab.nome)}
                      </div>
                    )}
                  </div>

                  {/* Badge de Ação / Toggle sobreposta na foto */}
                  <span
                    className={cn(
                      'absolute -bottom-1 -right-1 p-1 rounded-full text-white shadow-md transition-all duration-150',
                      isFalta
                        ? 'bg-rose-600 hover:bg-rose-500 ring-2 ring-background'
                        : 'bg-emerald-600 hover:bg-emerald-500 ring-2 ring-background'
                    )}
                  >
                    {isFalta ? (
                      <XCircle className="w-4 h-4" />
                    ) : (
                      <CheckCircle2 className="w-4 h-4" />
                    )}
                  </span>

                  {/* Tooltip Hover indicando a ação */}
                  <span className="absolute -top-7 left-1/2 -translate-x-1/2 whitespace-nowrap px-2 py-0.5 rounded-md bg-foreground text-background text-[10px] font-bold opacity-0 group-hover/photo:opacity-100 transition-opacity pointer-events-none z-20 shadow-lg">
                    {isFalta ? 'Marcar Presente' : 'Marcar Falta'}
                  </span>
                </button>

                {/* Dados do Colaborador */}
                <div className="mt-2.5 w-full">
                  <p
                    className={cn(
                      'text-xs font-bold truncate tracking-tight',
                      isFalta ? 'text-rose-400 line-through decoration-rose-500/50' : 'text-foreground'
                    )}
                    title={colab.nome}
                  >
                    {colab.nome}
                  </p>
                  <p className="text-[10px] text-muted-foreground truncate font-medium">
                    {colab.cargo || cargoPos}
                  </p>
                </div>

                {/* Pílula de Status com clique para alternar */}
                <button
                  type="button"
                  onClick={(e) => handleToggleColaboradorStatus(e, veiculo, colab)}
                  className={cn(
                    'mt-2 inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[10px] font-semibold border transition-all cursor-pointer hover:opacity-85',
                    cfg.badgeClass
                  )}
                  title="Clique para alternar presença / falta"
                >
                  <StatusIcon className="w-3 h-3" />
                  <span>{cfg.label}</span>
                </button>
              </div>
            );
          };

          return (
            <Card
              key={veiculo.id}
              className={cn(
                'rounded-3xl border transition-all duration-200 overflow-hidden bg-card/60 backdrop-blur-md hover:shadow-xl',
                faltasCount > 0 ? 'border-rose-500/30' : 'border-border/70'
              )}
            >
              {/* Header do Card */}
              <div className="p-4 border-b border-border/50 bg-gradient-to-r from-muted/20 via-transparent to-transparent flex items-center justify-between gap-3">
                <div className="flex items-center gap-2.5">
                  <div className="w-10 h-10 rounded-2xl bg-primary/10 border border-primary/20 flex items-center justify-center text-primary font-black">
                    <Car className="w-5 h-5" />
                  </div>
                  <div>
                    <div className="flex items-center gap-2">
                      <h3 className="font-extrabold text-sm sm:text-base text-foreground tracking-tight">
                        {veiculo.prefixo}
                      </h3>
                      <Badge
                        variant="outline"
                        className="text-[10px] py-0 px-1.5 border-border/70 font-mono text-muted-foreground"
                      >
                        {veiculo.placa}
                      </Badge>
                    </div>
                    <span className="text-[11px] text-muted-foreground font-medium">
                      {veiculo.regional === 'ribas' ? 'Ribas do Rio Pardo' : 'Água Clara'}
                    </span>
                  </div>
                </div>

                <div className="text-right">
                  <span
                    className={cn(
                      'inline-flex items-center gap-1 px-2.5 py-1 rounded-full text-xs font-bold border',
                      faltasCount > 0
                        ? 'bg-rose-500/10 text-rose-400 border-rose-500/30'
                        : 'bg-emerald-500/10 text-emerald-400 border-emerald-500/30'
                    )}
                  >
                    {faltasCount > 0 ? (
                      <>
                        <AlertTriangle className="w-3.5 h-3.5" />
                        <span>{faltasCount} Falta{faltasCount > 1 ? 's' : ''}</span>
                      </>
                    ) : (
                      <>
                        <CheckCircle2 className="w-3.5 h-3.5" />
                        <span>Completo</span>
                      </>
                    )}
                  </span>
                </div>
              </div>

              {/* Habitáculo / Representação das Posições do Veículo */}
              <div className="p-4 space-y-4">
                {/* Equipe 1: Dianteira (Motorista & Frente Direito) */}
                <div>
                  <div className="flex items-center justify-between mb-2 px-1">
                    <span className="text-[10px] font-bold uppercase tracking-wider text-muted-foreground flex items-center gap-1">
                      <Users className="w-3 h-3 text-emerald-400" />
                      Frente · {veiculo.equipe1Codigo || 'Equipe 1'}
                    </span>
                    <span className="text-[10px] text-muted-foreground/70">Cabine Dianteira</span>
                  </div>
                  <div className="grid grid-cols-2 gap-2.5">
                    {renderSeat(veiculo.assentos?.motorista, 'Motorista', 'Assento Motorista', 'esq')}
                    {renderSeat(veiculo.assentos?.frenteDir, 'Operador', 'Assento Dianteiro Dir', 'dir')}
                  </div>
                </div>

                {/* Divisor do habitáculo do carro */}
                <div className="relative flex items-center justify-center">
                  <div className="w-full border-t border-dashed border-border/60" />
                  <span className="absolute bg-card px-2 text-[9px] font-semibold text-muted-foreground/60 uppercase tracking-widest">
                    Bancos Traseiros
                  </span>
                </div>

                {/* Equipe 2: Traseira (Traseiro Esquerdo & Traseiro Direito) */}
                <div>
                  <div className="flex items-center justify-between mb-2 px-1">
                    <span className="text-[10px] font-bold uppercase tracking-wider text-muted-foreground flex items-center gap-1">
                      <Users className="w-3 h-3 text-teal-400" />
                      Atrás · {veiculo.equipe2Codigo || 'Equipe 2'}
                    </span>
                    <span className="text-[10px] text-muted-foreground/70">Cabine Traseira</span>
                  </div>
                  <div className="grid grid-cols-2 gap-2.5">
                    {renderSeat(veiculo.assentos?.trasEsq, 'Operador', 'Assento Traseiro Esq', 'esq')}
                    {renderSeat(veiculo.assentos?.trasDir, 'Operador', 'Assento Traseiro Dir', 'dir')}
                  </div>
                </div>
              </div>

              {/* Rodapé com botão de Gerenciar / Justificar */}
              <div className="p-3 bg-muted/20 border-t border-border/50 flex items-center justify-between gap-2">
                <span className="text-[11px] text-muted-foreground">
                  Toque na foto para marcar falta rápida
                </span>
                <Button
                  size="sm"
                  variant="outline"
                  onClick={() => setSelectedVehicleForModal(veiculo)}
                  className="text-xs h-8 px-3 rounded-xl gap-1.5 border-border/70 hover:bg-card"
                >
                  <Eye className="w-3.5 h-3.5" />
                  Detalhes & Justificativa
                </Button>
              </div>
            </Card>
          );
        })}
      </div>

      {veiculosFiltrados.length === 0 && (
        <div className="py-16 text-center rounded-3xl border border-dashed border-border/70 bg-card/20 space-y-3">
          <Car className="w-10 h-10 text-muted-foreground/50 mx-auto" />
          <h4 className="font-bold text-base text-foreground">Nenhum veículo encontrado</h4>
          <p className="text-xs text-muted-foreground max-w-sm mx-auto">
            Verifique o filtro de unidade operacional ou termo de busca pesquisado.
          </p>
        </div>
      )}

      {/* Modal de Detalhes e Justificativa de Presença */}
      {selectedVehicleForModal && (
        <AttendanceModal
          isOpen={Boolean(selectedVehicleForModal)}
          onClose={() => setSelectedVehicleForModal(null)}
          veiculo={selectedVehicleForModal}
          colaboradoresReserva={colaboradoresReserva}
          onSalvarPresenca={(dados) => {
            if (onUpdateStatus && selectedVehicleForModal) {
              Object.entries(dados).forEach(([posicao, info]: [string, any]) => {
                if (info?.status) {
                  const colab = (selectedVehicleForModal.assentos as any)?.[posicao];
                  if (colab) {
                    onUpdateStatus(
                      selectedVehicleForModal.id,
                      colab.id,
                      info.status,
                      info.motivo,
                      info.observacao,
                      info.substituto
                    );
                  }
                }
              });
            }
            setSelectedVehicleForModal(null);
          }}
        />
      )}
    </div>
  );
};

files.newContent:
import React, { useState } from 'react';
import {
  Car,
  AlertTriangle,
  CheckCircle2,
  XCircle,
  HelpCircle,
  Search,
  Filter,
  Eye,
  Disc,
  Users,
  Clock,
  Sparkles,
  Phone,
  UserCheck,
  UserX,
  RotateCcw,
  Check,
  X,
} from 'lucide-react';
import { Veiculo, Colaborador, StatusPresenca, MotivoFalta, Regional } from '../types';
import { Badge } from './ui/badge';
import { Button } from './ui/button';
import { Input } from './ui/input';
import { AttendanceModal } from './AttendanceModal';
import { cn } from '@/lib/utils';

export interface VehicleCardGridProps {
  veiculos?: Veiculo[];
  colaboradoresReserva?: Colaborador[];
  selectedRegional?: Regional;
  selectedDate?: Date;
  onUpdateColaboradorStatus?: (
    colabId: string,
    novoStatus: StatusPresenca,
    motivo?: MotivoFalta,
    obs?: string,
    substitutoId?: string,
    substitutoNome?: string
  ) => void;
  onSelectVeiculo?: (veiculo: Veiculo) => void;
}

const statusBadgeConfig: Record<StatusPresenca, { label: string; bg: string; text: string; border: string }> = {
  presente: { label: 'Presente', bg: 'bg-emerald-500/15', text: 'text-emerald-400', border: 'border-emerald-500/30' },
  falta: { label: 'Falta', bg: 'bg-rose-500/15', text: 'text-rose-400', border: 'border-rose-500/30' },
  substituto: { label: 'Substituto', bg: 'bg-amber-500/15', text: 'text-amber-400', border: 'border-amber-500/30' },
};

const MOTIVOS_FALTA: MotivoFalta[] = [
  'Atestado Médico',
  'Falta Injustificada',
  'Folga Compensatória',
  'Treinamento / Integração',
  'Problema de Transporte',
  'Licença Especial',
];

const getIniciais = (nome?: string) => {
  if (!nome) return 'OP';
  const partes = nome.trim().split(' ');
  if (partes.length === 1) return partes[0].substring(0, 2).toUpperCase();
  return (partes[0][0] + partes[partes.length - 1][0]).toUpperCase();
};

export const VehicleCardGrid: React.FC<VehicleCardGridProps> = ({
  veiculos = [],
  colaboradoresReserva = [],
  selectedRegional = 'todas',
  selectedDate = new Date(),
  onUpdateColaboradorStatus,
  onSelectVeiculo,
}) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState<'todos' | 'completos' | 'incompletos'>('todos');
  const [veiculoModal, setVeiculoModal] = useState<Veiculo | null>(null);

  // Estado para o Popover / Modal Rápido de troca de Status ao clicar na foto
  const [quickStatusTarget, setQuickStatusTarget] = useState<{
    colaborador: Colaborador;
    veiculoPrefixo: string;
    novoStatus: StatusPresenca;
    motivoFalta?: MotivoFalta;
    observacao?: string;
    substitutoId?: string;
    substitutoNome?: string;
  } | null>(null);

  const getStatusVeiculo = (veiculo: Veiculo) => {
    if (!veiculo || !veiculo.assentos) return { status: 'completo', countFaltas: 0, countTotal: 0 };
    const assentos = [
      veiculo.assentos.motorista,
      veiculo.assentos.frenteDir,
      veiculo.assentos.trasEsq,
      veiculo.assentos.trasDir,
    ].filter(Boolean);

    const countFaltas = assentos.filter((c) => c?.status === 'falta').length;
    return {
      status: countFaltas > 0 ? 'incompleto' : 'completo',
      countFaltas,
      countTotal: assentos.length,
    };
  };

  const veiculosFiltrados = (veiculos || []).filter((v) => {
    if (!v) return false;
    const matchRegional = selectedRegional === 'todas' || v.regional === selectedRegional;
    const { status } = getStatusVeiculo(v);
    const matchStatus =
      statusFilter === 'todos' ||
      (statusFilter === 'completos' && status === 'completo') ||
      (statusFilter === 'incompletos' && status === 'incompleto');

    const searchLower = searchTerm.toLowerCase();
    const assentosLista = v.assentos
      ? [v.assentos.motorista, v.assentos.frenteDir, v.assentos.trasEsq, v.assentos.trasDir].filter(Boolean)
      : [];

    const matchSearch =
      !searchTerm ||
      (v.prefixo || '').toLowerCase().includes(searchLower) ||
      (v.placa || '').toLowerCase().includes(searchLower) ||
      (v.modelo || '').toLowerCase().includes(searchLower) ||
      (v.equipe1Codigo || '').toLowerCase().includes(searchLower) ||
      (v.equipe2Codigo || '').toLowerCase().includes(searchLower) ||
      assentosLista.some((c) => (c?.nome || '').toLowerCase().includes(searchLower));

    return matchRegional && matchStatus && matchSearch;
  });

  const handleOpenQuickStatus = (e: React.MouseEvent, colab: Colaborador, veiculoPrefixo: string) => {
    e.stopPropagation();
    setQuickStatusTarget({
      colaborador: colab,
      veiculoPrefixo,
      novoStatus: colab.status || 'presente',
      motivoFalta: colab.motivoFalta || 'Atestado Médico',
      observacao: colab.observacao || '',
      substitutoId: colab.substitutoId || '',
      substitutoNome: colab.substitutoNome || '',
    });
  };

  const handleSalvarQuickStatus = () => {
    if (!quickStatusTarget || !onUpdateColaboradorStatus) {
      setQuickStatusTarget(null);
      return;
    }

    const { colaborador, novoStatus, motivoFalta, observacao, substitutoId, substitutoNome } = quickStatusTarget;

    onUpdateColaboradorStatus(
      colaborador.id,
      novoStatus,
      novoStatus === 'falta' ? motivoFalta : undefined,
      observacao,
      novoStatus === 'substituto' ? substitutoId : undefined,
      novoStatus === 'substituto' ? substitutoNome : undefined
    );

    setQuickStatusTarget(null);
  };

  // Renderizador de cada Assento com Destaque no Quadrado da Foto Clicável
  const renderAssento = (
    colab: Colaborador | undefined,
    posicaoTitulo: string,
    veiculo: Veiculo
  ) => {
    if (!colab) {
      return (
        <div className="flex items-center gap-3 p-3 rounded-2xl border border-dashed border-border/40 bg-card/20">
          <div className="w-12 h-12 rounded-2xl border border-dashed border-border/60 bg-muted/20 flex items-center justify-center text-muted-foreground shrink-0 text-xs font-semibold">
            Vazio
          </div>
          <div className="flex-1 min-w-0">
            <span className="text-[11px] font-bold text-muted-foreground uppercase tracking-wider block">
              {posicaoTitulo}
            </span>
            <span className="text-xs text-muted-foreground/80 italic">Posto não ocupado</span>
          </div>
        </div>
      );
    }

    const statusStyle = statusBadgeConfig[colab.status] || statusBadgeConfig.presente;

    return (
      <div
        className={cn(
          'group relative flex items-center gap-3.5 p-3 rounded-2xl border transition-all duration-200',
          colab.status === 'falta'
            ? 'border-rose-500/40 bg-rose-500/5 hover:border-rose-500/70 hover:bg-rose-500/10'
            : colab.status === 'substituto'
            ? 'border-amber-500/40 bg-amber-500/5 hover:border-amber-500/70 hover:bg-amber-500/10'
            : 'border-border/70 bg-card/60 hover:border-emerald-500/50 hover:bg-card/90'
        )}
      >
        {/* QUADRADO DA FOTO CLICÁVEL COM FEEDBACK VISUAL E BOTÃO DE STATUS */}
        <button
          type="button"
          onClick={(e) => handleOpenQuickStatus(e, colab, veiculo.prefixo)}
          title={`Clique para definir Falta, Presença ou Substituição de ${colab.nome}`}
          className={cn(
            'relative w-14 h-14 rounded-2xl overflow-hidden shrink-0 border-2 transition-transform duration-150 active:scale-95 shadow-md flex items-center justify-center cursor-pointer group/foto',
            colab.status === 'falta'
              ? 'border-rose-500 ring-2 ring-rose-500/30'
              : colab.status === 'substituto'
              ? 'border-amber-500 ring-2 ring-amber-500/30'
              : 'border-emerald-500/80 ring-2 ring-emerald-500/20'
          )}
        >
          {colab.foto ? (
            <img
              src={colab.foto}
              alt={colab.nome}
              className="w-full h-full object-cover group-hover/foto:scale-105 transition-transform duration-200"
            />
          ) : (
            <div className="w-full h-full bg-gradient-to-br from-muted to-muted/80 flex items-center justify-center font-bold text-sm text-foreground">
              {getIniciais(colab.nome)}
            </div>
          )}

          {/* Overlay Hover na Foto instruindo ação */}
          <div className="absolute inset-0 bg-black/60 opacity-0 group-hover/foto:opacity-100 transition-opacity duration-150 flex flex-col items-center justify-center text-white text-[10px] font-bold p-1 text-center leading-tight">
            <span>Alterar</span>
            <span className="text-[9px] text-emerald-300 font-medium">Status</span>
          </div>

          {/* Ícone fixo de status no canto da foto */}
          <span className="absolute bottom-0.5 right-0.5 p-0.5 rounded-full bg-background/90 shadow-sm border border-border/80">
            {colab.status === 'falta' ? (
              <XCircle className="w-3.5 h-3.5 text-rose-500" />
            ) : colab.status === 'substituto' ? (
              <HelpCircle className="w-3.5 h-3.5 text-amber-500" />
            ) : (
              <CheckCircle2 className="w-3.5 h-3.5 text-emerald-500" />
            )}
          </span>
        </button>

        {/* Detalhes do Colaborador */}
        <div className="flex-1 min-w-0 space-y-0.5">
          <div className="flex items-center justify-between gap-1">
            <span className="text-[10px] font-bold uppercase tracking-wider text-muted-foreground">
              {posicaoTitulo}
            </span>

            {/* Badge de Status Clicável também */}
            <button
              type="button"
              onClick={(e) => handleOpenQuickStatus(e, colab, veiculo.prefixo)}
              className={cn(
                'px-2 py-0.5 rounded-full border text-[11px] font-bold transition-all hover:scale-105 active:scale-95 cursor-pointer',
                statusStyle.bg,
                statusStyle.text,
                statusStyle.border
              )}
            >
              {statusStyle.label}
            </button>
          </div>

          <p className="text-sm font-bold text-foreground truncate">{colab.nome}</p>

          <div className="flex items-center gap-2 text-xs text-muted-foreground">
            <span className="truncate">{colab.cargo}</span>
            {colab.matricula && (
              <>
                <span className="opacity-40">•</span>
                <span className="font-mono text-[11px] tabular-nums">{colab.matricula}</span>
              </>
            )}
          </div>

          {colab.status === 'falta' && colab.motivoFalta && (
            <p className="text-[11px] font-semibold text-rose-400 truncate flex items-center gap-1 pt-0.5">
              <span className="w-1.5 h-1.5 rounded-full bg-rose-500 shrink-0" />
              {colab.motivoFalta}
            </p>
          )}

          {colab.status === 'substituto' && colab.substitutoNome && (
            <p className="text-[11px] font-semibold text-amber-400 truncate flex items-center gap-1 pt-0.5">
              <span className="w-1.5 h-1.5 rounded-full bg-amber-500 shrink-0" />
              Subst: {colab.substitutoNome}
            </p>
          )}
        </div>
      </div>
    );
  };

  return (
    <div className="space-y-6">
      {/* Barra de Filtro e Busca */}
      <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3 bg-card/60 p-4 rounded-3xl border border-border/80 shadow-md backdrop-blur-md">
        <div className="relative flex-1">
          <Search className="w-4 h-4 text-muted-foreground absolute left-3.5 top-1/2 -translate-y-1/2" />
          <Input
            placeholder="Buscar por prefixo, placa, equipe ou nome do colaborador..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="pl-10 h-10 text-xs sm:text-sm bg-background/50 border-border/70 rounded-2xl"
          />
        </div>

        <div className="flex items-center gap-2">
          <button
            type="button"
            onClick={() => setStatusFilter('todos')}
            className={cn(
              'px-3.5 py-2 rounded-xl text-xs font-bold border transition-all cursor-pointer',
              statusFilter === 'todos'
                ? 'bg-primary text-primary-foreground border-primary shadow-sm'
                : 'border-border/70 text-muted-foreground hover:bg-muted/40'
            )}
          >
            Todos ({veiculos.length})
          </button>
          <button
            type="button"
            onClick={() => setStatusFilter('completos')}
            className={cn(
              'px-3.5 py-2 rounded-xl text-xs font-bold border transition-all cursor-pointer',
              statusFilter === 'completos'
                ? 'bg-emerald-600 text-white border-emerald-500 shadow-sm'
                : 'border-border/70 text-muted-foreground hover:bg-muted/40'
            )}
          >
            Completos
          </button>
          <button
            type="button"
            onClick={() => setStatusFilter('incompletos')}
            className={cn(
              'px-3.5 py-2 rounded-xl text-xs font-bold border transition-all cursor-pointer',
              statusFilter === 'incompletos'
                ? 'bg-rose-600 text-white border-rose-500 shadow-sm'
                : 'border-border/70 text-muted-foreground hover:bg-muted/40'
            )}
          >
            Com Falta
          </button>
        </div>
      </div>

      {/* Grid de Veículos */}
      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-5">
        {veiculosFiltrados.length === 0 ? (
          <div className="col-span-full py-16 text-center rounded-3xl border border-dashed border-border/80 bg-card/30">
            <Car className="w-10 h-10 text-muted-foreground mx-auto mb-3 opacity-50" />
            <p className="text-base font-bold text-foreground">Nenhum veículo encontrado</p>
            <p className="text-xs text-muted-foreground mt-1 max-w-sm mx-auto">
              Tente redefinir os filtros de busca ou regional selecionada para ver mais registros.
            </p>
          </div>
        ) : (
          veiculosFiltrados.map((veiculo) => {
            const { status, countFaltas } = getStatusVeiculo(veiculo);

            return (
              <div
                key={veiculo.id}
                className={cn(
                  'group rounded-3xl border bg-card/70 backdrop-blur-md shadow-xl transition-all duration-200 overflow-hidden flex flex-col',
                  status === 'incompleto'
                    ? 'border-rose-500/40 hover:border-rose-500/70 shadow-rose-950/10'
                    : 'border-border/80 hover:border-emerald-500/40 shadow-emerald-950/5'
                )}
              >
                {/* Cabeçalho do Card do Veículo */}
                <div className="p-4 sm:p-5 border-b border-border/60 bg-gradient-to-r from-muted/20 to-transparent flex items-center justify-between gap-3">
                  <div className="space-y-1">
                    <div className="flex items-center gap-2">
                      <span className="font-black text-base tracking-tight text-foreground">
                        {veiculo.prefixo}
                      </span>
                      <Badge
                        variant="outline"
                        className={cn(
                          'text-[10px] py-0 px-2 font-bold',
                          status === 'incompleto'
                            ? 'bg-rose-500/15 text-rose-400 border-rose-500/30'
                            : 'bg-emerald-500/15 text-emerald-400 border-emerald-500/30'
                        )}
                      >
                        {status === 'incompleto' ? `${countFaltas} Falta(s)` : 'Completo'}
                      </Badge>
                    </div>

                    <div className="flex items-center gap-2 text-xs text-muted-foreground font-mono">
                      <span>{veiculo.placa}</span>
                      <span className="opacity-40">•</span>
                      <span>{veiculo.modelo}</span>
                    </div>
                  </div>

                  <Button
                    size="sm"
                    variant="outline"
                    onClick={() => {
                      setVeiculoModal(veiculo);
                      onSelectVeiculo?.(veiculo);
                    }}
                    className="h-8 px-3 rounded-xl border-border/80 hover:border-emerald-500/60 hover:text-emerald-400 text-xs font-semibold gap-1.5"
                  >
                    <Eye className="w-3.5 h-3.5" />
                    <span>Detalhar</span>
                  </Button>
                </div>

                {/* Corpo do Veículo: 4 Assentos (Clique na Foto para alterar presença/falta/substituto) */}
                <div className="p-4 sm:p-5 space-y-4 flex-1">
                  {/* Equipe 1 (Frente) */}
                  <div className="space-y-2.5">
                    <div className="flex items-center justify-between text-xs font-semibold text-muted-foreground px-1">
                      <span className="flex items-center gap-1.5 text-emerald-400">
                        <Users className="w-3.5 h-3.5" />
                        {veiculo.equipe1Codigo || 'Equipe 1 (Frente)'}
                      </span>
                      <span className="text-[10px] text-muted-foreground/70 font-mono">Assentos Dianteiros</span>
                    </div>

                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-2.5">
                      {renderAssento(veiculo.assentos?.motorista, 'Motorista', veiculo)}
                      {renderAssento(veiculo.assentos?.frenteDir, 'Ajudante Frente', veiculo)}
                    </div>
                  </div>

                  {/* Equipe 2 (Traseira) */}
                  <div className="space-y-2.5 pt-2 border-t border-border/40">
                    <div className="flex items-center justify-between text-xs font-semibold text-muted-foreground px-1">
                      <span className="flex items-center gap-1.5 text-teal-400">
                        <Users className="w-3.5 h-3.5" />
                        {veiculo.equipe2Codigo || 'Equipe 2 (Traseira)'}
                      </span>
                      <span className="text-[10px] text-muted-foreground/70 font-mono">Assentos Traseiros</span>
                    </div>

                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-2.5">
                      {renderAssento(veiculo.assentos?.trasEsq, 'Ajudante Trás Esq.', veiculo)}
                      {renderAssento(veiculo.assentos?.trasDir, 'Ajudante Trás Dir.', veiculo)}
                    </div>
                  </div>
                </div>

                {/* Rodapé informativo */}
                <div className="px-4 py-2.5 bg-muted/10 border-t border-border/40 flex items-center justify-between text-[11px] text-muted-foreground">
                  <span className="flex items-center gap-1">
                    <Clock className="w-3.5 h-3.5 opacity-60" />
                    Regional: <strong className="text-foreground capitalize">{veiculo.regional.replace('_', ' ')}</strong>
                  </span>
                  <span className="text-[10px] opacity-75">Clique na foto para alterar presença</span>
                </div>
              </div>
            );
          })
        )}
      </div>

      {/* MODAL RÁPIDO AO CLICAR NO QUADRADO DA FOTO DO COLABORADOR */}
      {quickStatusTarget && (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-background/80 backdrop-blur-md animate-in fade-in duration-150"
          onClick={() => setQuickStatusTarget(null)}
        >
          <div
            className="relative w-full max-w-md bg-card border border-border/80 rounded-3xl shadow-2xl p-5 space-y-4 animate-in zoom-in-95 duration-150"
            onClick={(e) => e.stopPropagation()}
          >
            {/* Header com Foto e Nome */}
            <div className="flex items-start justify-between gap-3 pb-3 border-b border-border/60">
              <div className="flex items-center gap-3">
                <div className="w-14 h-14 rounded-2xl overflow-hidden border-2 border-primary/50 shadow-md shrink-0">
                  {quickStatusTarget.colaborador.foto ? (
                    <img
                      src={quickStatusTarget.colaborador.foto}
                      alt={quickStatusTarget.colaborador.nome}
                      className="w-full h-full object-cover"
                    />
                  ) : (
                    <div className="w-full h-full bg-muted flex items-center justify-center font-bold text-sm">
                      {getIniciais(quickStatusTarget.colaborador.nome)}
                    </div>
                  )}
                </div>

                <div>
                  <h3 className="text-base font-bold text-foreground leading-tight">
                    {quickStatusTarget.colaborador.nome}
                  </h3>
                  <p className="text-xs text-muted-foreground mt-0.5">{quickTargetCargoSubtitle(quickStatusTarget)}</p>
                  <p className="text-[11px] text-emerald-400 font-semibold">{quickStatusTarget.veiculoPrefixo}</p>
                </div>
              </div>

              <button
                type="button"
                onClick={() => setQuickStatusTarget(null)}
                className="p-1 rounded-xl text-muted-foreground hover:text-foreground hover:bg-muted"
              >
                <X className="w-5 h-5" />
              </button>
            </div>

            {/* SELEÇÃO DO STATUS (PRESENTE, FALTA OU SUBSTITUIÇÃO) */}
            <div className="space-y-2">
              <label className="text-xs font-bold text-muted-foreground uppercase tracking-wider block">
                Selecione o Status Operacional
              </label>

              <div className="grid grid-cols-3 gap-2">
                {/* Presente */}
                <button
                  type="button"
                  onClick={() => setQuickStatusTarget((prev) => prev ? { ...prev, novoStatus: 'presente' } : null)}
                  className={cn(
                    'flex flex-col items-center justify-center gap-1.5 p-3 rounded-2xl border-2 transition-all cursor-pointer',
                    quickStatusTarget.novoStatus === 'presente'
                      ? 'border-emerald-500 bg-emerald-500/15 text-emerald-400 font-bold shadow-md'
                      : 'border-border/60 bg-muted/20 text-muted-foreground hover:border-emerald-500/40'
                  )}
                >
                  <UserCheck className="w-5 h-5" />
                  <span className="text-xs">Presente</span>
                </button>

                {/* Falta */}
                <button
                  type="button"
                  onClick={() => setQuickStatusTarget((prev) => prev ? { ...prev, novoStatus: 'falta' } : null)}
                  className={cn(
                    'flex flex-col items-center justify-center gap-1.5 p-3 rounded-2xl border-2 transition-all cursor-pointer',
                    quickStatusTarget.novoStatus === 'falta'
                      ? 'border-rose-500 bg-rose-500/15 text-rose-400 font-bold shadow-md'
                      : 'border-border/60 bg-muted/20 text-muted-foreground hover:border-rose-500/40'
                  )}
                >
                  <UserX className="w-5 h-5" />
                  <span className="text-xs">Falta</span>
                </button>

                {/* Substituto */}
                <button
                  type="button"
                  onClick={() => setQuickStatusTarget((prev) => prev ? { ...prev, novoStatus: 'substituto' } : null)}
                  className={cn(
                    'flex flex-col items-center justify-center gap-1.5 p-3 rounded-2xl border-2 transition-all cursor-pointer',
                    quickStatusTarget.novoStatus === 'substituto'
                      ? 'border-amber-500 bg-amber-500/15 text-amber-400 font-bold shadow-md'
                      : 'border-border/60 bg-muted/20 text-muted-foreground hover:border-amber-500/40'
                  )}
                >
                  <RotateCcw className="w-5 h-5" />
                  <span className="text-xs">Substituto</span>
                </button>
              </div>
            </div>

            {/* SE FOR FALTA: ESCOLHA DO MOTIVO */}
            {quickStatusTarget.novoStatus === 'falta' && (
              <div className="space-y-2 p-3 rounded-2xl bg-rose-500/5 border border-rose-500/20 animate-in fade-in-50">
                <label className="text-xs font-bold text-rose-400 block">
                  Motivo da Falta
                </label>
                <select
                  value={quickStatusTarget.motivoFalta || 'Atestado Médico'}
                  onChange={(e) =>
                    setQuickStatusTarget((prev) =>
                      prev ? { ...prev, motivoFalta: e.target.value as MotivoFalta } : null
                    )
                  }
                  className="w-full h-10 px-3 rounded-xl border border-rose-500/30 bg-background text-xs font-semibold text-foreground focus:outline-none focus:ring-2 focus:ring-rose-500/30"
                >
                  {MOTIVOS_FALTA.map((m) => (
                    <option key={m} value={m}>
                      {m}
                    </option>
                  ))}
                </select>
              </div>
            )}

            {/* SE FOR SUBSTITUTO: SELEÇÃO DO COLABORADOR RESERVA */}
            {quickStatusTarget.novoStatus === 'substituto' && (
              <div className="space-y-2 p-3 rounded-2xl bg-amber-500/5 border border-amber-500/20 animate-in fade-in-50">
                <label className="text-xs font-bold text-amber-400 block">
                  Selecione o Substituto do Banco de Reserva
                </label>
                <select
                  value={quickStatusTarget.substitutoId || ''}
                  onChange={(e) => {
                    const selId = e.target.value;
                    const r = colaboradoresReserva.find((res) => res.id === selId);
                    setQuickStatusTarget((prev) =>
                      prev
                        ? {
                            ...prev,
                            substitutoId: selId,
                            substitutoNome: r ? r.nome : '',
                          }
                        : null
                    );
                  }}
                  className="w-full h-10 px-3 rounded-xl border border-amber-500/30 bg-background text-xs font-semibold text-foreground focus:outline-none focus:ring-2 focus:ring-amber-500/30"
                >
                  <option value="">Selecione um substituto...</option>
                  {colaboradoresReserva.map((res) => (
                    <option key={res.id} value={res.id}>
                      {res.nome} ({res.cargo})
                    </option>
                  ))}
                </select>
              </div>
            )}

            {/* Observações Opcionais */}
            <div className="space-y-1">
              <label className="text-xs font-semibold text-muted-foreground block">
                Observação (Opcional)
              </label>
              <Input
                placeholder="Ex: Avisou com antecedência / consulta agendada"
                value={quickStatusTarget.observacao || ''}
                onChange={(e) =>
                  setQuickStatusTarget((prev) =>
                    prev ? { ...prev, observacao: e.target.value } : null
                  )
                }
                className="h-9 text-xs rounded-xl"
              />
            </div>

            {/* Ações */}
            <div className="flex items-center justify-end gap-2 pt-2 border-t border-border/60">
              <Button
                type="button"
                variant="outline"
                size="sm"
                onClick={() => setQuickStatusTarget(null)}
                className="rounded-xl"
              >
                Cancelar
              </Button>
              <Button
                type="button"
                size="sm"
                onClick={handleSalvarQuickStatus}
                className="gap-1.5 rounded-xl bg-emerald-600 hover:bg-emerald-500 text-white font-bold"
              >
                <Check className="w-4 h-4" />
                Confirmar
              </Button>
            </div>
          </div>
        </div>
      )}

      {/* Modal Completo de Gestão de Presença de Veículo */}
      {veiculoModal && (
        <AttendanceModal
          isOpen={!!veiculoModal}
          onClose={() => setVeiculoModal(null)}
          veiculo={veiculoModal}
          colaboradoresReserva={colaboradoresReserva}
          onSalvarStatus={(colabId, novoStatus, motivo, obs, subId, subNome) => {
            if (onUpdateColaboradorStatus) {
              onUpdateColaboradorStatus(colabId, novoStatus, motivo, obs, subId, subNome);
            }
          }}
        />
      )}
    </div>
  );
};

function quickTargetCargoSubtitle(target: { colaborador: Colaborador }): string {
  const c = target.colaborador;
  return `${c.cargo || 'Operador'}${c.matricula ? ` • Matrícula ${c.matricula}` : ''}`;
}

files.oldContent:
import React, { useState } from 'react';
import {
  X,
  UserCheck,
  UserX,
  ArrowRightLeft,
  Calendar,
  AlertCircle,
  Car,
  Check,
  CheckCircle2,
  XCircle,
  HelpCircle,
  ShieldAlert,
} from 'lucide-react';
import { Button } from './ui/button';
import { Badge } from './ui/badge';
import { Veiculo, Colaborador, StatusPresenca, MotivoFalta } from '../types';
import { cn } from '@/lib/utils';

export interface AttendanceModalProps {
  isOpen: boolean;
  onClose: () => void;
  veiculo: Veiculo | null;
  colaboradoresReserva?: Colaborador[];
  onSalvarPresenca?: (dadosPresenca: Record<string, {
    status: StatusPresenca;
    motivo?: MotivoFalta;
    observacao?: string;
    substituto?: Colaborador;
  }>) => void;
}

const MOTIVOS_FALTA: MotivoFalta[] = [
  'Atestado Médico',
  'Falta Injustificada',
  'Folga Compensatória',
  'Treinamento / Integração',
  'Problema de Transporte',
  'Licença Especial',
];

const getIniciais = (nome?: string) => {
  if (!nome) return 'OP';
  const partes = nome.trim().split(' ');
  if (partes.length === 1) return partes[0].substring(0, 2).toUpperCase();
  return (partes[0][0] + partes[partes.length - 1][0]).toUpperCase();
};

export const AttendanceModal: React.FC<AttendanceModalProps> = ({
  isOpen,
  onClose,
  veiculo,
  colaboradoresReserva = [],
  onSalvarPresenca,
}) => {
  if (!isOpen || !veiculo) return null;

  const [presencas, setPresencas] = useState<Record<string, {
    status: StatusPresenca;
    motivo?: MotivoFalta;
    observacao?: string;
    substitutoId?: string;
  }>>(() => {
    const initial: Record<string, any> = {};
    const assentos = ['motorista', 'frenteDir', 'trasEsq', 'trasDir'] as const;
    assentos.forEach((seat) => {
      const c = veiculo.assentos?.[seat];
      if (c) {
        initial[seat] = {
          status: c.status || 'presente',
          motivo: c.motivoFalta,
          observacao: c.observacao || '',
          substitutoId: c.substitutoId || '',
        };
      }
    });
    return initial;
  });

  const handleToggleStatus = (seatKey: string) => {
    setPresencas((prev) => {
      const current = prev[seatKey];
      const novoStatus: StatusPresenca = current?.status === 'falta' ? 'presente' : 'falta';
      return {
        ...prev,
        [seatKey]: {
          ...current,
          status: novoStatus,
          motivo: novoStatus === 'falta' ? current?.motivo || 'Falta Injustificada' : undefined,
        },
      };
    });
  };

  const handleSetStatus = (seatKey: string, status: StatusPresenca) => {
    setPresencas((prev) => ({
      ...prev,
      [seatKey]: {
        ...prev[seatKey],
        status,
        motivo: status === 'falta' ? prev[seatKey]?.motivo || 'Falta Injustificada' : undefined,
      },
    }));
  };

  const handleSetMotivo = (seatKey: string, motivo: MotivoFalta) => {
    setPresencas((prev) => ({
      ...prev,
      [seatKey]: {
        ...prev[seatKey],
        motivo,
      },
    }));
  };

  const handleSetSubstituto = (seatKey: string, substitutoId: string) => {
    setPresencas((prev) => ({
      ...prev,
      [seatKey]: {
        ...prev[seatKey],
        substitutoId,
      },
    }));
  };

  const handleSalvar = () => {
    if (!onSalvarPresenca) {
      onClose();
      return;
    }

    const payload: Record<string, any> = {};
    Object.entries(presencas).forEach(([seat, val]) => {
      const sub = colaboradoresReserva.find((r) => r.id === val.substitutoId);
      payload[seat] = {
        status: val.status,
        motivo: val.motivo,
        observacao: val.observacao,
        substituto: sub,
      };
    });

    onSalvarPresenca(payload);
    onClose();
  };

  const seatsList: Array<{ key: 'motorista' | 'frenteDir' | 'trasEsq' | 'trasDir'; label: string; equipe: string }> = [
    { key: 'motorista', label: 'Motorista (Dianteiro Esq.)', equipe: veiculo.equipe1Codigo || 'Equipe 1' },
    { key: 'frenteDir', label: 'Operador (Dianteiro Dir.)', equipe: veiculo.equipe1Codigo || 'Equipe 1' },
    { key: 'trasEsq', label: 'Operador (Traseiro Esq.)', equipe: veiculo.equipe2Codigo || 'Equipe 2' },
    { key: 'trasDir', label: 'Operador (Traseiro Dir.)', equipe: veiculo.equipe2Codigo || 'Equipe 2' },
  ];

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-background/80 backdrop-blur-md animate-in fade-in duration-200 overflow-y-auto"
      onClick={onClose}
    >
      <div
        className="relative w-full max-w-2xl bg-card border border-border/80 rounded-3xl shadow-2xl overflow-hidden my-8"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Header Modal */}
        <div className="flex items-center justify-between px-6 py-4 border-b border-border/60 bg-muted/20">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-2xl bg-primary/10 border border-primary/20 text-primary flex items-center justify-center">
              <Car className="w-5 h-5" />
            </div>
            <div>
              <div className="flex items-center gap-2">
                <h3 className="text-base font-bold text-foreground">{veiculo.prefixo}</h3>
                <Badge variant="outline" className="text-[10px] font-mono py-0 px-1.5">
                  {veiculo.placa}
                </Badge>
              </div>
              <p className="text-xs text-muted-foreground">
                Toque na foto ou nos botões para marcar presença ou registrar falta
              </p>
            </div>
          </div>

          <button
            type="button"
            onClick={onClose}
            className="p-2 rounded-xl text-muted-foreground hover:text-foreground hover:bg-muted transition-colors cursor-pointer"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Lista de Colaboradores nos Assentos */}
        <div className="p-6 space-y-4 max-h-[70vh] overflow-y-auto">
          {seatsList.map(({ key, label, equipe }) => {
            const colab = veiculo.assentos?.[key];
            if (!colab) return null;

            const dados = presencas[key] || { status: 'presente' };
            const isFalta = dados.status === 'falta';
            const isSub = dados.status === 'substituto';

            return (
              <div
                key={key}
                className={cn(
                  'p-4 rounded-2xl border transition-all duration-150',
                  isFalta
                    ? 'border-rose-500/40 bg-rose-500/5'
                    : isSub
                    ? 'border-amber-500/40 bg-amber-500/5'
                    : 'border-border/60 bg-card/40'
                )}
              >
                <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-3">
                  <div className="flex items-center gap-3 min-w-0">
                    {/* Foto clicável para alternar status falta/presente */}
                    <button
                      type="button"
                      onClick={() => handleToggleStatus(key)}
                      title={isFalta ? 'Clique para marcar como Presente' : 'Clique para marcar como Falta'}
                      className="relative group shrink-0 focus:outline-none focus:ring-2 focus:ring-emerald-500/40 rounded-full cursor-pointer"
                    >
                      <div
                        className={cn(
                          'w-14 h-14 rounded-full overflow-hidden border-2 shadow-sm transition-all flex items-center justify-center',
                          isFalta
                            ? 'border-rose-500 ring-2 ring-rose-500/30 grayscale'
                            : 'border-emerald-500 ring-2 ring-emerald-500/20 group-hover:scale-105'
                        )}
                      >
                        {colab.foto ? (
                          <img
                            src={colab.foto}
                            alt={colab.nome}
                            className="w-full h-full object-cover"
                            onError={(e) => {
                              (e.target as HTMLImageElement).style.display = 'none';
                            }}
                          />
                        ) : (
                          <div className="w-full h-full bg-muted flex items-center justify-center font-bold text-xs text-foreground">
                            {getIniciais(colab.nome)}
                          </div>
                        )}
                      </div>
                      <span
                        className={cn(
                          'absolute -bottom-0.5 -right-0.5 p-0.5 rounded-full text-white shadow',
                          isFalta ? 'bg-rose-600' : 'bg-emerald-600'
                        )}
                      >
                        {isFalta ? <XCircle className="w-3.5 h-3.5" /> : <CheckCircle2 className="w-3.5 h-3.5" />}
                      </span>
                    </button>

                    <div className="min-w-0">
                      <div className="flex items-center gap-1.5 flex-wrap">
                        <span
                          className={cn(
                            'text-sm font-bold truncate',
                            isFalta ? 'text-rose-400 line-through' : 'text-foreground'
                          )}
                        >
                          {colab.nome}
                        </span>
                        <span className="text-[10px] text-muted-foreground font-mono">
                          ({colab.matricula || label})
                        </span>
                      </div>
                      <p className="text-xs text-muted-foreground">{colab.cargo} · {equipe}</p>
                    </div>
                  </div>

                  {/* Botões de Ação de Presença */}
                  <div className="flex items-center gap-1.5 self-end sm:self-center">
                    <button
                      type="button"
                      onClick={() => handleSetStatus(key, 'presente')}
                      className={cn(
                        'flex items-center gap-1 px-3 py-1.5 rounded-xl text-xs font-semibold border transition-all cursor-pointer',
                        dados.status === 'presente'
                          ? 'bg-emerald-600 text-white border-emerald-500 shadow-sm'
                          : 'border-border/60 text-muted-foreground hover:bg-muted/40'
                      )}
                    >
                      <UserCheck className="w-3.5 h-3.5" />
                      Presente
                    </button>

                    <button
                      type="button"
                      onClick={() => handleSetStatus(key, 'falta')}
                      className={cn(
                        'flex items-center gap-1 px-3 py-1.5 rounded-xl text-xs font-semibold border transition-all cursor-pointer',
                        dados.status === 'falta'
                          ? 'bg-rose-600 text-white border-rose-500 shadow-sm'
                          : 'border-border/60 text-muted-foreground hover:bg-muted/40'
                      )}
                    >
                      <UserX className="w-3.5 h-3.5" />
                      Falta
                    </button>

                    <button
                      type="button"
                      onClick={() => handleSetStatus(key, 'substituto')}
                      className={cn(
                        'flex items-center gap-1 px-3 py-1.5 rounded-xl text-xs font-semibold border transition-all cursor-pointer',
                        dados.status === 'substituto'
                          ? 'bg-amber-600 text-white border-amber-500 shadow-sm'
                          : 'border-border/60 text-muted-foreground hover:bg-muted/40'
                      )}
                    >
                      <ArrowRightLeft className="w-3.5 h-3.5" />
                      Substituto
                    </button>
                  </div>
                </div>

                {/* Se for FALTA, exibir seletor de motivo */}
                {isFalta && (
                  <div className="mt-3 pt-3 border-t border-rose-500/20 grid grid-cols-1 sm:grid-cols-2 gap-2">
                    <div>
                      <label className="text-[10px] font-bold uppercase tracking-wider text-rose-400 block mb-1">
                        Motivo da Ausência:
                      </label>
                      <select
                        value={dados.motivo || 'Falta Injustificada'}
                        onChange={(e) => handleSetMotivo(key, e.target.value as MotivoFalta)}
                        className="w-full h-8 px-2.5 rounded-lg border border-rose-500/30 bg-background text-xs font-medium text-foreground focus:outline-none focus:ring-2 focus:ring-rose-500/40"
                      >
                        {MOTIVOS_FALTA.map((m) => (
                          <option key={m} value={m}>
                            {m}
                          </option>
                        ))}
                      </select>
                    </div>
                  </div>
                )}

                {/* Se for SUBSTITUTO, exibir seleção de quem substitui */}
                {isSub && (
                  <div className="mt-3 pt-3 border-t border-amber-500/20">
                    <label className="text-[10px] font-bold uppercase tracking-wider text-amber-400 block mb-1">
                      Selecione o Colaborador Reserva:
                    </label>
                    <select
                      value={dados.substitutoId || ''}
                      onChange={(e) => handleSetSubstituto(key, e.target.value)}
                      className="w-full h-8 px-2.5 rounded-lg border border-amber-500/30 bg-background text-xs font-medium text-foreground focus:outline-none focus:ring-2 focus:ring-amber-500/40"
                    >
                      <option value="">Selecione da lista de reservas...</option>
                      {colaboradoresReserva.map((r) => (
                        <option key={r.id} value={r.id}>
                          {r.nome} — {r.cargo}
                        </option>
                      ))}
                    </select>
                  </div>
                )}
              </div>
            );
          })}
        </div>

        {/* Rodapé de Ações */}
        <div className="flex items-center justify-between px-6 py-4 border-t border-border/60 bg-muted/20">
          <span className="text-xs text-muted-foreground">
            As alterações atualizam a escala em tempo real
          </span>
          <div className="flex items-center gap-2">
            <Button variant="outline" size="sm" onClick={onClose}>
              Cancelar
            </Button>
            <Button
              size="sm"
              onClick={handleSalvar}
              className="bg-emerald-600 hover:bg-emerald-500 text-white gap-1.5"
            >
              <Check className="w-4 h-4" />
              Salvar Presenças
            </Button>
          </div>
        </div>
      </div>
    </div>
  );
};

