import React, { useState } from 'react';
import {
  X,
  UserCheck,
  UserX,
  RotateCcw,
  Check,
  AlertTriangle,
  Car,
  Users,
  ShieldAlert,
} from 'lucide-react';
import { Button } from './ui/button';
import { Badge } from './ui/badge';
import { Input } from './ui/input';
import { Veiculo, Colaborador, StatusPresenca, MotivoFalta } from '../types';
import { cn } from '@/lib/utils';

export interface AttendanceModalProps {
  isOpen: boolean;
  onClose: () => void;
  veiculo: Veiculo;
  colaboradoresReserva?: Colaborador[];
  onSalvarStatus: (
    colaboradorId: string,
    novoStatus: StatusPresenca,
    motivoFalta?: MotivoFalta,
    observacao?: string,
    substitutoId?: string,
    substitutoNome?: string
  ) => void;
}

const MOTIVOS_FALTA: MotivoFalta[] = [
  'Atestado Médico',
  'Falta Injustificada',
  'Folga Compensatória',
  'Treinamento / Integração',
  'Problema de Transporte',
  'Licença Especial',
];

const getIniciais = (nome?: string) => {
  if (!nome) return 'OP';
  const partes = nome.trim().split(' ');
  if (partes.length === 1) return partes[0].substring(0, 2).toUpperCase();
  return (partes[0][0] + partes[partes.length - 1][0]).toUpperCase();
};

export const AttendanceModal: React.FC<AttendanceModalProps> = ({
  isOpen,
  onClose,
  veiculo,
  colaboradoresReserva = [],
  onSalvarStatus,
}) => {
  const [colaboradorAtivo, setColaboradorAtivo] = useState<Colaborador | null>(() => {
    return veiculo?.assentos?.motorista || null;
  });

  const [novoStatus, setNovoStatus] = useState<StatusPresenca>(
    () => colaboradorAtivo?.status || 'presente'
  );
  const [motivoFalta, setMotivoFalta] = useState<MotivoFalta>(
    () => colaboradorAtivo?.motivoFalta || 'Atestado Médico'
  );
  const [observacao, setObservacao] = useState<string>(
    () => colaboradorAtivo?.observacao || ''
  );
  const [substitutoId, setSubstitutoId] = useState<string>(
    () => colaboradorAtivo?.substitutoId || ''
  );

  if (!isOpen || !veiculo) return null;

  const handleSelecionarColaborador = (colab: Colaborador) => {
    setColaboradorAtivo(colab);
    setNovoStatus(colab.status || 'presente');
    setMotivoFalta(colab.motivoFalta || 'Atestado Médico');
    setObservacao(colab.observacao || '');
    setSubstitutoId(colab.substitutoId || '');
  };

  const handleSalvar = () => {
    if (!colaboradorAtivo) return;

    let subNome: string | undefined = undefined;
    if (novoStatus === 'substituto' && substitutoId) {
      const sub = colaboradoresReserva.find((r) => r.id === substitutoId);
      subNome = sub?.nome;
    }

    onSalvarStatus(
      colaboradorAtivo.id,
      novoStatus,
      novoStatus === 'falta' ? motivoFalta : undefined,
      observacao,
      novoStatus === 'substituto' ? substitutoId : undefined,
      subNome
    );

    onClose();
  };

  const assentosLista = [
    { label: 'Motorista (Eq 1)', colab: veiculo.assentos?.motorista },
    { label: 'Ajudante Frente (Eq 1)', colab: veiculo.assentos?.frenteDir },
    { label: 'Ajudante Trás Esq. (Eq 2)', colab: veiculo.assentos?.trasEsq },
    { label: 'Ajudante Trás Dir. (Eq 2)', colab: veiculo.assentos?.trasDir },
  ].filter((item) => !!item.colab);

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-background/80 backdrop-blur-md animate-in fade-in duration-150"
      onClick={onClose}
    >
      <div
        className="relative w-full max-w-2xl bg-card border border-border/80 rounded-3xl shadow-2xl overflow-hidden flex flex-col max-h-[92vh]"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Header do Modal */}
        <div className="flex items-center justify-between px-6 py-4 border-b border-border/60 bg-muted/20">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-2xl bg-emerald-500/10 text-emerald-400 border border-emerald-500/30 flex items-center justify-center shrink-0">
              <Car className="w-5 h-5" />
            </div>
            <div>
              <div className="flex items-center gap-2">
                <h2 className="text-base font-bold text-foreground">{veiculo.prefixo}</h2>
                <Badge variant="outline" className="text-[11px] font-mono">
                  {veiculo.placa}
                </Badge>
              </div>
              <p className="text-xs text-muted-foreground">
                Clique na foto de cada ocupante para registrar Falta, Substituição ou Presença
              </p>
            </div>
          </div>

          <button
            type="button"
            onClick={onClose}
            className="p-1.5 rounded-xl text-muted-foreground hover:text-foreground hover:bg-muted transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Corpo do Modal */}
        <div className="p-6 overflow-y-auto space-y-6">
          {/* Grade com os 4 Colaboradores: Seleção Clicando na Foto ou no Card */}
          <div>
            <label className="text-xs font-bold text-muted-foreground uppercase tracking-wider block mb-2.5">
              1. Selecione o Colaborador (Clique no Quadrado / Foto)
            </label>

            <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
              {assentosLista.map(({ label, colab }) => {
                if (!colab) return null;
                const isSelected = colaboradorAtivo?.id === colab.id;

                return (
                  <button
                    key={colab.id}
                    type="button"
                    onClick={() => handleSelecionarColaborador(colab)}
                    className={cn(
                      'flex flex-col items-center p-3 rounded-2xl border-2 transition-all cursor-pointer text-center relative group',
                      isSelected
                        ? 'border-emerald-500 bg-emerald-500/10 shadow-lg ring-2 ring-emerald-500/20'
                        : 'border-border/70 bg-card/60 hover:border-emerald-500/40 hover:bg-card/90'
                    )}
                  >
                    {/* Quadrado da foto com ênfase */}
                    <div
                      className={cn(
                        'w-16 h-16 rounded-2xl overflow-hidden border-2 mb-2 shadow-md relative',
                        colab.status === 'falta'
                          ? 'border-rose-500'
                          : colab.status === 'substituto'
                          ? 'border-amber-500'
                          : 'border-emerald-500'
                      )}
                    >
                      {colab.foto ? (
                        <img
                          src={colab.foto}
                          alt={colab.nome}
                          className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-200"
                        />
                      ) : (
                        <div className="w-full h-full bg-muted flex items-center justify-center font-bold text-xs">
                          {getIniciais(colab.nome)}
                        </div>
                      )}

                      <span className="absolute bottom-0.5 right-0.5 w-3 h-3 rounded-full border border-background bg-emerald-500" />
                    </div>

                    <span className="text-[10px] font-bold uppercase tracking-wider text-muted-foreground line-clamp-1">
                      {label}
                    </span>
                    <span className="text-xs font-bold text-foreground mt-0.5 line-clamp-1">
                      {colab.nome}
                    </span>

                    <span
                      className={cn(
                        'mt-1.5 px-2 py-0.5 rounded-full text-[10px] font-bold border',
                        colab.status === 'falta'
                          ? 'bg-rose-500/20 text-rose-400 border-rose-500/30'
                          : colab.status === 'substituto'
                          ? 'bg-amber-500/20 text-amber-400 border-amber-500/30'
                          : 'bg-emerald-500/20 text-emerald-400 border-emerald-500/30'
                      )}
                    >
                      {colab.status === 'falta'
                        ? 'Falta'
                        : colab.status === 'substituto'
                        ? 'Substituto'
                        : 'Presente'}
                    </span>
                  </button>
                );
              })}
            </div>
          </div>

          {/* Área de Definição de Status para o Colaborador Selecionado */}
          {colaboradorAtivo && (
            <div className="p-4 sm:p-5 rounded-2xl border border-border/80 bg-muted/15 space-y-4 animate-in fade-in-50">
              <div className="flex items-center justify-between border-b border-border/40 pb-3">
                <div>
                  <span className="text-xs text-muted-foreground">Colaborador em Edição:</span>
                  <p className="text-sm font-bold text-foreground">{colaboradorAtivo.nome}</p>
                </div>
                <Badge variant="outline" className="text-xs font-mono">
                  {colaboradorAtivo.cargo}
                </Badge>
              </div>

              {/* Opções de Status */}
              <div>
                <label className="text-xs font-bold text-muted-foreground uppercase tracking-wider block mb-2">
                  2. Definir Status de Presença
                </label>

                <div className="grid grid-cols-3 gap-2.5">
                  <button
                    type="button"
                    onClick={() => setNovoStatus('presente')}
                    className={cn(
                      'flex flex-col items-center justify-center gap-1.5 p-3 rounded-2xl border-2 transition-all cursor-pointer',
                      novoStatus === 'presente'
                        ? 'border-emerald-500 bg-emerald-500/15 text-emerald-400 font-bold shadow-md'
                        : 'border-border/60 bg-card/60 text-muted-foreground hover:border-emerald-500/40'
                    )}
                  >
                    <UserCheck className="w-5 h-5" />
                    <span className="text-xs">Presente</span>
                  </button>

                  <button
                    type="button"
                    onClick={() => setNovoStatus('falta')}
                    className={cn(
                      'flex flex-col items-center justify-center gap-1.5 p-3 rounded-2xl border-2 transition-all cursor-pointer',
                      novoStatus === 'falta'
                        ? 'border-rose-500 bg-rose-500/15 text-rose-400 font-bold shadow-md'
                        : 'border-border/60 bg-card/60 text-muted-foreground hover:border-rose-500/40'
                    )}
                  >
                    <UserX className="w-5 h-5" />
                    <span className="text-xs">Falta</span>
                  </button>

                  <button
                    type="button"
                    onClick={() => setNovoStatus('substituto')}
                    className={cn(
                      'flex flex-col items-center justify-center gap-1.5 p-3 rounded-2xl border-2 transition-all cursor-pointer',
                      novoStatus === 'substituto'
                        ? 'border-amber-500 bg-amber-500/15 text-amber-400 font-bold shadow-md'
                        : 'border-border/60 bg-card/60 text-muted-foreground hover:border-amber-500/40'
                    )}
                  >
                    <RotateCcw className="w-5 h-5" />
                    <span className="text-xs">Substituição</span>
                  </button>
                </div>
              </div>

              {/* Se for Falta: Justificativa */}
              {novoStatus === 'falta' && (
                <div className="space-y-2 p-3.5 rounded-2xl bg-rose-500/10 border border-rose-500/30 animate-in fade-in-50">
                  <label className="text-xs font-bold text-rose-400 block">
                    Motivo da Falta (Obrigatório)
                  </label>
                  <select
                    value={motivoFalta}
                    onChange={(e) => setMotivoFalta(e.target.value as MotivoFalta)}
                    className="w-full h-10 px-3 rounded-xl border border-rose-500/40 bg-background text-xs font-semibold text-foreground focus:outline-none focus:ring-2 focus:ring-rose-500/40"
                  >
                    {MOTIVOS_FALTA.map((m) => (
                      <option key={m} value={m}>
                        {m}
                      </option>
                    ))}
                  </select>
                </div>
              )}

              {/* Se for Substituto: Selecionar do Banco de Reserva */}
              {novoStatus === 'substituto' && (
                <div className="space-y-2 p-3.5 rounded-2xl bg-amber-500/10 border border-amber-500/30 animate-in fade-in-50">
                  <label className="text-xs font-bold text-amber-400 block">
                    Selecione o Colaborador Reserva Substituto
                  </label>
                  <select
                    value={substitutoId}
                    onChange={(e) => setSubstitutoId(e.target.value)}
                    className="w-full h-10 px-3 rounded-xl border border-amber-500/40 bg-background text-xs font-semibold text-foreground focus:outline-none focus:ring-2 focus:ring-amber-500/40"
                  >
                    <option value="">Selecione um colaborador reserva...</option>
                    {colaboradoresReserva.map((res) => (
                      <option key={res.id} value={res.id}>
                        {res.nome} ({res.cargo})
                      </option>
                    ))}
                  </select>
                </div>
              )}

              {/* Observação Livre */}
              <div className="space-y-1.5">
                <label className="text-xs font-semibold text-muted-foreground block">
                  Observações Complementares
                </label>
                <Input
                  placeholder="Ex: Apresentou atestado de 2 dias / liberação médica"
                  value={observacao}
                  onChange={(e) => setObservacao(e.target.value)}
                  className="h-10 text-xs rounded-xl"
                />
              </div>
            </div>
          )}
        </div>

        {/* Rodapé com Botões de Ação */}
        <div className="flex items-center justify-end gap-3 px-6 py-4 border-t border-border/60 bg-muted/20">
          <Button type="button" variant="outline" onClick={onClose} className="rounded-xl">
            Cancelar
          </Button>
          <Button
            type="button"
            onClick={handleSalvar}
            className="gap-2 bg-emerald-600 hover:bg-emerald-500 text-white font-bold rounded-xl"
          >
            <Check className="w-4 h-4" />
            Salvar Status
          </Button>
        </div>
      </div>
    </div>
  );
};

