import React, { useState, useMemo } from 'react';
import {
  Car,
  AlertTriangle,
  CheckCircle2,
  XCircle,
  HelpCircle,
  Search,
  Users,
  Compass,
  MapPin,
  Sparkles,
  UserCheck,
  UserX,
  RefreshCw,
} from 'lucide-react';
import { Veiculo, Colaborador, StatusPresenca, MotivoFalta, Regional } from '../types';
import { Badge } from './ui/badge';
import { Button } from './ui/button';
import { Input } from './ui/input';
import { AttendanceModal } from './AttendanceModal';
import { cn } from '@/lib/utils';

export interface VehicleCardGridProps {
  veiculos?: Veiculo[];
  colaboradoresReserva?: Colaborador[];
  selectedRegional?: Regional;
  onUpdateColaboradorStatus?: (
    colaboradorId: string,
    novoStatus: StatusPresenca,
    motivoFalta?: MotivoFalta,
    observacao?: string,
    substitutoId?: string,
    substitutoNome?: string
  ) => void;
  onSubstituirColaborador?: (colaboradorOriginalId: string, reservaId: string) => void;
}

const statusColorClasses: Record<StatusPresenca, { border: string; glow: string; badge: string; dot: string; label: string }> = {
  presente: {
    border: 'border-emerald-500/50 hover:border-emerald-400',
    glow: 'ring-1 ring-emerald-500/30 bg-emerald-950/20',
    badge: 'bg-emerald-500/15 text-emerald-300 border-emerald-500/30',
    dot: 'bg-emerald-400',
    label: 'Presente',
  },
  falta: {
    border: 'border-rose-500/60 hover:border-rose-400',
    glow: 'ring-2 ring-rose-500/40 bg-rose-950/30',
    badge: 'bg-rose-500/15 text-rose-300 border-rose-500/30',
    dot: 'bg-rose-400',
    label: 'Falta',
  },
  substituto: {
    border: 'border-amber-500/50 hover:border-amber-400',
    glow: 'ring-1 ring-amber-500/30 bg-amber-950/20',
    badge: 'bg-amber-500/15 text-amber-300 border-amber-500/30',
    dot: 'bg-amber-400',
    label: 'Substituto',
  },
};

const getIniciais = (nome?: string) => {
  if (!nome) return 'CO';
  const partes = nome.trim().split(' ');
  if (partes.length === 1) return partes[0].substring(0, 2).toUpperCase();
  return (partes[0][0] + partes[partes.length - 1][0]).toUpperCase();
};

export const VehicleCardGrid: React.FC<VehicleCardGridProps> = ({
  veiculos = [],
  colaboradoresReserva = [],
  selectedRegional = 'todas',
  onUpdateColaboradorStatus,
  onSubstituirColaborador,
}) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState<'todos' | 'com_falta' | 'completos'>('todos');
  const [colaboradorSelecionado, setColaboradorSelecionado] = useState<Colaborador | null>(null);
  const [veiculoAtivo, setVeiculoAtivo] = useState<Veiculo | null>(null);
  const [modalAberto, setModalAberto] = useState(false);

  const veiculosFiltrados = useMemo(() => {
    return (veiculos || []).filter((veiculo) => {
      if (!veiculo || !veiculo.assentos) return false;

      // Filtro de regional
      if (selectedRegional !== 'todas' && veiculo.regional !== selectedRegional) {
        return false;
      }

      // Filtro de busca de texto
      const termo = searchTerm.toLowerCase().trim();
      const colaboradores = [
        veiculo.assentos.motorista,
        veiculo.assentos.frenteDir,
        veiculo.assentos.trasEsq,
        veiculo.assentos.trasDir,
      ].filter(Boolean) as Colaborador[];

      const matchPlaca = (veiculo.placa || '').toLowerCase().includes(termo);
      const matchPrefixo = (veiculo.prefixo || '').toLowerCase().includes(termo);
      const matchModelo = (veiculo.modelo || '').toLowerCase().includes(termo);
      const matchEq1 = (veiculo.equipe1Codigo || '').toLowerCase().includes(termo);
      const matchEq2 = (veiculo.equipe2Codigo || '').toLowerCase().includes(termo);
      const matchColaborador = colaboradores.some((c) =>
        (c.nome || '').toLowerCase().includes(termo) ||
        (c.matricula || '').toLowerCase().includes(termo) ||
        (c.cargo || '').toLowerCase().includes(termo)
      );

      const atendeBusca = !termo || matchPlaca || matchPrefixo || matchModelo || matchEq1 || matchEq2 || matchColaborador;
      if (!atendeBusca) return false;

      // Filtro de status de desfalque
      const temFalta = colaboradores.some((c) => c.status === 'falta');
      if (statusFilter === 'com_falta') return temFalta;
      if (statusFilter === 'completos') return !temFalta;

      return true;
    });
  }, [veiculos, selectedRegional, searchTerm, statusFilter]);

  const abrirModalColaborador = (colaborador: Colaborador, veiculo: Veiculo) => {
    setColaboradorSelecionado(colaborador);
    setVeiculoAtivo(veiculo);
    setModalAberto(true);
  };

  const handleSalvarStatus = (
    colaboradorId: string,
    novoStatus: StatusPresenca,
    motivoFalta?: MotivoFalta,
    observacao?: string,
    substitutoId?: string,
    substitutoNome?: string
  ) => {
    if (onUpdateColaboradorStatus) {
      onUpdateColaboradorStatus(
        colaboradorId,
        novoStatus,
        motivoFalta,
        observacao,
        substitutoId,
        substitutoNome
      );
    }
  };

  // Renderizador do assento na vista superior (Top-Down Car Seat)
  const renderAssentoTopDown = (
    colaborador: Colaborador | undefined,
    veiculo: Veiculo,
    tituloPosicao: string,
    posicaoChave: 'motorista' | 'frente_dir' | 'tras_esq' | 'tras_dir',
    temVolante: boolean = false
  ) => {
    if (!colaborador) {
      return (
        <div className="relative flex flex-col items-center justify-center p-3 rounded-2xl border-2 border-dashed border-border/40 bg-muted/10 min-h-[145px]">
          <span className="text-[10px] uppercase font-bold tracking-wider text-muted-foreground/60">{tituloPosicao}</span>
          <span className="text-xs text-muted-foreground/50 mt-1">Vago</span>
        </div>
      );
    }

    const cfg = statusColorClasses[colaborador.status] || statusColorClasses.presente;
    const ehFalta = colaborador.status === 'falta';

    return (
      <div
        onClick={() => abrirModalColaborador(colaborador, veiculo)}
        role="button"
        tabIndex={0}
        onKeyDown={(e) => {
          if (e.key === 'Enter' || e.key === ' ') {
            abrirModalColaborador(colaborador, veiculo);
          }
        }}
        className={cn(
          'group relative flex flex-col items-center p-2.5 rounded-2xl border transition-all duration-200 cursor-pointer select-none text-left',
          'bg-gradient-to-b from-card/90 via-card/75 to-background/90 backdrop-blur-md shadow-md hover:shadow-xl hover:-translate-y-0.5',
          cfg.border,
          cfg.glow
        )}
      >
        {/* Encosto do banco do carro (Top-View Seat Contour) */}
        <div className="absolute inset-x-2 top-1.5 h-3 rounded-t-lg bg-neutral-800/40 border-t border-x border-neutral-700/50 pointer-events-none" />

        {/* Indicador de Volante no banco do Motorista */}
        {temVolante && (
          <div className="absolute -top-2 left-3 w-5 h-5 rounded-full border-2 border-dashed border-emerald-400/80 bg-neutral-900 flex items-center justify-center shadow-sm z-10" title="Posto do Motorista">
            <div className="w-1.5 h-1.5 rounded-full bg-emerald-400" />
          </div>
        )}

        {/* Etiqueta da Posição e Status */}
        <div className="w-full flex items-center justify-between gap-1 mb-2 z-10">
          <span className="text-[10px] font-bold uppercase tracking-wider text-muted-foreground/80 flex items-center gap-1">
            {tituloPosicao}
          </span>
          <span className={cn('inline-flex items-center gap-1 px-1.5 py-0.5 rounded-md text-[9px] font-bold border', cfg.badge)}>
            <span className={cn('w-1.5 h-1.5 rounded-full', cfg.dot)} />
            {cfg.label}
          </span>
        </div>

        {/* Corpo do Assento: Foto do Colaborador Visto Sentado no Banco */}
        <div className="relative my-1">
          {/* Suporte do encosto de cabeça */}
          <div className="absolute -inset-1.5 rounded-full bg-neutral-800/60 border border-neutral-700/60 shadow-inner -z-0" />

          {/* Avatar com foto */}
          <div className={cn(
            'relative w-14 h-14 rounded-full overflow-hidden border-2 shadow-lg transition-transform duration-200 group-hover:scale-105 z-10 flex items-center justify-center bg-muted',
            ehFalta ? 'border-rose-500 ring-2 ring-rose-500/40' : 'border-emerald-500/70 ring-1 ring-emerald-500/20'
          )}>
            {colaborador.foto ? (
              <img
                src={colaborador.foto}
                alt={colaborador.nome}
                className={cn(
                  'w-full h-full object-cover',
                  ehFalta && 'grayscale contrast-125 opacity-70'
                )}
                onError={(e) => {
                  (e.target as HTMLImageElement).style.display = 'none';
                }}
              />
            ) : (
              <span className="text-sm font-black text-foreground/80">
                {getIniciais(colaborador.nome)}
              </span>
            )}

            {/* Ícone flutuante de alerta sobre a foto caso falta */}
            {ehFalta && (
              <div className="absolute inset-0 bg-rose-950/60 flex items-center justify-center">
                <AlertTriangle className="w-6 h-6 text-rose-400 animate-pulse" />
              </div>
            )}
          </div>
        </div>

        {/* Dados do Colaborador */}
        <div className="w-full text-center mt-1.5 z-10">
          <p className="text-xs font-bold text-foreground truncate group-hover:text-primary transition-colors">
            {colaborador.nome}
          </p>
          <p className="text-[10px] text-muted-foreground truncate">
            {colaborador.cargo || 'Operador'}
          </p>
          {colaborador.matricula && (
            <p className="text-[9px] font-mono text-muted-foreground/60 tabular-nums">
              Mat: {colaborador.matricula}
            </p>
          )}

          {colaborador.substitutoNome && (
            <div className="mt-1 px-1.5 py-0.5 rounded bg-amber-500/10 border border-amber-500/25 text-[9px] text-amber-300 font-medium truncate">
              Sub: {colaborador.substitutoNome}
            </div>
          )}
        </div>

        {/* Dica de clique na foto */}
        <div className="w-full mt-2 pt-1.5 border-t border-border/30 flex items-center justify-center gap-1 text-[9px] text-muted-foreground/70 group-hover:text-primary transition-colors">
          <span>Clique p/ alterar</span>
        </div>
      </div>
    );
  };

  return (
    <div className="space-y-6">
      {/* Barra de Filtros e Busca de Campo */}
      <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3 bg-card/60 backdrop-blur-md p-3.5 rounded-2xl border border-border/60 shadow-sm">
        <div className="relative flex-1">
          <Search className="w-4 h-4 text-muted-foreground absolute left-3 top-1/2 -translate-y-1/2" />
          <Input
            placeholder="Buscar por placa, prefixo, equipe ou nome do operador..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="pl-9 h-10 text-xs bg-background/60 border-border/60 rounded-xl"
          />
        </div>

        <div className="flex items-center gap-2 overflow-x-auto pb-1 sm:pb-0">
          <Button
            type="button"
            size="sm"
            variant={statusFilter === 'todos' ? 'default' : 'outline'}
            onClick={() => setStatusFilter('todos')}
            className="text-xs h-9 rounded-xl font-semibold"
          >
            Todos ({veiculos.length})
          </Button>

          <Button
            type="button"
            size="sm"
            variant={statusFilter === 'com_falta' ? 'destructive' : 'outline'}
            onClick={() => setStatusFilter('com_falta')}
            className="text-xs h-9 rounded-xl font-semibold gap-1.5"
          >
            <AlertTriangle className="w-3.5 h-3.5" />
            Com Faltas
          </Button>

          <Button
            type="button"
            size="sm"
            variant={statusFilter === 'completos' ? 'default' : 'outline'}
            onClick={() => setStatusFilter('completos')}
            className={cn(
              'text-xs h-9 rounded-xl font-semibold gap-1.5',
              statusFilter === 'completos' && 'bg-emerald-600 hover:bg-emerald-500 text-white'
            )}
          >
            <CheckCircle2 className="w-3.5 h-3.5" />
            Completos
          </Button>
        </div>
      </div>

      {/* Grid de Veículos com Vista de Cima (Top-Down Car Cabin) */}
      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
        {veiculosFiltrados.length === 0 ? (
          <div className="col-span-full py-16 text-center rounded-3xl border border-dashed border-border/70 bg-card/20">
            <Car className="w-10 h-10 text-muted-foreground mx-auto mb-3 opacity-40" />
            <h3 className="text-base font-bold text-foreground">Nenhum veículo encontrado</h3>
            <p className="text-xs text-muted-foreground mt-1 max-w-sm mx-auto">
              Tente alterar os termos da busca ou desativar os filtros de status selecionados.
            </p>
          </div>
        ) : (
          veiculosFiltrados.map((veiculo) => {
            const ocupantes = [
              veiculo.assentos?.motorista,
              veiculo.assentos?.frenteDir,
              veiculo.assentos?.trasEsq,
              veiculo.assentos?.trasDir,
            ].filter(Boolean) as Colaborador[];

            const totalPresentes = ocupantes.filter((c) => c.status === 'presente' || c.status === 'substituto').length;
            const totalFaltas = ocupantes.filter((c) => c.status === 'falta').length;
            const temDesfalque = totalFaltas > 0;

            return (
              <div
                key={veiculo.id}
                className={cn(
                  'relative rounded-3xl border transition-all duration-200 overflow-hidden shadow-xl bg-card/85 backdrop-blur-md flex flex-col justify-between',
                  temDesfalque
                    ? 'border-rose-500/40 shadow-rose-950/10'
                    : 'border-border/70 hover:border-emerald-500/40'
                )}
              >
                {/* Cabeçalho do Veículo: Identificação, Placa e Regional */}
                <div className="p-4 border-b border-border/50 bg-gradient-to-r from-muted/40 via-muted/20 to-transparent">
                  <div className="flex items-center justify-between gap-2">
                    <div className="flex items-center gap-2.5">
                      <div className="w-9 h-9 rounded-xl bg-primary/10 border border-primary/25 flex items-center justify-center shrink-0">
                        <Car className="w-4 h-4 text-primary" />
                      </div>
                      <div>
                        <div className="flex items-center gap-2">
                          <h3 className="font-extrabold text-base text-foreground tracking-tight">
                            {veiculo.prefixo}
                          </h3>
                          <span className="font-mono text-xs px-2 py-0.5 rounded-md bg-background/80 border border-border/80 font-bold tabular-nums">
                            {veiculo.placa}
                          </span>
                        </div>
                        <p className="text-[11px] text-muted-foreground flex items-center gap-1.5 mt-0.5">
                          <MapPin className="w-3 h-3 text-emerald-400" />
                          <span>{veiculo.regional === 'ribas' ? 'Ribas do Rio Pardo' : 'Água Clara'}</span>
                          <span className="opacity-40">·</span>
                          <span>{veiculo.modelo}</span>
                        </p>
                      </div>
                    </div>

                    <Badge
                      variant="outline"
                      className={cn(
                        'text-[10px] font-bold py-0.5 px-2 tabular-nums',
                        temDesfalque
                          ? 'bg-rose-500/15 text-rose-300 border-rose-500/30'
                          : 'bg-emerald-500/15 text-emerald-300 border-emerald-500/30'
                      )}
                    >
                      {totalPresentes}/4 a bordo
                    </Badge>
                  </div>
                </div>

                {/* VISTA SUPERIOR DO CARRO (CABINE TOP-DOWN) */}
                <div className="p-4 flex-1 flex flex-col justify-center">
                  <div className="relative mx-auto w-full max-w-[340px] rounded-[32px] border-2 border-neutral-700/60 bg-gradient-to-b from-neutral-900/90 via-neutral-950/95 to-neutral-900/90 p-3 shadow-2xl overflow-hidden">
                    {/* Linhas externas do veículo: Frente / Capô e Para-brisa */}
                    <div className="relative w-full mb-3 flex flex-col items-center">
                      {/* Para-choque dianteiro sutil */}
                      <div className="w-28 h-1.5 rounded-t-full bg-neutral-600/70 mb-1" />
                      {/* Para-brisa frontal curvo translúcido */}
                      <div className="w-full h-4 rounded-t-2xl border-t-2 border-x border-teal-400/30 bg-gradient-to-b from-teal-500/15 to-transparent flex items-center justify-center">
                        <span className="text-[9px] uppercase tracking-widest text-teal-300/60 font-black">
                          Frente do Veículo
                        </span>
                      </div>
                    </div>

                    {/* Divisão: Equipe 1 (Bancos Dianteiros) */}
                    <div className="mb-2">
                      <div className="flex items-center justify-between mb-1.5 px-1">
                        <span className="text-[10px] font-bold text-muted-foreground uppercase tracking-wider flex items-center gap-1">
                          <Users className="w-3 h-3 text-emerald-400" />
                          {veiculo.equipe1Codigo || 'Equipe 1'}
                        </span>
                        <span className="text-[9px] text-muted-foreground/70 font-semibold">Bancos Dianteiros</span>
                      </div>

                      <div className="grid grid-cols-2 gap-2.5">
                        {renderAssentoTopDown(
                          veiculo.assentos?.motorista,
                          veiculo,
                          'Motorista',
                          'motorista',
                          true
                        )}
                        {renderAssentoTopDown(
                          veiculo.assentos?.frenteDir,
                          veiculo,
                          'Carona',
                          'frente_dir',
                          false
                        )}
                      </div>
                    </div>

                    {/* Console Central do Carro / Divisória interna vista de cima */}
                    <div className="relative my-2 py-1 flex items-center justify-center">
                      <div className="w-full border-t border-dashed border-neutral-700/50" />
                      <div className="absolute px-2 py-0.5 rounded-full bg-neutral-800 border border-neutral-700 text-[8px] font-mono text-muted-foreground/80 tracking-widest uppercase">
                        Cabine
                      </div>
                    </div>

                    {/* Divisão: Equipe 2 (Bancos Traseiros) */}
                    <div>
                      <div className="flex items-center justify-between mb-1.5 px-1">
                        <span className="text-[10px] font-bold text-muted-foreground uppercase tracking-wider flex items-center gap-1">
                          <Users className="w-3 h-3 text-teal-400" />
                          {veiculo.equipe2Codigo || 'Equipe 2'}
                        </span>
                        <span className="text-[9px] text-muted-foreground/70 font-semibold">Bancos Traseiros</span>
                      </div>

                      <div className="grid grid-cols-2 gap-2.5">
                        {renderAssentoTopDown(
                          veiculo.assentos?.trasEsq,
                          veiculo,
                          'Traseiro Esq',
                          'tras_esq',
                          false
                        )}
                        {renderAssentoTopDown(
                          veiculo.assentos?.trasDir,
                          veiculo,
                          'Traseiro Dir',
                          'tras_dir',
                          false
                        )}
                      </div>
                    </div>

                    {/* Vidro Traseiro e Caçamba / Porta-malas */}
                    <div className="mt-3 flex flex-col items-center">
                      <div className="w-full h-3 rounded-b-2xl border-b-2 border-x border-neutral-700/60 bg-gradient-to-t from-neutral-800/40 to-transparent" />
                      <div className="w-20 h-1 rounded-b-full bg-neutral-700/70 mt-1" />
                    </div>
                  </div>
                </div>

                {/* Rodapé informativo do Veículo */}
                <div className="p-3 bg-muted/20 border-t border-border/40 flex items-center justify-between text-xs text-muted-foreground">
                  <div className="flex items-center gap-2">
                    <span className="inline-flex items-center gap-1 text-[11px] text-emerald-400 font-semibold">
                      <UserCheck className="w-3.5 h-3.5" />
                      {totalPresentes} presentes
                    </span>
                    {totalFaltas > 0 && (
                      <span className="inline-flex items-center gap-1 text-[11px] text-rose-400 font-bold">
                        <UserX className="w-3.5 h-3.5" />
                        {totalFaltas} falta(s)
                      </span>
                    )}
                  </div>

                  <span className="text-[10px] text-muted-foreground/60 font-mono">
                    Toque no banco p/ editar
                  </span>
                </div>
              </div>
            );
          })
        )}
      </div>

      {/* Modal Interativo de Marcação de Presença / Falta / Substituição */}
      <AttendanceModal
        isOpen={modalAberto}
        onClose={() => {
          setModalAberto(false);
          setColaboradorSelecionado(null);
          setVeiculoAtivo(null);
        }}
        colaborador={colaboradorSelecionado}
        veiculo={veiculoAtivo}
        colaboradoresReserva={colaboradoresReserva}
        onSaveStatus={handleSalvarStatus}
      />
    </div>
  );
};

