import React, { useState } from 'react';
import {
  X,
  CheckCircle2,
  XCircle,
  UserCheck,
  UserX,
  AlertCircle,
  Car,
  Users,
  Info,
  Calendar,
  Save,
} from 'lucide-react';
import { Button } from './ui/button';
import { Badge } from './ui/badge';
import { Input } from './ui/input';
import { Colaborador, Veiculo, StatusPresenca, MotivoFalta } from '../types';
import { cn } from '@/lib/utils';

export interface AttendanceModalProps {
  isOpen: boolean;
  onClose: () => void;
  colaborador?: Colaborador | null;
  veiculo?: Veiculo | null;
  posicao?: string;
  colaboradoresReserva?: Colaborador[];
  onSalvar?: (
    novoStatus: StatusPresenca,
    motivo?: MotivoFalta,
    observacao?: string,
    substitutoId?: string
  ) => void;
}

const MOTIVOS_FALTA: MotivoFalta[] = [
  'Atestado Médico',
  'Falta Injustificada',
  'Folga Compensatória',
  'Treinamento / Integração',
  'Problema de Transporte',
  'Licença Especial',
];

const getIniciais = (nome?: string) => {
  if (!nome) return 'OP';
  const partes = nome.trim().split(' ');
  if (partes.length === 1) return partes[0].substring(0, 2).toUpperCase();
  return (partes[0][0] + partes[partes.length - 1][0]).toUpperCase();
};

export const AttendanceModal: React.FC<AttendanceModalProps> = ({
  isOpen,
  onClose,
  colaborador,
  veiculo,
  posicao = 'Assento',
  colaboradoresReserva = [],
  onSalvar,
}) => {
  if (!isOpen || !colaborador) return null;

  const [status, setStatus] = useState<StatusPresenca>(colaborador.status || 'presente');
  const [motivo, setMotivo] = useState<MotivoFalta | undefined>(colaborador.motivoFalta);
  const [observacao, setObservacao] = useState<string>(colaborador.observacao || '');
  const [substitutoId, setSubstitutoId] = useState<string>(colaborador.substitutoId || '');

  const handleSalvar = (e: React.FormEvent) => {
    e.preventDefault();
    if (onSalvar) {
      onSalvar(status, status === 'falta' ? motivo : undefined, observacao, substitutoId);
    }
    onClose();
  };

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-background/80 backdrop-blur-md animate-in fade-in duration-150"
      onClick={onClose}
    >
      <div
        className="relative w-full max-w-lg bg-card border border-border/80 rounded-3xl shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Topo Limpo do Modal */}
        <div className="flex items-center justify-between px-6 py-4 border-b border-border/60 bg-muted/20">
          <div className="flex items-center gap-2">
            <span className="font-bold text-base text-foreground">Registro de Frequência</span>
            <Badge variant="outline" className="text-[10px] py-0 px-2 border-emerald-500/30 text-emerald-400">
              {veiculo?.prefixo || 'Veículo'}
            </Badge>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="p-1.5 rounded-xl text-muted-foreground hover:text-foreground hover:bg-muted transition-colors cursor-pointer"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        <form onSubmit={handleSalvar} className="p-6 space-y-5">
          {/* Cartão de Destaque Limpo do Colaborador */}
          <div className="flex items-center gap-4 p-4 rounded-2xl border border-border/60 bg-muted/15">
            <div className="relative shrink-0">
              {colaborador.foto ? (
                <img
                  src={colaborador.foto}
                  alt={colaborador.nome}
                  className="w-16 h-16 rounded-2xl object-cover ring-2 ring-emerald-500/40 shadow-sm"
                />
              ) : (
                <div className="w-16 h-16 rounded-2xl bg-secondary ring-2 ring-emerald-500/40 flex items-center justify-center font-extrabold text-base text-foreground shadow-sm">
                  {getIniciais(colaborador.nome)}
                </div>
              )}
            </div>

            <div className="min-w-0 flex-1 space-y-1">
              <h3 className="font-bold text-base text-foreground truncate">{colaborador.nome}</h3>
              <p className="text-xs text-muted-foreground truncate">{colaborador.cargo}</p>
              <div className="flex items-center gap-2 text-[11px] text-muted-foreground/80">
                <span className="font-mono">Mat: {colaborador.matricula || '---'}</span>
                <span>•</span>
                <span>{posicao}</span>
              </div>
            </div>
          </div>

          {/* Seleção Direta de Status: Presente, Falta, Substituto */}
          <div>
            <label className="text-xs font-semibold text-muted-foreground uppercase tracking-wider block mb-2">
              Selecione o Status do Dia
            </label>
            <div className="grid grid-cols-3 gap-2.5">
              <button
                type="button"
                onClick={() => setStatus('presente')}
                className={cn(
                  'flex flex-col items-center justify-center gap-1.5 p-3 rounded-2xl border text-xs font-bold transition-all cursor-pointer',
                  status === 'presente'
                    ? 'bg-emerald-500/20 border-emerald-500 text-emerald-300 ring-2 ring-emerald-500/20'
                    : 'border-border/60 text-muted-foreground hover:bg-muted/40 hover:text-foreground'
                )}
              >
                <CheckCircle2 className="w-5 h-5 text-emerald-400" />
                Presente
              </button>

              <button
                type="button"
                onClick={() => setStatus('falta')}
                className={cn(
                  'flex flex-col items-center justify-center gap-1.5 p-3 rounded-2xl border text-xs font-bold transition-all cursor-pointer',
                  status === 'falta'
                    ? 'bg-rose-500/20 border-rose-500 text-rose-300 ring-2 ring-rose-500/20'
                    : 'border-border/60 text-muted-foreground hover:bg-muted/40 hover:text-foreground'
                )}
              >
                <XCircle className="w-5 h-5 text-rose-400" />
                Falta
              </button>

              <button
                type="button"
                onClick={() => setStatus('substituto')}
                className={cn(
                  'flex flex-col items-center justify-center gap-1.5 p-3 rounded-2xl border text-xs font-bold transition-all cursor-pointer',
                  status === 'substituto'
                    ? 'bg-amber-500/20 border-amber-500 text-amber-300 ring-2 ring-amber-500/20'
                    : 'border-border/60 text-muted-foreground hover:bg-muted/40 hover:text-foreground'
                )}
              >
                <UserCheck className="w-5 h-5 text-amber-400" />
                Substituto
              </button>
            </div>
          </div>

          {/* Opções condicionais para FALTA */}
          {status === 'falta' && (
            <div className="space-y-3 p-3.5 rounded-2xl border border-rose-500/30 bg-rose-950/10 animate-in fade-in duration-200">
              <label className="text-xs font-semibold text-rose-300 uppercase tracking-wider block">
                Motivo da Falta
              </label>
              <div className="grid grid-cols-2 gap-2">
                {MOTIVOS_FALTA.map((m) => (
                  <button
                    key={m}
                    type="button"
                    onClick={() => setMotivo(m)}
                    className={cn(
                      'text-left p-2.5 rounded-xl border text-xs transition-all cursor-pointer',
                      motivo === m
                        ? 'bg-rose-500/20 border-rose-500 text-rose-200 font-semibold'
                        : 'border-border/60 text-muted-foreground hover:bg-muted/30'
                    )}
                  >
                    {m}
                  </button>
                ))}
              </div>
            </div>
          )}

          {/* Opções condicionais para SUBSTITUTO */}
          {status === 'substituto' && (
            <div className="space-y-3 p-3.5 rounded-2xl border border-amber-500/30 bg-amber-950/10 animate-in fade-in duration-200">
              <label className="text-xs font-semibold text-amber-300 uppercase tracking-wider block">
                Selecione o Colaborador Reserva
              </label>
              <select
                value={substitutoId}
                onChange={(e) => setSubstitutoId(e.target.value)}
                className="w-full h-10 px-3 rounded-xl border border-border/80 bg-background text-xs text-foreground focus:outline-none focus:ring-2 focus:ring-amber-500/30"
              >
                <option value="">Selecione um reserva do banco florestal...</option>
                {colaboradoresReserva.map((res) => (
                  <option key={res.id} value={res.id}>
                    {res.nome} ({res.cargo})
                  </option>
                ))}
              </select>
            </div>
          )}

          {/* Observações Opcionais */}
          <div>
            <label className="text-xs font-semibold text-muted-foreground uppercase tracking-wider block mb-1.5">
              Observações Operacionais (Opcional)
            </label>
            <Input
              placeholder="Ex: Atestado entregue ao líder, retorno previsto amanhã..."
              value={observacao}
              onChange={(e) => setObservacao(e.target.value)}
              className="text-xs rounded-xl bg-background/50 border-border/60"
            />
          </div>

          {/* Ações */}
          <div className="flex items-center justify-end gap-3 pt-3 border-t border-border/40">
            <Button type="button" variant="outline" onClick={onClose} className="rounded-xl text-xs">
              Cancelar
            </Button>
            <Button
              type="submit"
              className="gap-2 bg-emerald-600 hover:bg-emerald-500 text-white rounded-xl text-xs font-bold"
            >
              <Save className="w-4 h-4" />
              Confirmar Alteração
            </Button>
          </div>
        </form>
      </div>
    </div>
  );
};

