            </div>
          </div>

          <form onSubmit={handleSubmit} className="space-y-5">
            {/* Seletor Rápido de Status */}
            <div>
              <label className="text-xs font-bold uppercase tracking-wider text-muted-foreground block mb-2">
                Status Operacional de Hoje
              </label>

              <div className="grid grid-cols-3 gap-2.5">
                <button
                  type="button"
                  onClick={() => setStatus('presente')}
                  className={cn(
                    'flex flex-col items-center justify-center gap-1.5 p-3 rounded-2xl border text-xs font-bold transition-all cursor-pointer',
                    status === 'presente'
                      ? 'bg-emerald-500/15 border-emerald-500 text-emerald-400 shadow-sm ring-1 ring-emerald-500/30'
                      : 'border-border/60 bg-muted/20 text-muted-foreground hover:bg-muted/40 hover:text-foreground'
                  )}
                >
                  <CheckCircle2 className="w-5 h-5 text-emerald-400" />
                  <span>Presente</span>
                </button>

                <button
                  type="button"
                  onClick={() => setStatus('falta')}
                  className={cn(
                    'flex flex-col items-center justify-center gap-1.5 p-3 rounded-2xl border text-xs font-bold transition-all cursor-pointer',
                    status === 'falta'
                      ? 'bg-rose-500/20 border-rose-500 text-rose-300 shadow-sm ring-1 ring-rose-500/40'
                      : 'border-border/60 bg-muted/20 text-muted-foreground hover:bg-muted/40 hover:text-foreground'
                  )}
                >
                  <XCircle className="w-5 h-5 text-rose-400" />
                  <span>Marcar Falta</span>
                </button>

                <button
                  type="button"
                  onClick={() => setStatus('substituto')}
                  className={cn(
                    'flex flex-col items-center justify-center gap-1.5 p-3 rounded-2xl border text-xs font-bold transition-all cursor-pointer',
                    status === 'substituto'
                      ? 'bg-amber-500/20 border-amber-500 text-amber-300 shadow-sm ring-1 ring-amber-500/40'
                      : 'border-border/60 bg-muted/20 text-muted-foreground hover:bg-muted/40 hover:text-foreground'
                  )}
                >
                  <RefreshCw className="w-5 h-5 text-amber-400" />
                  <span>Substituição</span>
                </button>
              </div>
            </div>

            {/* Campos Condicionais: Se Falta */}
            {status === 'falta' && (
              <div className="space-y-3.5 p-4 rounded-2xl bg-rose-950/20 border border-rose-500/30 animate-in fade-in duration-200">
                <div className="flex items-center gap-2 text-rose-400 text-xs font-bold">
                  <AlertTriangle className="w-4 h-4" />
                  <span>Motivo da Ausência</span>
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
                  {MOTIVOS_FALTA.map((m) => (
                    <button
                      key={m}
                      type="button"
                      onClick={() => setMotivo(m)}
                      className={cn(
                        'text-left px-3 py-2 rounded-xl text-xs font-medium border transition-all cursor-pointer',
                        motivo === m
                          ? 'bg-rose-500/20 border-rose-500/70 text-rose-200 font-bold ring-1 ring-rose-500/30'
                          : 'border-border/60 bg-muted/10 text-muted-foreground hover:bg-muted/30 hover:text-foreground'
                      )}
                    >
                      {m}
                    </button>
                  ))}
                </div>
              </div>
            )}

            {/* Campos Condicionais: Se Substituto */}
            {status === 'substituto' && (
              <div className="space-y-3.5 p-4 rounded-2xl bg-amber-950/20 border border-amber-500/30 animate-in fade-in duration-200">
                <div className="flex items-center gap-2 text-amber-400 text-xs font-bold">
                  <UserCheck className="w-4 h-4" />
                  <span>Selecione o Colaborador Reserva para Assumir o Posto</span>
                </div>

                <select
                  value={substitutoId}
                  onChange={(e) => setSubstitutoId(e.target.value)}
                  className="w-full h-10 rounded-xl border border-input bg-card px-3 py-2 text-sm text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                >
                  <option value="">Selecione um substituto disponível...</option>
                  {(colaboradoresReserva || []).map((res) => (
                    <option key={res.id} value={res.id}>
                      {res.nome} — {res.cargo} ({res.matricula || 'Sem matrícula'})
                    </option>
                  ))}
                </select>
              </div>
            )}

            {/* Observações Opcionais */}
            <div className="space-y-1.5">
              <label className="text-xs font-medium text-muted-foreground flex items-center gap-1.5">
                <FileText className="w-3.5 h-3.5" />
                <span>Observação / Justificativa adicional</span>
              </label>
              <textarea
                value={observacao}
                onChange={(e) => setObservacao(e.target.value)}
                placeholder="Ex: Avisou liderança às 06h30; Atestado será entregue até amanhã..."
                rows={3}
                className="w-full rounded-xl border border-input bg-card/60 px-3 py-2 text-sm text-foreground placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring resize-none"
              />
            </div>

            {/* Ações */}
            <div className="flex items-center justify-end gap-3 pt-2 border-t border-border/40">
              <Button type="button" variant="outline" onClick={onClose}>
                Cancelar
              </Button>
              <Button type="submit" className="bg-emerald-600 hover:bg-emerald-500 text-white font-semibold shadow-sm">
                Salvar Alterações
              </Button>
            </div>
          </form>
        </div>
      </div>
    </div>
  );
};

