import React, { useState, useMemo } from 'react';
import {
  Car,
  Search,
  Filter,
  CheckCircle2,
  XCircle,
  HelpCircle,
  Users,
  Compass,
  MapPin,
  ShieldCheck,
  UserCheck,
  UserX,
  RefreshCw,
  Sparkles,
  Info,
} from 'lucide-react';
import { Card, CardContent } from './ui/card';
import { Badge } from './ui/badge';
import { Input } from './ui/input';
import { Button } from './ui/button';
import { Veiculo, Colaborador, StatusPresenca, MotivoFalta, Regional } from '../types';
import { AttendanceModal } from './AttendanceModal';
import { cn } from '@/lib/utils';

export interface VehicleCardGridProps {
  veiculos?: Veiculo[];
  colaboradoresReserva?: Colaborador[];
  selectedRegional?: Regional;
  onUpdateColaboradorStatus?: (
    colabId: string,
    novoStatus: StatusPresenca,
    motivo?: MotivoFalta,
    obs?: string,
    substitutoId?: string,
    substitutoNome?: string
  ) => void;
  onSubstituirColaborador?: (
    colaboradorOriginal: Colaborador,
    colaboradorReserva: Colaborador,
    motivo?: MotivoFalta,
    obs?: string
  ) => void;
}

// Configuração de cores de ALTA VISIBILIDADE e contraste profissional
const statusBadgeConfig: Record<StatusPresenca, {
  label: string;
  pillBg: string;
  pillText: string;
  pillBorder: string;
  avatarRing: string;
  seatBg: string;
  glow: string;
  icon: React.ReactNode;
}> = {
  presente: {
    label: 'PRESENTE',
    pillBg: 'bg-emerald-500 text-white',
    pillText: 'text-white font-black',
    pillBorder: 'border-emerald-400 shadow-sm shadow-emerald-500/20',
    avatarRing: 'ring-3 ring-emerald-400 ring-offset-2 ring-offset-slate-900',
    seatBg: 'bg-emerald-950/40 border-emerald-500/50 hover:border-emerald-400 hover:bg-emerald-950/60',
    glow: 'shadow-[0_0_15px_rgba(16,185,129,0.25)]',
    icon: <CheckCircle2 className="w-3.5 h-3.5 text-white" strokeWidth={2.5} />,
  },
  falta: {
    label: 'FALTA',
    pillBg: 'bg-rose-600 text-white animate-pulse',
    pillText: 'text-white font-black',
    pillBorder: 'border-rose-400 shadow-sm shadow-rose-600/30',
    avatarRing: 'ring-3 ring-rose-500 ring-offset-2 ring-offset-slate-900',
    seatBg: 'bg-rose-950/45 border-rose-500/60 hover:border-rose-400 hover:bg-rose-950/70',
    glow: 'shadow-[0_0_18px_rgba(225,29,72,0.35)]',
    icon: <XCircle className="w-3.5 h-3.5 text-white" strokeWidth={2.5} />,
  },
  substituto: {
    label: 'SUBSTITUTO',
    pillBg: 'bg-amber-500 text-slate-950',
    pillText: 'text-slate-950 font-black',
    pillBorder: 'border-amber-300 shadow-sm shadow-amber-500/25',
    avatarRing: 'ring-3 ring-amber-400 ring-offset-2 ring-offset-slate-900',
    seatBg: 'bg-amber-950/40 border-amber-500/60 hover:border-amber-400 hover:bg-amber-950/60',
    glow: 'shadow-[0_0_15px_rgba(245,158,11,0.25)]',
    icon: <RefreshCw className="w-3.5 h-3.5 text-slate-950" strokeWidth={2.5} />,
  },
};

const getIniciais = (nome?: string) => {
  if (!nome) return 'OP';
  const partes = nome.trim().split(' ');
  if (partes.length === 1) return partes[0].substring(0, 2).toUpperCase();
  return (partes[0][0] + partes[partes.length - 1][0]).toUpperCase();
};

export const VehicleCardGrid: React.FC<VehicleCardGridProps> = ({
  veiculos = [],
  colaboradoresReserva = [],
  selectedRegional = 'todas',
  onUpdateColaboradorStatus,
  onSubstituirColaborador,
}) => {
  const [busca, setBusca] = useState('');
  const [filtroStatus, setFiltroStatus] = useState<StatusPresenca | 'todos'>('todos');
  const [filtroRegional, setFiltroRegional] = useState<Regional | 'todas'>(selectedRegional);

  // Estado para o modal de presença / falta / substituição
  const [colaboradorSelecionado, setColaboradorSelecionado] = useState<Colaborador | null>(null);
  const [veiculoDoColaborador, setVeiculoDoColaborador] = useState<Veiculo | null>(null);
  const [modalAberto, setModalAberto] = useState(false);

  // Sincroniza se prop externa mudar
  React.useEffect(() => {
    if (selectedRegional) {
      setFiltroRegional(selectedRegional);
    }
  }, [selectedRegional]);

  const abrirModalPresenca = (colab?: Colaborador, veic?: Veiculo) => {
    if (!colab || !veic) return;
    setColaboradorSelecionado(colab);
    setVeiculoDoColaborador(veic);
    setModalAberto(true);
  };

  const fecharModal = () => {
    setModalAberto(false);
    setColaboradorSelecionado(null);
    setVeiculoDoColaborador(null);
  };

  // Filtragem dos veículos
  const veiculosFiltrados = useMemo(() => {
    return (veiculos || []).filter((v) => {
      if (!v) return false;
      const matchRegional = filtroRegional === 'todas' || v.regional === filtroRegional;

      const assentosLista = [
        v.assentos?.motorista,
        v.assentos?.frenteDir,
        v.assentos?.trasEsq,
        v.assentos?.trasDir,
      ].filter(Boolean) as Colaborador[];

      const matchBusca =
        !busca ||
        (v.prefixo || '').toLowerCase().includes(busca.toLowerCase()) ||
        (v.placa || '').toLowerCase().includes(busca.toLowerCase()) ||
        (v.modelo || '').toLowerCase().includes(busca.toLowerCase()) ||
        assentosLista.some((c) =>
          (c.nome || '').toLowerCase().includes(busca.toLowerCase()) ||
          (c.cargo || '').toLowerCase().includes(busca.toLowerCase()) ||
          (c.matricula || '').toLowerCase().includes(busca.toLowerCase())
        );

      const matchStatus =
        filtroStatus === 'todos' ||
        assentosLista.some((c) => c.status === filtroStatus);

      return matchRegional && matchBusca && matchStatus;
    });
  }, [veiculos, busca, filtroStatus, filtroRegional]);

  // Contadores rápidos para a barra de resumo de visibilidade
  const totais = useMemo(() => {
    let presentes = 0;
    let faltas = 0;
    let substitutos = 0;
    let totalAssentos = 0;

    (veiculos || []).forEach((v) => {
      if (!v?.assentos) return;
      const assentos = [
        v.assentos.motorista,
        v.assentos.frenteDir,
        v.assentos.trasEsq,
        v.assentos.trasDir,
      ].filter(Boolean) as Colaborador[];

      assentos.forEach((c) => {
        totalAssentos++;
        if (c.status === 'presente') presentes++;
        else if (c.status === 'falta') faltas++;
        else if (c.status === 'substituto') substitutos++;
      });
    });

    return { presentes, faltas, substitutos, totalAssentos };
  }, [veiculos]);

  // Render do assento com visão de topo do ocupante
  const renderAssentoTopo = (
    colab: Colaborador | undefined,
    veiculo: Veiculo,
    tituloPosicao: string,
    ehMotorista: boolean = false
  ) => {
    if (!colab) {
      return (
        <div className="h-full min-h-[148px] rounded-2xl border-2 border-dashed border-slate-700/80 bg-slate-900/60 flex flex-col items-center justify-center p-3 text-slate-500">
          <span className="text-[11px] font-semibold tracking-wider uppercase">{tituloPosicao}</span>
          <span className="text-xs text-slate-400 mt-1">Assento Vago</span>
        </div>
      );
    }

    const cfg = statusBadgeConfig[colab.status || 'presente'] || statusBadgeConfig.presente;

    return (
      <div
        onClick={() => abrirModalPresenca(colab, veiculo)}
        title="Clique para apontar Presença, Falta ou Substituição"
        className={cn(
          'relative group cursor-pointer rounded-2xl p-3 border-2 transition-all duration-200 flex flex-col justify-between select-none',
          cfg.seatBg,
          cfg.glow,
          'hover:scale-[1.02] active:scale-[0.99] backdrop-blur-md shadow-lg'
        )}
      >
        {/* Top Header do Assento: Posição + Ícone Volante + Status Pill de Alta Visibilidade */}
        <div className="flex items-center justify-between gap-1.5 pb-2 border-b border-white/10">
          <div className="flex items-center gap-1.5 min-w-0">
            {ehMotorista ? (
              <span className="inline-flex items-center gap-1 px-1.5 py-0.5 rounded-md bg-amber-400 text-slate-950 font-black text-[10px] tracking-wide uppercase shrink-0 shadow-sm">
                <Compass className="w-3 h-3 text-slate-950" />
                Motorista
              </span>
            ) : (
              <span className="inline-flex items-center px-1.5 py-0.5 rounded-md bg-slate-800 text-slate-200 border border-slate-700 font-bold text-[10px] tracking-wide uppercase shrink-0">
                {tituloPosicao}
              </span>
            )}
          </div>

          {/* Badge de Status Vibrante e Nítida */}
          <span
            className={cn(
              'inline-flex items-center gap-1 px-2.5 py-0.5 rounded-full text-[11px] border tracking-wider shadow-sm shrink-0',
              cfg.pillBg,
              cfg.pillBorder
            )}
          >
            {cfg.icon}
            <span className={cfg.pillText}>{cfg.label}</span>
          </span>
        </div>

        {/* Centro: Visão de Topo - Cabeça/Foto do Colaborador no Assento */}
        <div className="flex items-center gap-3 my-2.5">
          {/* Avatar com contorno de topo do assento */}
          <div className="relative shrink-0">
            {/* Desenho do encosto de cabeça visto de cima */}
            <div className="absolute -inset-1 rounded-2xl bg-gradient-to-b from-slate-700/80 to-slate-900/90 border border-slate-600/60 -z-0" />

            <div
              className={cn(
                'relative z-10 w-13 h-13 sm:w-14 sm:h-14 rounded-xl overflow-hidden bg-slate-800 flex items-center justify-center transition-all',
                cfg.avatarRing
              )}
            >
              {colab.foto ? (
                <img
                  src={colab.foto}
                  alt={colab.nome}
                  className="w-full h-full object-cover"
                  onError={(e) => {
                    (e.target as HTMLImageElement).style.display = 'none';
                  }}
                />
              ) : (
                <span className="text-sm font-black text-white tracking-wider">
                  {getIniciais(colab.nome)}
                </span>
              )}
            </div>

            {/* Marcador de status no canto do avatar */}
            <div
              className={cn(
                'absolute -bottom-1 -right-1 z-20 w-5 h-5 rounded-full border-2 border-slate-950 flex items-center justify-center',
                colab.status === 'presente' && 'bg-emerald-500 text-white',
                colab.status === 'falta' && 'bg-rose-500 text-white animate-bounce',
                colab.status === 'substituto' && 'bg-amber-400 text-slate-950'
              )}
            >
              {colab.status === 'presente' && <CheckCircle2 className="w-3 h-3" />}
              {colab.status === 'falta' && <XCircle className="w-3 h-3" />}
              {colab.status === 'substituto' && <RefreshCw className="w-2.5 h-2.5 font-bold" />}
            </div>
          </div>

          {/* Dados do Colaborador com Alto Contraste */}
          <div className="min-w-0 flex-1">
            <h4 className="text-sm font-black text-white tracking-tight leading-snug truncate drop-shadow-sm group-hover:text-emerald-300 transition-colors">
              {colab.nome}
            </h4>
            <p className="text-xs font-semibold text-slate-300 truncate mt-0.5">
              {colab.cargo || 'Operador Florestal'}
            </p>
            {colab.matricula && (
              <span className="inline-block mt-1 font-mono text-[10px] font-bold text-slate-400 bg-slate-900/90 px-1.5 py-0.5 rounded border border-slate-700/60">
                Matr: {colab.matricula}
              </span>
            )}
          </div>
        </div>

        {/* Rodapé do Assento: Motivo de falta ou alerta visual */}
        <div className="pt-2 border-t border-white/10 flex items-center justify-between text-[11px]">
          {colab.status === 'falta' ? (
            <span className="text-rose-300 font-bold flex items-center gap-1 truncate">
              <span className="w-2 h-2 rounded-full bg-rose-500 shrink-0" />
              {colab.motivoFalta || 'Falta Registrada'}
            </span>
          ) : colab.status === 'substituto' ? (
            <span className="text-amber-300 font-bold flex items-center gap-1 truncate">
              <RefreshCw className="w-3 h-3 text-amber-400 shrink-0" />
              Substituto Operacional
            </span>
          ) : (
            <span className="text-emerald-400 font-bold flex items-center gap-1">
              <span className="w-2 h-2 rounded-full bg-emerald-400 shrink-0" />
              Em Operação Ativa
            </span>
          )}

          <span className="text-[10px] text-slate-400 font-medium group-hover:text-white transition-colors bg-white/5 px-2 py-0.5 rounded-md border border-white/10 shrink-0 ml-1">
            Editar Status
          </span>
        </div>
      </div>
    );
  };

  return (
    <div className="space-y-6">
      {/* Barra de Filtros e Resumo Visual de Alto Contraste */}
      <div className="rounded-2xl border-2 border-border/80 bg-card/90 backdrop-blur-xl p-4 sm:p-5 shadow-xl space-y-4">
        {/* Contadores Nítidos de Status */}
        <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
          <div
            onClick={() => setFiltroStatus('todos')}
            className={cn(
              'cursor-pointer rounded-xl p-3 border-2 transition-all flex items-center justify-between',
              filtroStatus === 'todos'
                ? 'bg-primary/20 border-primary text-white shadow-md'
                : 'bg-muted/40 border-border/70 text-slate-300 hover:border-slate-500'
            )}
          >
            <div>
              <p className="text-[11px] font-bold uppercase tracking-wider text-muted-foreground">Total Ocupantes</p>
              <p className="text-2xl font-black text-foreground tabular-nums">{totais.totalAssentos}</p>
            </div>
            <Users className="w-6 h-6 text-primary opacity-80" />
          </div>

          <div
            onClick={() => setFiltroStatus('presente')}
            className={cn(
              'cursor-pointer rounded-xl p-3 border-2 transition-all flex items-center justify-between',
              filtroStatus === 'presente'
                ? 'bg-emerald-500/25 border-emerald-400 text-white shadow-md shadow-emerald-500/10'
                : 'bg-emerald-950/20 border-emerald-500/30 text-emerald-300 hover:border-emerald-400'
            )}
          >
            <div>
              <p className="text-[11px] font-bold uppercase tracking-wider text-emerald-400">Presentes</p>
              <p className="text-2xl font-black text-emerald-300 tabular-nums">{totais.presentes}</p>
            </div>
            <CheckCircle2 className="w-6 h-6 text-emerald-400" />
          </div>

          <div
            onClick={() => setFiltroStatus('falta')}
            className={cn(
              'cursor-pointer rounded-xl p-3 border-2 transition-all flex items-center justify-between',
              filtroStatus === 'falta'
                ? 'bg-rose-500/30 border-rose-400 text-white shadow-md shadow-rose-500/20'
                : 'bg-rose-950/20 border-rose-500/35 text-rose-300 hover:border-rose-400'
            )}
          >
            <div>
              <p className="text-[11px] font-bold uppercase tracking-wider text-rose-400">Faltas</p>
              <p className="text-2xl font-black text-rose-300 tabular-nums">{totais.faltas}</p>
            </div>
            <XCircle className="w-6 h-6 text-rose-400" />
          </div>

          <div
            onClick={() => setFiltroStatus('substituto')}
            className={cn(
              'cursor-pointer rounded-xl p-3 border-2 transition-all flex items-center justify-between',
              filtroStatus === 'substituto'
                ? 'bg-amber-500/30 border-amber-400 text-white shadow-md shadow-amber-500/20'
                : 'bg-amber-950/20 border-amber-500/30 text-amber-300 hover:border-amber-400'
            )}
          >
            <div>
              <p className="text-[11px] font-bold uppercase tracking-wider text-amber-400">Substitutos</p>
              <p className="text-2xl font-black text-amber-300 tabular-nums">{totais.substitutos}</p>
            </div>
            <RefreshCw className="w-6 h-6 text-amber-400" />
          </div>
        </div>

        {/* Inputs de Busca e Seletores de Unidade */}
        <div className="flex flex-col sm:flex-row items-stretch sm:items-center gap-3 pt-1">
          <div className="relative flex-1">
            <Search className="w-4 h-4 text-emerald-400 absolute left-3.5 top-1/2 -translate-y-1/2" />
            <Input
              placeholder="Buscar por colaborador, cargo, placa ou prefixo..."
              value={busca}
              onChange={(e) => setBusca(e.target.value)}
              className="pl-10 h-10 text-sm bg-background/80 border-border/80 focus:border-emerald-400 rounded-xl"
            />
          </div>

          <div className="flex items-center gap-2">
            <select
              value={filtroRegional}
              onChange={(e) => setFiltroRegional(e.target.value as any)}
              className="h-10 px-3.5 rounded-xl border border-border/80 bg-background text-sm font-semibold text-foreground focus:outline-none focus:ring-2 focus:ring-emerald-500/40"
            >
              <option value="todas">Todas as Unidades</option>
              <option value="ribas">Ribas do Rio Pardo</option>
              <option value="agua_clara">Água Clara</option>
            </select>

            {(busca || filtroStatus !== 'todos' || filtroRegional !== 'todas') && (
              <Button
                variant="outline"
                size="sm"
                onClick={() => {
                  setBusca('');
                  setFiltroStatus('todos');
                  setFiltroRegional('todas');
                }}
                className="h-10 text-xs font-bold text-muted-foreground hover:text-foreground"
              >
                Limpar Filtros
              </Button>
            )}
          </div>
        </div>
      </div>

      {/* Grid de Veículos com Visão Superior (Top View dos Carros) */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {veiculosFiltrados.length === 0 ? (
          <div className="col-span-full py-16 text-center rounded-3xl border-2 border-dashed border-border/70 bg-card/30">
            <Car className="w-12 h-12 text-slate-500 mx-auto mb-3 opacity-60" />
            <h3 className="text-base font-bold text-foreground">Nenhum veículo encontrado</h3>
            <p className="text-xs text-muted-foreground mt-1 max-w-sm mx-auto">
              Tente alterar os termos da busca ou selecionar outra regional nos filtros acima.
            </p>
          </div>
        ) : (
          veiculosFiltrados.map((veiculo) => {
            const assentos = [
              veiculo.assentos?.motorista,
              veiculo.assentos?.frenteDir,
              veiculo.assentos?.trasEsq,
              veiculo.assentos?.trasDir,
            ].filter(Boolean) as Colaborador[];

            const temFalta = assentos.some((c) => c.status === 'falta');
            const temSubstituto = assentos.some((c) => c.status === 'substituto');

            return (
              <div
                key={veiculo.id}
                className={cn(
                  'rounded-3xl border-2 transition-all duration-200 overflow-hidden shadow-2xl bg-slate-950/90 text-slate-100',
                  temFalta
                    ? 'border-rose-500/70 shadow-rose-950/20'
                    : temSubstituto
                    ? 'border-amber-500/70 shadow-amber-950/20'
                    : 'border-emerald-500/50 hover:border-emerald-400'
                )}
              >
                {/* Cabeçalho do Card: Identificação do Veículo com Cores Vivas */}
                <div className="p-4 sm:p-5 border-b border-slate-800 bg-gradient-to-r from-slate-900 via-slate-900/95 to-slate-950 flex flex-wrap items-center justify-between gap-3">
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 rounded-xl bg-emerald-500/20 border-2 border-emerald-400 flex items-center justify-center text-emerald-300 shadow-md">
                      <Car className="w-5 h-5" />
                    </div>
                    <div>
                      <div className="flex items-center gap-2">
                        <h3 className="font-black text-lg sm:text-xl text-white tracking-tight">
                          {veiculo.prefixo}
                        </h3>
                        <span className="px-2.5 py-0.5 rounded-md bg-slate-800 text-emerald-400 border border-slate-700 font-mono text-xs font-extrabold tracking-wider">
                          {veiculo.placa}
                        </span>
                      </div>
                      <p className="text-xs text-slate-400 font-medium mt-0.5">
                        {veiculo.modelo} · {veiculo.regional === 'ribas' ? 'Ribas do Rio Pardo' : 'Água Clara'}
                      </p>
                    </div>
                  </div>

                  {/* Badges de Operação do Carro */}
                  <div className="flex items-center gap-2 flex-wrap">
                    {temFalta && (
                      <span className="px-2.5 py-1 rounded-full bg-rose-600 text-white font-black text-xs border border-rose-400 shadow-sm flex items-center gap-1.5 animate-pulse">
                        <XCircle className="w-3.5 h-3.5" />
                        DESFALQUE
                      </span>
                    )}
                    {temSubstituto && (
                      <span className="px-2.5 py-1 rounded-full bg-amber-500 text-slate-950 font-black text-xs border border-amber-300 shadow-sm flex items-center gap-1.5">
                        <RefreshCw className="w-3.5 h-3.5" />
                        SUBSTITUIÇÃO
                      </span>
                    )}
                    {!temFalta && !temSubstituto && (
                      <span className="px-2.5 py-1 rounded-full bg-emerald-500 text-white font-black text-xs border border-emerald-400 shadow-sm flex items-center gap-1.5">
                        <CheckCircle2 className="w-3.5 h-3.5" />
                        COMPLETO
                      </span>
                    )}
                  </div>
                </div>

                {/* VISÃO DE CIMA DO VEÍCULO (TOP VIEW CHASSIS) */}
                <div className="p-4 sm:p-5 bg-gradient-to-b from-slate-950 via-slate-900 to-slate-950 relative">
                  {/* Contorno estético do Carro visto de cima */}
                  <div className="relative rounded-3xl border-2 border-slate-700/80 bg-slate-900/90 p-3 sm:p-4 shadow-inner">
                    {/* Frente do Carro: Para-brisa e Capô */}
                    <div className="mb-3 flex items-center justify-between px-3 py-1.5 rounded-xl bg-slate-800/80 border border-slate-700/60 text-slate-300 text-xs">
                      <div className="flex items-center gap-2">
                        <span className="w-2 h-2 rounded-full bg-emerald-400 animate-ping" />
                        <span className="font-bold uppercase tracking-wider text-[11px] text-emerald-400">
                          FRENTE DO VEÍCULO
                        </span>
                      </div>
                      <span className="font-semibold text-slate-400 text-[11px]">
                        Cabine Dupla 4x4
                      </span>
                    </div>

                    {/* ASSENTOS DIANTEIROS (MOTORISTA + PASSAGEIRO DIANTEIRO - EQUIPE 1) */}
                    <div className="mb-3">
                      <div className="flex items-center justify-between mb-2 px-1">
                        <span className="text-[11px] font-black uppercase tracking-wider text-emerald-400 flex items-center gap-1">
                          <Users className="w-3.5 h-3.5" />
                          Equipe 1 · Postos Dianteiros
                        </span>
                        <span className="text-[10px] text-slate-400">
                          {veiculo.equipe1Codigo || 'Frente'}
                        </span>
                      </div>

                      <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                        {renderAssentoTopo(veiculo.assentos?.motorista, veiculo, 'Motorista (Lado Esq)', true)}
                        {renderAssentoTopo(veiculo.assentos?.frenteDir, veiculo, 'Passageiro Dianteiro', false)}
                      </div>
                    </div>

                    {/* Divisor do habitáculo interno */}
                    <div className="my-3 border-t border-dashed border-slate-700/80 relative">
                      <span className="absolute left-1/2 -translate-x-1/2 -translate-y-1/2 px-2 py-0.5 rounded-full bg-slate-800 border border-slate-700 text-[9px] font-bold uppercase tracking-widest text-slate-400">
                        Fileira Traseira
                      </span>
                    </div>

                    {/* ASSENTOS TRASEIROS (EQUIPE 2) */}
                    <div>
                      <div className="flex items-center justify-between mb-2 px-1">
                        <span className="text-[11px] font-black uppercase tracking-wider text-teal-400 flex items-center gap-1">
                          <Users className="w-3.5 h-3.5" />
                          Equipe 2 · Postos Traseiros
                        </span>
                        <span className="text-[10px] text-slate-400">
                          {veiculo.equipe2Codigo || 'Traseira'}
                        </span>
                      </div>

                      <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                        {renderAssentoTopo(veiculo.assentos?.trasEsq, veiculo, 'Traseiro Esquerdo', false)}
                        {renderAssentoTopo(veiculo.assentos?.trasDir, veiculo, 'Traseiro Direito', false)}
                      </div>
                    </div>

                    {/* Traseira do Carro / Caçamba */}
                    <div className="mt-3 py-1 text-center rounded-lg bg-slate-800/40 border border-slate-700/40 text-[10px] font-bold text-slate-500 uppercase tracking-widest">
                      Traseira / Compartimento de Carga Florestal
                    </div>
                  </div>
                </div>

                {/* Footer do Card do Veículo */}
                <div className="px-5 py-3 bg-slate-900 border-t border-slate-800 flex items-center justify-between text-xs text-slate-400">
                  <span className="flex items-center gap-1">
                    <Info className="w-3.5 h-3.5 text-slate-500" />
                    Toque em qualquer assento para alterar o status do colaborador
                  </span>
                  <span className="font-mono text-slate-500 text-[11px]">
                    4 Assentos
                  </span>
                </div>
              </div>
            );
          })
        )}
      </div>

      {/* Modal de Presença / Falta / Substituição com Alto Contraste */}
      {modalAberto && colaboradorSelecionado && (
        <AttendanceModal
          isOpen={modalAberto}
          onClose={fecharModal}
          colaborador={colaboradorSelecionado}
          colaboradoresReserva={colaboradoresReserva}
          onSalvarStatus={(colabId, novoStatus, motivo, obs, subId, subNome) => {
            if (onUpdateColaboradorStatus) {
              onUpdateColaboradorStatus(colabId, novoStatus, motivo, obs, subId, subNome);
            }
            fecharModal();
          }}
          onSubstituir={(colabOriginal, colabReserva, motivo, obs) => {
            if (onSubstituirColaborador) {
              onSubstituirColaborador(colabOriginal, colabReserva, motivo, obs);
            }
            fecharModal();
          }}
        />
      )}
    </div>
  );
};

