import React, { useState, useMemo, useRef } from 'react';
import {
  Users,
  Search,
  Phone,
  MapPin,
  ChevronDown,
  ChevronUp,
  UserCheck,
  UserX,
  UploadCloud,
  FileSpreadsheet,
  Download,
  CheckCircle2,
  AlertCircle,
  X,
  Plus,
  Camera,
  Trash2,
  Building2,
  Briefcase,
  FileCheck,
  Eye,
} from 'lucide-react';
import { Card, CardContent } from './ui/card';
import { Badge } from './ui/badge';
import { Input } from './ui/input';
import { Button } from './ui/button';
import { cn } from '@/lib/utils';
import { Colaborador, Veiculo, StatusPresenca, MotivoFalta, Regional } from '../types';

export interface ColaboradorCompleto {
  id: string;
  nome: string;
  cargo: string;
  matricula: string;
  foto: string;
  telefone: string;
  status: StatusPresenca;
  motivoFalta?: MotivoFalta;
  observacao?: string;
  substitutoNome?: string;
  equipeId: string;
  equipeNumero: 1 | 2;
  posicaoVeiculo: 'motorista' | 'frente_dir' | 'tras_esq' | 'tras_dir';
  veiculoPrefixo: string;
  veiculoPlaca: string;
  regional: 'ribas' | 'agua_clara';
}

export interface CollaboratorsManagementProps {
  veiculos?: Veiculo[];
  colaboradoresReserva?: Colaborador[];
  selectedRegional?: Regional;
  onUpdateColaboradorStatus?: (
    colabId: string,
    novoStatus: StatusPresenca,
    motivo?: MotivoFalta,
    obs?: string
  ) => void;
  onImportarColaboradores?: (novosColaboradores: ColaboradorCompleto[]) => void;
  onAdicionarColaborador?: (novoColaborador: ColaboradorCompleto) => void;
}

const statusConfig: Record<StatusPresenca, { label: string; className: string }> = {
  presente: { label: 'Presente', className: 'bg-emerald-500/20 text-emerald-400 border-emerald-500/30' },
  falta: { label: 'Falta', className: 'bg-rose-500/20 text-rose-400 border-rose-500/30' },
  substituto: { label: 'Substituto', className: 'bg-amber-500/20 text-amber-400 border-amber-500/30' },
};

const regionalLabel: Record<string, string> = {
  ribas: 'Ribas do Rio Pardo',
  agua_clara: 'Água Clara',
};

const getIniciais = (nome?: string) => {
  if (!nome) return 'CO';
  const partes = nome.trim().split(' ');
  if (partes.length === 1) return partes[0].substring(0, 2).toUpperCase();
  return (partes[0][0] + partes[partes.length - 1][0]).toUpperCase();
};

export const CollaboratorsManagement: React.FC<CollaboratorsManagementProps> = ({
  veiculos = [],
  colaboradoresReserva = [],
  selectedRegional = 'todas',
  onUpdateColaboradorStatus,
  onAdicionarColaborador,
}) => {
  const [search, setSearch] = useState('');
  const [filterStatus, setFilterStatus] = useState<StatusPresenca | 'todos'>('todos');
  const [filterRegional, setFilterRegional] = useState<Regional | 'todas'>(selectedRegional);
  const [fotoModalAberta, setFotoModalAberta] = useState<{ url: string; nome: string; cargo: string } | null>(null);

  const [modalNovoAberto, setModalNovoAberto] = useState(false);
  const [novoNome, setNovoNome] = useState('');
  const [novoCargo, setNovoCargo] = useState('');
  const [novoTelefone, setNovoTelefone] = useState('');
  const [novaFoto, setNovaFoto] = useState<string>('');
  const [novaUnidade, setNovaUnidade] = useState<'ribas' | 'agua_clara'>('ribas');
  const fotoInputRef = useRef<HTMLInputElement>(null);

  const colaboradoresBase: ColaboradorCompleto[] = useMemo(() => {
    const lista: ColaboradorCompleto[] = [];
    (veiculos || []).forEach((v) => {
      if (!v || !v.assentos) return;
      const assentos: Array<{ colab?: Colaborador; pos: ColaboradorCompleto['posicaoVeiculo'] }> = [
        { colab: v.assentos.motorista, pos: 'motorista' },
        { colab: v.assentos.frenteDir, pos: 'frente_dir' },
        { colab: v.assentos.trasEsq, pos: 'tras_esq' },
        { colab: v.assentos.trasDir, pos: 'tras_dir' },
      ];
      assentos.forEach(({ colab, pos }) => {
        if (!colab) return;
        lista.push({
          id: colab.id,
          nome: colab.nome || 'Sem Nome',
          cargo: colab.cargo || 'Operador',
          matricula: '',
          foto: colab.foto ?? '',
          telefone: colab.telefone ?? '',
          status: colab.status || 'presente',
          motivoFalta: colab.motivoFalta,
          observacao: colab.observacao,
          substitutoNome: colab.substitutoNome,
          equipeId: colab.equipeId || '',
          equipeNumero: colab.equipeNumero || 1,
          posicaoVeiculo: pos,
          veiculoPrefixo: v.prefixo || '',
          veiculoPlaca: v.placa || '',
          regional: v.regional || 'ribas',
        });
      });
    });

    (colaboradoresReserva || []).forEach((r, idx) => {
      if (!r) return;
      lista.push({
        id: r.id || `res-${idx}`,
        nome: r.nome || 'Colaborador Reserva',
        cargo: r.cargo || 'Reserva Operacional',
        matricula: '',
        foto: r.foto || '',
        telefone: r.telefone || '',
        status: r.status || 'presente',
        motivoFalta: r.motivoFalta,
        observacao: r.observacao,
        substitutoNome: r.substitutoNome,
        equipeId: 'reserva',
        equipeNumero: 1,
        posicaoVeiculo: 'motorista',
        veiculoPrefixo: 'Banco de Reserva',
        veiculoPlaca: '-',
        regional: 'ribas',
      });
    });

    return lista;
  }, [veiculos, colaboradoresReserva]);

  const [colaboradoresAdicionados, setColaboradoresAdicionados] = useState<ColaboradorCompleto[]>([]);

  const todosColaboradores = useMemo(() => {
    return [...colaboradoresBase, ...colaboradoresAdicionados];
  }, [colaboradoresBase, colaboradoresAdicionados]);

  const colaboradoresFiltrados = useMemo(() => {
    return todosColaboradores.filter((c) => {
      if (!c) return false;
      const matchSearch =
        !search ||
        (c.nome || '').toLowerCase().includes(search.toLowerCase()) ||
        (c.cargo || '').toLowerCase().includes(search.toLowerCase()) ||
        (c.veiculoPlaca || '').toLowerCase().includes(search.toLowerCase()) ||
        (c.veiculoPrefixo || '').toLowerCase().includes(search.toLowerCase());

      const matchStatus = filterStatus === 'todos' || c.status === filterStatus;
      const matchRegional = filterRegional === 'todas' || c.regional === filterRegional;

      return matchSearch && matchStatus && matchRegional;
    });
  }, [todosColaboradores, search, filterStatus, filterRegional]);

  const handleFotoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      if (event.target?.result) {
        setNovaFoto(event.target.result as string);
      }
    };
    reader.readAsDataURL(file);
  };

  const handleCadastrarColaborador = (e: React.FormEvent) => {
    e.preventDefault();
    if (!novoNome.trim()) return;

    const novo: ColaboradorCompleto = {
      id: `colab-custom-${Date.now()}`,
      nome: novoNome.trim(),
      cargo: novoCargo.trim() || 'Operador Florestal',
      matricula: '',
      foto: novaFoto,
      telefone: novoTelefone.trim(),
      status: 'presente',
      equipeId: 'reserva',
      equipeNumero: 1,
      posicaoVeiculo: 'motorista',
      veiculoPrefixo: 'Banco de Reserva',
      veiculoPlaca: '-',
      regional: novaUnidade,
    };

    setColaboradoresAdicionados((prev) => [novo, ...prev]);
    if (onAdicionarColaborador) onAdicionarColaborador(novo);

    setNovoNome('');
    setNovoCargo('');
    setNovoTelefone('');
    setNovaFoto('');
    setModalNovoAberto(false);
  };

  return (
    <div className="space-y-6">
      {/* Top Header */}
      <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
        <div>
          <h2 className="text-xl font-bold tracking-tight text-foreground flex items-center gap-2">
            <Users className="w-5 h-5 text-emerald-400" />
            Quadro Geral de Colaboradores
          </h2>
          <p className="text-xs text-muted-foreground mt-0.5">
            Consulta rápida dos operadores, frentes de trabalho e fotos de identificação
          </p>
        </div>

        <Button
          type="button"
          onClick={() => setModalNovoAberto(true)}
          className="gap-2 bg-emerald-600 hover:bg-emerald-500 text-white rounded-xl shadow-md text-xs font-bold"
        >
          <Plus className="w-4 h-4" />
          Novo Colaborador
        </Button>
      </div>

      {/* Barra de Filtros */}
      <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3 bg-card/60 p-3 rounded-2xl border border-border/60">
        <div className="relative flex-1">
          <Search className="w-4 h-4 text-muted-foreground absolute left-3 top-1/2 -translate-y-1/2" />
          <Input
            placeholder="Buscar por nome, cargo ou veículo..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="pl-9 h-9 text-xs bg-background/50 border-border/60 rounded-xl"
          />
        </div>

        <div className="flex items-center gap-2">
          <select
            value={filterStatus}
            onChange={(e) => setFilterStatus(e.target.value as any)}
            className="h-9 px-3 rounded-xl border border-border/60 bg-background/50 text-xs font-medium text-foreground focus:outline-none focus:ring-2 focus:ring-emerald-500/30"
          >
            <option value="todos">Todos os Status</option>
            <option value="presente">Presente</option>
            <option value="falta">Falta</option>
            <option value="substituto">Substituto</option>
          </select>

          <select
            value={filterRegional}
            onChange={(e) => setFilterRegional(e.target.value as any)}
            className="h-9 px-3 rounded-xl border border-border/60 bg-background/50 text-xs font-medium text-foreground focus:outline-none focus:ring-2 focus:ring-emerald-500/30"
          >
            <option value="todas">Todas as Unidades</option>
            <option value="ribas">Ribas do Rio Pardo</option>
            <option value="agua_clara">Água Clara</option>
          </select>
        </div>
      </div>

      {/* Grid de Cartões de Colaboradores */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
        {colaboradoresFiltrados.length === 0 ? (
          <div className="col-span-full py-12 text-center rounded-2xl border border-dashed border-border/70 bg-card/20">
            <Users className="w-8 h-8 text-muted-foreground mx-auto mb-2 opacity-50" />
            <p className="text-sm font-semibold text-foreground">Nenhum colaborador encontrado</p>
            <p className="text-xs text-muted-foreground mt-1">Ajuste os filtros de busca para encontrar registros.</p>
          </div>
        ) : (
          colaboradoresFiltrados.map((colab) => {
            const cfg = statusConfig[colab.status] || statusConfig.presente;

            return (
              <Card
                key={colab.id}
                className="overflow-hidden border border-border/70 bg-card/60 hover:border-emerald-500/40 transition-all duration-200 rounded-2xl flex flex-col justify-between"
              >
                <div className="p-4 space-y-3">
                  <div className="flex items-start gap-3">
                    {/* Foto do Colaborador */}
                    <div
                      className="relative cursor-pointer shrink-0"
                      onClick={() =>
                        setFotoModalAberta({
                          url: colab.foto,
                          nome: colab.nome,
                          cargo: colab.cargo,
                        })
                      }
                    >
                      <div className="w-12 h-12 rounded-full overflow-hidden border-2 border-emerald-400 ring-2 ring-emerald-500/20 bg-slate-800 flex items-center justify-center">
                        {colab.foto ? (
                          <img
                            src={colab.foto}
                            alt={colab.nome}
                            className="w-full h-full object-cover"
                            onError={(e) => {
                              (e.target as HTMLImageElement).style.display = 'none';
                            }}
                          />
                        ) : (
                          <span className="text-xs font-bold text-foreground">
                            {getIniciais(colab.nome)}
                          </span>
                        )}
                      </div>
                      <div className="absolute inset-0 bg-black/40 opacity-0 hover:opacity-100 transition-opacity rounded-full flex items-center justify-center">
                        <Eye className="w-4 h-4 text-white" />
                      </div>
                    </div>

                    <div className="min-w-0 flex-1">
                      <h4 className="font-bold text-sm text-foreground truncate">{colab.nome}</h4>
                      <p className="text-xs text-muted-foreground truncate">{colab.cargo}</p>
                      <Badge variant="outline" className={cn('text-[10px] mt-1.5 py-0 px-2 font-bold', cfg.className)}>
                        {cfg.label}
                      </Badge>
                    </div>
                  </div>

                  <div className="pt-2 border-t border-border/40 space-y-1 text-xs text-muted-foreground">
                    <div className="flex items-center justify-between">
                      <span>Lotação:</span>
                      <span className="font-semibold text-foreground">{colab.veiculoPrefixo}</span>
                    </div>
                    <div className="flex items-center justify-between">
                      <span>Unidade:</span>
                      <span className="font-semibold text-foreground">
                        {regionalLabel[colab.regional] || 'Ribas'}
                      </span>
                    </div>
                  </div>
                </div>
              </Card>
            );
          })
        )}
      </div>

      {/* Modal de Zoom da Foto */}
      {fotoModalAberta && (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-background/80 backdrop-blur-md animate-in fade-in"
          onClick={() => setFotoModalAberta(null)}
        >
          <div
            className="relative bg-card border border-border rounded-3xl p-6 max-w-sm w-full text-center space-y-4"
            onClick={(e) => e.stopPropagation()}
          >
            <button
              onClick={() => setFotoModalAberta(null)}
              className="absolute top-4 right-4 p-1.5 rounded-lg text-muted-foreground hover:text-foreground hover:bg-muted"
            >
              <X className="w-5 h-5" />
            </button>

            <div className="w-32 h-32 mx-auto rounded-full overflow-hidden border-4 border-emerald-400 ring-4 ring-emerald-500/30 shadow-2xl bg-slate-800 flex items-center justify-center">
              {fotoModalAberta.url ? (
                <img
                  src={fotoModalAberta.url}
                  alt={fotoModalAberta.nome}
                  className="w-full h-full object-cover"
                />
              ) : (
                <span className="text-2xl font-bold text-foreground">
                  {getIniciais(fotoModalAberta.nome)}
                </span>
              )}
            </div>

            <div>
              <h3 className="font-bold text-base text-foreground">{fotoModalAberta.nome}</h3>
              <p className="text-xs text-muted-foreground">{fotoModalAberta.cargo}</p>
            </div>
          </div>
        </div>
      )}

      {/* Modal de Cadastro de Colaborador */}
      {modalNovoAberto && (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-background/80 backdrop-blur-md animate-in fade-in"
          onClick={() => setModalNovoAberto(false)}
        >
          <div
            className="relative bg-card border border-border rounded-3xl p-6 max-w-md w-full shadow-2xl"
            onClick={(e) => e.stopPropagation()}
          >
            <div className="flex items-center justify-between pb-3 border-b border-border">
              <h3 className="font-bold text-base text-foreground flex items-center gap-2">
                <Users className="w-4 h-4 text-emerald-400" />
                Cadastrar Novo Colaborador
              </h3>
              <button
                onClick={() => setModalNovoAberto(false)}
                className="p-1.5 rounded-lg text-muted-foreground hover:text-foreground hover:bg-muted"
              >
                <X className="w-5 h-5" />
              </button>
            </div>

            <form onSubmit={handleCadastrarColaborador} className="space-y-4 mt-4">
              {/* Foto Upload */}
              <div className="flex flex-col items-center gap-2">
                <div
                  onClick={() => fotoInputRef.current?.click()}
                  className="w-20 h-20 rounded-full border-2 border-dashed border-emerald-500/50 hover:border-emerald-400 bg-muted/40 cursor-pointer flex flex-col items-center justify-center overflow-hidden transition-colors"
                >
                  {novaFoto ? (
                    <img src={novaFoto} alt="Prévia" className="w-full h-full object-cover" />
                  ) : (
                    <div className="flex flex-col items-center text-muted-foreground">
                      <Camera className="w-5 h-5 mb-0.5 text-emerald-400" />
                      <span className="text-[10px]">Foto</span>
                    </div>
                  )}
                </div>
                <input
                  type="file"
                  ref={fotoInputRef}
                  onChange={handleFotoUpload}
                  accept="image/*"
                  className="hidden"
                />
              </div>

              <div>
                <label className="text-xs font-semibold text-muted-foreground block mb-1">
                  Nome Completo
                </label>
                <Input
                  required
                  placeholder="Ex: João da Silva"
                  value={novoNome}
                  onChange={(e) => setNovoNome(e.target.value)}
                />
              </div>

              <div>
                <label className="text-xs font-semibold text-muted-foreground block mb-1">
                  Função / Cargo
                </label>
                <Input
                  placeholder="Ex: Operador de Máquinas Florestais"
                  value={novoCargo}
                  onChange={(e) => setNovoCargo(e.target.value)}
                />
              </div>

              <div>
                <label className="text-xs font-semibold text-muted-foreground block mb-1">
                  Unidade Operacional
                </label>
                <div className="grid grid-cols-2 gap-2">
                  <button
                    type="button"
                    onClick={() => setNovaUnidade('ribas')}
                    className={cn(
                      'p-2.5 rounded-xl border text-xs font-bold transition-all',
                      novaUnidade === 'ribas'
                        ? 'bg-emerald-500/20 border-emerald-500 text-emerald-400'
                        : 'border-border text-muted-foreground hover:bg-muted'
                    )}
                  >
                    Ribas do Rio Pardo
                  </button>
                  <button
                    type="button"
                    onClick={() => setNovaUnidade('agua_clara')}
                    className={cn(
                      'p-2.5 rounded-xl border text-xs font-bold transition-all',
                      novaUnidade === 'agua_clara'
                        ? 'bg-teal-500/20 border-teal-500 text-teal-400'
                        : 'border-border text-muted-foreground hover:bg-muted'
                    )}
                  >
                    Água Clara
                  </button>
                </div>
              </div>

              <div className="flex items-center justify-end gap-3 pt-3 border-t border-border">
                <Button type="button" variant="outline" onClick={() => setModalNovoAberto(false)}>
                  Cancelar
                </Button>
                <Button type="submit" className="bg-emerald-600 hover:bg-emerald-500 text-white font-bold">
                  Cadastrar
                </Button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

