import React, { useState, useMemo } from 'react';
import {
  Car,
  Search,
  Filter,
  CheckCircle2,
  XCircle,
  HelpCircle,
  Users,
  Compass,
  MapPin,
  ChevronRight,
  Sparkles,
} from 'lucide-react';
import { Card } from './ui/card';
import { Badge } from './ui/badge';
import { Input } from './ui/input';
import { Button } from './ui/button';
import { Veiculo, Colaborador, StatusPresenca, MotivoFalta, Regional } from '../types';
import { AttendanceModal } from './AttendanceModal';
import { cn } from '@/lib/utils';

export interface VehicleCardGridProps {
  veiculos?: Veiculo[];
  colaboradoresReserva?: Colaborador[];
  selectedRegional?: Regional;
  selectedDate?: Date;
  onUpdateColaboradorStatus?: (
    colaboradorId: string,
    novoStatus: StatusPresenca,
    motivoFalta?: MotivoFalta,
    observacao?: string,
    substitutoId?: string
  ) => void;
  onAdicionarColaborador?: (novoColab: any) => void;
  onNovaEquipeClick?: () => void;
}

const statusBadgeStyles: Record<StatusPresenca, { label: string; dot: string; border: string; bg: string; text: string }> = {
  presente: {
    label: 'Presente',
    dot: 'bg-emerald-400 shadow-[0_0_8px_rgba(52,211,153,0.8)]',
    border: 'border-emerald-500/50 hover:border-emerald-400',
    bg: 'bg-emerald-950/20',
    text: 'text-emerald-300',
  },
  falta: {
    label: 'Falta',
    dot: 'bg-rose-500 shadow-[0_0_8px_rgba(244,63,94,0.8)]',
    border: 'border-rose-500/60 hover:border-rose-400 ring-1 ring-rose-500/30',
    bg: 'bg-rose-950/30',
    text: 'text-rose-300',
  },
  substituto: {
    label: 'Substituto',
    dot: 'bg-amber-400 shadow-[0_0_8px_rgba(251,191,36,0.8)]',
    border: 'border-amber-500/50 hover:border-amber-400',
    bg: 'bg-amber-950/20',
    text: 'text-amber-300',
  },
};

const getIniciais = (nome?: string) => {
  if (!nome) return 'OP';
  const partes = nome.trim().split(' ');
  if (partes.length === 1) return partes[0].substring(0, 2).toUpperCase();
  return (partes[0][0] + partes[partes.length - 1][0]).toUpperCase();
};

export const VehicleCardGrid: React.FC<VehicleCardGridProps> = ({
  veiculos = [],
  colaboradoresReserva = [],
  selectedRegional = 'todas',
  onUpdateColaboradorStatus,
  onAdicionarColaborador,
  onNovaEquipeClick,
}) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [filtroStatus, setFiltroStatus] = useState<'todos' | 'presente' | 'falta' | 'substituto'>('todos');
  const [modalAberto, setModalAberto] = useState(false);
  const [colaboradorSelecionado, setColaboradorSelecionado] = useState<Colaborador | null>(null);
  const [veiculoDoColaborador, setVeiculoDoColaborador] = useState<Veiculo | null>(null);

  const veiculosFiltrados = useMemo(() => {
    return (veiculos || []).filter((veiculo) => {
      if (!veiculo) return false;
      const matchRegional =
        selectedRegional === 'todas' || veiculo.regional === selectedRegional;

      const assentos = [
        veiculo.assentos?.motorista,
        veiculo.assentos?.frenteDir,
        veiculo.assentos?.trasEsq,
        veiculo.assentos?.trasDir,
      ].filter(Boolean) as Colaborador[];

      const matchSearch =
        !searchTerm ||
        (veiculo.prefixo || '').toLowerCase().includes(searchTerm.toLowerCase()) ||
        (veiculo.placa || '').toLowerCase().includes(searchTerm.toLowerCase()) ||
        (veiculo.modelo || '').toLowerCase().includes(searchTerm.toLowerCase()) ||
        (veiculo.equipe1Codigo || '').toLowerCase().includes(searchTerm.toLowerCase()) ||
        (veiculo.equipe2Codigo || '').toLowerCase().includes(searchTerm.toLowerCase()) ||
        assentos.some(
          (c) =>
            (c.nome || '').toLowerCase().includes(searchTerm.toLowerCase()) ||
            (c.cargo || '').toLowerCase().includes(searchTerm.toLowerCase())
        );

      const matchStatus =
        filtroStatus === 'todos' ||
        assentos.some((c) => c.status === filtroStatus);

      return matchRegional && matchSearch && matchStatus;
    });
  }, [veiculos, selectedRegional, searchTerm, filtroStatus]);

  const handleOpenAttendance = (colab: Colaborador, veiculo: Veiculo) => {
    setColaboradorSelecionado(colab);
    setVeiculoDoColaborador(veiculo);
    setModalAberto(true);
  };

  const handleSaveAttendance = (
    colaboradorId: string,
    novoStatus: StatusPresenca,
    motivoFalta?: MotivoFalta,
    observacao?: string,
    substitutoId?: string
  ) => {
    if (onUpdateColaboradorStatus) {
      onUpdateColaboradorStatus(
        colaboradorId,
        novoStatus,
        motivoFalta,
        observacao,
        substitutoId
      );
    }
    setModalAberto(false);
  };

  const renderAssentoTopView = (colab: Colaborador | undefined, veiculo: Veiculo) => {
    if (!colab) {
      return (
        <div className="flex flex-col items-center justify-center p-3 rounded-2xl border border-dashed border-border/40 bg-background/30 min-h-[148px]">
          <div className="w-16 h-16 rounded-full border border-dashed border-border/50 flex items-center justify-center text-muted-foreground/40 mb-2">
            <Users className="w-6 h-6" />
          </div>
          <span className="text-[11px] font-medium text-muted-foreground/60">Vago</span>
        </div>
      );
    }

    const cfg = statusBadgeStyles[colab.status] || statusBadgeStyles.presente;

    return (
      <div
        role="button"
        tabIndex={0}
        onClick={() => handleOpenAttendance(colab, veiculo)}
        onKeyDown={(e) => {
          if (e.key === 'Enter' || e.key === ' ') {
            e.preventDefault();
            handleOpenAttendance(colab, veiculo);
          }
        }}
        className={cn(
          'group relative flex flex-col items-center justify-between p-3 rounded-2xl border transition-all duration-200 cursor-pointer select-none text-center',
          'bg-card/90 hover:bg-card hover:scale-[1.02] shadow-sm hover:shadow-md min-h-[160px]',
          cfg.border
        )}
      >
        {/* Status Dot Superior Direito */}
        <div className="absolute top-2.5 right-2.5 flex items-center gap-1.5 z-10">
          <span className={cn('w-2.5 h-2.5 rounded-full ring-2 ring-background', cfg.dot)} />
        </div>

        {/* Foto do Colaborador (em destaque centralizada) */}
        <div className="relative mt-1 mb-2">
          <div className={cn(
            'w-16 h-16 sm:w-20 sm:h-20 rounded-full overflow-hidden border-2 bg-muted/60 flex items-center justify-center shadow-md transition-transform duration-200 group-hover:scale-105',
            colab.status === 'falta' ? 'border-rose-500/80 ring-2 ring-rose-500/20' : 
            colab.status === 'substituto' ? 'border-amber-500/80 ring-2 ring-amber-500/20' : 
            'border-emerald-500/80 ring-2 ring-emerald-500/20'
          )}>
            {colab.foto ? (
              <img
                src={colab.foto}
                alt={colab.nome}
                className="w-full h-full object-cover"
                onError={(e) => {
                  (e.target as HTMLImageElement).style.display = 'none';
                }}
              />
            ) : (
              <span className="text-base font-extrabold text-foreground/80 tracking-wider">
                {getIniciais(colab.nome)}
              </span>
            )}
          </div>

          {/* Microbadge com ícone de status acoplado à foto */}
          <div className="absolute -bottom-1 -right-1 rounded-full bg-background p-0.5 shadow-sm border border-border/60">
            {colab.status === 'presente' && (
              <CheckCircle2 className="w-4 h-4 text-emerald-400 fill-emerald-500/20" />
            )}
            {colab.status === 'falta' && (
              <XCircle className="w-4 h-4 text-rose-400 fill-rose-500/20" />
            )}
            {colab.status === 'substituto' && (
              <HelpCircle className="w-4 h-4 text-amber-400 fill-amber-500/20" />
            )}
          </div>
        </div>

        {/* Nome do Colaborador abaixo da foto */}
        <div className="w-full px-1">
          <p
            className="text-xs sm:text-sm font-bold text-foreground truncate group-hover:text-emerald-400 transition-colors"
            title={colab.nome}
          >
            {colab.nome}
          </p>
          <p className="text-[11px] text-muted-foreground truncate mt-0.5">
            {colab.cargo || 'Operador'}
          </p>
        </div>

        {/* Pílula de Status / Ação */}
        <div className="mt-2 w-full pt-1.5 border-t border-border/40 flex items-center justify-between text-[11px]">
          <span className={cn('font-semibold capitalize truncate', cfg.text)}>
            {cfg.label}
          </span>
          <span className="text-[10px] text-muted-foreground group-hover:text-foreground flex items-center transition-colors">
            Alterar
            <ChevronRight className="w-3 h-3 ml-0.5" />
          </span>
        </div>
      </div>
    );
  };

  return (
    <div className="space-y-6">
      {/* Barra de Filtros e Busca */}
      <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3 bg-card/60 p-3 sm:p-4 rounded-2xl border border-border/60 backdrop-blur-md shadow-sm">
        <div className="relative flex-1">
          <Search className="w-4 h-4 text-muted-foreground absolute left-3 top-1/2 -translate-y-1/2" />
          <Input
            placeholder="Buscar por placa, prefixo, equipe ou nome do colaborador..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="pl-9 h-10 text-xs sm:text-sm bg-background/50 border-border/60 rounded-xl"
          />
        </div>

        <div className="flex items-center gap-2 flex-wrap">
          <div className="flex items-center gap-1 bg-background/60 p-1 rounded-xl border border-border/60 text-xs">
            <Filter className="w-3.5 h-3.5 text-muted-foreground ml-2 mr-1" />
            {(['todos', 'presente', 'falta', 'substituto'] as const).map((st) => (
              <button
                key={st}
                type="button"
                onClick={() => setFiltroStatus(st)}
                className={cn(
                  'px-2.5 py-1 rounded-lg font-medium capitalize transition-all text-xs cursor-pointer',
                  filtroStatus === st
                    ? 'bg-emerald-600 text-white font-semibold shadow-sm'
                    : 'text-muted-foreground hover:text-foreground hover:bg-muted/50'
                )}
              >
                {st}
              </button>
            ))}
          </div>
        </div>
      </div>

      {/* Grid de Veículos */}
      {veiculosFiltrados.length === 0 ? (
        <div className="py-16 text-center rounded-3xl border border-dashed border-border/70 bg-card/20 p-8 space-y-3">
          <Car className="w-12 h-12 text-muted-foreground mx-auto opacity-40" />
          <h3 className="text-base font-bold text-foreground">Nenhum veículo encontrado</h3>
          <p className="text-xs text-muted-foreground max-w-sm mx-auto">
            Não foram localizados veículos para os critérios de busca selecionados. Tente alterar os filtros.
          </p>
        </div>
      ) : (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          {veiculosFiltrados.map((veiculo) => {
            const assentos = [
              veiculo.assentos?.motorista,
              veiculo.assentos?.frenteDir,
              veiculo.assentos?.trasEsq,
              veiculo.assentos?.trasDir,
            ].filter(Boolean) as Colaborador[];

            const faltasCount = assentos.filter((c) => c.status === 'falta').length;
            const substitutosCount = assentos.filter((c) => c.status === 'substituto').length;
            const presentesCount = assentos.filter((c) => c.status === 'presente').length;

            return (
              <Card
                key={veiculo.id}
                className="overflow-hidden rounded-3xl border border-border/70 bg-card/40 backdrop-blur-md shadow-lg hover:shadow-xl transition-all"
              >
                {/* Header do Cartão de Veículo */}
                <div className="p-4 sm:p-5 border-b border-border/50 bg-gradient-to-r from-muted/30 via-background/40 to-muted/20 flex flex-wrap items-center justify-between gap-3">
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 rounded-2xl bg-emerald-500/10 border border-emerald-500/25 flex items-center justify-center text-emerald-400 shrink-0 shadow-sm">
                      <Car className="w-5 h-5" />
                    </div>
                    <div>
                      <div className="flex items-center gap-2">
                        <span className="font-extrabold text-base text-foreground tracking-tight">
                          {veiculo.prefixo}
                        </span>
                        <span className="px-2 py-0.5 rounded-md bg-muted text-[11px] font-mono font-bold text-muted-foreground border border-border/60">
                          {veiculo.placa}
                        </span>
                      </div>
                      <p className="text-xs text-muted-foreground flex items-center gap-1.5 mt-0.5">
                        <span>{veiculo.modelo}</span>
                        <span>•</span>
                        <MapPin className="w-3 h-3 text-muted-foreground" />
                        <span>{veiculo.regional === 'ribas' ? 'Ribas do Rio Pardo' : 'Água Clara'}</span>
                      </p>
                    </div>
                  </div>

                  <div className="flex items-center gap-1.5 flex-wrap">
                    {faltasCount > 0 ? (
                      <Badge variant="destructive" className="text-[11px] gap-1 font-bold">
                        <XCircle className="w-3 h-3" />
                        {faltasCount} {faltasCount === 1 ? 'Falta' : 'Faltas'}
                      </Badge>
                    ) : (
                      <Badge className="bg-emerald-500/20 text-emerald-300 border-emerald-500/30 text-[11px] gap-1 font-bold">
                        <CheckCircle2 className="w-3 h-3" />
                        Completo ({presentesCount + substitutosCount}/4)
                      </Badge>
                    )}

                    {substitutosCount > 0 && (
                      <Badge className="bg-amber-500/20 text-amber-300 border-amber-500/30 text-[11px] font-bold">
                        {substitutosCount} Subst.
                      </Badge>
                    )}
                  </div>
                </div>

                {/* Área da Cabine do Carro com visão superior dos 4 assentos */}
                <div className="p-4 sm:p-5">
                  <div className="relative rounded-2xl border border-border/70 bg-gradient-to-b from-background/90 via-background/60 to-background/90 p-4 shadow-inner">
                    {/* Linha Divisória de Cabine (Sutil) */}
                    <div className="absolute inset-x-8 top-1/2 -translate-y-1/2 h-[1px] bg-border/40 pointer-events-none" />

                    {/* Fileira da Frente: Motorista & Dianteiro Direito */}
                    <div className="grid grid-cols-2 gap-3 sm:gap-4 mb-3">
                      <div>
                        {renderAssentoTopView(veiculo.assentos?.motorista, veiculo)}
                      </div>
                      <div>
                        {renderAssentoTopView(veiculo.assentos?.frenteDir, veiculo)}
                      </div>
                    </div>

                    {/* Fileira Traseira: Traseiro Esquerdo & Traseiro Direito */}
                    <div className="grid grid-cols-2 gap-3 sm:gap-4">
                      <div>
                        {renderAssentoTopView(veiculo.assentos?.trasEsq, veiculo)}
                      </div>
                      <div>
                        {renderAssentoTopView(veiculo.assentos?.trasDir, veiculo)}
                      </div>
                    </div>
                  </div>

                  {/* Rodapé com identificação das duas equipes do veículo */}
                  <div className="mt-3 pt-3 border-t border-border/40 flex items-center justify-between text-xs text-muted-foreground px-1">
                    <div className="flex items-center gap-1.5 truncate">
                      <span className="font-semibold text-foreground/80">EQ 1:</span>
                      <span className="truncate">{veiculo.equipe1Codigo || 'Frente'}</span>
                    </div>
                    <div className="flex items-center gap-1.5 truncate">
                      <span className="font-semibold text-foreground/80">EQ 2:</span>
                      <span className="truncate">{veiculo.equipe2Codigo || 'Traseira'}</span>
                    </div>
                  </div>
                </div>
              </Card>
            );
          })}
        </div>
      )}

      {/* Modal de Presença / Falta */}
      {colaboradorSelecionado && veiculoDoColaborador && (
        <AttendanceModal
          isOpen={modalAberto}
          onClose={() => setModalAberto(false)}
          colaborador={colaboradorSelecionado}
          veiculo={veiculoDoColaborador}
          colaboradoresReserva={colaboradoresReserva}
          onSave={handleSaveAttendance}
        />
      )}
    </div>
  );
};

files.oldContent:
import React, { useState, useEffect } from 'react';
import {
  X,
  CheckCircle2,
  XCircle,
  HelpCircle,
  AlertTriangle,
  UserCheck,
  FileText,
  User,
  ShieldAlert,
  Car,
  MapPin,
} from 'lucide-react';
import { Colaborador, Veiculo, StatusPresenca, MotivoFalta } from '../types';
import { Button } from './ui/button';
import { Badge } from './ui/badge';
import { cn } from '@/lib/utils';

export interface AttendanceModalProps {
  isOpen: boolean;
  onClose: () => void;
  colaborador?: Colaborador | null;
  veiculo?: Veiculo | null;
  colaboradoresReserva?: Colaborador[];
  onSalvarStatus?: (
    colabId: string,
    novoStatus: StatusPresenca,
    motivo?: MotivoFalta,
    obs?: string,
    substitutoId?: string,
    substitutoNome?: string
  ) => void;
}

const MOTIVOS_FALTA: MotivoFalta[] = [
  'Atestado Médico',
  'Falta Injustificada',
  'Folga Compensatória',
  'Treinamento / Integração',
  'Problema de Transporte',
  'Licença Especial',
];

const getIniciais = (nome?: string) => {
  if (!nome) return 'CO';
  const partes = nome.trim().split(' ');
  if (partes.length === 1) return partes[0].substring(0, 2).toUpperCase();
  return (partes[0][0] + partes[partes.length - 1][0]).toUpperCase();
};

export const AttendanceModal: React.FC<AttendanceModalProps> = ({
  isOpen,
  onClose,
  colaborador,
  veiculo,
  colaboradoresReserva = [],
  onSalvarStatus,
}) => {
  const [status, setStatus] = useState<StatusPresenca>('presente');
  const [motivoFalta, setMotivoFalta] = useState<MotivoFalta | undefined>(undefined);
  const [observacao, setObservacao] = useState('');
  const [substitutoId, setSubstitutoId] = useState('');
  const [substitutoNome, setSubstitutoNome] = useState('');

  // Sincroniza o estado interno sempre que o colaborador selecionado mudar
  useEffect(() => {
    if (colaborador) {
      setStatus(colaborador.status || 'presente');
      setMotivoFalta(colaborador.motivoFalta);
      setObservacao(colaborador.observacao || '');
      setSubstitutoId(colaborador.substitutoId || '');
      setSubstitutoNome(colaborador.substitutoNome || '');
    }
  }, [colaborador]);

  if (!isOpen || !colaborador) return null;

  const handleSubstitutoSelect = (id: string) => {
    setSubstitutoId(id);
    const sub = (colaboradoresReserva || []).find((c) => c?.id === id);
    if (sub) {
      setSubstitutoNome(sub.nome);
    } else {
      setSubstitutoNome('');
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (onSalvarStatus && colaborador?.id) {
      onSalvarStatus(
        colaborador.id,
        status,
        status === 'falta' ? motivoFalta : undefined,
        observacao,
        status === 'substituto' ? substitutoId : undefined,
        status === 'substituto' ? substitutoNome : undefined
      );
    }
    onClose();
  };

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-background/80 backdrop-blur-md animate-in fade-in duration-200"
      onClick={onClose}
    >
      <div
        className="relative w-full max-w-lg bg-card border-2 border-border/80 rounded-3xl shadow-2xl overflow-hidden"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Cabeçalho do Modal */}
        <div className="flex items-center justify-between px-6 py-4 border-b border-border/80 bg-gradient-to-r from-muted/50 to-card">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-2xl bg-emerald-500/15 border border-emerald-500/30 text-emerald-400 flex items-center justify-center shadow-inner">
              <UserCheck className="w-5 h-5" />
            </div>
            <div>
              <h2 className="text-base sm:text-lg font-bold text-foreground">
                Apontamento de Presença
              </h2>
              <p className="text-xs text-muted-foreground">
                Atualize a frequência e motivos operacionais
              </p>
            </div>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="p-2 rounded-xl text-muted-foreground hover:text-foreground hover:bg-muted/80 transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Informações em Destaque do Colaborador (sem matrícula) */}
        <div className="p-6 space-y-5">
          <div className="flex items-center gap-4 p-4 rounded-2xl bg-muted/30 border border-border/80">
            {/* Foto de alta visibilidade */}
            <div className="relative shrink-0">
              <div className="w-16 h-16 rounded-full overflow-hidden border-2 border-emerald-400 ring-2 ring-emerald-500/30 shadow-md bg-slate-800 flex items-center justify-center">
                {colaborador.foto ? (
                  <img
                    src={colaborador.foto}
                    alt={colaborador.nome}
                    className="w-full h-full object-cover"
                    onError={(e) => {
                      (e.target as HTMLImageElement).style.display = 'none';
                    }}
                  />
                ) : (
                  <span className="font-extrabold text-foreground text-sm">
                    {getIniciais(colaborador.nome)}
                  </span>
                )}
              </div>
            </div>

            <div className="flex-1 min-w-0">
              <h3 className="text-base font-extrabold text-foreground truncate">
                {colaborador.nome}
              </h3>
              <p className="text-xs text-muted-foreground font-medium mt-0.5">
                {colaborador.cargo || 'Operador Florestal'}
              </p>

              {veiculo && (
                <div className="flex items-center gap-2 mt-2 text-[11px] text-muted-foreground font-medium">
                  <span className="flex items-center gap-1 text-emerald-400">
                    <Car className="w-3.5 h-3.5" />
                    {veiculo.prefixo}
                  </span>
                  <span>•</span>
                  <span>{veiculo.placa}</span>
                  <span>•</span>
                  <span>{veiculo.regional === 'ribas' ? 'Ribas' : 'Água Clara'}</span>
                </div>
              )}
            </div>
          </div>

          <form onSubmit={handleSubmit} className="space-y-5">
            {/* Seletor Visual de Status */}
            <div>
              <label className="text-xs font-bold uppercase tracking-wider text-muted-foreground block mb-2">
                Status de Hoje
              </label>
              <div className="grid grid-cols-3 gap-2.5">
                <button
                  type="button"
                  onClick={() => setStatus('presente')}
                  className={cn(
                    'flex flex-col items-center justify-center p-3 rounded-2xl border-2 transition-all font-bold text-xs gap-1.5',
                    status === 'presente'
                      ? 'bg-emerald-500/20 border-emerald-500 text-emerald-400 shadow-md ring-2 ring-emerald-500/30'
                      : 'border-border/80 text-muted-foreground hover:bg-muted/40'
                  )}
                >
                  <CheckCircle2 className="w-5 h-5 text-emerald-400" />
                  Presente
                </button>

                <button
                  type="button"
                  onClick={() => setStatus('falta')}
                  className={cn(
                    'flex flex-col items-center justify-center p-3 rounded-2xl border-2 transition-all font-bold text-xs gap-1.5',
                    status === 'falta'
                      ? 'bg-rose-500/20 border-rose-500 text-rose-400 shadow-md ring-2 ring-rose-500/30'
                      : 'border-border/80 text-muted-foreground hover:bg-muted/40'
                  )}
                >
                  <XCircle className="w-5 h-5 text-rose-400" />
                  Falta
                </button>

                <button
                  type="button"
                  onClick={() => setStatus('substituto')}
                  className={cn(
                    'flex flex-col items-center justify-center p-3 rounded-2xl border-2 transition-all font-bold text-xs gap-1.5',
                    status === 'substituto'
                      ? 'bg-amber-500/20 border-amber-500 text-amber-400 shadow-md ring-2 ring-amber-500/30'
                      : 'border-border/80 text-muted-foreground hover:bg-muted/40'
                  )}
                >
                  <HelpCircle className="w-5 h-5 text-amber-400" />
                  Substituto
                </button>
              </div>
            </div>

            {/* Campos Condicionais para Falta */}
            {status === 'falta' && (
              <div className="space-y-2 p-3.5 rounded-2xl border border-rose-500/30 bg-rose-950/20 animate-in fade-in duration-150">
                <label className="text-xs font-bold text-rose-300 flex items-center gap-1.5">
                  <ShieldAlert className="w-4 h-4 text-rose-400" />
                  Motivo da Falta (Obrigatório)
                </label>
                <select
                  value={motivoFalta || ''}
                  onChange={(e) => setMotivoFalta(e.target.value as MotivoFalta)}
                  className="w-full h-10 px-3 rounded-xl border border-rose-500/40 bg-card text-xs font-semibold text-foreground focus:outline-none focus:ring-2 focus:ring-rose-500/40"
                  required
                >
                  <option value="">Selecione o motivo da ausência...</option>
                  {MOTIVOS_FALTA.map((motivo) => (
                    <option key={motivo} value={motivo}>
                      {motivo}
                    </option>
                  ))}
                </select>
              </div>
            )}

            {/* Campos Condicionais para Substituto */}
            {status === 'substituto' && (
              <div className="space-y-3 p-3.5 rounded-2xl border border-amber-500/30 bg-amber-950/20 animate-in fade-in duration-150">
                <label className="text-xs font-bold text-amber-300 flex items-center gap-1.5">
                  <User className="w-4 h-4 text-amber-400" />
                  Selecionar Substituto (Banco de Reserva)
                </label>

                {colaboradoresReserva.length > 0 ? (
                  <select
                    value={substitutoId}
                    onChange={(e) => handleSubstitutoSelect(e.target.value)}
                    className="w-full h-10 px-3 rounded-xl border border-amber-500/40 bg-card text-xs font-semibold text-foreground focus:outline-none focus:ring-2 focus:ring-amber-500/40"
                  >
                    <option value="">Escolher do Banco de Reserva...</option>
                    {colaboradoresReserva.map((res) => (
                      <option key={res.id} value={res.id}>
                        {res.nome} - {res.cargo}
                      </option>
                    ))}
                  </select>
                ) : (
                  <div className="text-xs text-amber-300/80 italic">
                    Nenhum colaborador reserva cadastrado. Digite o nome abaixo:
                  </div>
                )}

                <input
                  type="text"
                  placeholder="Ou digite o nome do substituto..."
                  value={substitutoNome}
                  onChange={(e) => setSubstitutoNome(e.target.value)}
                  className="w-full h-10 px-3 rounded-xl border border-amber-500/40 bg-card text-xs font-semibold text-foreground focus:outline-none focus:ring-2 focus:ring-amber-500/40"
                />
              </div>
            )}

            {/* Observações Operacionais */}
            <div>
              <label className="text-xs font-bold uppercase tracking-wider text-muted-foreground block mb-1.5 flex items-center gap-1.5">
                <FileText className="w-3.5 h-3.5 text-muted-foreground" />
                Observações Operacionais
              </label>
              <textarea
                rows={2}
                placeholder="Detalhes adicionais, horário de contato ou alinhamento..."
                value={observacao}
                onChange={(e) => setObservacao(e.target.value)}
                className="w-full p-3 rounded-xl border border-border/80 bg-background/50 text-xs text-foreground focus:outline-none focus:ring-2 focus:ring-emerald-500/30 resize-none"
              />
            </div>

            {/* Botões de Ação */}
            <div className="flex items-center justify-end gap-3 pt-3 border-t border-border/80">
              <Button type="button" variant="outline" onClick={onClose} className="rounded-xl text-xs">
                Cancelar
              </Button>
              <Button
                type="submit"
                className="gap-2 rounded-xl text-xs font-bold bg-emerald-600 hover:bg-emerald-500 text-white shadow-md"
              >
                <CheckCircle2 className="w-4 h-4" />
                Confirmar Apontamento
              </Button>
            </div>
          </form>
        </div>
      </div>
    </div>
  );
};

