import React, { useState, useEffect } from 'react';
import {
  X,
  CheckCircle2,
  XCircle,
  HelpCircle,
  UserCheck,
  Calendar,
  AlertCircle,
  UserX,
  Camera,
} from 'lucide-react';
import { Button } from './ui/button';
import { Badge } from './ui/badge';
import { Colaborador, StatusPresenca, MotivoFalta } from '../types';
import { cn } from '@/lib/utils';

export interface AttendanceModalProps {
  isOpen: boolean;
  onClose: () => void;
  colaborador?: Colaborador | null;
  colaboradoresReserva?: Colaborador[];
  onSave?: (
    colaboradorId: string,
    status: StatusPresenca,
    motivo?: MotivoFalta,
    observacao?: string,
    substitutoId?: string,
    substitutoNome?: string
  ) => void;
}

const MOTIVOS_FALTA: MotivoFalta[] = [
  'Atestado Médico',
  'Falta Injustificada',
  'Folga Compensatória',
  'Treinamento / Integração',
  'Problema de Transporte',
  'Licença Especial',
];

const getIniciais = (nome?: string) => {
  if (!nome) return 'OP';
  const partes = nome.trim().split(' ').filter(Boolean);
  if (partes.length === 1) return partes[0].substring(0, 2).toUpperCase();
  return (partes[0][0] + partes[partes.length - 1][0]).toUpperCase();
};

export const AttendanceModal: React.FC<AttendanceModalProps> = ({
  isOpen,
  onClose,
  colaborador,
  colaboradoresReserva = [],
  onSave,
}) => {
  const [status, setStatus] = useState<StatusPresenca>(colaborador?.status ?? 'presente');
  const [motivo, setMotivo] = useState<MotivoFalta | undefined>(colaborador?.motivoFalta);
  const [observacao, setObservacao] = useState<string>(colaborador?.observacao ?? '');
  const [substitutoId, setSubstitutoId] = useState<string>(colaborador?.substitutoId ?? '');
  const [substitutoNome, setSubstitutoNome] = useState<string>(colaborador?.substitutoNome ?? '');

  useEffect(() => {
    if (colaborador) {
      setStatus(colaborador.status ?? 'presente');
      setMotivo(colaborador.motivoFalta);
      setObservacao(colaborador.observacao ?? '');
      setSubstitutoId(colaborador.substitutoId ?? '');
      setSubstitutoNome(colaborador.substitutoNome ?? '');
    }
  }, [colaborador]);

  if (!isOpen || !colaborador) return null;

  const handleSubstitutoSelect = (id: string) => {
    setSubstitutoId(id);
    const sub = colaboradoresReserva.find((c) => c.id === id);
    setSubstitutoNome(sub ? sub.nome : '');
  };

  const handleSalvar = (e: React.FormEvent) => {
    e.preventDefault();
    if (onSave) {
      onSave(
        colaborador.id,
        status,
        status === 'falta' ? motivo : undefined,
        observacao,
        status === 'substituto' ? substitutoId : undefined,
        status === 'substituto' ? substitutoNome : undefined
      );
    }
    onClose();
  };

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-background/80 backdrop-blur-md animate-in fade-in duration-150"
      onClick={onClose}
    >
      <div
        className="relative w-full max-w-lg bg-card border border-border/80 rounded-3xl shadow-2xl overflow-hidden"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Header do Modal */}
        <div className="flex items-center justify-between px-6 py-5 border-b border-border/60">
          <div className="flex items-center gap-2.5">
            <div className="w-9 h-9 rounded-xl bg-emerald-500/10 text-emerald-400 border border-emerald-500/25 flex items-center justify-center">
              <UserCheck className="w-5 h-5" />
            </div>
            <div>
              <h2 className="text-base font-bold text-foreground">Registro de Frequência</h2>
              <p className="text-xs text-muted-foreground">Atualize o status operacional do colaborador</p>
            </div>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="p-1.5 rounded-xl text-muted-foreground hover:text-foreground hover:bg-muted transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Card do Colaborador com Foto Ampliada */}
        <div className="p-6 space-y-5">
          <div className="flex items-center gap-4 p-4 rounded-2xl bg-muted/30 border border-border/60">
            {/* Foto Ampliada */}
            <div className="w-20 h-20 sm:w-24 sm:h-24 rounded-2xl overflow-hidden border-2 border-emerald-500/40 ring-4 ring-emerald-500/15 shrink-0 bg-muted flex items-center justify-center shadow-md">
              {colaborador.foto ? (
                <img
                  src={colaborador.foto}
                  alt={colaborador.nome}
                  className="w-full h-full object-cover"
                  onError={(e) => {
                    (e.target as HTMLElement).style.display = 'none';
                  }}
                />
              ) : (
                <span className="font-black text-xl text-foreground">
                  {getIniciais(colaborador.nome)}
                </span>
              )}
            </div>

            {/* Dados do Colaborador */}
            <div className="min-w-0 flex-1">
              <h3 className="font-extrabold text-base text-foreground truncate">
                {colaborador.nome}
              </h3>
              <p className="text-xs text-muted-foreground mt-0.5">
                {colaborador.cargo || 'Operador de Campo'}
              </p>
              {colaborador.telefone && (
                <p className="text-[11px] text-muted-foreground/80 mt-1 font-mono">
                  {colaborador.telefone}
                </p>
              )}
            </div>
          </div>

          <form onSubmit={handleSalvar} className="space-y-4">
            {/* Opções de Status (Presente, Falta, Substituto) */}
            <div>
              <label className="text-xs font-bold text-foreground uppercase tracking-wider block mb-2">
                Status Operacional
              </label>
              <div className="grid grid-cols-3 gap-2.5">
                <button
                  type="button"
                  onClick={() => setStatus('presente')}
                  className={cn(
                    'flex flex-col items-center justify-center gap-1.5 p-3 rounded-2xl border text-xs font-bold transition-all',
                    status === 'presente'
                      ? 'bg-emerald-500/20 border-emerald-500 text-emerald-300 ring-2 ring-emerald-500/30'
                      : 'border-border/70 hover:bg-muted text-muted-foreground'
                  )}
                >
                  <CheckCircle2 className="w-5 h-5 text-emerald-400" />
                  Presente
                </button>

                <button
                  type="button"
                  onClick={() => setStatus('falta')}
                  className={cn(
                    'flex flex-col items-center justify-center gap-1.5 p-3 rounded-2xl border text-xs font-bold transition-all',
                    status === 'falta'
                      ? 'bg-rose-500/20 border-rose-500 text-rose-300 ring-2 ring-rose-500/30'
                      : 'border-border/70 hover:bg-muted text-muted-foreground'
                  )}
                >
                  <XCircle className="w-5 h-5 text-rose-400" />
                  Falta
                </button>

                <button
                  type="button"
                  onClick={() => setStatus('substituto')}
                  className={cn(
                    'flex flex-col items-center justify-center gap-1.5 p-3 rounded-2xl border text-xs font-bold transition-all',
                    status === 'substituto'
                      ? 'bg-amber-500/20 border-amber-500 text-amber-300 ring-2 ring-amber-500/30'
                      : 'border-border/70 hover:bg-muted text-muted-foreground'
                  )}
                >
                  <HelpCircle className="w-5 h-5 text-amber-400" />
                  Substituto
                </button>
              </div>
            </div>

            {/* Campo de Motivo quando Falta */}
            {status === 'falta' && (
