import React, { useState, useMemo } from 'react';
import {
  Car,
  Search,
  Filter,
  CheckCircle2,
  XCircle,
  HelpCircle,
  Users,
  Compass,
  MapPin,
  ArrowRightLeft,
  ChevronDown,
  ChevronUp,
  FileSpreadsheet,
} from 'lucide-react';
import { Card, CardHeader, CardTitle, CardContent } from './ui/card';
import { Badge } from './ui/badge';
import { Button } from './ui/button';
import { Input } from './ui/input';
import { Veiculo, Colaborador, StatusPresenca, MotivoFalta, Regional } from '../types';
import { AttendanceModal } from './AttendanceModal';
import { cn } from '@/lib/utils';

export interface VehicleCardGridProps {
  veiculos?: Veiculo[];
  colaboradoresReserva?: Colaborador[];
  selectedRegional?: Regional;
  onUpdateColaboradorStatus?: (
    colabId: string,
    novoStatus: StatusPresenca,
    motivo?: MotivoFalta,
    obs?: string,
    substitutoId?: string,
    substitutoNome?: string
  ) => void;
  onUpdateAssentoStatus?: (
    veiculoId: string,
    posicao: 'motorista' | 'frenteDir' | 'trasEsq' | 'trasDir',
    novoStatus: StatusPresenca,
    motivo?: MotivoFalta,
    observacao?: string,
    substituto?: { id: string; nome: string }
  ) => void;
  onNovaEquipeClick?: () => void;
}

const getIniciais = (nome?: string) => {
  if (!nome) return 'CO';
  const partes = nome.trim().split(' ');
  if (partes.length === 1) return partes[0].substring(0, 2).toUpperCase();
  return (partes[0][0] + (partes[partes.length - 1]?.[0] || '')).toUpperCase();
};

export const VehicleCardGrid: React.FC<VehicleCardGridProps> = ({
  veiculos = [],
  colaboradoresReserva = [],
  selectedRegional = 'todas',
  onUpdateColaboradorStatus,
  onUpdateAssentoStatus,
  onNovaEquipeClick,
}) => {
  const [busca, setBusca] = useState('');
  const [filtroStatus, setFiltroStatus] = useState<'todos' | 'completos' | 'incompletos'>('todos');
  const [modalAberto, setModalAberto] = useState(false);
  const [colaboradorAtivo, setColaboradorAtivo] = useState<Colaborador | null>(null);
  const [veiculoAtivo, setVeiculoAtivo] = useState<Veiculo | null>(null);

  const veiculosFiltrados = useMemo(() => {
    return (veiculos || []).filter((v) => {
      if (!v) return false;
      const matchRegional = selectedRegional === 'todas' || v.regional === selectedRegional;

      const termo = busca.toLowerCase();
      const assentosLista = [
        v.assentos?.motorista?.nome,
        v.assentos?.frenteDir?.nome,
        v.assentos?.trasEsq?.nome,
        v.assentos?.trasDir?.nome,
      ]
        .filter(Boolean)
        .map((n) => n!.toLowerCase());

      const matchBusca =
        !busca ||
        (v.prefixo || '').toLowerCase().includes(termo) ||
        (v.placa || '').toLowerCase().includes(termo) ||
        (v.modelo || '').toLowerCase().includes(termo) ||
        assentosLista.some((nome) => nome.includes(termo));

      if (!matchRegional || !matchBusca) return false;

      const todosAssentos = [
        v.assentos?.motorista,
        v.assentos?.frenteDir,
        v.assentos?.trasEsq,
        v.assentos?.trasDir,
      ].filter(Boolean);

      const temFalta = todosAssentos.some((c) => c?.status === 'falta');

      if (filtroStatus === 'completos') return !temFalta;
      if (filtroStatus === 'incompletos') return temFalta;

      return true;
    });
  }, [veiculos, selectedRegional, busca, filtroStatus]);

  const handleAbrirPresenca = (colab: Colaborador | undefined, v: Veiculo) => {
    if (!colab) return;
    setColaboradorAtivo(colab);
    setVeiculoAtivo(v);
    setModalAberto(true);
  };

  const handleSalvarPresenca = (
    colabId: string,
    novoStatus: StatusPresenca,
    motivo?: MotivoFalta,
    obs?: string,
    substitutoId?: string,
    substitutoNome?: string
  ) => {
    if (onUpdateColaboradorStatus) {
      onUpdateColaboradorStatus(colabId, novoStatus, motivo, obs, substitutoId, substitutoNome);
    }
    if (onUpdateAssentoStatus && veiculoAtivo && colaboradorAtivo) {
      let posicaoAssento: 'motorista' | 'frenteDir' | 'trasEsq' | 'trasDir' = 'motorista';
      if (veiculoAtivo.assentos?.motorista?.id === colabId) posicaoAssento = 'motorista';
      else if (veiculoAtivo.assentos?.frenteDir?.id === colabId) posicaoAssento = 'frenteDir';
      else if (veiculoAtivo.assentos?.trasEsq?.id === colabId) posicaoAssento = 'trasEsq';
      else if (veiculoAtivo.assentos?.trasDir?.id === colabId) posicaoAssento = 'trasDir';

      onUpdateAssentoStatus(
        veiculoAtivo.id,
        posicaoAssento,
        novoStatus,
        motivo,
        obs,
        substitutoId && substitutoNome ? { id: substitutoId, nome: substitutoNome } : undefined
      );
    }
    setModalAberto(false);
  };

  const renderAssentoCockpit = (
    colab: Colaborador | undefined,
    v: Veiculo
  ) => {
    if (!colab) {
      return (
        <div className="flex flex-col items-center justify-center p-3 rounded-2xl border border-dashed border-border/60 bg-muted/10 min-h-[140px]">
          <span className="text-[11px] font-semibold text-muted-foreground">Posto Vago</span>
        </div>
      );
    }

    const statusBadgeConfig = {
      presente: {
        bg: 'bg-emerald-500/20 text-emerald-300 border-emerald-500/30',
        dot: 'bg-emerald-400',
        label: 'Presente',
      },
      falta: {
        bg: 'bg-rose-500/20 text-rose-300 border-rose-500/30',
        dot: 'bg-rose-400',
        label: 'Falta',
      },
      substituto: {
        bg: 'bg-amber-500/20 text-amber-300 border-amber-500/30',
        dot: 'bg-amber-400',
        label: 'Substituto',
      },
    };

    const badge = statusBadgeConfig[colab.status || 'presente'];

    return (
      <div
        onClick={() => handleAbrirPresenca(colab, v)}
        className={cn(
          'group relative flex flex-col items-center justify-between p-3 rounded-2xl border transition-all cursor-pointer text-center select-none min-h-[145px]',
          colab.status === 'falta'
            ? 'border-rose-500/40 bg-rose-950/15 hover:border-rose-500/70'
            : colab.status === 'substituto'
            ? 'border-amber-500/40 bg-amber-950/15 hover:border-amber-500/70'
            : 'border-border/70 bg-card/70 hover:border-emerald-500/50 hover:bg-muted/40 shadow-sm'
        )}
      >
        <div className="relative mt-0.5">
          <div
            className={cn(
              'w-16 h-16 sm:w-18 sm:h-18 rounded-2xl overflow-hidden border-2 shadow-md transition-transform group-hover:scale-105 bg-zinc-900',
              colab.status === 'falta'
                ? 'border-rose-500/80 ring-2 ring-rose-500/20'
                : colab.status === 'substituto'
                ? 'border-amber-500/80 ring-2 ring-amber-500/20'
                : 'border-emerald-500/70 ring-2 ring-emerald-500/10'
            )}
          >
            {colab.foto ? (
              <img
                src={colab.foto}
                alt={colab.nome}
                className={cn(
                  'w-full h-full object-cover transition-opacity',
                  colab.status === 'falta' && 'opacity-40 grayscale'
                )}
              />
            ) : (
              <div className="w-full h-full flex items-center justify-center font-black text-sm text-zinc-300 bg-emerald-950/40">
                {getIniciais(colab.nome)}
              </div>
            )}
          </div>

          <span
            className={cn(
              'absolute -top-1 -right-1 w-4 h-4 rounded-full border-2 border-card flex items-center justify-center shrink-0',
              badge.dot
            )}
          />
        </div>

        <div className="w-full mt-2 space-y-0.5">
          <p
            className={cn(
              'text-xs font-bold truncate transition-colors px-1',
              colab.status === 'falta'
                ? 'text-rose-300 line-through'
                : 'text-foreground group-hover:text-emerald-300'
            )}
            title={colab.nome}
          >
            {colab.nome}
          </p>
          <p className="text-[10px] text-muted-foreground truncate px-1">
            {colab.cargo || 'Operador'}
          </p>
        </div>

        <div className="w-full mt-1.5 pt-1.5 border-t border-border/40">
          <span
            className={cn(
              'inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[10px] font-semibold border',
              badge.bg
            )}
          >
            <span className={cn('w-1.5 h-1.5 rounded-full', badge.dot)} />
            {colab.status === 'substituto' && colab.substitutoNome
              ? `Subst: ${colab.substitutoNome.split(' ')[0]}`
              : badge.label}
          </span>
        </div>
      </div>
    );
  };

  return (
    <div className="space-y-5">
      <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3 p-3 bg-card/60 backdrop-blur-md border border-border/60 rounded-2xl">
        <div className="relative flex-1">
          <Search className="absolute left-3.5 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
          <Input
            placeholder="Buscar por veículo, placa ou nome do operador..."
            value={busca}
            onChange={(e) => setBusca(e.target.value)}
            className="pl-10 h-10 bg-background/50 border-border/60 text-sm"
          />
        </div>

        <div className="flex items-center gap-2">
          <div className="flex items-center bg-muted/40 p-1 rounded-xl border border-border/50 text-xs">
            <button
              type="button"
              onClick={() => setFiltroStatus('todos')}
              className={cn(
                'px-3 py-1.5 rounded-lg font-medium transition-colors cursor-pointer',
                filtroStatus === 'todos' ? 'bg-background text-foreground shadow-sm' : 'text-muted-foreground hover:text-foreground'
              )}
            >
              Todos
            </button>
            <button
              type="button"
              onClick={() => setFiltroStatus('completos')}
              className={cn(
                'px-3 py-1.5 rounded-lg font-medium transition-colors cursor-pointer',
                filtroStatus === 'completos' ? 'bg-emerald-500/20 text-emerald-300 font-semibold shadow-sm' : 'text-muted-foreground hover:text-foreground'
              )}
            >
              Completos
            </button>
            <button
              type="button"
              onClick={() => setFiltroStatus('incompletos')}
              className={cn(
                'px-3 py-1.5 rounded-lg font-medium transition-colors cursor-pointer',
                filtroStatus === 'incompletos' ? 'bg-rose-500/20 text-rose-300 font-semibold shadow-sm' : 'text-muted-foreground hover:text-foreground'
              )}
            >
              Com Faltas
            </button>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-5">
        {veiculosFiltrados.map((v) => {
          const assentosArr = [
            v.assentos?.motorista,
            v.assentos?.frenteDir,
            v.assentos?.trasEsq,
            v.assentos?.trasDir,
          ].filter(Boolean);

          const totalPresentes = assentosArr.filter(
            (c) => c?.status === 'presente' || c?.status === 'substituto'
          ).length;

          const temFaltas = assentosArr.some((c) => c?.status === 'falta');

          return (
            <Card
              key={v.id}
              className={cn(
                'overflow-hidden transition-all duration-200 border bg-card/80 hover:shadow-2xl',
                temFaltas ? 'border-rose-500/30 shadow-rose-950/10' : 'border-border/70 hover:border-emerald-500/40'
              )}
            >
              <CardHeader className="p-4 pb-3 border-b border-border/40 bg-gradient-to-r from-muted/30 to-transparent">
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-2">
                    <div className="w-8 h-8 rounded-xl bg-emerald-500/15 border border-emerald-500/30 flex items-center justify-center text-emerald-400">
                      <Car className="w-4 h-4" />
                    </div>
                    <div>
                      <CardTitle className="text-sm font-bold text-foreground flex items-center gap-2">
                        {v.prefixo}
                        <span className="text-[11px] font-mono font-medium text-muted-foreground">
                          {v.placa}
                        </span>
                      </CardTitle>
                      <p className="text-[11px] text-muted-foreground">{v.modelo}</p>
                    </div>
                  </div>

                  <div className="flex items-center gap-1.5">
                    <Badge
                      variant="outline"
                      className={cn(
                        'text-[10px] font-bold px-2 py-0.5',
                        temFaltas
                          ? 'border-rose-500/40 text-rose-400 bg-rose-500/10'
                          : 'border-emerald-500/40 text-emerald-400 bg-emerald-500/10'
                      )}
                    >
                      {totalPresentes}/4 Operadores
                    </Badge>
                  </div>
                </div>
              </CardHeader>

              <CardContent className="p-4 space-y-4">
                <div className="grid grid-cols-2 gap-2.5">
                  {renderAssentoCockpit(v.assentos?.motorista, v)}
                  {renderAssentoCockpit(v.assentos?.frenteDir, v)}
                  {renderAssentoCockpit(v.assentos?.trasEsq, v)}
                  {renderAssentoCockpit(v.assentos?.trasDir, v)}
                </div>

                <div className="flex items-center justify-between pt-2 border-t border-border/40 text-[11px] text-muted-foreground">
                  <span className="flex items-center gap-1">
                    <MapPin className="w-3 h-3 text-emerald-400" />
                    {v.regional === 'ribas' ? 'Ribas do Rio Pardo' : 'Água Clara'}
