import React, { useState } from 'react';
import { Navbar } from './components/Navbar';
import { MetricsHeader } from './components/MetricsHeader';
import { VehicleCardGrid } from './components/VehicleCardGrid';
import { CollaboratorsManagement, ColaboradorCompleto } from './components/CollaboratorsManagement';
import { TeamsManagement } from './components/TeamsManagement';
import { ExportReports } from './components/ExportReports';
import { NewTeamModal } from './components/NewTeamModal';
import { VEICULOS_INICIAIS, COLABORADORES_RESERVA } from './data/mockData';
import { Regional, StatusPresenca, MotivoFalta, Veiculo, Colaborador } from './types';

export function App() {
  const [activeTab, setActiveTab] = useState<'veiculos' | 'colaboradores' | 'equipes' | 'relatorios'>('veiculos');
  const [selectedRegional, setSelectedRegional] = useState<Regional>('todas');
  const [selectedDate, setSelectedDate] = useState<Date>(new Date());
  const [veiculos, setVeiculos] = useState<Veiculo[]>(VEICULOS_INICIAIS);
  const [colaboradoresReserva, setColaboradoresReserva] = useState<Colaborador[]>(COLABORADORES_RESERVA);
  const [isNewTeamModalOpen, setIsNewTeamModalOpen] = useState(false);

  // Atualização do status de um colaborador (global ou assento)
  const handleUpdateColaboradorStatus = (
    colabId: string,
    novoStatus: StatusPresenca,
    motivo?: MotivoFalta,
    obs?: string,
    substitutoId?: string,
    substitutoNome?: string
  ) => {
    // 1. Atualiza nos assentos dos veículos
    setVeiculos((prevVeiculos) =>
      prevVeiculos.map((v) => {
        const assentos = { ...v.assentos };
        let mudou = false;

        const posicoes: Array<keyof typeof assentos> = ['motorista', 'frenteDir', 'trasEsq', 'trasDir'];
        posicoes.forEach((pos) => {
          if (assentos[pos]?.id === colabId) {
            assentos[pos] = {
              ...assentos[pos],
              status: novoStatus,
              motivoFalta: motivo,
              observacao: obs,
              substitutoId: substitutoId || undefined,
              substitutoNome: substitutoNome || undefined,
            };
            mudou = true;
          }
        });

        return mudou ? { ...v, assentos } : v;
      })
    );

    // 2. Atualiza caso esteja no banco de reservas
    setColaboradoresReserva((prev) =>
      prev.map((r) =>
        r.id === colabId
          ? {
              ...r,
              status: novoStatus,
              motivoFalta: motivo,
              observacao: obs,
              substitutoId: substitutoId || undefined,
              substitutoNome: substitutoNome || undefined,
            }
          : r
      )
    );
  };

  // Atualização direta por assento do veículo
  const handleUpdateAssentoStatus = (
    veiculoId: string,
    posicao: 'motorista' | 'frenteDir' | 'trasEsq' | 'trasDir',
    novoStatus: StatusPresenca,
    motivo?: MotivoFalta,
    observacao?: string,
    substituto?: { id: string; nome: string }
  ) => {
    setVeiculos((prevVeiculos) =>
      prevVeiculos.map((v) => {
        if (v.id !== veiculoId) return v;
        const assentoAtual = v.assentos[posicao];
        if (!assentoAtual) return v;

        return {
          ...v,
          assentos: {
            ...v.assentos,
            [posicao]: {
              ...assentoAtual,
              status: novoStatus,
              motivoFalta: motivo,
              observacao,
              substitutoId: substituto?.id,
              substitutoNome: substituto?.nome,
            },
          },
        };
      })
    );
  };

  // Importar novos colaboradores para o banco de reserva
  const handleImportarColaboradores = (novos: ColaboradorCompleto[]) => {
    const convertidos: Colaborador[] = novos.map((n) => ({
      id: n.id,
      nome: n.nome,
      cargo: n.cargo,
      matricula: n.matricula,
      foto: n.foto,
      telefone: n.telefone,
      status: n.status,
      motivoFalta: n.motivoFalta,
      observacao: n.observacao,
      substitutoNome: n.substitutoNome,
      equipeId: 'reserva',
      equipeNumero: 1,
      posicaoVeiculo: 'motorista',
    }));

    setColaboradoresReserva((prev) => [...prev, ...convertidos]);
  };

  // Adicionar um novo colaborador
  const handleAdicionarColaborador = (novo: ColaboradorCompleto) => {
    const novoColab: Colaborador = {
      id: novo.id,
      nome: novo.nome,
      cargo: novo.cargo,
      matricula: novo.matricula,
      foto: novo.foto,
      telefone: novo.telefone,
      status: novo.status,
      equipeId: 'reserva',
      equipeNumero: 1,
      posicaoVeiculo: 'motorista',
    };
    setColaboradoresReserva((prev) => [novoColab, ...prev]);
  };

  return (
    <div className="min-h-screen bg-background text-foreground flex flex-col font-sans selection:bg-emerald-500/30 selection:text-emerald-200">
      <Navbar
        activeTab={activeTab}
        onTabChange={setActiveTab}
        selectedRegional={selectedRegional}
        onRegionalChange={setSelectedRegional}
        selectedDate={selectedDate}
        onDateChange={setSelectedDate}
        onNovaEquipeClick={() => setIsNewTeamModalOpen(true)}
      />

      <main className="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-6 space-y-6">
        {activeTab === 'veiculos' && (
          <>
            <MetricsHeader
              veiculos={veiculos}
              selectedRegional={selectedRegional}
              selectedDate={selectedDate}
              onFiltroRegionalChange={(reg) => setSelectedRegional(reg)}
              onNovaEquipe={() => setIsNewTeamModalOpen(true)}
            />
            <VehicleCardGrid
              veiculos={veiculos}
              colaboradoresReserva={colaboradoresReserva}
              selectedRegional={selectedRegional}
              onUpdateColaboradorStatus={handleUpdateColaboradorStatus}
              onUpdateAssentoStatus={handleUpdateAssentoStatus}
              onNovaEquipeClick={() => setIsNewTeamModalOpen(true)}
            />
          </>
        )}

        {activeTab === 'colaboradores' && (
          <CollaboratorsManagement
            veiculos={veiculos}
            colaboradoresReserva={colaboradoresReserva}
            selectedRegional={selectedRegional}
            onUpdateColaboradorStatus={handleUpdateColaboradorStatus}
            onImportarColaboradores={handleImportarColaboradores}
            onAdicionarColaborador={handleAdicionarColaborador}
          />
        )}

        {activeTab === 'equipes' && (
          <TeamsManagement
            veiculos={veiculos}
            colaboradoresReserva={colaboradoresReserva}
            selectedRegional={selectedRegional}
            onNovaEquipeClick={() => setIsNewTeamModalOpen(true)}
          />
        )}

        {activeTab === 'relatorios' && (
          <ExportReports
            veiculos={veiculos}
            colaboradoresReserva={colaboradoresReserva}
            selectedRegional={selectedRegional}
            selectedDate={selectedDate}
          />
        )}
      </main>

      <NewTeamModal
        isOpen={isNewTeamModalOpen}
        onClose={() => setIsNewTeamModalOpen(false)}
        colaboradoresReserva={colaboradoresReserva}
        onCriarEquipe={(novaEquipe) => {
          setVeiculos((prev) => [novaEquipe, ...prev]);
          setIsNewTeamModalOpen(false);
        }}
      />
    </div>
  );
}

export default App;

