export const ExportReports: React.FC<ExportReportsProps> = ({
  veiculos = [],
  colaboradoresReserva = [],
  selectedRegional = 'todas',
  selectedDate = new Date(),
}) => {
  const [mesSelecionado, setMesSelecionado] = useState<number>(new Date().getMonth());
  const [unidadeFiltro, setUnidadeFiltro] = useState<Regional>(selectedRegional);

  // Lista consolidada de colaboradores dos veículos e reservas com Nome, Unidade, Função e Data de Admissão
  const todosColaboradores = useMemo(() => {
    const list: Array<{
      nome: string;
      unidade: string;
      funcao: string;
      dataAdmissao: string;
      status: string;
      motivoFalta: string;
      veiculo: string;
      regionalKey: string;
    }> = [];

    (veiculos || []).forEach((v) => {
      if (!v || !v.assentos) return;
      const assentos = [v.assentos.motorista, v.assentos.frenteDir, v.assentos.trasEsq, v.assentos.trasDir];
      assentos.forEach((c) => {
        if (!c) return;
        list.push({
          nome: c.nome || 'Não Informado',
          unidade: c.unidade || (v.regional === 'agua_clara' ? 'Água Clara' : 'Ribas do Rio Pardo'),
          funcao: c.cargo || 'Operador Florestal',
          dataAdmissao: c.dataAdmissao || '15/01/2023',
          status: c.status === 'presente' ? 'Presente' : c.status === 'falta' ? 'Falta' : 'Substituto',
          motivoFalta: c.motivoFalta || '-',
          veiculo: v.prefixo || '-',
          regionalKey: v.regional || 'ribas',
        });
      });
    });

    (colaboradoresReserva || []).forEach((r) => {
      if (!r) return;
      list.push({
        nome: r.nome || 'Não Informado',
        unidade: r.unidade || 'Ribas do Rio Pardo',
        funcao: r.cargo || 'Operador Reserva',
        dataAdmissao: r.dataAdmissao || '10/05/2023',
        status: r.status === 'presente' ? 'Presente' : r.status === 'falta' ? 'Falta' : 'Substituto',
        motivoFalta: r.motivoFalta || '-',
        veiculo: 'Banco de Reserva',
        regionalKey: 'ribas',
      });
    });

    return list;
  }, [veiculos, colaboradoresReserva]);

  // Histórico do mês filtrado por unidade
  const dadosMesAtual = useMemo(() => {
    const item = HISTORICO_MENSAL_FALTAS.find((h) => h.mesIndex === mesSelecionado);
    if (!item) return [];
    if (unidadeFiltro === 'todas') return item.faltas;
    return item.faltas.filter((f) => f.regionalKey === unidadeFiltro);
  }, [mesSelecionado, unidadeFiltro]);

  // Função principal para exportar a planilha Excel (.xlsx) com Nome, Unidade, Função e Data de Admissão
  const exportarPlanilhaExcel = () => {
    const dadosFormatados = todosColaboradores
      .filter((c) => unidadeFiltro === 'todas' || c.regionalKey === unidadeFiltro)
      .map((c) => ({
        'Nome': c.nome,
        'Unidade': c.unidade,
        'Função': c.funcao,
        'Data de Admissão': c.dataAdmissao,
        'Status Atual': c.status,
        'Motivo de Falta': c.motivoFalta,
        'Veículo / Prefixo': c.veiculo,
      }));

    const worksheet = XLSX.utils.json_to_sheet(dadosFormatados);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, 'Colaboradores');

    // Largura automática das colunas
    worksheet['!cols'] = [
      { wch: 32 }, // Nome
      { wch: 24 }, // Unidade
      { wch: 28 }, // Função
      { wch: 18 }, // Data de Admissão
      { wch: 16 }, // Status Atual
      { wch: 24 }, // Motivo de Falta
      { wch: 20 }, // Veículo
    ];

    const dataFormatada = new Date().toISOString().split('T')[0];
    XLSX.writeFile(workbook, `relatorio_colaboradores_${dataFormatada}.xlsx`);
  };

  // Função para exportar a planilha do histórico mensal de faltas
  const exportarHistoricoMensalExcel = () => {
    const nomeMes = MESES[mesSelecionado];
    const dados = dadosMesAtual.map((item) => ({
      'Nome': item.nome,
      'Unidade': item.unidade,
      'Função': item.funcao,
      'Data de Admissão': item.dataAdmissao,
      'Total de Faltas no Mês': item.totalFaltas,
      'Mês Referência': nomeMes,
    }));

    const worksheet = XLSX.utils.json_to_sheet(dados);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, `Faltas_${nomeMes}`);

    worksheet['!cols'] = [
      { wch: 32 }, // Nome
      { wch: 24 }, // Unidade
      { wch: 28 }, // Função
      { wch: 18 }, // Data de Admissão
      { wch: 22 }, // Total de Faltas
      { wch: 18 }, // Mês
    ];

    XLSX.writeFile(workbook, `relatorio_faltas_${nomeMes.toLowerCase()}_2025.xlsx`);
  };

  return (
    <div className="space-y-6">
      {/* Banner / Cabeçalho do Módulo */}
      <div className="p-6 rounded-2xl border border-border/80 bg-gradient-to-r from-card via-card/90 to-card/60 backdrop-blur-md shadow-xl flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <div className="flex items-center gap-2 mb-1">
            <span className="w-2.5 h-2.5 rounded-full bg-emerald-500 animate-pulse" />
            <span className="text-xs font-semibold uppercase tracking-wider text-emerald-400">
              Módulo de Exportação & Auditoria
            </span>
          </div>
          <h2 className="text-2xl font-bold tracking-tight text-foreground">
            Relatórios e Planilhas Operacionais
          </h2>
          <p className="text-sm text-muted-foreground mt-0.5">
            Gere e baixe relatórios padronizados contendo Nome, Unidade, Função e Data de Admissão.
          </p>
        </div>

        <div className="flex flex-wrap items-center gap-2">
          {/* Botão de Exportação Excel com as 4 colunas obrigatórias */}
          <Button
            onClick={exportarPlanilhaExcel}
            className="gap-2 bg-emerald-600 hover:bg-emerald-500 text-white font-semibold shadow-md active:scale-95 transition-all"
          >
            <FileSpreadsheet className="w-4 h-4" />
            Exportar Planilha Completa (.XLSX)
          </Button>
          <Button
            onClick={() => window.print()}
            variant="outline"
            className="gap-2 border-border/70 hover:bg-muted/60"
          >
            <Printer className="w-4 h-4 text-muted-foreground" />
            Imprimir
          </Button>
        </div>
      </div>

      {/* Grid de Especificação dos Campos da Planilha */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-3.5">
        <div className="p-4 rounded-xl border border-emerald-500/20 bg-emerald-500/5 flex items-center gap-3">
          <div className="w-10 h-10 rounded-lg bg-emerald-500/20 flex items-center justify-center text-emerald-400 shrink-0">
            <Users className="w-5 h-5" />
          </div>
          <div>
            <p className="text-xs text-muted-foreground font-medium">Coluna 1</p>
            <p className="text-sm font-bold text-foreground">Nome do Colaborador</p>
            <p className="text-[11px] text-emerald-400/90">Identificação nominal</p>
          </div>
        </div>

        <div className="p-4 rounded-xl border border-teal-500/20 bg-teal-500/5 flex items-center gap-3">
          <div className="w-10 h-10 rounded-lg bg-teal-500/20 flex items-center justify-center text-teal-400 shrink-0">
            <Building2 className="w-5 h-5" />
          </div>
          <div>
            <p className="text-xs text-muted-foreground font-medium">Coluna 2</p>
            <p className="text-sm font-bold text-foreground">Unidade</p>
            <p className="text-[11px] text-teal-400/90">Ribas / Água Clara</p>
          </div>
        </div>

        <div className="p-4 rounded-xl border border-cyan-500/20 bg-cyan-500/5 flex items-center gap-3">
          <div className="w-10 h-10 rounded-lg bg-cyan-500/20 flex items-center justify-center text-cyan-400 shrink-0">
            <Briefcase className="w-5 h-5" />
          </div>
          <div>
            <p className="text-xs text-muted-foreground font-medium">Coluna 3</p>
            <p className="text-sm font-bold text-foreground">Função</p>
            <p className="text-[11px] text-cyan-400/90">Cargo operacional</p>
          </div>
        </div>

        <div className="p-4 rounded-xl border border-amber-500/20 bg-amber-500/5 flex items-center gap-3">
          <div className="w-10 h-10 rounded-lg bg-amber-500/20 flex items-center justify-center text-amber-400 shrink-0">
            <CalendarDays className="w-5 h-5" />
          </div>
          <div>
            <p className="text-xs text-muted-foreground font-medium">Coluna 4</p>
            <p className="text-sm font-bold text-foreground">Data de Admissão</p>
            <p className="text-[11px] text-amber-400/90">Registro de contratação</p>
          </div>
        </div>
      </div>

      {/* Filtro por Mês e por Unidade para Pré-visualização */}
      <Card className="border border-border/80">
        <CardHeader className="pb-3 border-b border-border/40">
          <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3">
            <div>
              <CardTitle className="text-lg font-bold flex items-center gap-2">
                <BarChart3 className="w-5 h-5 text-emerald-400" />
                Histórico Mensal com as 4 Colunas Obrigatórias
              </CardTitle>
              <CardDescription>
                Selecione o mês e filtre por unidade para visualizar e baixar a planilha correspondente.
              </CardDescription>
            </div>

            <Button
              onClick={exportarHistoricoMensalExcel}
              variant="outline"
              size="sm"
              className="gap-2 border-emerald-500/40 text-emerald-400 hover:bg-emerald-500/10 font-semibold"
            >
              <FileDown className="w-4 h-4" />
              Baixar Faltas de {MESES[mesSelecionado]} (.XLSX)
            </Button>
          </div>
        </CardHeader>

        <CardContent className="pt-4 space-y-4">
          {/* Seletor de Mês */}
          <div className="flex items-center gap-1.5 overflow-x-auto pb-2 scrollbar-thin">
            {MESES.map((m, idx) => (
              <button
                key={m}
                onClick={() => setMesSelecionado(idx)}
                className={cn(
                  'px-3 py-1.5 rounded-lg text-xs font-semibold whitespace-nowrap transition-all',
                  mesSelecionado === idx
                    ? 'bg-emerald-600 text-white shadow-sm'
                    : 'bg-muted/40 text-muted-foreground hover:bg-muted hover:text-foreground'
                )}
              >
                {m}
              </button>
            ))}
          </div>

          {/* Filtro de Unidade */}
          <div className="flex items-center gap-2">
            <span className="text-xs font-medium text-muted-foreground">Filtrar por Unidade:</span>
            {(['todas', 'ribas', 'agua_clara'] as Regional[]).map((r) => (
              <button
                key={r}
                onClick={() => setUnidadeFiltro(r)}
                className={cn(
                  'px-2.5 py-1 rounded-md text-xs font-medium transition-colors border',
                  unidadeFiltro === r
                    ? 'bg-zinc-800 text-foreground border-border'
                    : 'border-transparent text-muted-foreground hover:bg-muted/50'
                )}
              >
                {regionalLabel[r]}
              </button>
            ))}
          </div>

          {/* Tabela de Apresentação com Nome, Unidade, Função e Data de Admissão */}
          <div className="rounded-xl border border-border/80 overflow-hidden bg-card">
            <div className="overflow-x-auto">
              <table className="w-full text-left text-sm">
                <thead className="bg-muted/50 border-b border-border/60 text-xs uppercase font-bold text-muted-foreground">
                  <tr>
                    <th className="px-4 py-3">Nome</th>
                    <th className="px-4 py-3">Unidade</th>
                    <th className="px-4 py-3">Função</th>
                    <th className="px-4 py-3">Data de Admissão</th>
                    <th className="px-4 py-3 text-center">Faltas Registradas</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-border/40">
                  {dadosMesAtual.length === 0 ? (
                    <tr>
                      <td colSpan={5} className="px-4 py-8 text-center text-muted-foreground">
                        Nenhum registro encontrado para {MESES[mesSelecionado]} nesta unidade.
                      </td>
                    </tr>
                  ) : (
                    dadosMesAtual.map((colab, idx) => (
                      <tr key={`${colab.nome}-${idx}`} className="hover:bg-muted/20 transition-colors">
                        <td className="px-4 py-3 font-semibold text-foreground">
                          {colab.nome}
                        </td>
                        <td className="px-4 py-3 text-muted-foreground flex items-center gap-1.5">
                          <Building2 className="w-3.5 h-3.5 text-muted-foreground/70" />
                          {colab.unidade}
                        </td>
                        <td className="px-4 py-3 text-muted-foreground">
                          {colab.funcao}
                        </td>
                        <td className="px-4 py-3 tabular-nums font-mono text-xs text-muted-foreground">
                          {colab.dataAdmissao}
                        </td>
                        <td className="px-4 py-3 text-center">
                          <Badge
                            variant={colab.totalFaltas > 3 ? 'destructive' : 'secondary'}
                            className="tabular-nums font-bold"
                          >
                            {colab.totalFaltas} {colab.totalFaltas === 1 ? 'falta' : 'faltas'}
                          </Badge>
                        </td>
                      </tr>
                    ))
                  )}
                </tbody>
              </table>
            </div>
          </div>
        </CardContent>
      </Card>
    </div>
  );
};

