import React, { useState, useMemo, useRef } from 'react';
import {
  Users,
  Search,
  Phone,
  MapPin,
  ChevronDown,
  ChevronUp,
  UserCheck,
  UserX,
  UploadCloud,
  FileSpreadsheet,
  Download,
  CheckCircle2,
  AlertCircle,
  X,
  Plus,
  Camera,
  Trash2,
  Building2,
  Briefcase,
  FileCheck,
  Eye,
  FileUp,
  Loader2,
  Sparkles,
} from 'lucide-react';
import { Card, CardContent } from './ui/card';
import { Badge } from './ui/badge';
import { Input } from './ui/input';
import { Button } from './ui/button';
import { cn } from '@/lib/utils';
import { Colaborador, Veiculo, StatusPresenca, MotivoFalta, Regional } from '../types';

export interface ColaboradorCompleto {
  id: string;
  nome: string;
  cargo: string;
  matricula: string;
  foto: string;
  telefone: string;
  status: StatusPresenca;
  motivoFalta?: MotivoFalta;
  observacao?: string;
  substitutoNome?: string;
  equipeId: string;
  equipeNumero: 1 | 2;
  posicaoVeiculo: 'motorista' | 'frente_dir' | 'tras_esq' | 'tras_dir';
  veiculoPrefixo: string;
  veiculoPlaca: string;
  regional: 'ribas' | 'agua_clara';
}

export interface CollaboratorsManagementProps {
  veiculos?: Veiculo[];
  colaboradoresReserva?: Colaborador[];
  selectedRegional?: Regional;
  onUpdateColaboradorStatus?: (
    colabId: string,
    novoStatus: StatusPresenca,
    motivo?: MotivoFalta,
    obs?: string
  ) => void;
  onImportarColaboradores?: (novosColaboradores: ColaboradorCompleto[]) => void;
  onAdicionarColaborador?: (novoColaborador: ColaboradorCompleto) => void;
}

const statusConfig: Record<StatusPresenca, { label: string; className: string }> = {
  presente: { label: 'Presente', className: 'bg-emerald-500/20 text-emerald-400 border-emerald-500/30' },
  falta: { label: 'Falta', className: 'bg-rose-500/20 text-rose-400 border-rose-500/30' },
  substituto: { label: 'Substituto', className: 'bg-amber-500/20 text-amber-400 border-amber-500/30' },
};

const regionalLabel: Record<string, string> = {
  ribas: 'Ribas do Rio Pardo',
  agua_clara: 'Água Clara',
};

const getIniciais = (nome?: string) => {
  if (!nome) return 'CO';
  const partes = nome.trim().split(' ');
  if (partes.length === 1) return partes[0].substring(0, 2).toUpperCase();
  return (partes[0][0] + (partes[partes.length - 1]?.[0] || '')).toUpperCase();
};

export const CollaboratorsManagement: React.FC<CollaboratorsManagementProps> = ({
  veiculos = [],
  colaboradoresReserva = [],
  selectedRegional = 'todas',
  onUpdateColaboradorStatus,
  onImportarColaboradores,
  onAdicionarColaborador,
}) => {
  const [search, setSearch] = useState('');
  const [filterStatus, setFilterStatus] = useState<StatusPresenca | 'todos'>('todos');
  const [filterRegional, setFilterRegional] = useState<Regional | 'todas'>(selectedRegional);
  const [fotoModalAberta, setFotoModalAberta] = useState<{ url: string; nome: string; cargo: string } | null>(null);

  // Modal de cadastro manual
  const [modalNovoAberto, setModalNovoAberto] = useState(false);
  const [novoNome, setNovoNome] = useState('');
  const [novoCargo, setNovoCargo] = useState('');
  const [novoTelefone, setNovoTelefone] = useState('');
  const [novaFoto, setNovaFoto] = useState<string>('');
  const [novaUnidade, setNovaUnidade] = useState<'ribas' | 'agua_clara'>('ribas');
  const fotoInputRef = useRef<HTMLInputElement>(null);

  // Modal de Importação Excel
  const [modalExcelAberto, setModalExcelAberto] = useState(false);
  const [isProcessandoExcel, setIsProcessandoExcel] = useState(false);
  const [excelPreview, setExcelPreview] = useState<ColaboradorCompleto[]>([]);
  const [excelErro, setExcelErro] = useState<string | null>(null);
  const [excelArquivoNome, setExcelArquivoNome] = useState<string>('');
  const [excelImportSucesso, setExcelImportSucesso] = useState(false);
  const excelInputRef = useRef<HTMLInputElement>(null);

  const colaboradoresBase: ColaboradorCompleto[] = useMemo(() => {
    const lista: ColaboradorCompleto[] = [];
    (veiculos || []).forEach((v) => {
      if (!v || !v.assentos) return;
      const assentos: Array<{ colab?: Colaborador; pos: ColaboradorCompleto['posicaoVeiculo'] }> = [
        { colab: v.assentos.motorista, pos: 'motorista' },
        { colab: v.assentos.frenteDir, pos: 'frente_dir' },
        { colab: v.assentos.trasEsq, pos: 'tras_esq' },
        { colab: v.assentos.trasDir, pos: 'tras_dir' },
      ];
      assentos.forEach(({ colab, pos }) => {
        if (!colab) return;
        lista.push({
          id: colab.id,
          nome: colab.nome || 'Sem Nome',
          cargo: colab.cargo || 'Operador',
          matricula: '',
          foto: colab.foto ?? '',
          telefone: colab.telefone ?? '',
          status: colab.status || 'presente',
          motivoFalta: colab.motivoFalta,
          observacao: colab.observacao,
          substitutoNome: colab.substitutoNome,
          equipeId: colab.equipeId || '',
          equipeNumero: colab.equipeNumero || 1,
          posicaoVeiculo: pos,
          veiculoPrefixo: v.prefixo || '',
          veiculoPlaca: v.placa || '',
          regional: v.regional || 'ribas',
        });
      });
    });

    (colaboradoresReserva || []).forEach((r, idx) => {
      if (!r) return;
      lista.push({
        id: r.id || `res-${idx}`,
        nome: r.nome || 'Colaborador Reserva',
        cargo: r.cargo || 'Reserva Operacional',
        matricula: '',
        foto: r.foto || '',
        telefone: r.telefone || '',
        status: r.status || 'presente',
        motivoFalta: r.motivoFalta,
        observacao: r.observacao,
        substitutoNome: r.substitutoNome,
        equipeId: 'reserva',
        equipeNumero: 1,
        posicaoVeiculo: 'motorista',
        veiculoPrefixo: 'Banco de Reserva',
        veiculoPlaca: '-',
        regional: 'ribas',
      });
    });

    return lista;
  }, [veiculos, colaboradoresReserva]);

  const [colaboradoresAdicionados, setColaboradoresAdicionados] = useState<ColaboradorCompleto[]>([]);

  const todosColaboradores = useMemo(() => {
    return [...colaboradoresBase, ...colaboradoresAdicionados];
  }, [colaboradoresBase, colaboradoresAdicionados]);

  const colaboradoresFiltrados = useMemo(() => {
    return todosColaboradores.filter((c) => {
      if (!c) return false;
      const matchSearch =
        !search ||
        (c.nome || '').toLowerCase().includes(search.toLowerCase()) ||
        (c.cargo || '').toLowerCase().includes(search.toLowerCase()) ||
        (c.veiculoPlaca || '').toLowerCase().includes(search.toLowerCase()) ||
        (c.veiculoPrefixo || '').toLowerCase().includes(search.toLowerCase());

      const matchStatus = filterStatus === 'todos' || c.status === filterStatus;
      const matchRegional = filterRegional === 'todas' || c.regional === filterRegional;

      return matchSearch && matchStatus && matchRegional;
    });
  }, [todosColaboradores, search, filterStatus, filterRegional]);

  const handleFotoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      if (event.target?.result) {
        setNovaFoto(event.target.result as string);
      }
    };
    reader.readAsDataURL(file);
  };

  const handleCadastrarColaborador = (e: React.FormEvent) => {
    e.preventDefault();
    if (!novoNome.trim()) return;

    const novo: ColaboradorCompleto = {
      id: `colab-custom-${Date.now()}`,
      nome: novoNome.trim(),
      cargo: novoCargo.trim() || 'Operador Florestal',
      matricula: '',
      foto: novaFoto,
      telefone: novoTelefone.trim(),
      status: 'presente',
      equipeId: 'reserva',
      equipeNumero: 1,
      posicaoVeiculo: 'motorista',
      veiculoPrefixo: 'Banco de Reserva',
      veiculoPlaca: '-',
      regional: novaUnidade,
    };

    setColaboradoresAdicionados((prev) => [novo, ...prev]);
    if (onAdicionarColaborador) onAdicionarColaborador(novo);

    setNovoNome('');
    setNovoCargo('');
    setNovoTelefone('');
    setNovaFoto('');
    setModalNovoAberto(false);
  };

  // Leitura e Processamento da Planilha Excel (.xlsx, .xls ou .csv)
  const carregarSheetJs = async (): Promise<any> => {
    if ((window as any).XLSX) {
      return (window as any).XLSX;
    }
    return new Promise((resolve, reject) => {
      const script = document.createElement('script');
      script.src = 'https://cdn.jsdelivr.net/npm/xlsx@0.18.5/dist/xlsx.full.min.js';
      script.async = true;
      script.onload = () => resolve((window as any).XLSX);
      script.onerror = () => reject(new Error('Não foi possível carregar a biblioteca de processamento de Excel.'));
      document.head.appendChild(script);
    });
  };

  const processarLinhasImportadas = (rows: any[]): ColaboradorCompleto[] => {
    const convertidos: ColaboradorCompleto[] = [];

    rows.forEach((row, index) => {
      if (!row || typeof row !== 'object') return;

      // Suporte flexível para os cabeçalhos de coluna em maiúsculo, minúsculo ou acentuado
      const rowNormalizada: Record<string, any> = {};
      Object.keys(row).forEach((chave) => {
        const limpa = chave.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();
        rowNormalizada[limpa] = row[chave];
      });

      const nome =
        rowNormalizada['nome'] ||
        rowNormalizada['colaborador'] ||
        rowNormalizada['nome completo'] ||
        rowNormalizada['operador'] ||
        rowNormalizada['name'] ||
        Object.values(row)[0];

      if (!nome || typeof nome !== 'string' || !nome.trim() || nome.trim().toLowerCase() === 'nome') {
        return; // Pula linha em branco ou cabeçalho duplicado
      }

      const cargo =
        rowNormalizada['cargo'] ||
        rowNormalizada['funcao'] ||
        rowNormalizada['ocupacao'] ||
        rowNormalizada['role'] ||
        'Operador Florestal';

      const telefone =
        rowNormalizada['telefone'] ||
        rowNormalizada['contato'] ||
        rowNormalizada['celular'] ||
        rowNormalizada['fone'] ||
        '';

      const regionalRaw =
        rowNormalizada['unidade'] ||
        rowNormalizada['regional'] ||
        rowNormalizada['polo'] ||
        'ribas';

      let reg: 'ribas' | 'agua_clara' = 'ribas';
      const regString = String(regionalRaw).toLowerCase();
      if (regString.includes('agua') || regString.includes('água') || regString.includes('clara') || regString.includes('agc')) {
        reg = 'agua_clara';
      }

      const foto =
        rowNormalizada['foto'] ||
        rowNormalizada['imagem'] ||
        rowNormalizada['url_foto'] ||
        rowNormalizada['avatar'] ||
        '';

      const statusRaw = String(rowNormalizada['status'] || 'presente').toLowerCase();
      let status: StatusPresenca = 'presente';
      if (statusRaw.includes('falta')) status = 'falta';
      else if (statusRaw.includes('substitu')) status = 'substituto';

      convertidos.push({
        id: `import-${Date.now()}-${index}`,
        nome: String(nome).trim(),
        cargo: String(cargo).trim(),
        matricula: '',
        foto: typeof foto === 'string' && foto.startsWith('http') ? foto : '',
        telefone: String(telefone).trim(),
        status,
        equipeId: 'reserva',
        equipeNumero: 1,
        posicaoVeiculo: 'motorista',
        veiculoPrefixo: 'Banco de Reserva',
        veiculoPlaca: '-',
        regional: reg,
      });
    });

    return convertidos;
  };

  const handleArquivoExcelSelecionado = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsProcessandoExcel(true);
    setExcelErro(null);
    setExcelImportSucesso(false);
    setExcelArquivoNome(file.name);

    try {
      let dadosProcessados: any[] = [];

      if (file.name.endsWith('.csv') || file.name.endsWith('.txt')) {
        const text = await file.text();
        const linhas = text.split(/\r?\n/).filter((l) => l.trim().length > 0);
        if (linhas.length <= 1) {
          throw new Error('A planilha selecionada está vazia ou não possui colaboradores.');
        }

        // Detecta separador (, ou ;)
        const headerLine = linhas[0];
        const separador = headerLine.includes(';') ? ';' : ',';
        const headers = headerLine.split(separador).map((h) => h.trim().replace(/^["']|["']$/g, ''));

        for (let i = 1; i < linhas.length; i++) {
          const colunas = linhas[i].split(separador).map((c) => c.trim().replace(/^["']|["']$/g, ''));
          const objetoLinha: Record<string, string> = {};
          headers.forEach((h, idx) => {
            objetoLinha[h] = colunas[idx] ?? '';
          });
          dadosProcessados.push(objetoLinha);
        }
      } else {
        // Arquivo .xlsx / .xls via SheetJS
        const XLSX = await carregarSheetJs();
        const arrayBuffer = await file.arrayBuffer();
        const workbook = XLSX.read(arrayBuffer, { type: 'array' });
        const sheetName = workbook.SheetNames[0];
        if (!sheetName) {
          throw new Error('Nenhuma aba encontrada no arquivo Excel.');
        }
        const worksheet = workbook.Sheets[sheetName];
        dadosProcessados = XLSX.utils.sheet_to_json(worksheet, { defval: '' });
      }

      const colaboradoresExtraidos = processarLinhasImportadas(dadosProcessados);

      if (colaboradoresExtraidos.length === 0) {
        throw new Error('Nenhum colaborador válido foi encontrado. Certifique-se de que a planilha possui a coluna "Nome".');
      }

      setExcelPreview(colaboradoresExtraidos);
    } catch (err: any) {
      setExcelErro(err?.message || 'Falha ao ler o arquivo Excel. Verifique o formato.');
      setExcelPreview([]);
    } finally {
      setIsProcessandoExcel(false);
      if (excelInputRef.current) {
        excelInputRef.current.value = '';
      }
    }
  };

  const handleConfirmarImportacao = () => {
    if (excelPreview.length === 0) return;

    setColaboradoresAdicionados((prev) => [...excelPreview, ...prev]);

    if (onImportarColaboradores) {
      onImportarColaboradores(excelPreview);
    }

    setExcelImportSucesso(true);
    setTimeout(() => {
      setModalExcelAberto(false);
      setExcelPreview([]);
      setExcelImportSucesso(false);
      setExcelArquivoNome('');
    }, 1200);
  };

  const baixarModeloExcel = () => {
    const csvContent =
      'Nome,Cargo,Telefone,Unidade\n' +
      'Lucas Albuquerque,Operador de Trator,(67) 99876-1122,Ribas do Rio Pardo\n' +
      'Guilherme Siqueira,Motosserrista Especializado,(67) 99123-4455,Água Clara\n' +
      'Anderson Ferreira,Ajudante Operacional,(67) 99765-8899,Ribas do Rio Pardo\n' +
      'Matheus Oliveira,Supervisor de Frentes,(67) 99654-7788,Água Clara\n';

    const blob = new Blob(['\uFEFF' + csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', 'modelo_colaboradores_excel.csv');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="space-y-6">
      {/* Top Header */}
      <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
        <div>
          <h2 className="text-xl font-bold tracking-tight text-foreground flex items-center gap-2">
            <Users className="w-5 h-5 text-emerald-400" />
            Quadro Geral de Colaboradores
          </h2>
          <p className="text-xs text-muted-foreground mt-0.5">
            Consulta rápida dos operadores, frentes de trabalho e banco de substitutos.
          </p>
        </div>

        <div className="flex items-center gap-2.5 flex-wrap">
          {/* Botão Subir Planilha Excel */}
          <Button
            type="button"
            variant="outline"
            onClick={() => setModalExcelAberto(true)}
            className="gap-2 border-emerald-500/40 bg-emerald-500/10 text-emerald-300 hover:bg-emerald-500/20 hover:text-emerald-200 transition-colors cursor-pointer"
          >
            <FileSpreadsheet className="w-4 h-4 text-emerald-400" />
            <span>Subir Planilha Excel</span>
          </Button>

          {/* Botão Cadastrar Colaborador Manual */}
          <Button
            type="button"
            onClick={() => setModalNovoAberto(true)}
            className="gap-2 bg-emerald-600 hover:bg-emerald-500 text-white shadow-sm cursor-pointer"
          >
            <Plus className="w-4 h-4" />
            <span>Novo Colaborador</span>
          </Button>
        </div>
      </div>

      {/* Barra de Filtros e Busca */}
      <div className="flex flex-col md:flex-row items-stretch md:items-center justify-between gap-3 p-3 rounded-2xl border border-border/60 bg-card/60 backdrop-blur-md">
        <div className="relative flex-1">
          <Search className="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground" />
          <Input
            placeholder="Buscar por nome, cargo ou veículo..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="pl-9 bg-background/50 border-border/60 text-sm"
          />
        </div>

        <div className="flex items-center gap-2 overflow-x-auto pb-1 md:pb-0">
          <div className="flex items-center gap-1 bg-background/40 p-1 rounded-xl border border-border/50">
            <button
              type="button"
              onClick={() => setFilterRegional('todas')}
              className={cn(
                'px-2.5 py-1 rounded-lg text-xs font-semibold transition-colors',
                filterRegional === 'todas'
                  ? 'bg-emerald-600 text-white'
                  : 'text-muted-foreground hover:text-foreground'
              )}
            >
              Todas
            </button>
            <button
              type="button"
              onClick={() => setFilterRegional('ribas')}
              className={cn(
                'px-2.5 py-1 rounded-lg text-xs font-semibold transition-colors',
                filterRegional === 'ribas'
                  ? 'bg-emerald-600 text-white'
                  : 'text-muted-foreground hover:text-foreground'
              )}
            >
              Ribas
            </button>
            <button
              type="button"
              onClick={() => setFilterRegional('agua_clara')}
              className={cn(
                'px-2.5 py-1 rounded-lg text-xs font-semibold transition-colors',
                filterRegional === 'agua_clara'
                  ? 'bg-emerald-600 text-white'
                  : 'text-muted-foreground hover:text-foreground'
              )}
            >
              Água Clara
            </button>
          </div>

          <div className="flex items-center gap-1 bg-background/40 p-1 rounded-xl border border-border/50">
            <button
              type="button"
              onClick={() => setFilterStatus('todos')}
              className={cn(
                'px-2.5 py-1 rounded-lg text-xs font-semibold transition-colors',
                filterStatus === 'todos'
                  ? 'bg-primary text-primary-foreground'
                  : 'text-muted-foreground hover:text-foreground'
              )}
            >
              Todos ({todosColaboradores.length})
            </button>
            <button
              type="button"
              onClick={() => setFilterStatus('presente')}
              className={cn(
                'px-2.5 py-1 rounded-lg text-xs font-semibold transition-colors',
                filterStatus === 'presente'
                  ? 'bg-emerald-600 text-white'
                  : 'text-muted-foreground hover:text-emerald-400'
              )}
            >
              Presentes
            </button>
            <button
              type="button"
              onClick={() => setFilterStatus('falta')}
              className={cn(
                'px-2.5 py-1 rounded-lg text-xs font-semibold transition-colors',
                filterStatus === 'falta'
                  ? 'bg-rose-600 text-white'
                  : 'text-muted-foreground hover:text-rose-400'
              )}
            >
              Faltas
            </button>
          </div>
        </div>
      </div>

      {/* Grid de Cards de Colaboradores */}
      {colaboradoresFiltrados.length === 0 ? (
        <div className="flex flex-col items-center justify-center p-12 text-center border border-dashed border-border/60 rounded-2xl bg-card/30">
          <Users className="w-10 h-10 text-muted-foreground mb-3 opacity-50" />
          <h3 className="text-base font-semibold text-foreground">Nenhum colaborador encontrado</h3>
          <p className="text-xs text-muted-foreground mt-1 max-w-sm">
            Nenhum registro atende aos critérios do filtro ou busca atual. Você pode cadastrar manualmente ou subir uma planilha Excel.
          </p>
          <div className="flex items-center gap-3 mt-4">
            <Button
              type="button"
              variant="outline"
              size="sm"
              onClick={() => setModalExcelAberto(true)}
              className="gap-2 border-emerald-500/40 text-emerald-300"
            >
              <FileSpreadsheet className="w-3.5 h-3.5" />
              Subir Planilha Excel
            </Button>
            <Button
              type="button"
              size="sm"
              onClick={() => setModalNovoAberto(true)}
              className="gap-2 bg-emerald-600 hover:bg-emerald-500 text-white"
            >
              <Plus className="w-3.5 h-3.5" />
              Novo Colaborador
            </Button>
          </div>
        </div>
      ) : (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
          {colaboradoresFiltrados.map((colab) => {
            const statusInfo = statusConfig[colab.status] || statusConfig.presente;

            return (
              <Card
                key={colab.id}
                className="overflow-hidden border-border/60 hover:border-emerald-500/40 hover:shadow-lg transition-all flex flex-col justify-between bg-card/80"
              >
                <div className="p-4 space-y-3">
                  <div className="flex items-start justify-between gap-3">
                    <div className="flex items-center gap-3">
                      <div
                        onClick={() =>
                          colab.foto &&
                          setFotoModalAberta({
                            url: colab.foto,
                            nome: colab.nome,
                            cargo: colab.cargo,
                          })
                        }
                        className={cn(
                          'w-13 h-13 rounded-xl overflow-hidden border-2 shrink-0 bg-zinc-900 shadow-sm flex items-center justify-center cursor-pointer transition-transform hover:scale-105',
                          colab.status === 'falta'
                            ? 'border-rose-500/60'
                            : colab.status === 'substituto'
                            ? 'border-amber-500/60'
                            : 'border-emerald-500/60'
                        )}
                        title={colab.foto ? 'Clique para ampliar a foto' : undefined}
                      >
                        {colab.foto ? (
                          <img
                            src={colab.foto}
                            alt={colab.nome}
                            className={cn(
                              'w-full h-full object-cover',
                              colab.status === 'falta' && 'grayscale opacity-60'
                            )}
                          />
                        ) : (
                          <span className="font-bold text-xs text-zinc-300">
                            {getIniciais(colab.nome)}
                          </span>
                        )}
                      </div>

                      <div className="min-w-0 flex-1">
                        <h4 className="text-sm font-bold text-foreground truncate" title={colab.nome}>
                          {colab.nome}
                        </h4>
                        <p className="text-xs text-muted-foreground truncate" title={colab.cargo}>
                          {colab.cargo}
                        </p>
                      </div>
                    </div>

                    <Badge
                      variant="outline"
                      className={cn('text-[10px] px-2 py-0.5 border shrink-0 font-bold', statusInfo.className)}
                    >
                      {statusInfo.label}
                    </Badge>
                  </div>

                  <div className="pt-2 border-t border-border/40 space-y-1.5 text-xs text-muted-foreground">
                    <div className="flex items-center justify-between">
                      <span className="text-[11px]">Unidade:</span>
                      <span className="font-medium text-foreground text-[11px]">
                        {regionalLabel[colab.regional] || colab.regional}
                      </span>
                    </div>

                    <div className="flex items-center justify-between">
                      <span className="text-[11px]">Veículo / Posição:</span>
                      <span className="font-medium text-foreground text-[11px] truncate max-w-[130px] text-right">
                        {colab.veiculoPrefixo}
                      </span>
                    </div>

                    {colab.telefone && (
                      <div className="flex items-center justify-between">
                        <span className="text-[11px]">Telefone:</span>
                        <a
                          href={`tel:${colab.telefone.replace(/\D/g, '')}`}
                          className="font-medium text-emerald-400 hover:underline text-[11px] flex items-center gap-1"
                        >
                          <Phone className="w-3 h-3" />
                          {colab.telefone}
                        </a>
                      </div>
                    )}

                    {colab.status === 'falta' && colab.motivoFalta && (
                      <div className="mt-2 p-2 rounded-lg bg-rose-500/10 border border-rose-500/20 text-rose-300 text-[11px]">
                        <span className="font-semibold">Motivo:</span> {colab.motivoFalta}
                      </div>
                    )}

                    {colab.status === 'substituto' && colab.substitutoNome && (
                      <div className="mt-2 p-2 rounded-lg bg-amber-500/10 border border-amber-500/20 text-amber-300 text-[11px]">
                        <span className="font-semibold">Substituído por:</span> {colab.substitutoNome}
                      </div>
                    )}
                  </div>
                </div>
              </Card>
            );
          })}
        </div>
      )}

      {/* MODAL DE SUBIR PLANILHA EXCEL */}
      {modalExcelAberto && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/75 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="w-full max-w-2xl bg-card border border-border/80 rounded-2xl shadow-2xl overflow-hidden flex flex-col max-h-[90vh]">
            <div className="p-4 sm:p-5 border-b border-border/50 flex items-center justify-between bg-muted/20">
              <div className="flex items-center gap-2.5">
                <div className="w-9 h-9 rounded-xl bg-emerald-500/15 border border-emerald-500/30 flex items-center justify-center text-emerald-400">
                  <FileSpreadsheet className="w-5 h-5" />
                </div>
                <div>
                  <h3 className="font-bold text-base text-foreground">Importar Colaboradores via Excel</h3>
                  <p className="text-xs text-muted-foreground">
                    Carregue arquivos .xlsx, .xls ou .csv com os dados da sua equipe
                  </p>
                </div>
              </div>
              <button
                type="button"
                onClick={() => {
                  setModalExcelAberto(false);
                  setExcelPreview([]);
                  setExcelErro(null);
                }}
                className="p-1.5 rounded-lg text-muted-foreground hover:text-foreground hover:bg-muted/50"
              >
                <X className="w-5 h-5" />
              </button>
            </div>

            <div className="p-4 sm:p-6 overflow-y-auto space-y-4 flex-1">
              {/* Área de Drop e Upload */}
              <input
                ref={excelInputRef}
                type="file"
                accept=".xlsx, .xls, .csv"
                onChange={handleArquivoExcelSelecionado}
                className="hidden"
              />

              <div
                onClick={() => excelInputRef.current?.click()}
                className={cn(
                  'border-2 border-dashed rounded-2xl p-6 sm:p-8 flex flex-col items-center justify-center text-center cursor-pointer transition-all',
                  isProcessandoExcel
                    ? 'border-emerald-500/50 bg-emerald-500/5'
                    : 'border-border/80 bg-background/40 hover:border-emerald-500/60 hover:bg-emerald-500/5'
                )}
              >
                {isProcessandoExcel ? (
                  <div className="flex flex-col items-center gap-2">
                    <Loader2 className="w-8 h-8 text-emerald-400 animate-spin" />
                    <p className="text-sm font-semibold text-foreground">Processando dados da planilha...</p>
                    <p className="text-xs text-muted-foreground">Isso levará apenas alguns segundos.</p>
                  </div>
                ) : (
                  <>
                    <div className="w-12 h-12 rounded-2xl bg-emerald-500/10 border border-emerald-500/25 flex items-center justify-center text-emerald-400 mb-3 shadow-inner">
                      <FileUp className="w-6 h-6" />
                    </div>
                    <p className="text-sm font-bold text-foreground">
                      Clique para selecionar a planilha no seu computador
                    </p>
                    <p className="text-xs text-muted-foreground mt-1">
                      Formatos aceitos: <span className="text-emerald-400 font-semibold">.XLSX, .XLS, .CSV</span>
                    </p>
                    <p className="text-[11px] text-muted-foreground/80 mt-2">
                      Colunas recomendadas: <strong>Nome, Cargo, Telefone, Unidade</strong>
                    </p>
                  </>
                )}
              </div>

              {/* Botão de baixar planilha modelo */}
              <div className="flex items-center justify-between p-3 rounded-xl bg-muted/20 border border-border/50 text-xs">
                <span className="text-muted-foreground">
                  Precisa de uma planilha de exemplo para preencher?
                </span>
                <button
                  type="button"
                  onClick={baixarModeloExcel}
                  className="font-semibold text-emerald-400 hover:text-emerald-300 flex items-center gap-1.5 cursor-pointer hover:underline"
                >
                  <Download className="w-3.5 h-3.5" />
                  Baixar Modelo CSV/Excel
                </button>
              </div>

              {/* Alerta de Erro */}
              {excelErro && (
                <div className="p-3.5 rounded-xl bg-rose-500/10 border border-rose-500/25 flex items-start gap-2.5 text-rose-300 text-xs">
                  <AlertCircle className="w-4 h-4 shrink-0 mt-0.5" />
                  <div>
                    <span className="font-semibold">Erro ao importar: </span>
                    {excelErro}
                  </div>
                </div>
              )}

              {/* Alerta de Sucesso */}
              {excelImportSucesso && (
                <div className="p-3.5 rounded-xl bg-emerald-500/15 border border-emerald-500/30 flex items-center gap-2.5 text-emerald-300 text-xs">
                  <CheckCircle2 className="w-4 h-4 shrink-0 text-emerald-400" />
                  <span className="font-semibold">Colaboradores adicionados com sucesso ao quadro e banco de reservas!</span>
                </div>
              )}

              {/* Pré-visualização dos dados importados */}
              {excelPreview.length > 0 && !excelImportSucesso && (
                <div className="space-y-3">
                  <div className="flex items-center justify-between">
                    <span className="text-xs font-bold text-foreground flex items-center gap-1.5">
                      <Sparkles className="w-3.5 h-3.5 text-emerald-400" />
                      {excelPreview.length} colaboradores identificados em {excelArquivoNome}
                    </span>
                    <Badge variant="outline" className="text-[11px] border-emerald-500/30 text-emerald-300">
                      Pronto para importação
                    </Badge>
                  </div>

                  <div className="max-h-52 overflow-y-auto rounded-xl border border-border/60 bg-background/50 divide-y divide-border/40">
                    {excelPreview.map((item, i) => (
                      <div key={i} className="p-2.5 flex items-center justify-between text-xs hover:bg-muted/30">
                        <div className="min-w-0 pr-3">
                          <p className="font-semibold text-foreground truncate">{item.nome}</p>
                          <p className="text-[11px] text-muted-foreground truncate">{item.cargo || 'Operador Florestal'}</p>
                        </div>
                        <div className="flex items-center gap-2 text-right shrink-0">
                          <Badge variant="secondary" className="text-[10px] py-0 px-2">
                            {regionalLabel[item.regional] || item.regional}
                          </Badge>
                          {item.telefone && (
                            <span className="text-[11px] text-muted-foreground hidden sm:inline">
                              {item.telefone}
                            </span>
                          )}
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>

            {/* Rodapé do Modal */}
            <div className="p-4 border-t border-border/50 bg-muted/10 flex items-center justify-end gap-2.5">
              <Button
                type="button"
                variant="outline"
                size="sm"
                onClick={() => {
                  setModalExcelAberto(false);
                  setExcelPreview([]);
                  setExcelErro(null);
                }}
              >
                Cancelar
              </Button>
              <Button
                type="button"
                size="sm"
                disabled={excelPreview.length === 0 || isProcessandoExcel || excelImportSucesso}
                onClick={handleConfirmarImportacao}
                className="gap-2 bg-emerald-600 hover:bg-emerald-500 text-white font-semibold cursor-pointer"
              >
                <CheckCircle2 className="w-4 h-4" />
                Confirmar e Inserir ({excelPreview.length})
              </Button>
            </div>
          </div>
        </div>
      )}

      {/* MODAL DE CADASTRO MANUAL */}
      {modalNovoAberto && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/75 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="w-full max-w-md bg-card border border-border/80 rounded-2xl shadow-2xl overflow-hidden">
            <div className="p-4 sm:p-5 border-b border-border/50 flex items-center justify-between bg-muted/20">
              <h3 className="font-bold text-base text-foreground flex items-center gap-2">
                <Plus className="w-4 h-4 text-emerald-400" />
                Novo Colaborador
              </h3>
              <button
                type="button"
                onClick={() => setModalNovoAberto(false)}
                className="p-1.5 rounded-lg text-muted-foreground hover:text-foreground hover:bg-muted/50"
              >
                <X className="w-5 h-5" />
              </button>
            </div>

            <form onSubmit={handleCadastrarColaborador} className="p-4 sm:p-5 space-y-4">
              <div className="flex flex-col items-center justify-center gap-2 pb-2">
                <input
                  ref={fotoInputRef}
                  type="file"
                  accept="image/*"
                  onChange={handleFotoUpload}
                  className="hidden"
                />
                <div
                  onClick={() => fotoInputRef.current?.click()}
                  className="w-20 h-20 rounded-2xl border-2 border-dashed border-emerald-500/40 bg-zinc-900 flex flex-col items-center justify-center cursor-pointer hover:border-emerald-500 overflow-hidden relative group"
                >
                  {novaFoto ? (
                    <img src={novaFoto} alt="Foto selecionada" className="w-full h-full object-cover" />
                  ) : (
                    <div className="flex flex-col items-center justify-center p-2 text-center text-muted-foreground group-hover:text-emerald-400">
                      <Camera className="w-5 h-5 mb-1" />
                      <span className="text-[10px]">Adicionar Foto</span>
                    </div>
                  )}
                </div>
              </div>

              <div className="space-y-1.5">
                <label className="text-xs font-semibold text-foreground">Nome do Colaborador *</label>
                <Input
                  required
                  placeholder="Ex: João da Silva"
                  value={novoNome}
                  onChange={(e) => setNovoNome(e.target.value)}
                />
              </div>

              <div className="space-y-1.5">
                <label className="text-xs font-semibold text-foreground">Cargo / Função</label>
                <Input
                  placeholder="Ex: Operador Florestal / Motosserrista"
                  value={novoCargo}
                  onChange={(e) => setNovoCargo(e.target.value)}
                />
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                <div className="space-y-1.5">
                  <label className="text-xs font-semibold text-foreground">Telefone de Contato</label>
                  <Input
                    placeholder="(67) 99999-9999"
                    value={novoTelefone}
                    onChange={(e) => setNovoTelefone(e.target.value)}
                  />
                </div>

                <div className="space-y-1.5">
                  <label className="text-xs font-semibold text-foreground">Unidade Operacional</label>
                  <select
                    value={novaUnidade}
                    onChange={(e) => setNovaUnidade(e.target.value as any)}
                    className="w-full h-10 px-3 text-sm rounded-xl border border-border/80 bg-background text-foreground focus:outline-none focus:ring-2 focus:ring-emerald-500/30"
                  >
                    <option value="ribas">Ribas do Rio Pardo</option>
                    <option value="agua_clara">Água Clara</option>
                  </select>
                </div>
              </div>

              <div className="pt-3 border-t border-border/50 flex items-center justify-end gap-2">
                <Button
                  type="button"
                  variant="outline"
                  size="sm"
                  onClick={() => setModalNovoAberto(false)}
                >
                  Cancelar
                </Button>
                <Button
                  type="submit"
                  size="sm"
                  className="bg-emerald-600 hover:bg-emerald-500 text-white font-semibold"
                >
                  Salvar Colaborador
                </Button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* MODAL DE FOTO AMPLIADA */}
      {fotoModalAberta && (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/85 backdrop-blur-md animate-in fade-in"
          onClick={() => setFotoModalAberta(null)}
        >
          <div
            className="relative max-w-sm w-full bg-card border border-border rounded-2xl p-4 shadow-2xl flex flex-col items-center"
            onClick={(e) => e.stopPropagation()}
          >
            <button
              type="button"
              onClick={() => setFotoModalAberta(null)}
              className="absolute top-3 right-3 p-1 rounded-full bg-muted/60 hover:bg-muted text-foreground"
            >
              <X className="w-5 h-5" />
            </button>
            <div className="w-64 h-64 rounded-xl overflow-hidden border-2 border-emerald-500/50 shadow-xl bg-zinc-950 mt-2">
              <img
                src={fotoModalAberta.url}
                alt={fotoModalAberta.nome}
                className="w-full h-full object-cover"
              />
            </div>
            <div className="mt-3 text-center">
              <h4 className="text-base font-bold text-foreground">{fotoModalAberta.nome}</h4>
              <p className="text-xs text-muted-foreground">{fotoModalAberta.cargo}</p>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

