import React, { useState, useMemo, useRef } from 'react';
import {
  Users,
  Search,
  Phone,
  Building2,
  Briefcase,
  FileSpreadsheet,
  Download,
  CheckCircle2,
  AlertCircle,
  X,
  Plus,
  Trash2,
  FileCheck,
  Eye,
  FileUp,
  Loader2,
  CalendarDays,
} from 'lucide-react';
import { Card, CardContent } from './ui/card';
import { Badge } from './ui/badge';
import { Input } from './ui/input';
import { Button } from './ui/button';
import { cn } from '@/lib/utils';
import { Colaborador, Veiculo, StatusPresenca, MotivoFalta, Regional } from '../types';
import * as XLSX from 'xlsx';

export interface ColaboradorCompleto {
  id: string;
  nome: string;
  cargo: string;
  matricula?: string;
  foto: string;
  telefone: string;
  status: StatusPresenca;
  motivoFalta?: MotivoFalta;
  observacao?: string;
  substitutoNome?: string;
  equipeId: string;
  equipeNumero: 1 | 2;
  posicaoVeiculo: 'motorista' | 'frente_dir' | 'tras_esq' | 'tras_dir';
  veiculoPrefixo: string;
  veiculoPlaca: string;
  regional: 'ribas' | 'agua_clara';
  unidade?: string;
  dataAdmissao?: string;
}

export interface CollaboratorsManagementProps {
  veiculos?: Veiculo[];
  colaboradoresReserva?: Colaborador[];
  selectedRegional?: Regional;
  onUpdateColaboradorStatus?: (
    colabId: string,
    novoStatus: StatusPresenca,
    motivo?: MotivoFalta,
    obs?: string
  ) => void;
  onImportarColaboradores?: (novosColaboradores: ColaboradorCompleto[]) => void;
  onAdicionarColaborador?: (novoColaborador: ColaboradorCompleto) => void;
}

const statusConfig: Record<StatusPresenca, { label: string; className: string }> = {
  presente: { label: 'Presente', className: 'bg-emerald-500/20 text-emerald-400 border-emerald-500/30' },
  falta: { label: 'Falta', className: 'bg-rose-500/20 text-rose-400 border-rose-500/30' },
  substituto: { label: 'Substituto', className: 'bg-amber-500/20 text-amber-400 border-amber-500/30' },
};

const regionalLabel: Record<string, string> = {
  ribas: 'Ribas do Rio Pardo',
  agua_clara: 'Água Clara',
};

const getIniciais = (nome?: string) => {
  if (!nome) return 'CO';
  const partes = nome.trim().split(' ');
  if (partes.length === 1) return partes[0].substring(0, 2).toUpperCase();
  return (partes[0][0] + (partes[partes.length - 1]?.[0] || '')).toUpperCase();
};

export const CollaboratorsManagement: React.FC<CollaboratorsManagementProps> = ({
  veiculos = [],
  colaboradoresReserva = [],
  selectedRegional = 'todas',
  onUpdateColaboradorStatus,
  onImportarColaboradores,
  onAdicionarColaborador,
}) => {
  const [search, setSearch] = useState('');
  const [filterStatus, setFilterStatus] = useState<StatusPresenca | 'todos'>('todos');
  const [filterRegional, setFilterRegional] = useState<Regional | 'todas'>(selectedRegional);
  const [fotoModalAberta, setFotoModalAberta] = useState<{ url: string; nome: string; cargo: string } | null>(null);

  // Modal de cadastro manual
  const [modalNovoAberto, setModalNovoAberto] = useState(false);
  const [novoNome, setNovoNome] = useState('');
  const [novoCargo, setNovoCargo] = useState('');
  const [novoTelefone, setNovoTelefone] = useState('');
  const [novaFoto, setNovaFoto] = useState<string>('');
  const [novaUnidade, setNovaUnidade] = useState<'ribas' | 'agua_clara'>('ribas');
  const [novaDataAdmissao, setNovaDataAdmissao] = useState('15/01/2023');

  // Modal de Importação Excel
  const [modalExcelAberto, setModalExcelAberto] = useState(false);
  const [isProcessandoExcel, setIsProcessandoExcel] = useState(false);
  const [excelPreview, setExcelPreview] = useState<ColaboradorCompleto[]>([]);
  const [excelErro, setExcelErro] = useState<string | null>(null);
  const [excelArquivoNome, setExcelArquivoNome] = useState<string>('');
  const [excelImportSucesso, setExcelImportSucesso] = useState(false);
  const excelInputRef = useRef<HTMLInputElement>(null);

  const colaboradoresBase: ColaboradorCompleto[] = useMemo(() => {
    const lista: ColaboradorCompleto[] = [];
    (veiculos || []).forEach((v) => {
      if (!v || !v.assentos) return;
      const assentos: Array<{ colab?: Colaborador; pos: ColaboradorCompleto['posicaoVeiculo'] }> = [
        { colab: v.assentos.motorista, pos: 'motorista' },
        { colab: v.assentos.frenteDir, pos: 'frente_dir' },
        { colab: v.assentos.trasEsq, pos: 'tras_esq' },
        { colab: v.assentos.trasDir, pos: 'tras_dir' },
      ];
      assentos.forEach(({ colab, pos }) => {
        if (!colab) return;
        lista.push({
          id: colab.id,
          nome: colab.nome || 'Sem Nome',
          cargo: colab.cargo || 'Operador',
          matricula: '',
          foto: colab.foto ?? '',
          telefone: colab.telefone ?? '',
          status: colab.status || 'presente',
          motivoFalta: colab.motivoFalta,
          observacao: colab.observacao,
          substitutoNome: colab.substitutoNome,
          equipeId: colab.equipeId || '',
          equipeNumero: colab.equipeNumero || 1,
          posicaoVeiculo: pos,
          veiculoPrefixo: v.prefixo || '',
          veiculoPlaca: v.placa || '',
          regional: v.regional || 'ribas',
          unidade: colab.unidade || (v.regional === 'agua_clara' ? 'Água Clara' : 'Ribas do Rio Pardo'),
          dataAdmissao: colab.dataAdmissao || '10/02/2023',
        });
      });
    });

    (colaboradoresReserva || []).forEach((r, idx) => {
      if (!r) return;
      lista.push({
        id: r.id || `res-${idx}`,
        nome: r.nome || 'Colaborador Reserva',
        cargo: r.cargo || 'Reserva Operacional',
        matricula: '',
        foto: r.foto || '',
        telefone: r.telefone || '',
        status: r.status || 'presente',
        motivoFalta: r.motivoFalta,
        observacao: r.observacao,
        substitutoNome: r.substitutoNome,
        equipeId: 'reserva',
        equipeNumero: 1,
        posicaoVeiculo: 'motorista',
        veiculoPrefixo: 'Banco de Reserva',
        veiculoPlaca: '-',
        regional: 'ribas',
        unidade: r.unidade || 'Ribas do Rio Pardo',
        dataAdmissao: r.dataAdmissao || '05/06/2023',
      });
    });

    return lista;
  }, [veiculos, colaboradoresReserva]);

  const [colaboradoresAdicionados, setColaboradoresAdicionados] = useState<ColaboradorCompleto[]>([]);

  const todosColaboradores = useMemo(() => {
    return [...colaboradoresBase, ...colaboradoresAdicionados];
  }, [colaboradoresBase, colaboradoresAdicionados]);

  const colaboradoresFiltrados = useMemo(() => {
    return todosColaboradores.filter((c) => {
      if (!c) return false;
      const matchSearch =
        !search ||
        (c.nome || '').toLowerCase().includes(search.toLowerCase()) ||
        (c.cargo || '').toLowerCase().includes(search.toLowerCase()) ||
        (c.veiculoPlaca || '').toLowerCase().includes(search.toLowerCase()) ||
        (c.veiculoPrefixo || '').toLowerCase().includes(search.toLowerCase()) ||
        (c.unidade || '').toLowerCase().includes(search.toLowerCase());

      const matchStatus = filterStatus === 'todos' || c.status === filterStatus;
      const matchRegional = filterRegional === 'todas' || c.regional === filterRegional;

      return matchSearch && matchStatus && matchRegional;
    });
  }, [todosColaboradores, search, filterStatus, filterRegional]);

  const handleFotoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      if (event.target?.result) {
        setNovaFoto(event.target.result as string);
      }
    };
    reader.readAsDataURL(file);
  };

  const handleCadastrarColaborador = (e: React.FormEvent) => {
    e.preventDefault();
    if (!novoNome.trim()) return;

    const novo: ColaboradorCompleto = {
      id: `colab-custom-${Date.now()}`,
      nome: novoNome.trim(),
      cargo: novoCargo.trim() || 'Operador Florestal',
      matricula: '',
      foto: novaFoto,
      telefone: novoTelefone.trim(),
      status: 'presente',
      equipeId: 'reserva',
      equipeNumero: 1,
      posicaoVeiculo: 'motorista',
      veiculoPrefixo: 'Banco de Reserva',
      veiculoPlaca: '-',
      regional: novaUnidade,
      unidade: novaUnidade === 'agua_clara' ? 'Água Clara' : 'Ribas do Rio Pardo',
      dataAdmissao: novaDataAdmissao.trim() || '15/01/2023',
    };

    setColaboradoresAdicionados((prev) => [novo, ...prev]);
    if (onAdicionarColaborador) onAdicionarColaborador(novo);

    setNovoNome('');
    setNovoCargo('');
    setNovoTelefone('');
    setNovaFoto('');
    setNovaDataAdmissao('15/01/2023');
    setModalNovoAberto(false);
  };

  // Processamento do Arquivo Excel (.xlsx / .xls / .csv)
  const processarArquivoExcel = async (file: File) => {
    setExcelArquivoNome(file.name);
    setExcelErro(null);
    setIsProcessandoExcel(true);
    setExcelPreview([]);

    try {
      const buffer = await file.arrayBuffer();
      const workbook = XLSX.read(buffer, { type: 'array' });
      const primeiraAbaNome = workbook.SheetNames[0];
      const worksheet = workbook.Sheets[primeiraAbaNome];

      if (!worksheet) {
        throw new Error('A planilha fornecida está vazia ou ilegível.');
      }

      const linhasJson = XLSX.utils.sheet_to_json<Record<string, any>>(worksheet, { defval: '' });

      if (linhasJson.length === 0) {
        throw new Error('Nenhuma linha de dados encontrada na planilha.');
      }

      const importados: ColaboradorCompleto[] = linhasJson
        .map((linha, idx) => {
          // Busca inteligente de campos: Nome, Unidade, Função e Data de Admissão
          const nome =
            linha['Nome'] ||
            linha['NOME'] ||
            linha['Nome Completo'] ||
            linha['Colaborador'] ||
            linha['nome'] ||
            Object.values(linha)[0];

          if (!nome || String(nome).trim() === '') return null;

          const unidadeValor =
            linha['Unidade'] ||
            linha['UNIDADE'] ||
            linha['unidade'] ||
            linha['Regional'] ||
            linha['Filial'] ||
            '';

          const funcaoValor =
            linha['Função'] ||
            linha['FUNÇÃO'] ||
            linha['Funcao'] ||
            linha['FUNCAO'] ||
            linha['Cargo'] ||
            linha['CARGO'] ||
            linha['funcao'] ||
            linha['cargo'] ||
            'Operador Florestal';

          const dataAdmissaoValor =
            linha['Data de Admissão'] ||
            linha['DATA DE ADMISSÃO'] ||
            linha['Data Admissao'] ||
            linha['Data Admissão'] ||
            linha['DATA ADMISSAO'] ||
            linha['Admissão'] ||
            linha['Admissao'] ||
            linha['data_admissao'] ||
            '15/01/2023';

          const telefone =
            linha['Telefone'] ||
            linha['TELEFONE'] ||
            linha['Contato'] ||
            '(67) 99999-0000';

          const reg: 'ribas' | 'agua_clara' =
            String(unidadeValor).toLowerCase().includes('clara')
              ? 'agua_clara'
              : 'ribas';

          const colab: ColaboradorCompleto = {
            id: `colab-excel-${Date.now()}-${idx}`,
            nome: String(nome).trim(),
            cargo: String(funcaoValor).trim(),
            matricula: '',
            foto: '',
            telefone: String(telefone).trim(),
            status: 'presente',
            equipeId: 'reserva',
            equipeNumero: 1,
            posicaoVeiculo: 'motorista',
            veiculoPrefixo: 'Banco de Reserva',
            veiculoPlaca: '-',
            regional: reg,
            unidade: reg === 'agua_clara' ? 'Água Clara' : 'Ribas do Rio Pardo',
            dataAdmissao: String(dataAdmissaoValor).trim(),
          };

          return colab;
        })
        .filter(Boolean) as ColaboradorCompleto[];

      if (importados.length === 0) {
        throw new Error('Não foi possível identificar nomes nas colunas. Certifique-se de ter colunas Nome, Unidade, Função e Data de Admissão.');
      }

      setExcelPreview(importados);
    } catch (err: any) {
      setExcelErro(err.message || 'Erro ao processar o arquivo Excel.');
    } finally {
      setIsProcessandoExcel(false);
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      processarArquivoExcel(file);
    }
  };

  const confirmarImportacaoExcel = () => {
    if (excelPreview.length === 0) return;

    setColaboradoresAdicionados((prev) => [...excelPreview, ...prev]);
    if (onImportarColaboradores) {
      onImportarColaboradores(excelPreview);
    }

    setExcelImportSucesso(true);
    setTimeout(() => {
      setExcelImportSucesso(false);
      setModalExcelAberto(false);
      setExcelPreview([]);
      setExcelArquivoNome('');
    }, 1200);
  };

  // Exportação padrão com Nome, Unidade, Função e Data de Admissão
  const exportarExcel = () => {
    const dados = colaboradoresFiltrados.map((c) => ({
      'Nome': c.nome,
      'Unidade': c.unidade || (c.regional === 'agua_clara' ? 'Água Clara' : 'Ribas do Rio Pardo'),
      'Função': c.cargo,
      'Data de Admissão': c.dataAdmissao || '15/01/2023',
      'Telefone': c.telefone || '-',
      'Status': c.status === 'presente' ? 'Presente' : c.status === 'falta' ? 'Falta' : 'Substituto',
      'Veículo': c.veiculoPrefixo,
    }));

    const worksheet = XLSX.utils.json_to_sheet(dados);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, 'Colaboradores');

    worksheet['!cols'] = [
      { wch: 30 }, // Nome
      { wch: 22 }, // Unidade
      { wch: 25 }, // Função
      { wch: 18 }, // Data de Admissão
      { wch: 18 }, // Telefone
      { wch: 15 }, // Status
      { wch: 20 }, // Veículo
    ];

    XLSX.writeFile(workbook, `colaboradores_exportacao_${new Date().toISOString().split('T')[0]}.xlsx`);
  };

  // Baixar modelo de planilha Excel com as 4 colunas solicitadas
  const baixarModeloExcel = () => {
    const modelo = [
      {
        'Nome': 'Carlos Eduardo Silva',
        'Unidade': 'Ribas do Rio Pardo',
        'Função': 'Motorista Florestal',
        'Data de Admissão': '12/03/2022',
        'Telefone': '(67) 99876-1234',
      },
      {
        'Nome': 'Lucas Santana Rocha',
        'Unidade': 'Água Clara',
        'Função': 'Operador de Máquinas',
        'Data de Admissão': '05/08/2021',
        'Telefone': '(67) 99123-4567',
      },
      {
        'Nome': 'Marcos Vinícius Costa',
        'Unidade': 'Ribas do Rio Pardo',
        'Função': 'Ajudante Geral',
        'Data de Admissão': '19/01/2023',
        'Telefone': '(67) 99988-7766',
      },
    ];

    const ws = XLSX.utils.json_to_sheet(modelo);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, 'Modelo');

    ws['!cols'] = [
      { wch: 28 }, // Nome
      { wch: 22 }, // Unidade
      { wch: 25 }, // Função
      { wch: 18 }, // Data de Admissão
      { wch: 18 }, // Telefone
    ];

    XLSX.writeFile(wb, 'modelo_importacao_colaboradores.xlsx');
  };

  return (
    <div className="space-y-5">
      {/* Barra de Ações Superior */}
      <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3 bg-card/60 p-4 rounded-2xl border border-border/80 backdrop-blur-md shadow-sm">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-xl bg-emerald-500/10 border border-emerald-500/20 flex items-center justify-center text-emerald-400">
            <Users className="w-5 h-5" />
          </div>
          <div>
            <h2 className="text-base font-bold text-foreground">Gestão de Colaboradores</h2>
            <p className="text-xs text-muted-foreground">
              Total de <span className="text-foreground font-semibold tabular-nums">{colaboradoresFiltrados.length}</span> colaboradores
            </p>
          </div>
        </div>

        <div className="flex items-center gap-2 flex-wrap">
          {/* Botão Subir Planilha Excel */}
          <Button
            type="button"
            onClick={() => setModalExcelAberto(true)}
            className="gap-2 bg-emerald-600 hover:bg-emerald-500 text-white shadow-sm font-semibold text-xs h-9"
          >
            <FileSpreadsheet className="w-4 h-4" />
            <span>Importar Planilha</span>
          </Button>

          {/* Botão Exportar Excel com Nome, Unidade, Função e Data de Admissão */}
          <Button
            type="button"
            variant="outline"
            onClick={exportarExcel}
            className="gap-2 border-border/70 hover:bg-muted/60 text-xs h-9 font-semibold"
          >
            <Download className="w-3.5 h-3.5 text-muted-foreground" />
            <span>Exportar Planilha</span>
          </Button>

          {/* Botão Novo Colaborador */}
          <Button
            type="button"
            variant="outline"
            onClick={() => setModalNovoAberto(true)}
            className="gap-2 border-border/70 hover:bg-muted/60 text-xs h-9 font-semibold"
          >
            <Plus className="w-3.5 h-3.5 text-muted-foreground" />
            <span>Novo</span>
          </Button>
        </div>
      </div>

      {/* Filtros e Busca */}
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
        <div className="relative">
          <Search className="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground" />
          <Input
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder="Buscar por nome, função ou unidade..."
            className="pl-9 h-10 rounded-xl bg-card border-border text-xs"
          />
        </div>

        <div className="flex items-center gap-1.5 overflow-x-auto pb-1">
          {(['todos', 'presente', 'falta', 'substituto'] as const).map((st) => (
            <button
              key={st}
              onClick={() => setFilterStatus(st)}
              className={cn(
                'px-3 py-2 rounded-xl text-xs font-semibold whitespace-nowrap transition-colors border',
                filterStatus === st
                  ? 'bg-zinc-800 text-foreground border-border'
                  : 'bg-card/40 text-muted-foreground border-transparent hover:bg-card hover:text-foreground'
              )}
            >
              {st === 'todos' ? 'Todos Status' : st === 'presente' ? 'Presente' : st === 'falta' ? 'Falta' : 'Substituto'}
            </button>
          ))}
        </div>

        <div className="flex items-center gap-1.5 overflow-x-auto pb-1">
          {(['todas', 'ribas', 'agua_clara'] as const).map((reg) => (
            <button
              key={reg}
              onClick={() => setFilterRegional(reg)}
              className={cn(
                'px-3 py-2 rounded-xl text-xs font-semibold whitespace-nowrap transition-colors border',
                filterRegional === reg
                  ? 'bg-zinc-800 text-foreground border-border'
                  : 'bg-card/40 text-muted-foreground border-transparent hover:bg-card hover:text-foreground'
              )}
            >
              {reg === 'todas' ? 'Todas Unidades' : regionalLabel[reg]}
            </button>
          ))}
        </div>
      </div>

      {/* Grid de Colaboradores com os novos campos integrados */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {colaboradoresFiltrados.map((c) => {
          const cfg = statusConfig[c.status] || statusConfig.presente;
          return (
            <Card key={c.id} className="border border-border/80 hover:border-border transition-all overflow-hidden bg-card/60 backdrop-blur-sm">
              <CardContent className="p-4 space-y-3">
                <div className="flex items-start gap-3.5">
                  <div
                    onClick={() => c.foto && setFotoModalAberta({ url: c.foto, nome: c.nome, cargo: c.cargo })}
                    className={cn(
                      'w-14 h-14 rounded-2xl overflow-hidden border-2 border-border/80 bg-zinc-900 shrink-0 shadow-sm flex items-center justify-center',
                      c.foto ? 'cursor-pointer hover:border-emerald-500/50' : ''
                    )}
                  >
                    {c.foto ? (
                      <img src={c.foto} alt={c.nome} className="w-full h-full object-cover" />
                    ) : (
                      <span className="text-zinc-300 font-bold text-base bg-emerald-950/40 w-full h-full flex items-center justify-center">
                        {getIniciais(c.nome)}
                      </span>
                    )}
                  </div>

                  <div className="flex-1 min-w-0">
                    <div className="flex items-center justify-between gap-2">
                      <Badge className={cn('text-[10px] px-2 py-0.5 border', cfg.className)}>
                        {cfg.label}
                      </Badge>
                      <span className="text-[11px] text-muted-foreground font-mono">
                        {c.veiculoPrefixo}
                      </span>
                    </div>

                    <h3 className="font-bold text-sm text-foreground truncate mt-1">{c.nome}</h3>
                    <p className="text-xs text-muted-foreground truncate flex items-center gap-1 mt-0.5">
                      <Briefcase className="w-3 h-3 text-muted-foreground/70" />
                      {c.cargo}
                    </p>
                  </div>
                </div>

                {/* Bloco de Unidade & Data de Admissão */}
                <div className="grid grid-cols-2 gap-2 pt-2 border-t border-border/40 text-[11px]">
                  <div className="flex items-center gap-1.5 text-muted-foreground truncate">
                    <Building2 className="w-3.5 h-3.5 text-emerald-400 shrink-0" />
                    <span className="truncate">{c.unidade || regionalLabel[c.regional]}</span>
                  </div>
                  <div className="flex items-center gap-1.5 text-muted-foreground justify-end font-mono">
                    <CalendarDays className="w-3.5 h-3.5 text-amber-400 shrink-0" />
                    <span className="tabular-nums">{c.dataAdmissao || '15/01/2023'}</span>
                  </div>
                </div>
              </CardContent>
            </Card>
          );
        })}
      </div>

      {/* Modal de Importação de Planilha Excel */}
      {modalExcelAberto && (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-background/80 backdrop-blur-md animate-in fade-in duration-200"
          onClick={() => setModalExcelAberto(false)}
        >
          <div
            className="relative w-full max-w-2xl bg-card border border-border rounded-3xl shadow-2xl overflow-hidden flex flex-col max-h-[90vh]"
            onClick={(e) => e.stopPropagation()}
          >
            {/* Header */}
            <div className="flex items-center justify-between px-6 py-4 border-b border-border bg-muted/20">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 rounded-2xl bg-emerald-500/10 border border-emerald-500/20 flex items-center justify-center text-emerald-400">
                  <FileSpreadsheet className="w-5 h-5" />
                </div>
                <div>
                  <h3 className="text-base font-bold text-foreground">Importar Planilha em Excel</h3>
                  <p className="text-xs text-muted-foreground">
                    Carregue a planilha contendo Nome, Unidade, Função e Data de Admissão
                  </p>
                </div>
              </div>
              <button
                type="button"
                onClick={() => setModalExcelAberto(false)}
                className="p-2 rounded-xl text-muted-foreground hover:text-foreground hover:bg-muted/60 transition-colors"
              >
                <X className="w-5 h-5" />
              </button>
            </div>

            {/* Conteúdo */}
            <div className="p-6 space-y-5 overflow-y-auto flex-1">
              {/* Card explicativo das 4 colunas */}
              <div className="p-4 rounded-2xl border border-emerald-500/30 bg-emerald-500/5 space-y-2">
                <p className="text-xs font-bold text-emerald-400 flex items-center gap-1.5">
                  <FileCheck className="w-4 h-4" /> Colunas Reconhecidas na Planilha:
                </p>
                <div className="grid grid-cols-2 sm:grid-cols-4 gap-2 text-[11px] text-foreground font-semibold">
                  <div className="bg-card/80 p-2 rounded-lg border border-border/60">
                    <span className="text-emerald-400">1.</span> Nome
                  </div>
                  <div className="bg-card/80 p-2 rounded-lg border border-border/60">
                    <span className="text-emerald-400">2.</span> Unidade
                  </div>
                  <div className="bg-card/80 p-2 rounded-lg border border-border/60">
                    <span className="text-emerald-400">3.</span> Função
                  </div>
                  <div className="bg-card/80 p-2 rounded-lg border border-border/60">
                    <span className="text-emerald-400">4.</span> Data de Admissão
                  </div>
                </div>
              </div>

              {/* Botão Baixar Modelo */}
              <div className="flex items-center justify-between p-3 rounded-xl border border-border bg-muted/20">
                <span className="text-xs text-muted-foreground">
                  Precisa do formato pronto? Baixe a planilha modelo:
                </span>
                <Button
                  type="button"
                  variant="outline"
                  size="sm"
                  onClick={baixarModeloExcel}
                  className="gap-1.5 text-xs font-semibold h-8"
                >
                  <Download className="w-3.5 h-3.5" />
                  Baixar Modelo .XLSX
                </Button>
              </div>

              {/* Área de Drop / Upload */}
              <div
                onClick={() => excelInputRef.current?.click()}
                className="border-2 border-dashed border-border/80 hover:border-emerald-500/60 rounded-2xl p-6 text-center cursor-pointer transition-colors bg-muted/10 hover:bg-emerald-500/5 group"
              >
                <input
                  ref={excelInputRef}
                  type="file"
                  accept=".xlsx, .xls, .csv"
                  onChange={handleFileChange}
                  className="hidden"
                />
                <div className="w-12 h-12 rounded-2xl bg-muted/60 group-hover:bg-emerald-500/20 text-muted-foreground group-hover:text-emerald-400 mx-auto flex items-center justify-center transition-colors mb-3">
                  <FileUp className="w-6 h-6" />
                </div>
                <p className="text-sm font-semibold text-foreground">
                  {excelArquivoNome ? excelArquivoNome : 'Clique para selecionar o arquivo Excel (.xlsx, .xls)'}
                </p>
                <p className="text-xs text-muted-foreground mt-1">
                  Arraste ou clique para carregar a lista de colaboradores
                </p>
              </div>

              {/* Feedback de Carregamento */}
              {isProcessandoExcel && (
                <div className="flex items-center justify-center gap-2 py-4 text-emerald-400 text-xs font-semibold">
                  <Loader2 className="w-4 h-4 animate-spin" />
                  Processando dados da planilha...
                </div>
              )}

              {/* Erro */}
              {excelErro && (
                <div className="p-3.5 rounded-xl border border-rose-500/30 bg-rose-500/10 text-rose-400 text-xs flex items-center gap-2">
                  <AlertCircle className="w-4 h-4 shrink-0" />
                  <span>{excelErro}</span>
                </div>
              )}

              {/* Pré-visualização dos Registros da Planilha */}
              {excelPreview.length > 0 && (
                <div className="space-y-2">
                  <div className="flex items-center justify-between">
                    <span className="text-xs font-bold text-muted-foreground">
                      Pré-visualização: {excelPreview.length} colaboradores encontrados
                    </span>
                    <Badge variant="outline" className="text-emerald-400 border-emerald-500/30 text-[10px]">
                      Pronto para importar
                    </Badge>
                  </div>

                  <div className="max-h-48 overflow-y-auto rounded-xl border border-border bg-card">
                    <table className="w-full text-left text-xs">
                      <thead className="bg-muted/40 border-b border-border/60 text-[10px] uppercase font-bold text-muted-foreground sticky top-0">
                        <tr>
                          <th className="p-2.5">Nome</th>
                          <th className="p-2.5">Unidade</th>
                          <th className="p-2.5">Função</th>
                          <th className="p-2.5">Data de Admissão</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-border/40">
                        {excelPreview.map((item, idx) => (
                          <tr key={idx} className="hover:bg-muted/20">
                            <td className="p-2.5 font-semibold text-foreground">{item.nome}</td>
                            <td className="p-2.5 text-muted-foreground">{item.unidade}</td>
                            <td className="p-2.5 text-muted-foreground">{item.cargo}</td>
                            <td className="p-2.5 font-mono text-muted-foreground">{item.dataAdmissao}</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                </div>
              )}

              {/* Sucesso */}
              {excelImportSucesso && (
                <div className="p-3.5 rounded-xl border border-emerald-500/30 bg-emerald-500/10 text-emerald-400 text-xs font-semibold flex items-center gap-2">
                  <CheckCircle2 className="w-4 h-4 shrink-0" />
                  <span>Colaboradores importados com sucesso!</span>
                </div>
              )}
            </div>

            {/* Rodapé com Ações */}
            <div className="flex items-center justify-end gap-2 px-6 py-4 border-t border-border bg-muted/20">
              <Button
                type="button"
                variant="ghost"
                onClick={() => setModalExcelAberto(false)}
                className="text-xs"
              >
                Cancelar
              </Button>
              <Button
                type="button"
                disabled={excelPreview.length === 0 || isProcessandoExcel || excelImportSucesso}
                onClick={confirmarImportacaoExcel}
                className="gap-2 bg-emerald-600 hover:bg-emerald-500 text-white font-semibold text-xs"
              >
                <CheckCircle2 className="w-4 h-4" />
                Confirmar e Inserir {excelPreview.length > 0 ? `(${excelPreview.length})` : ''}
              </Button>
            </div>
          </div>
        </div>
      )}

      {/* Modal Cadastro Manual com os 4 campos */}
      {modalNovoAberto && (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-background/80 backdrop-blur-md animate-in fade-in duration-200"
          onClick={() => setModalNovoAberto(false)}
        >
          <div
            className="relative w-full max-w-md bg-card border border-border rounded-3xl shadow-2xl overflow-hidden p-6 space-y-4"
            onClick={(e) => e.stopPropagation()}
          >
            <div className="flex items-center justify-between pb-3 border-b border-border">
              <h3 className="font-bold text-base text-foreground">Novo Colaborador</h3>
              <button
                type="button"
                onClick={() => setModalNovoAberto(false)}
                className="p-1 rounded-lg text-muted-foreground hover:text-foreground"
              >
                <X className="w-4 h-4" />
              </button>
            </div>

            <form onSubmit={handleCadastrarColaborador} className="space-y-3.5">
              <div>
                <label className="text-xs font-semibold text-muted-foreground mb-1 block">Nome Completo</label>
                <Input
                  required
                  placeholder="Ex: Carlos Eduardo Silva"
                  value={novoNome}
                  onChange={(e) => setNovoNome(e.target.value)}
                  className="h-9 text-xs"
                />
              </div>

              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="text-xs font-semibold text-muted-foreground mb-1 block">Unidade</label>
                  <select
                    value={novaUnidade}
                    onChange={(e) => setNovaUnidade(e.target.value as 'ribas' | 'agua_clara')}
                    className="w-full h-9 rounded-xl border border-input bg-card px-2 text-xs text-foreground focus:outline-none focus:ring-2 focus:ring-ring"
                  >
                    <option value="ribas">Ribas do Rio Pardo</option>
                    <option value="agua_clara">Água Clara</option>
                  </select>
                </div>

                <div>
                  <label className="text-xs font-semibold text-muted-foreground mb-1 block">Função / Cargo</label>
                  <Input
                    required
                    placeholder="Ex: Motorista Florestal"
                    value={novoCargo}
                    onChange={(e) => setNovoCargo(e.target.value)}
                    className="h-9 text-xs"
                  />
                </div>
              </div>

              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="text-xs font-semibold text-muted-foreground mb-1 block">Data de Admissão</label>
                  <Input
                    placeholder="DD/MM/AAAA"
                    value={novaDataAdmissao}
                    onChange={(e) => setNovaDataAdmissao(e.target.value)}
                    className="h-9 text-xs font-mono"
                  />
                </div>

                <div>
                  <label className="text-xs font-semibold text-muted-foreground mb-1 block">Telefone</label>
                  <Input
                    placeholder="(67) 99999-0000"
                    value={novoTelefone}
                    onChange={(e) => setNovoTelefone(e.target.value)}
                    className="h-9 text-xs"
                  />
                </div>
              </div>

              <div className="pt-2 flex justify-end gap-2">
                <Button type="button" variant="ghost" size="sm" onClick={() => setModalNovoAberto(false)}>
                  Cancelar
                </Button>
                <Button type="submit" size="sm" className="bg-emerald-600 hover:bg-emerald-500 text-white font-semibold">
                  Cadastrar
                </Button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Modal Visualização de Foto */}
      {fotoModalAberta && (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-background/90 backdrop-blur-md"
          onClick={() => setFotoModalAberta(null)}
        >
          <div className="relative max-w-sm w-full bg-card border border-border rounded-2xl overflow-hidden p-4 space-y-3" onClick={(e) => e.stopPropagation()}>
            <div className="w-full aspect-square rounded-xl overflow-hidden bg-zinc-900 border border-border">
              <img src={fotoModalAberta.url} alt={fotoModalAberta.nome} className="w-full h-full object-cover" />
            </div>
            <div className="text-center">
              <h4 className="font-bold text-foreground text-sm">{fotoModalAberta.nome}</h4>
              <p className="text-xs text-muted-foreground">{fotoModalAberta.cargo}</p>
            </div>
            <Button size="sm" variant="outline" className="w-full text-xs" onClick={() => setFotoModalAberta(null)}>
              Fechar
            </Button>
          </div>
        </div>
      )}
    </div>
  );
};

