      assentos.forEach(({ c, eq }) => {
        if (!c) return;
        lista.push({
          id: c.id,
          nome: c.nome,
          cargo: c.cargo,
          unidade: c.unidade || (v.regional === 'agua_clara' ? 'Água Clara' : 'Ribas do Rio Pardo'),
          dataAdmissao: c.dataAdmissao || '10/02/2023',
          regional: v.regional,
          status: c.status,
          motivo: c.motivoFalta || '-',
          veiculo: v.prefixo,
          placa: v.placa,
          equipe: eq,
        });
      });
    });

    colaboradoresReserva.forEach((r) => {
      if (!r) return;
      lista.push({
        id: r.id,
        nome: r.nome,
        cargo: r.cargo,
        unidade: r.unidade || 'Ribas do Rio Pardo',
        dataAdmissao: r.dataAdmissao || '05/06/2023',
        regional: 'ribas',
        status: r.status,
        motivo: r.motivoFalta || '-',
        veiculo: 'Banco de Reserva',
        placa: '-',
        equipe: 'Reserva',
