  // Processamento do Arquivo Excel (.xlsx / .xls / .csv)
  const processarArquivoExcel = async (file: File) => {
    setExcelArquivoNome(file.name);
    setExcelErro(null);
    setIsProcessandoExcel(true);
    setExcelPreview([]);

    try {
      const buffer = await file.arrayBuffer();
      const workbook = XLSX.read(buffer, { type: 'array' });
      const primeiraAbaNome = workbook.SheetNames[0];
      const worksheet = workbook.Sheets[primeiraAbaNome];

      if (!worksheet) {
        throw new Error('A planilha fornecida está vazia ou ilegível.');
      }

      const linhasJson = XLSX.utils.sheet_to_json<Record<string, any>>(worksheet, { defval: '' });

      if (linhasJson.length === 0) {
        throw new Error('Nenhuma linha de dados encontrada na planilha.');
      }

      const importados: ColaboradorCompleto[] = linhasJson
        .map((linha, idx) => {
          // Busca inteligente de campos: Nome, Unidade, Função e Data de Admissão
          const nome =
            linha['Nome'] ||
            linha['NOME'] ||
            linha['Nome Completo'] ||
            linha['Colaborador'] ||
            linha['nome'] ||
            Object.values(linha)[0];

          if (!nome || String(nome).trim() === '') return null;

          const unidadeValor =
            linha['Unidade'] ||
            linha['UNIDADE'] ||
            linha['unidade'] ||
            linha['Regional'] ||
            linha['Filial'] ||
            '';

          const funcaoValor =
            linha['Função'] ||
            linha['FUNÇÃO'] ||
            linha['Funcao'] ||
            linha['FUNCAO'] ||
            linha['Cargo'] ||
            linha['CARGO'] ||
            linha['funcao'] ||
            linha['cargo'] ||
            'Operador Florestal';

          const dataAdmissaoValor =
            linha['Data de Admissão'] ||
            linha['DATA DE ADMISSÃO'] ||
            linha['Data Admissao'] ||
            linha['Data Admissão'] ||
            linha['DATA ADMISSAO'] ||
            linha['Admissão'] ||
            linha['Admissao'] ||
            linha['data_admissao'] ||
            '15/01/2023';

          const telefone =
            linha['Telefone'] ||
            linha['TELEFONE'] ||
            linha['Contato'] ||
            '(67) 99999-0000';

          const reg: 'ribas' | 'agua_clara' =
            String(unidadeValor).toLowerCase().includes('clara')
              ? 'agua_clara'
              : 'ribas';

          const colab: ColaboradorCompleto = {
            id: `colab-excel-${Date.now()}-${idx}`,
            nome: String(nome).trim(),
            cargo: String(funcaoValor).trim(),
            matricula: '',
            foto: '',
            telefone: String(telefone).trim(),
            status: 'presente',
            equipeId: 'reserva',
            equipeNumero: 1,
            posicaoVeiculo: 'motorista',
            veiculoPrefixo: 'Banco de Reserva',
            veiculoPlaca: '-',
            regional: reg,
            unidade: reg === 'agua_clara' ? 'Água Clara' : 'Ribas do Rio Pardo',
            dataAdmissao: String(dataAdmissaoValor).trim(),
          };

          return colab;
        })
        .filter(Boolean) as ColaboradorCompleto[];

      if (importados.length === 0) {
        throw new Error('Não foi possível identificar nomes nas colunas. Certifique-se de ter colunas Nome, Unidade, Função e Data de Admissão.');
      }

      setExcelPreview(importados);
    } catch (err: any) {
      setExcelErro(err.message || 'Erro ao processar o arquivo Excel.');
    } finally {
      setIsProcessandoExcel(false);
    }
  };

