                <X className="w-4 h-4" />
              </button>
            </div>

            <form onSubmit={handleCadastrarColaborador} className="space-y-3.5">
              <div>
                <label className="text-xs font-semibold text-muted-foreground mb-1 block">Nome Completo</label>
                <Input
                  required
                  placeholder="Ex: Carlos Eduardo Silva"
                  value={novoNome}
                  onChange={(e) => setNovoNome(e.target.value)}
                  className="h-9 text-xs"
                />
              </div>

              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="text-xs font-semibold text-muted-foreground mb-1 block">Unidade</label>
                  <select
                    value={novaUnidade}
                    onChange={(e) => setNovaUnidade(e.target.value as 'ribas' | 'agua_clara')}
                    className="w-full h-9 rounded-xl border border-input bg-card px-2 text-xs text-foreground focus:outline-none focus:ring-2 focus:ring-ring"
                  >
                    <option value="ribas">Ribas do Rio Pardo</option>
                    <option value="agua_clara">Água Clara</option>
                  </select>
                </div>

                <div>
                  <label className="text-xs font-semibold text-muted-foreground mb-1 block">Função / Cargo</label>
                  <Input
                    required
                    placeholder="Ex: Motorista Florestal"
                    value={novoCargo}
                    onChange={(e) => setNovoCargo(e.target.value)}
                    className="h-9 text-xs"
                  />
                </div>
              </div>

              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="text-xs font-semibold text-muted-foreground mb-1 block">Data de Admissão</label>
                  <Input
                    placeholder="DD/MM/AAAA"
                    value={novaDataAdmissao}
                    onChange={(e) => setNovaDataAdmissao(e.target.value)}
                    className="h-9 text-xs font-mono"
                  />
                </div>

                <div>
                  <label className="text-xs font-semibold text-muted-foreground mb-1 block">Telefone</label>
                  <Input
                    placeholder="(67) 99999-0000"
                    value={novoTelefone}
                    onChange={(e) => setNovoTelefone(e.target.value)}
                    className="h-9 text-xs"
                  />
                </div>
              </div>

              <div className="pt-2 flex justify-end gap-2">
                <Button type="button" variant="ghost" size="sm" onClick={() => setModalNovoAberto(false)}>
                  Cancelar
                </Button>
                <Button type="submit" size="sm" className="bg-emerald-600 hover:bg-emerald-500 text-white font-semibold">
                  Cadastrar
                </Button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Modal Visualização de Foto */}
      {fotoModalAberta && (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-background/90 backdrop-blur-md"
          onClick={() => setFotoModalAberta(null)}
        >
          <div className="relative max-w-sm w-full bg-card border border-border rounded-2xl overflow-hidden p-4 space-y-3" onClick={(e) => e.stopPropagation()}>
            <div className="w-full aspect-square rounded-xl overflow-hidden bg-zinc-900 border border-border">
              <img src={fotoModalAberta.url} alt={fotoModalAberta.nome} className="w-full h-full object-cover" />
            </div>
            <div className="text-center">
              <h4 className="font-bold text-foreground text-sm">{fotoModalAberta.nome}</h4>
              <p className="text-xs text-muted-foreground">{fotoModalAberta.cargo}</p>
            </div>
            <Button size="sm" variant="outline" className="w-full text-xs" onClick={() => setFotoModalAberta(null)}>
              Fechar
            </Button>
          </div>
        </div>
      )}
    </div>
  );
};

