import React, { useState, useMemo, useRef } from 'react';
import {
  Users,
  Search,
  Phone,
  Building2,
  Briefcase,
  FileSpreadsheet,
  Download,
  CheckCircle2,
  AlertCircle,
  X,
  Plus,
  Trash2,
  FileCheck,
  Eye,
  FileUp,
  Loader2,
  CalendarDays,
} from 'lucide-react';
import { Card, CardContent } from './ui/card';
import { Badge } from './ui/badge';
import { Input } from './ui/input';
import { Button } from './ui/button';
import { cn } from '@/lib/utils';
import { Colaborador, Veiculo, StatusPresenca, MotivoFalta, Regional } from '../types';

export interface ColaboradorCompleto {
  id: string;
  nome: string;
  cargo: string;
  matricula?: string;
  foto: string;
  telefone: string;
  status: StatusPresenca;
  motivoFalta?: MotivoFalta;
  observacao?: string;
  substitutoNome?: string;
  equipeId: string;
  equipeNumero: 1 | 2;
  posicaoVeiculo: 'motorista' | 'frente_dir' | 'tras_esq' | 'tras_dir';
  veiculoPrefixo: string;
  veiculoPlaca: string;
  regional: 'ribas' | 'agua_clara';
  unidade?: string;
  dataAdmissao?: string;
}

export interface CollaboratorsManagementProps {
  veiculos?: Veiculo[];
  colaboradoresReserva?: Colaborador[];
  selectedRegional?: Regional;
  onUpdateColaboradorStatus?: (
    colabId: string,
    novoStatus: StatusPresenca,
    motivo?: MotivoFalta,
    obs?: string
  ) => void;
  onImportarColaboradores?: (novosColaboradores: ColaboradorCompleto[]) => void;
  onAdicionarColaborador?: (novoColaborador: ColaboradorCompleto) => void;
}

const statusConfig: Record<StatusPresenca, { label: string; className: string }> = {
  presente: { label: 'Presente', className: 'bg-emerald-500/20 text-emerald-400 border-emerald-500/30' },
  falta: { label: 'Falta', className: 'bg-rose-500/20 text-rose-400 border-rose-500/30' },
  substituto: { label: 'Substituto', className: 'bg-amber-500/20 text-amber-400 border-amber-500/30' },
};

const regionalLabel: Record<string, string> = {
  ribas: 'Ribas do Rio Pardo',
  agua_clara: 'Água Clara',
};

const getIniciais = (nome?: string) => {
  if (!nome) return 'CO';
  const partes = nome.trim().split(' ');
  if (partes.length === 1) return partes[0].substring(0, 2).toUpperCase();
  return (partes[0][0] + (partes[partes.length - 1]?.[0] || '')).toUpperCase();
};

export const CollaboratorsManagement: React.FC<CollaboratorsManagementProps> = ({
  veiculos = [],
  colaboradoresReserva = [],
  selectedRegional = 'todas',
  onImportarColaboradores,
  onAdicionarColaborador,
}) => {
  const [search, setSearch] = useState('');
  const [filterStatus, setFilterStatus] = useState<StatusPresenca | 'todos'>('todos');
  const [filterRegional, setFilterRegional] = useState<Regional | 'todas'>(selectedRegional);
  const [fotoModalAberta, setFotoModalAberta] = useState<{ url: string; nome: string; cargo: string } | null>(null);

  // Modal de cadastro manual
  const [modalNovoAberto, setModalNovoAberto] = useState(false);
  const [novoNome, setNovoNome] = useState('');
  const [novoCargo, setNovoCargo] = useState('');
  const [novoTelefone, setNovoTelefone] = useState('');
  const [novaFoto, setNovaFoto] = useState<string>('');
  const [novaUnidade, setNovaUnidade] = useState<'ribas' | 'agua_clara'>('ribas');
  const [novaDataAdmissao, setNovaDataAdmissao] = useState('15/01/2023');

  // Modal de Importação Excel
  const [modalExcelAberto, setModalExcelAberto] = useState(false);
  const [isProcessandoExcel, setIsProcessandoExcel] = useState(false);
  const [excelPreview, setExcelPreview] = useState<ColaboradorCompleto[]>([]);
  const [excelErro, setExcelErro] = useState<string | null>(null);
  const [excelArquivoNome, setExcelArquivoNome] = useState<string>('');
  const [excelImportSucesso, setExcelImportSucesso] = useState(false);
  const excelInputRef = useRef<HTMLInputElement>(null);

  const colaboradoresBase: ColaboradorCompleto[] = useMemo(() => {
    const lista: ColaboradorCompleto[] = [];
    (veiculos || []).forEach((v) => {
      if (!v || !v.assentos) return;
      const assentos: Array<{ colab?: Colaborador; pos: ColaboradorCompleto['posicaoVeiculo'] }> = [
        { colab: v.assentos.motorista, pos: 'motorista' },
        { colab: v.assentos.frenteDir, pos: 'frente_dir' },
        { colab: v.assentos.trasEsq, pos: 'tras_esq' },
        { colab: v.assentos.trasDir, pos: 'tras_dir' },
      ];
      assentos.forEach(({ colab, pos }) => {
        if (!colab) return;
        lista.push({
          id: colab.id,
          nome: colab.nome || 'Sem Nome',
          cargo: colab.cargo || 'Operador',
          matricula: '',
          foto: colab.foto ?? '',
          telefone: colab.telefone ?? '',
          status: colab.status || 'presente',
          motivoFalta: colab.motivoFalta,
          observacao: colab.observacao,
          substitutoNome: colab.substitutoNome,
          equipeId: colab.equipeId || '',
          equipeNumero: colab.equipeNumero || 1,
          posicaoVeiculo: pos,
          veiculoPrefixo: v.prefixo || '',
          veiculoPlaca: v.placa || '',
          regional: v.regional || 'ribas',
          unidade: colab.unidade || (v.regional === 'agua_clara' ? 'Água Clara' : 'Ribas do Rio Pardo'),
          dataAdmissao: colab.dataAdmissao || '10/02/2023',
        });
      });
    });

    (colaboradoresReserva || []).forEach((r, idx) => {
      if (!r) return;
      lista.push({
        id: r.id || `res-${idx}`,
        nome: r.nome || 'Colaborador Reserva',
        cargo: r.cargo || 'Reserva Operacional',
        matricula: '',
        foto: r.foto || '',
        telefone: r.telefone || '',
        status: r.status || 'presente',
        motivoFalta: r.motivoFalta,
        observacao: r.observacao,
        substitutoNome: r.substitutoNome,
        equipeId: 'reserva',
        equipeNumero: 1,
        posicaoVeiculo: 'motorista',
        veiculoPrefixo: 'Banco de Reserva',
        veiculoPlaca: '-',
        regional: 'ribas',
        unidade: r.unidade || 'Ribas do Rio Pardo',
        dataAdmissao: r.dataAdmissao || '05/06/2023',
      });
    });

    return lista;
  }, [veiculos, colaboradoresReserva]);

  const [colaboradoresAdicionados, setColaboradoresAdicionados] = useState<ColaboradorCompleto[]>([]);

  const todosColaboradores = useMemo(() => {
    return [...colaboradoresBase, ...colaboradoresAdicionados];
  }, [colaboradoresBase, colaboradoresAdicionados]);

  const colaboradoresFiltrados = useMemo(() => {
    return todosColaboradores.filter((c) => {
      if (!c) return false;
      const matchSearch =
        !search ||
        (c.nome || '').toLowerCase().includes(search.toLowerCase()) ||
        (c.cargo || '').toLowerCase().includes(search.toLowerCase()) ||
        (c.veiculoPlaca || '').toLowerCase().includes(search.toLowerCase()) ||
        (c.veiculoPrefixo || '').toLowerCase().includes(search.toLowerCase()) ||
        (c.unidade || '').toLowerCase().includes(search.toLowerCase());

      const matchStatus = filterStatus === 'todos' || c.status === filterStatus;
      const matchRegional = filterRegional === 'todas' || c.regional === filterRegional;

      return matchSearch && matchStatus && matchRegional;
    });
  }, [todosColaboradores, search, filterStatus, filterRegional]);

  const handleFotoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      if (event.target?.result) {
        setNovaFoto(event.target.result as string);
      }
    };
    reader.readAsDataURL(file);
  };

  const handleCadastrarColaborador = (e: React.FormEvent) => {
    e.preventDefault();
    if (!novoNome.trim()) return;

    const novo: ColaboradorCompleto = {
      id: `colab-custom-${Date.now()}`,
      nome: novoNome.trim(),
      cargo: novoCargo.trim() || 'Operador Florestal',
      matricula: '',
      foto: novaFoto,
      telefone: novoTelefone.trim(),
      status: 'presente',
      equipeId: 'reserva',
      equipeNumero: 1,
      posicaoVeiculo: 'motorista',
      veiculoPrefixo: 'Banco de Reserva',
      veiculoPlaca: '-',
      regional: novaUnidade,
      unidade: novaUnidade === 'agua_clara' ? 'Água Clara' : 'Ribas do Rio Pardo',
      dataAdmissao: novaDataAdmissao || '15/01/2023',
    };

    setColaboradoresAdicionados((prev) => [novo, ...prev]);
    onAdicionarColaborador?.(novo);

    setNovoNome('');
    setNovoCargo('');
    setNovoTelefone('');
    setNovaFoto('');
    setModalNovoAberto(false);
  };

  const handleArquivoExcel = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setExcelArquivoNome(file.name);
    setIsProcessandoExcel(true);
    setExcelErro(null);
    setExcelPreview([]);
    setExcelImportSucesso(false);

    try {
      // Leitura dinâmica resiliente (suporta CSV nativo ou XLSX se disponível)
      if (file.name.endsWith('.csv') || file.type.includes('csv')) {
        const text = await file.text();
        const linhas = text.split(/\r?\n/).filter(Boolean);
        if (linhas.length < 2) throw new Error('A planilha CSV está vazia ou sem cabeçalho.');

        const colunas = linhas[0].split(/[;,]/).map((h) => h.replace(/"/g, '').trim().toLowerCase());
        const nomeIdx = colunas.findIndex((c) => c.includes('nome'));
        const cargoIdx = colunas.findIndex((c) => c.includes('cargo') || c.includes('função') || c.includes('funcao'));
        const unidadeIdx = colunas.findIndex((c) => c.includes('unidade') || c.includes('regional'));
        const admissaoIdx = colunas.findIndex((c) => c.includes('admissão') || c.includes('admissao') || c.includes('data'));
        const telIdx = colunas.findIndex((c) => c.includes('telefone') || c.includes('contato'));

        const parsed: ColaboradorCompleto[] = [];
        for (let i = 1; i < linhas.length; i++) {
          const vals = linhas[i].split(/[;,]/).map((v) => v.replace(/"/g, '').trim());
          const nome = nomeIdx >= 0 ? vals[nomeIdx] : vals[0];
          if (!nome) continue;
          const cargo = cargoIdx >= 0 ? vals[cargoIdx] : 'Operador Florestal';
          const unidadeStr = (unidadeIdx >= 0 ? vals[unidadeIdx] : 'Ribas do Rio Pardo').toLowerCase();
          const isAguaClara = unidadeStr.includes('água') || unidadeStr.includes('agua') || unidadeStr.includes('clara');
          const dataAdmissao = admissaoIdx >= 0 && vals[admissaoIdx] ? vals[admissaoIdx] : '10/02/2023';
          const telefone = telIdx >= 0 && vals[telIdx] ? vals[telIdx] : '(67) 99800-0000';

          parsed.push({
            id: `imp-${Date.now()}-${i}`,
            nome,
            cargo: cargo || 'Operador Florestal',
            matricula: '',
            foto: '',
            telefone,
            status: 'presente',
            equipeId: 'reserva',
            equipeNumero: 1,
            posicaoVeiculo: 'motorista',
            veiculoPrefixo: 'Banco de Reserva',
            veiculoPlaca: '-',
            regional: isAguaClara ? 'agua_clara' : 'ribas',
            unidade: isAguaClara ? 'Água Clara' : 'Ribas do Rio Pardo',
            dataAdmissao,
          });
        }
        setExcelPreview(parsed);
      } else {
        // Arquivo .xlsx / .xls usando import dinâmico seguro
        const XLSX = await import('xlsx');
        const buffer = await file.arrayBuffer();
        const workbook = XLSX.read(buffer, { type: 'array' });
        const firstSheetName = workbook.SheetNames[0];
        const worksheet = workbook.Sheets[firstSheetName];
        const json: Array<Record<string, any>> = XLSX.utils.sheet_to_json(worksheet, { defval: '' });

        if (!json || json.length === 0) {
          throw new Error('A planilha selecionada não possui linhas de dados válidas.');
        }

        const parsed: ColaboradorCompleto[] = json.map((row, idx) => {
          const chaves = Object.keys(row);
          const acharChave = (termo: string) =>
            chaves.find((k) => k.toLowerCase().includes(termo.toLowerCase())) || '';

          const kNome = acharChave('nome');
          const kCargo = acharChave('cargo') || acharChave('função') || acharChave('funcao');
          const kUnidade = acharChave('unidade') || acharChave('regional');
          const kAdmissao = acharChave('admissão') || acharChave('admissao') || acharChave('data');
          const kTel = acharChave('telefone') || acharChave('contato');

          const nome = String(row[kNome] || row[chaves[0]] || '').trim();
          const cargo = String(row[kCargo] || 'Operador Florestal').trim();
          const unidadeRaw = String(row[kUnidade] || 'Ribas do Rio Pardo').trim();
          const isAguaClara =
            unidadeRaw.toLowerCase().includes('água') ||
            unidadeRaw.toLowerCase().includes('agua') ||
            unidadeRaw.toLowerCase().includes('clara');

          const dataAdmissao = String(row[kAdmissao] || '10/02/2023').trim();
          const telefone = String(row[kTel] || '(67) 99800-0000').trim();

          return {
            id: `imp-${Date.now()}-${idx}`,
            nome: nome || `Colaborador ${idx + 1}`,
            cargo: cargo || 'Operador Florestal',
            matricula: '',
            foto: '',
            telefone,
            status: 'presente',
            equipeId: 'reserva',
            equipeNumero: 1,
            posicaoVeiculo: 'motorista',
            veiculoPrefixo: 'Banco de Reserva',
            veiculoPlaca: '-',
            regional: isAguaClara ? 'agua_clara' : 'ribas',
            unidade: isAguaClara ? 'Água Clara' : 'Ribas do Rio Pardo',
            dataAdmissao,
          };
        });

        setExcelPreview(parsed);
      }
    } catch (err: any) {
      setExcelErro(err?.message || 'Erro ao processar o arquivo. Verifique o formato enviado.');
    } finally {
      setIsProcessandoExcel(false);
    }
  };

  const handleConfirmarImportacao = () => {
    if (excelPreview.length === 0) return;
    setColaboradoresAdicionados((prev) => [...excelPreview, ...prev]);
    onImportarColaboradores?.(excelPreview);
    setExcelImportSucesso(true);
    setTimeout(() => {
      setModalExcelAberto(false);
      setExcelPreview([]);
      setExcelImportSucesso(false);
      setExcelArquivoNome('');
    }, 1200);
  };

  return (
    <div className="space-y-6">
      {/* Barra de Ações Superior */}
      <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
        <div>
          <h2 className="text-xl font-bold tracking-tight text-foreground flex items-center gap-2">
            <Users className="w-5 h-5 text-emerald-400" />
            Quadro Geral de Colaboradores
          </h2>
          <p className="text-xs text-muted-foreground mt-0.5">
            Gerenciamento completo, cadastro individual e upload em lote de planilha Excel
          </p>
        </div>

        <div className="flex items-center gap-2 flex-wrap">
          <Button
            size="sm"
            onClick={() => setModalExcelAberto(true)}
            className="bg-teal-600 hover:bg-teal-500 text-white text-xs font-bold gap-1.5 shadow-md rounded-xl"
          >
            <FileSpreadsheet className="w-4 h-4" />
            <span>Subir Planilha Excel</span>
          </Button>

          <Button
            size="sm"
            onClick={() => setModalNovoAberto(true)}
            className="bg-emerald-600 hover:bg-emerald-500 text-white text-xs font-bold gap-1.5 shadow-md rounded-xl"
          >
            <Plus className="w-4 h-4" />
            <span>Novo Colaborador</span>
          </Button>
        </div>
      </div>

      {/* Filtros */}
      <div className="flex flex-col md:flex-row items-stretch md:items-center gap-3 bg-card/60 p-3 rounded-2xl border border-border/60">
        <div className="relative flex-1">
          <Search className="w-4 h-4 text-muted-foreground absolute left-3 top-1/2 -translate-y-1/2" />
          <Input
            placeholder="Buscar por nome, função, unidade ou veículo..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="pl-9 h-9 text-xs bg-background/50 border-border/60 rounded-xl"
          />
        </div>

        <div className="flex items-center gap-2 flex-wrap">
          <select
            value={filterStatus}
            onChange={(e) => setFilterStatus(e.target.value as any)}
            className="h-9 px-3 rounded-xl border border-border/60 bg-background/50 text-xs font-medium text-foreground focus:outline-none focus:ring-2 focus:ring-emerald-500/30"
          >
            <option value="todos">Todos os Status</option>
            <option value="presente">Presentes</option>
            <option value="falta">Faltas</option>
            <option value="substituto">Substitutos</option>
          </select>

          <select
            value={filterRegional}
            onChange={(e) => setFilterRegional(e.target.value as any)}
            className="h-9 px-3 rounded-xl border border-border/60 bg-background/50 text-xs font-medium text-foreground focus:outline-none focus:ring-2 focus:ring-emerald-500/30"
          >
            <option value="todas">Todas as Unidades</option>
            <option value="ribas">Ribas do Rio Pardo</option>
            <option value="agua_clara">Água Clara</option>
          </select>
        </div>
      </div>

      {/* Grid de Cards de Colaboradores com FOTO MAIOR e NOME ABAIXO */}
      <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4">
        {colaboradoresFiltrados.length === 0 ? (
          <div className="col-span-full py-12 text-center rounded-2xl border border-dashed border-border/70 bg-card/20">
            <Users className="w-8 h-8 text-muted-foreground mx-auto mb-2 opacity-50" />
            <p className="text-sm font-semibold text-foreground">Nenhum colaborador encontrado</p>
            <p className="text-xs text-muted-foreground mt-1">
              Verifique os filtros aplicados ou suba uma nova planilha em Excel.
            </p>
          </div>
        ) : (
          colaboradoresFiltrados.map((colab) => {
            const statusInfo = statusConfig[colab.status] || statusConfig.presente;
            return (
              <Card
                key={colab.id}
                className="overflow-hidden border-border/60 bg-card/50 hover:bg-card/80 transition-all rounded-2xl group flex flex-col"
              >
                <div className="p-4 flex flex-col items-center text-center flex-1">
                  {/* Foto ampliada com visualização em modal ao clicar */}
                  <div
                    onClick={() =>
                      colab.foto && setFotoModalAberta({ url: colab.foto, nome: colab.nome, cargo: colab.cargo })
                    }
                    className={cn(
                      'relative w-20 h-20 rounded-2xl overflow-hidden mb-3 border-2 shadow-md transition-transform group-hover:scale-105',
                      colab.foto ? 'cursor-pointer border-emerald-500/40' : 'border-border/60 bg-muted/40 flex items-center justify-center'
                    )}
                  >
                    {colab.foto ? (
                      <img src={colab.foto} alt={colab.nome} className="w-full h-full object-cover" />
                    ) : (
                      <span className="font-bold text-lg text-emerald-400">{getIniciais(colab.nome)}</span>
                    )}
                    {colab.foto && (
                      <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 flex items-center justify-center transition-opacity">
                        <Eye className="w-4 h-4 text-white" />
                      </div>
                    )}
                  </div>

                  {/* Nome do Colaborador posicionado logo abaixo da foto */}
                  <h3 className="font-bold text-sm text-foreground leading-tight tracking-tight mb-1">
                    {colab.nome}
                  </h3>

                  <div className="flex items-center gap-1 text-xs text-emerald-400 font-medium mb-2">
                    <Briefcase className="w-3 h-3 shrink-0" />
                    <span className="truncate">{colab.cargo}</span>
                  </div>

                  <Badge variant="outline" className={cn('text-[10px] py-0 px-2 font-semibold mb-3', statusInfo.className)}>
                    {statusInfo.label}
                  </Badge>

                  {/* Dados de Unidade e Data de Admissão */}
                  <div className="w-full pt-3 border-t border-border/40 text-[11px] text-muted-foreground space-y-1 text-left">
                    <div className="flex items-center justify-between">
                      <span className="flex items-center gap-1">
                        <Building2 className="w-3 h-3 text-muted-foreground" />
                        Unidade:
                      </span>
                      <span className="font-semibold text-foreground truncate max-w-[120px]">
                        {colab.unidade}
                      </span>
                    </div>

                    <div className="flex items-center justify-between">
                      <span className="flex items-center gap-1">
                        <CalendarDays className="w-3 h-3 text-muted-foreground" />
                        Admissão:
                      </span>
                      <span className="font-medium text-foreground tabular-nums">
                        {colab.dataAdmissao}
                      </span>
                    </div>

                    <div className="flex items-center justify-between">
                      <span className="flex items-center gap-1">
                        <Phone className="w-3 h-3 text-muted-foreground" />
                        Contato:
                      </span>
                      <span className="font-medium text-foreground truncate max-w-[120px]">
                        {colab.telefone || '-'}
                      </span>
                    </div>
                  </div>
                </div>
              </Card>
            );
          })
        )}
      </div>

      {/* Modal de Importação de Planilha Excel */}
      {modalExcelAberto && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/70 backdrop-blur-sm p-4">
          <div className="bg-popover border border-border rounded-3xl max-w-2xl w-full p-6 shadow-2xl relative animate-in fade-in zoom-in-95">
            <button
              onClick={() => {
                setModalExcelAberto(false);
                setExcelPreview([]);
                setExcelErro(null);
              }}
              className="absolute top-4 right-4 p-1.5 rounded-full text-muted-foreground hover:bg-muted"
            >
              <X className="w-4 h-4" />
            </button>

            <div className="flex items-center gap-3 mb-4">
              <div className="w-10 h-10 rounded-2xl bg-teal-500/15 border border-teal-500/30 flex items-center justify-center text-teal-400">
                <FileSpreadsheet className="w-5 h-5" />
              </div>
              <div>
                <h3 className="text-base font-bold text-foreground">Importar Planilha Excel com Colaboradores</h3>
                <p className="text-xs text-muted-foreground">Envie arquivos nos formatos .xlsx, .xls ou .csv</p>
              </div>
            </div>

            {/* Input de arquivo */}
            <div
              onClick={() => excelInputRef.current?.click()}
              className="border-2 border-dashed border-border/80 hover:border-teal-500/60 transition-colors rounded-2xl p-6 text-center cursor-pointer bg-card/40 flex flex-col items-center justify-center gap-2 mb-4"
            >
              <input
                ref={excelInputRef}
                type="file"
                accept=".xlsx,.xls,.csv"
                onChange={handleArquivoExcel}
                className="hidden"
              />
              <FileUp className="w-8 h-8 text-teal-400" />
              <div className="text-xs font-semibold text-foreground">
                {excelArquivoNome || 'Clique aqui para selecionar a planilha no seu computador'}
              </div>
              <p className="text-[11px] text-muted-foreground">
                Colunas aceitas: Nome, Função (ou Cargo), Unidade, Data de Admissão e Telefone
              </p>
            </div>

            {isProcessandoExcel && (
              <div className="py-6 text-center text-xs text-muted-foreground flex items-center justify-center gap-2">
                <Loader2 className="w-4 h-4 animate-spin text-teal-400" />
                <span>Processando dados da planilha...</span>
              </div>
            )}

            {excelErro && (
              <div className="p-3 mb-4 rounded-xl bg-rose-500/15 border border-rose-500/30 text-rose-400 text-xs flex items-center gap-2">
                <AlertCircle className="w-4 h-4 shrink-0" />
                <span>{excelErro}</span>
              </div>
            )}

            {excelImportSucesso && (
              <div className="p-3 mb-4 rounded-xl bg-emerald-500/15 border border-emerald-500/30 text-emerald-400 text-xs flex items-center gap-2">
                <CheckCircle2 className="w-4 h-4 shrink-0" />
                <span>Colaboradores importados com sucesso! Atualizando quadro...</span>
              </div>
            )}

            {/* Pré-visualização da Importação */}
            {excelPreview.length > 0 && !excelImportSucesso && (
              <div className="space-y-3 mb-4">
                <div className="flex items-center justify-between text-xs font-bold text-foreground">
                  <span className="flex items-center gap-1.5">
                    <FileCheck className="w-4 h-4 text-teal-400" />
                    Prévia: {excelPreview.length} colaboradores identificados
                  </span>
                </div>

                <div className="max-h-52 overflow-y-auto rounded-xl border border-border/60 bg-background/50 divide-y divide-border/20 text-xs">
                  {excelPreview.slice(0, 8).map((p, i) => (
                    <div key={i} className="p-2.5 flex items-center justify-between gap-2">
                      <div className="min-w-0">
                        <p className="font-bold text-foreground truncate">{p.nome}</p>
                        <p className="text-[11px] text-muted-foreground">
                          {p.cargo} · {p.unidade}
                        </p>
                      </div>
                      <span className="text-[11px] text-muted-foreground tabular-nums shrink-0">
                        Admissão: {p.dataAdmissao}
                      </span>
                    </div>
                  ))}
                  {excelPreview.length > 8 && (
                    <div className="p-2 text-center text-[11px] text-muted-foreground bg-muted/20">
                      + {excelPreview.length - 8} outros colaboradores na planilha
                    </div>
                  )}
                </div>
              </div>
            )}

            <div className="flex items-center justify-end gap-2 pt-2 border-t border-border/40">
              <Button
                variant="outline"
                size="sm"
                onClick={() => setModalExcelAberto(false)}
                className="text-xs rounded-xl"
              >
                Cancelar
              </Button>
              <Button
                size="sm"
                disabled={excelPreview.length === 0 || isProcessandoExcel || excelImportSucesso}
                onClick={handleConfirmarImportacao}
                className="bg-teal-600 hover:bg-teal-500 text-white text-xs font-bold gap-1.5 rounded-xl shadow-md"
              >
                <CheckCircle2 className="w-4 h-4" />
                <span>Confirmar e Adicionar ({excelPreview.length})</span>
              </Button>
            </div>
          </div>
        </div>
      )}

      {/* Modal de Cadastro Manual de Colaborador */}
      {modalNovoAberto && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/70 backdrop-blur-sm p-4">
          <div className="bg-popover border border-border rounded-3xl max-w-md w-full p-6 shadow-2xl relative animate-in fade-in zoom-in-95">
            <button
              onClick={() => setModalNovoAberto(false)}
              className="absolute top-4 right-4 p-1.5 rounded-full text-muted-foreground hover:bg-muted"
            >
              <X className="w-4 h-4" />
            </button>

            <h3 className="text-base font-bold text-foreground mb-1">Cadastrar Novo Colaborador</h3>
            <p className="text-xs text-muted-foreground mb-4">Adicione um novo integrante ao banco operacional</p>

            <form onSubmit={handleCadastrarColaborador} className="space-y-3">
              <div>
                <label className="text-xs font-semibold text-foreground">Nome Completo</label>
                <Input
                  required
                  placeholder="Ex: João da Silva"
                  value={novoNome}
                  onChange={(e) => setNovoNome(e.target.value)}
                  className="mt-1 h-9 text-xs"
                />
              </div>

              <div>
                <label className="text-xs font-semibold text-foreground">Função / Cargo</label>
                <Input
                  placeholder="Ex: Operador Florestal"
                  value={novoCargo}
                  onChange={(e) => setNovoCargo(e.target.value)}
                  className="mt-1 h-9 text-xs"
                />
              </div>

              <div className="grid grid-cols-2 gap-2">
                <div>
                  <label className="text-xs font-semibold text-foreground">Unidade</label>
                  <select
                    value={novaUnidade}
                    onChange={(e) => setNovaUnidade(e.target.value as any)}
                    className="mt-1 w-full h-9 px-3 rounded-xl border border-input bg-card/50 text-xs text-foreground focus:outline-none focus:ring-2 focus:ring-emerald-500/30"
                  >
                    <option value="ribas">Ribas do Rio Pardo</option>
                    <option value="agua_clara">Água Clara</option>
                  </select>
                </div>

                <div>
                  <label className="text-xs font-semibold text-foreground">Data de Admissão</label>
                  <Input
                    placeholder="Ex: 15/01/2023"
                    value={novaDataAdmissao}
                    onChange={(e) => setNovaDataAdmissao(e.target.value)}
                    className="mt-1 h-9 text-xs"
                  />
                </div>
              </div>

              <div>
                <label className="text-xs font-semibold text-foreground">Telefone de Contato</label>
                <Input
                  placeholder="Ex: (67) 99888-7766"
                  value={novoTelefone}
                  onChange={(e) => setNovoTelefone(e.target.value)}
                  className="mt-1 h-9 text-xs"
                />
              </div>

              <div>
                <label className="text-xs font-semibold text-foreground">Foto do Colaborador</label>
                <input
                  type="file"
                  accept="image/*"
                  onChange={handleFotoUpload}
                  className="mt-1 block w-full text-xs text-muted-foreground file:mr-2 file:py-1 file:px-2 file:rounded-lg file:border-0 file:text-xs file:font-semibold file:bg-emerald-500/20 file:text-emerald-400 hover:file:bg-emerald-500/30 cursor-pointer"
                />
              </div>

              <div className="flex items-center justify-end gap-2 pt-3 border-t border-border/40">
                <Button
                  type="button"
                  variant="outline"
                  size="sm"
                  onClick={() => setModalNovoAberto(false)}
                  className="text-xs rounded-xl"
                >
                  Cancelar
                </Button>
                <Button
                  type="submit"
                  size="sm"
                  className="bg-emerald-600 hover:bg-emerald-500 text-white text-xs font-bold rounded-xl shadow-md"
                >
                  Cadastrar
                </Button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Modal de Foto Ampliada */}
      {fotoModalAberta && (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-sm p-4"
          onClick={() => setFotoModalAberta(null)}
        >
          <div
            className="bg-popover border border-border rounded-3xl p-4 max-w-sm w-full text-center relative"
            onClick={(e) => e.stopPropagation()}
          >
            <button
              onClick={() => setFotoModalAberta(null)}
              className="absolute top-3 right-3 p-1.5 rounded-full text-muted-foreground hover:bg-muted"
            >
              <X className="w-4 h-4" />
            </button>
            <img
              src={fotoModalAberta.url}
              alt={fotoModalAberta.nome}
              className="w-48 h-48 rounded-2xl object-cover mx-auto mb-3 shadow-lg border border-border"
            />
            <h4 className="font-bold text-foreground text-sm">{fotoModalAberta.nome}</h4>
            <p className="text-xs text-emerald-400 mt-0.5">{fotoModalAberta.cargo}</p>
          </div>
        </div>
      )}
    </div>
  );
};

