// Função universal de download compatível com Excel (BOM UTF-8, delimitador ;)
function baixarPlanilhaCSV(linhas: Array<Record<string, string | number>>, nomeArquivo: string) {
  if (!linhas || linhas.length === 0) return;
  const colunas = Object.keys(linhas[0]);
  const cabecalho = colunas.join(';');
  const dados = linhas.map((linha) =>
    colunas
      .map((col) => {
        const valor = String(linha[col] ?? '').replace(/"/g, '""');
        return `"${valor}"`;
      })
      .join(';')
  );

  const conteudoCSV = '\uFEFF' + [cabecalho, ...dados].join('\r\n');
  const blob = new Blob([conteudoCSV], { type: 'text/csv;charset=utf-8;' });
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.setAttribute('href', url);
  link.setAttribute('download', `${nomeArquivo}.csv`);
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  URL.revokeObjectURL(url);
}

export const ExportReports: React.FC<ExportReportsProps> = ({
  veiculos = [],
  colaboradoresReserva = [],
  selectedRegional = 'todas',
  selectedDate = new Date(),
}) => {
  const [mesSelecionado, setMesSelecionado] = useState<number>(new Date().getMonth());
  const [exportando, setExportando] = useState(false);

  // Extrair colaboradores com unidade e data de admissão
  const todosColaboradores = useMemo(() => {
    const lista: Array<{
      id: string;
      nome: string;
      cargo: string;
      unidade: string;
      dataAdmissao: string;
      regional: 'ribas' | 'agua_clara';
      status: string;
      motivo?: string;
      veiculo: string;
      placa: string;
      equipe: string;
    }> = [];

    veiculos.forEach((v) => {
      if (!v?.assentos) return;
      const assentos = [
        { c: v.assentos.motorista, eq: v.equipe1Codigo || 'EQ 1' },
        { c: v.assentos.frenteDir, eq: v.equipe1Codigo || 'EQ 1' },
        { c: v.assentos.trasEsq, eq: v.equipe2Codigo || 'EQ 2' },
        { c: v.assentos.trasDir, eq: v.equipe2Codigo || 'EQ 2' },
      ];

      assentos.forEach(({ c, eq }) => {
        if (!c) return;
        lista.push({
          id: c.id,
          nome: c.nome,
          cargo: c.cargo,
          unidade: c.unidade || (v.regional === 'agua_clara' ? 'Água Clara' : 'Ribas do Rio Pardo'),
          dataAdmissao: c.dataAdmissao || '10/02/2023',
          regional: v.regional,
          status: c.status,
          motivo: c.motivoFalta || '-',
          veiculo: v.prefixo,
          placa: v.placa,
          equipe: eq,
        });
      });
    });

    colaboradoresReserva.forEach((r) => {
      if (!r) return;
      lista.push({
        id: r.id,
        nome: r.nome,
        cargo: r.cargo,
        unidade: r.unidade || 'Ribas do Rio Pardo',
        dataAdmissao: r.dataAdmissao || '05/06/2023',
        regional: 'ribas',
        status: r.status,
        motivo: r.motivoFalta || '-',
        veiculo: 'Banco de Reserva',
        placa: '-',
        equipe: 'Reserva',
      });
    });

    return lista;
  }, [veiculos, colaboradoresReserva]);

  // Colaboradores que faltaram hoje
  const faltantesHoje = useMemo(() => {
    return todosColaboradores.filter((c) => {
      const matchRegional = selectedRegional === 'todas' || c.regional === selectedRegional;
      return matchRegional && c.status === 'falta';
    });
  }, [todosColaboradores, selectedRegional]);

  // Histórico do mês selecionado filtrado por regional
  const faltasHistoricoMes = useMemo(() => {
    const registroMes = HISTORICO_MENSAL_FALTAS.find((h) => h.mesIndex === mesSelecionado);
    if (!registroMes) return [];
    if (selectedRegional === 'todas') return registroMes.faltas;
    return registroMes.faltas.filter((f) => f.regionalKey === selectedRegional);
  }, [mesSelecionado, selectedRegional]);

  const handleExportarExcelHoje = async () => {
    setExportando(true);
    try {
      // Tenta usar a biblioteca XLSX se disponível dinamicamente, ou fallback nativo
      let exportadoViaXLSX = false;
      try {
        const XLSX = await import('xlsx');
        if (XLSX && XLSX.utils) {
          const dadosPlanilha = todosColaboradores
            .filter((c) => selectedRegional === 'todas' || c.regional === selectedRegional)
            .map((c) => ({
              'Nome Completo': c.nome,
              'Unidade': c.unidade,
              'Função / Cargo': c.cargo,
              'Data de Admissão': c.dataAdmissao,
              'Status Hoje': c.status.toUpperCase(),
              'Motivo da Falta': c.motivo,
              'Veículo Prefixo': c.veiculo,
              'Placa': c.placa,
              'Equipe': c.equipe,
            }));

          const ws = XLSX.utils.json_to_sheet(dadosPlanilha);
          const wb = XLSX.utils.book_new();
          XLSX.utils.book_append_sheet(wb, ws, 'Presença e Faltas');
          XLSX.writeFile(wb, `Controle_Faltas_${new Date().toISOString().split('T')[0]}.xlsx`);
          exportadoViaXLSX = true;
        }
      } catch {
        // Fallback nativo
      }

      if (!exportadoViaXLSX) {
        const dadosCSV = todosColaboradores
          .filter((c) => selectedRegional === 'todas' || c.regional === selectedRegional)
          .map((c) => ({
            'Nome Completo': c.nome,
            'Unidade': c.unidade,
            'Função / Cargo': c.cargo,
            'Data de Admissão': c.dataAdmissao,
            'Status Hoje': c.status.toUpperCase(),
            'Motivo da Falta': c.motivo,
            'Veículo': c.veiculo,
            'Placa': c.placa,
            'Equipe': c.equipe,
          }));

        baixarPlanilhaCSV(dadosCSV, `Controle_Faltas_${new Date().toISOString().split('T')[0]}`);
      }
    } finally {
      setExportando(false);
    }
  };

  const handleExportarHistoricoMensal = async () => {
    setExportando(true);
    try {
      const nomeMes = MESES[mesSelecionado];
      let exportadoViaXLSX = false;
      try {
        const XLSX = await import('xlsx');
        if (XLSX && XLSX.utils) {
          const dadosPlanilha = faltasHistoricoMes.map((f) => ({
            'Mês de Referência': nomeMes,
            'Nome Completo': f.nome,
            'Unidade': f.unidade,
            'Função / Cargo': f.funcao,
            'Data de Admissão': f.dataAdmissao,
            'Total de Faltas no Mês': f.totalFaltas,
          }));

          const ws = XLSX.utils.json_to_sheet(dadosPlanilha);
          const wb = XLSX.utils.book_new();
          XLSX.utils.book_append_sheet(wb, ws, `Faltas_${nomeMes}`);
          XLSX.writeFile(wb, `Historico_Faltas_${nomeMes}_2024.xlsx`);
          exportadoViaXLSX = true;
        }
      } catch {
        // Fallback nativo
      }

      if (!exportadoViaXLSX) {
        const dadosCSV = faltasHistoricoMes.map((f) => ({
          'Mês de Referência': nomeMes,
          'Nome Completo': f.nome,
          'Unidade': f.unidade,
          'Função / Cargo': f.funcao,
          'Data de Admissão': f.dataAdmissao,
          'Total de Faltas no Mês': f.totalFaltas,
        }));

        baixarPlanilhaCSV(dadosCSV, `Historico_Faltas_${nomeMes}_2024`);
      }
    } finally {
      setExportando(false);
    }
  };

  return (
    <div className="space-y-6">
      {/* Cabeçalho */}
      <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
        <div>
          <h2 className="text-xl font-bold tracking-tight text-foreground flex items-center gap-2">
            <FileSpreadsheet className="w-5 h-5 text-emerald-400" />
            Relatórios e Histórico Mensal de Faltas
          </h2>
          <p className="text-xs text-muted-foreground mt-0.5">
            Exportação em planilha Excel com Nome, Unidade, Função e Data de Admissão
          </p>
        </div>

        <div className="flex items-center gap-2">
          <Button
            size="sm"
            onClick={handleExportarExcelHoje}
            disabled={exportando}
            className="bg-emerald-600 hover:bg-emerald-500 text-white text-xs font-bold gap-1.5 shadow-md rounded-xl"
          >
            <Download className="w-4 h-4" />
            <span>{exportando ? 'Exportando...' : 'Baixar Planilha Diária (Excel)'}</span>
          </Button>
        </div>
      </div>

      {/* Grid de Resumo */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <Card className="border-border/60 bg-card/60">
          <CardHeader className="p-4 pb-2">
            <CardDescription className="text-xs font-medium">Unidade Selecionada</CardDescription>
            <CardTitle className="text-base font-bold text-foreground flex items-center gap-2">
              <Building2 className="w-4 h-4 text-emerald-400" />
              {regionalLabel[selectedRegional]}
            </CardTitle>
          </CardHeader>
          <CardContent className="p-4 pt-0 text-xs text-muted-foreground">
            Filtro ativo para relatórios e análises
          </CardContent>
        </Card>

        <Card className="border-border/60 bg-card/60">
          <CardHeader className="p-4 pb-2">
            <CardDescription className="text-xs font-medium">Faltas Registradas Hoje</CardDescription>
            <CardTitle className="text-base font-bold text-rose-400 flex items-center gap-2 tabular-nums">
              <AlertCircle className="w-4 h-4 text-rose-400" />
              {faltantesHoje.length} colaboradores
            </CardTitle>
          </CardHeader>
          <CardContent className="p-4 pt-0 text-xs text-muted-foreground">
            {selectedDate.toLocaleDateString('pt-BR')}
          </CardContent>
        </Card>

        <Card className="border-border/60 bg-card/60">
          <CardHeader className="p-4 pb-2">
            <CardDescription className="text-xs font-medium">Total de Operadores Ativos</CardDescription>
            <CardTitle className="text-base font-bold text-emerald-400 flex items-center gap-2 tabular-nums">
              <Users className="w-4 h-4 text-emerald-400" />
              {todosColaboradores.filter((c) => selectedRegional === 'todas' || c.regional === selectedRegional).length} colaboradores
            </CardTitle>
          </CardHeader>
          <CardContent className="p-4 pt-0 text-xs text-muted-foreground">
            Escalados em veículos e banco reserva
          </CardContent>
        </Card>
      </div>

      {/* Seção Histórico Mensal com Seleção de Mês */}
      <Card className="border-border/60 bg-card/40 overflow-hidden">
        <CardHeader className="p-5 border-b border-border/40 bg-muted/20">
          <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
            <div>
              <CardTitle className="text-base font-bold text-foreground flex items-center gap-2">
                <BarChart3 className="w-4 h-4 text-emerald-400" />
                Histórico de Faltas por Mês
              </CardTitle>
              <CardDescription className="text-xs mt-0.5">
                Relação consolidada com Nome, Unidade, Função e Data de Admissão
              </CardDescription>
            </div>

            <div className="flex items-center gap-2 flex-wrap">
              <select
                value={mesSelecionado}
                onChange={(e) => setMesSelecionado(Number(e.target.value))}
                className="h-9 px-3 rounded-xl border border-border/60 bg-background/70 text-xs font-bold text-foreground focus:outline-none focus:ring-2 focus:ring-emerald-500/30"
              >
                {MESES.map((mes, idx) => (
                  <option key={mes} value={idx}>
                    {mes}
                  </option>
                ))}
              </select>

              <Button
                size="sm"
                variant="outline"
                onClick={handleExportarHistoricoMensal}
                disabled={exportando}
                className="h-9 text-xs font-semibold gap-1.5 border-emerald-500/30 text-emerald-400 hover:bg-emerald-500/10 rounded-xl"
              >
                <FileDown className="w-3.5 h-3.5" />
                <span>Exportar Mês ({MESES[mesSelecionado]})</span>
              </Button>
            </div>
          </div>
        </CardHeader>

        <CardContent className="p-0">
          <div className="overflow-x-auto">
            <table className="w-full text-xs text-left border-collapse">
              <thead>
                <tr className="border-b border-border/40 bg-muted/30 text-muted-foreground font-semibold">
                  <th className="py-3 px-4">Nome do Colaborador</th>
                  <th className="py-3 px-4">Unidade</th>
                  <th className="py-3 px-4">Função</th>
                  <th className="py-3 px-4">Data de Admissão</th>
                  <th className="py-3 px-4 text-center">Faltas no Mês</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-border/20">
                {faltasHistoricoMes.length === 0 ? (
                  <tr>
                    <td colSpan={5} className="py-8 text-center text-muted-foreground">
                      Nenhum registro de falta encontrado para este mês e filtro.
                    </td>
                  </tr>
                ) : (
                  faltasHistoricoMes.map((item, idx) => (
                    <tr key={idx} className="hover:bg-muted/10 transition-colors">
                      <td className="py-3 px-4 font-bold text-foreground flex items-center gap-2">
                        <div className="w-6 h-6 rounded-full bg-emerald-500/15 border border-emerald-500/30 flex items-center justify-center text-[10px] text-emerald-400 font-bold shrink-0">
                          {item.nome.charAt(0)}
                        </div>
                        {item.nome}
                      </td>
                      <td className="py-3 px-4 text-muted-foreground">
                        <span className="flex items-center gap-1.5 font-medium">
                          <Building2 className="w-3.5 h-3.5 text-muted-foreground" />
                          {item.unidade}
                        </span>
                      </td>
                      <td className="py-3 px-4 text-muted-foreground">
                        <span className="flex items-center gap-1.5">
                          <Briefcase className="w-3.5 h-3.5 text-muted-foreground" />
                          {item.funcao}
                        </span>
                      </td>
                      <td className="py-3 px-4 text-muted-foreground">
                        <span className="flex items-center gap-1.5 tabular-nums">
