import React, { useState, useMemo } from 'react';
import { Navbar } from './components/Navbar';
import { MetricsHeader } from './components/MetricsHeader';
import { VehicleCardGrid } from './components/VehicleCardGrid';
import { CollaboratorsManagement, ColaboradorCompleto } from './components/CollaboratorsManagement';
import { TeamsManagement } from './components/TeamsManagement';
import { ExportReports } from './components/ExportReports';
import { NewTeamModal, NovaEquipePayload } from './components/NewTeamModal';
import { VEICULOS_INICIAIS, COLABORADORES_RESERVA } from './data/mockData';
import { Regional, StatusPresenca, MotivoFalta, Veiculo, Colaborador } from './types';

export function App() {
  const [activeTab, setActiveTab] = useState<'veiculos' | 'colaboradores' | 'equipes' | 'relatorios'>('veiculos');
  const [selectedRegional, setSelectedRegional] = useState<Regional>('todas');
  const [selectedDate, setSelectedDate] = useState<Date>(new Date());
  const [modalNovaEquipeAberto, setModalNovaEquipeAberto] = useState(false);

  const [veiculos, setVeiculos] = useState<Veiculo[]>(VEICULOS_INICIAIS);
  const [colaboradoresReserva, setColaboradoresReserva] = useState<Colaborador[]>(COLABORADORES_RESERVA);

  const handleUpdateStatus = (
    veiculoId: string,
    posicao: 'motorista' | 'frenteDir' | 'trasEsq' | 'trasDir',
    novoStatus: StatusPresenca,
    motivo?: MotivoFalta,
    obs?: string,
    substituto?: Colaborador
  ) => {
    setVeiculos((prev) =>
      prev.map((v) => {
        if (v.id !== veiculoId) return v;
        const currentAssento = v.assentos[posicao];
        if (!currentAssento) return v;

        let atualizado: Colaborador = {
          ...currentAssento,
          status: novoStatus,
          motivoFalta: novoStatus === 'falta' ? motivo : undefined,
          observacao: obs,
        };

        if (novoStatus === 'substituto' && substituto) {
          atualizado = {
            ...atualizado,
            substitutoId: substituto.id,
            substitutoNome: substituto.nome,
          };
        } else if (novoStatus === 'presente') {
          atualizado.substitutoId = undefined;
          atualizado.substitutoNome = undefined;
        }

        return {
          ...v,
          assentos: {
            ...v.assentos,
            [posicao]: atualizado,
          },
        };
      })
    );
  };

  const handleCriarEquipe = (nova: NovaEquipePayload) => {
    const novoVeiculo: Veiculo = {
      id: `v-${Date.now()}`,
      prefixo: nova.veiculoPrefixo,
      placa: nova.veiculoPlaca,
      modelo: nova.veiculoModelo,
      ano: 2024,
      regional: nova.regional,
      statusOperacional: 'ativo',
      equipe1Codigo: nova.codigo,
      equipe2Codigo: `${nova.codigo} - B`,
      assentos: {
        motorista: nova.motorista,
        frenteDir: nova.frenteDir,
        trasEsq: nova.trasEsq || {
          id: `tras-1-${Date.now()}`,
          nome: 'Operador Traseiro 1',
          cargo: 'Operador Florestal',
          foto: '',
          telefone: '(67) 99999-0000',
          status: 'presente',
          equipeId: nova.codigo,
          equipeNumero: 2,
          posicaoVeiculo: 'tras_esq',
          unidade: nova.regional === 'ribas' ? 'Ribas do Rio Pardo' : 'Água Clara',
        },
        trasDir: nova.trasDir || {
          id: `tras-2-${Date.now()}`,
          nome: 'Operador Traseiro 2',
          cargo: 'Operador Florestal',
          foto: '',
          telefone: '(67) 99999-0000',
          status: 'presente',
          equipeId: nova.codigo,
          equipeNumero: 2,
          posicaoVeiculo: 'tras_dir',
          unidade: nova.regional === 'ribas' ? 'Ribas do Rio Pardo' : 'Água Clara',
        },
      },
    };

    setVeiculos((prev) => [novoVeiculo, ...prev]);
  };

  const handleImportarColaboradores = (novos: ColaboradorCompleto[]) => {
    const convertidos: Colaborador[] = novos.map((n) => ({
      id: n.id,
      nome: n.nome,
      cargo: n.cargo,
      matricula: '',
      foto: n.foto,
      telefone: n.telefone,
      status: n.status,
      equipeId: n.equipeId,
      equipeNumero: n.equipeNumero,
      posicaoVeiculo: n.posicaoVeiculo,
      unidade: n.unidade,
      dataAdmissao: n.dataAdmissao,
    }));
    setColaboradoresReserva((prev) => [...convertidos, ...prev]);
  };

  return (
    <div className="min-h-screen bg-background text-foreground flex flex-col">
      <Navbar
        activeTab={activeTab}
        onTabChange={setActiveTab}
        selectedRegional={selectedRegional}
        onRegionalChange={setSelectedRegional}
        selectedDate={selectedDate}
        onDateChange={setSelectedDate}
        onNovaEquipeClick={() => setModalNovaEquipeAberto(true)}
      />

      <main className="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-6 space-y-6">
        <MetricsHeader
          veiculos={veiculos}
          selectedRegional={selectedRegional}
          onFiltroRegionalChange={(reg) => setSelectedRegional(reg)}
          onNovaEquipe={() => setModalNovaEquipeAberto(true)}
        />

        {activeTab === 'veiculos' && (
          <VehicleCardGrid
            veiculos={veiculos}
            colaboradoresReserva={colaboradoresReserva}
            selectedRegional={selectedRegional}
            onUpdateAssentoStatus={handleUpdateStatus}
          />
        )}

        {activeTab === 'colaboradores' && (
          <CollaboratorsManagement
            veiculos={veiculos}
            colaboradoresReserva={colaboradoresReserva}
            selectedRegional={selectedRegional}
            onImportarColaboradores={handleImportarColaboradores}
          />
        )}

        {activeTab === 'equipes' && (
          <TeamsManagement
            veiculos={veiculos}
            colaboradoresReserva={colaboradoresReserva}
            selectedRegional={selectedRegional}
            onNovaEquipeClick={() => setModalNovaEquipeAberto(true)}
          />
        )}

        {activeTab === 'relatorios' && (
          <ExportReports
            veiculos={veiculos}
            colaboradoresReserva={colaboradoresReserva}
            selectedRegional={selectedRegional}
            selectedDate={selectedDate}
          />
        )}
      </main>

      <NewTeamModal
        isOpen={modalNovaEquipeAberto}
        onClose={() => setModalNovaEquipeAberto(false)}
        colaboradoresReserva={colaboradoresReserva}
        onCriarEquipe={handleCriarEquipe}
      />
    </div>
  );
}

export default App;

