import React, { useState, useEffect, useMemo } from 'react';
import { X, CheckCircle2, XCircle, UserCheck, Search, Phone, Briefcase, Building2, UserX } from 'lucide-react';
import { Colaborador, MotivoFalta, StatusPresenca } from '../types';
import { Button } from './ui/button';
import { Badge } from './ui/badge';
import { Input } from './ui/input';
import { cn } from '@/lib/utils';

export interface AttendanceModalProps {
  isOpen: boolean;
  onClose: () => void;
  colaborador: Colaborador | null;
  veiculoPrefixo?: string;
  posicaoLabel?: string;
  colaboradoresReserva?: Colaborador[];
  onSave?: (
    status: StatusPresenca,
    motivo?: MotivoFalta,
    obs?: string,
    substitutoId?: string,
    substitutoNome?: string
  ) => void;
  onSalvarStatus?: (
    status: StatusPresenca,
    motivo?: MotivoFalta,
    obs?: string,
    substitutoId?: string,
    substitutoNome?: string
  ) => void;
}

const MOTIVOS_FALTA: MotivoFalta[] = [
  'Atestado Médico',
  'Falta Injustificada',
  'Folga Compensatória',
  'Treinamento / Integração',
  'Problema de Transporte',
  'Licença Especial',
];

export const AttendanceModal: React.FC<AttendanceModalProps> = ({
  isOpen,
  onClose,
  colaborador,
  veiculoPrefixo,
  posicaoLabel,
  colaboradoresReserva = [],
  onSave,
  onSalvarStatus,
}) => {
  const [status, setStatus] = useState<StatusPresenca>('presente');
  const [motivo, setMotivo] = useState<MotivoFalta>('Atestado Médico');
  const [observacao, setObservacao] = useState('');
  const [buscaReserva, setBuscaReserva] = useState('');
  const [substitutoSelecionado, setSubstitutoSelecionado] = useState<Colaborador | null>(null);

  useEffect(() => {
    if (colaborador) {
      setStatus(colaborador.status || 'presente');
      setMotivo(colaborador.motivoFalta || 'Atestado Médico');
      setObservacao(colaborador.observacao || '');
      if (colaborador.substitutoId) {
        const found = colaboradoresReserva.find((r) => r.id === colaborador.substitutoId);
        setSubstitutoSelecionado(found || null);
      } else {
        setSubstitutoSelecionado(null);
      }
    }
  }, [colaborador, colaboradoresReserva]);

  const reservasFiltrados = useMemo(() => {
    return (colaboradoresReserva || []).filter((r) => {
      if (!buscaReserva.trim()) return true;
      const termo = buscaReserva.toLowerCase();
      return (
        (r.nome || '').toLowerCase().includes(termo) ||
        (r.cargo || '').toLowerCase().includes(termo) ||
        (r.unidade || '').toLowerCase().includes(termo)
      );
    });
  }, [colaboradoresReserva, buscaReserva]);

  if (!isOpen || !colaborador) return null;

  const handleSalvar = () => {
    const fn = onSave || onSalvarStatus;
    if (fn) {
      fn(
        status,
        status === 'falta' ? motivo : undefined,
        observacao.trim() || undefined,
        status === 'substituto' ? substitutoSelecionado?.id : undefined,
        status === 'substituto' ? substitutoSelecionado?.nome : undefined
      );
    }
    onClose();
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm animate-in fade-in duration-200">
      <div className="relative w-full max-w-lg rounded-2xl border border-border/80 bg-card p-6 shadow-2xl space-y-4">
        <div className="flex items-center justify-between border-b border-border/40 pb-3">
          <div className="flex items-center gap-3">
            {colaborador.foto ? (
              <img
                src={colaborador.foto}
                alt={colaborador.nome}
                className="w-12 h-12 rounded-xl object-cover border border-border"
              />
            ) : (
              <div className="w-12 h-12 rounded-xl bg-muted border border-border flex items-center justify-center text-sm font-bold text-foreground">
                {colaborador.nome.substring(0, 2).toUpperCase()}
              </div>
            )}
            <div>
              <h3 className="text-base font-bold text-foreground">{colaborador.nome}</h3>
              <p className="text-xs text-muted-foreground">
                {colaborador.cargo} {veiculoPrefixo ? `• Veículo ${veiculoPrefixo}` : ''} {posicaoLabel ? `• ${posicaoLabel}` : ''}
              </p>
            </div>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="p-1 rounded-lg text-muted-foreground hover:bg-muted transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        <div className="space-y-4 text-xs">
          <div>
            <label className="block font-semibold text-foreground mb-2">Selecione o Status da Presença</label>
            <div className="grid grid-cols-3 gap-2">
              <button
                type="button"
                onClick={() => setStatus('presente')}
                className={cn(
                  'flex flex-col items-center gap-1.5 p-3 rounded-xl border font-semibold transition-all',
                  status === 'presente'
                    ? 'border-emerald-500 bg-emerald-500/15 text-emerald-400 ring-2 ring-emerald-500/30'
                    : 'border-border/60 hover:bg-muted/50 text-muted-foreground'
                )}
              >
                <CheckCircle2 className="w-5 h-5 text-emerald-400" />
                <span>Presente</span>
              </button>

              <button
                type="button"
                onClick={() => setStatus('falta')}
                className={cn(
                  'flex flex-col items-center gap-1.5 p-3 rounded-xl border font-semibold transition-all',
                  status === 'falta'
                    ? 'border-rose-500 bg-rose-500/15 text-rose-400 ring-2 ring-rose-500/30'
                    : 'border-border/60 hover:bg-muted/50 text-muted-foreground'
                )}
              >
                <XCircle className="w-5 h-5 text-rose-400" />
                <span>Falta</span>
              </button>

              <button
                type="button"
                onClick={() => setStatus('substituto')}
                className={cn(
                  'flex flex-col items-center gap-1.5 p-3 rounded-xl border font-semibold transition-all',
                  status === 'substituto'
                    ? 'border-amber-500 bg-amber-500/15 text-amber-400 ring-2 ring-amber-500/30'
                    : 'border-border/60 hover:bg-muted/50 text-muted-foreground'
                )}
              >
                <UserCheck className="w-5 h-5 text-amber-400" />
                <span>Substituto</span>
              </button>
            </div>
          </div>

          {status === 'falta' && (
            <div className="space-y-2 p-3 rounded-xl border border-rose-500/30 bg-rose-500/5 animate-in fade-in">
              <label className="block font-medium text-foreground">Motivo da Falta</label>
              <select
                value={motivo}
                onChange={(e) => setMotivo(e.target.value as MotivoFalta)}
                className="w-full h-9 px-3 rounded-lg border border-input bg-card text-xs text-foreground focus:outline-none focus:ring-2 focus:ring-rose-500/30"
              >
                {MOTIVOS_FALTA.map((m) => (
                  <option key={m} value={m}>
                    {m}
                  </option>
                ))}
              </select>
            </div>
          )}

          {status === 'substituto' && (
            <div className="space-y-3 p-3 rounded-xl border border-amber-500/30 bg-amber-500/5 animate-in fade-in">
              <div className="flex items-center justify-between">
                <label className="block font-medium text-foreground">Escolha o Substituto no Banco de Reserva</label>
                {substitutoSelecionado && (
                  <Badge variant="outline" className="border-amber-500/40 text-amber-400 text-[10px]">
                    Selecionado: {substitutoSelecionado.nome.split(' ')[0]}
                  </Badge>
                )}
              </div>

              <div className="relative">
                <Search className="w-3.5 h-3.5 absolute left-2.5 top-2.5 text-muted-foreground" />
                <Input
                  placeholder="Filtrar por nome ou cargo..."
                  value={buscaReserva}
                  onChange={(e) => setBuscaReserva(e.target.value)}
                  className="pl-8 h-8 text-xs bg-card"
                />
              </div>

              <div className="max-h-40 overflow-y-auto space-y-1 pr-1">
                {reservasFiltrados.map((res) => {
                  const isSelected = substitutoSelecionado?.id === res.id;
                  return (
                    <div
                      key={res.id}
                      onClick={() => setSubstitutoSelecionado(res)}
                      className={cn(
                        'flex items-center justify-between p-2 rounded-lg border cursor-pointer transition-all',
                        isSelected
                          ? 'border-amber-500 bg-amber-500/20 text-foreground shadow-sm'
                          : 'border-border/60 hover:bg-muted/40 text-muted-foreground'
                      )}
                    >
                      <div className="flex items-center gap-2">
                        {res.foto ? (
                          <img src={res.foto} alt="" className="w-7 h-7 rounded-full object-cover" />
                        ) : (
                          <div className="w-7 h-7 rounded-full bg-muted flex items-center justify-center text-[10px] font-bold">
                            {res.nome.substring(0, 2).toUpperCase()}
                          </div>
                        )}
                        <div>
                          <p className="font-semibold text-xs text-foreground">{res.nome}</p>
                          <p className="text-[10px] text-muted-foreground">{res.cargo}</p>
                        </div>
                      </div>
                      <Badge variant="outline" className="text-[10px] border-border">
                        {res.unidade || 'Reserva'}
                      </Badge>
                    </div>
                  );
                })}
              </div>
            </div>
          )}

          <div>
            <label className="block font-medium text-foreground mb-1">Observações Internas (Opcional)</label>
            <Input
              placeholder="Ex: Liberado pelo gestor / comprovante anexo..."
              value={observacao}
              onChange={(e) => setObservacao(e.target.value)}
            />
          </div>
        </div>

        <div className="flex items-center justify-end gap-2 border-t border-border/40 pt-4">
          <Button type="button" variant="outline" size="sm" onClick={onClose}>
            Cancelar
          </Button>
          <Button type="button" size="sm" onClick={handleSalvar} className="bg-emerald-600 hover:bg-emerald-500 text-white">
            Confirmar Alteração
          </Button>
        </div>
      </div>
    </div>
  );
};

