import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { Navbar } from './components/Navbar';
import { MetricsHeader } from './components/MetricsHeader';
import { VehicleCardGrid } from './components/VehicleCardGrid';
import { CollaboratorsManagement, ColaboradorCompleto } from './components/CollaboratorsManagement';
import { TeamsManagement } from './components/TeamsManagement';
import { ExportReports } from './components/ExportReports';
import { NewTeamModal, NovaEquipePayload } from './components/NewTeamModal';
import { supabase } from './integrations/supabase/client';
import { Veiculo, Colaborador, Regional, StatusPresenca, MotivoFalta } from './types';
import { VEICULOS_INICIAIS, COLABORADORES_RESERVA } from './data/mockData';
import { AlertCircle, RefreshCw, ShieldCheck } from 'lucide-react';
import { Button } from './components/ui/button';

export function App() {
  const [activeTab, setActiveTab] = useState<'veiculos' | 'colaboradores' | 'equipes' | 'relatorios'>('veiculos');
  const [selectedRegional, setSelectedRegional] = useState<Regional>('todas');
  const [selectedDate, setSelectedDate] = useState<Date>(new Date());
  const [veiculos, setVeiculos] = useState<Veiculo[]>(VEICULOS_INICIAIS);
  const [colaboradoresReserva, setColaboradoresReserva] = useState<Colaborador[]>(COLABORADORES_RESERVA);
  const [isNewTeamModalOpen, setIsNewTeamModalOpen] = useState(false);
  const [authPronta, setAuthPronta] = useState(false);
  const [sincronizando, setSincronizando] = useState(false);
  const [usuarioEmail, setUsuarioEmail] = useState<string | null>(null);

  // Failsafe rápido para autenticação - evita tela branca e timeout do host
  useEffect(() => {
    let montado = true;

    const timer = setTimeout(() => {
      if (montado && !authPronta) {
        setAuthPronta(true);
      }
    }, 600);

    const verificarSessao = async () => {
      try {
        const { data } = await supabase.auth.getSession();
        if (montado) {
          if (data?.session?.user?.email) {
            setUsuarioEmail(data.session.user.email);
          }
          setAuthPronta(true);
        }
      } catch (err) {
        console.warn('Supabase auth getSession fallback:', err);
        if (montado) {
          setAuthPronta(true);
        }
      }
    };

    verificarSessao();

    const {
      data: { subscription },
    } = supabase.auth.onAuthStateChange((_event, session) => {
      if (montado) {
        setUsuarioEmail(session?.user?.email ?? null);
        setAuthPronta(true);
      }
    });

    return () => {
      montado = false;
      clearTimeout(timer);
      subscription?.unsubscribe();
    };
  }, [authPronta]);

  // Carregar dados salvos do Supabase se existirem
  const carregarDadosDoBanco = useCallback(async () => {
    setSincronizando(true);
    try {
      const { data: veiculosDb, error: errVeiculos } = await supabase
        .from('veiculos')
        .select('*');

      if (!errVeiculos && Array.isArray(veiculosDb) && veiculosDb.length > 0) {
        // Se houver dados no banco, mapeia com assentos íntegros
        const mapeados: Veiculo[] = veiculosDb.map((v) => ({
          id: v.id,
          prefixo: v.prefixo || 'V-00',
          placa: v.placa || 'ABC-0000',
          modelo: v.modelo || 'Hilux 4x4',
          ano: v.ano || 2023,
          regional: v.regional || 'ribas',
          statusOperacional: v.status_operacional || 'ativo',
          equipe1Codigo: v.equipe1_codigo || 'EQ-01',
          equipe2Codigo: v.equipe2_codigo || 'EQ-02',
          assentos: v.assentos || {
            motorista: {
              id: `${v.id}-m`,
              nome: 'Motorista',
              cargo: 'Motorista',
              foto: '',
              telefone: '(67) 99999-0000',
              status: 'presente',
              equipeId: v.equipe1_codigo || 'EQ-01',
              equipeNumero: 1,
              posicaoVeiculo: 'motorista',
            },
            frenteDir: {
              id: `${v.id}-f`,
              nome: 'Ajudante',
              cargo: 'Ajudante',
              foto: '',
              telefone: '(67) 99999-0000',
              status: 'presente',
              equipeId: v.equipe1_codigo || 'EQ-01',
              equipeNumero: 1,
              posicaoVeiculo: 'frente_dir',
            },
            trasEsq: {
              id: `${v.id}-te`,
              nome: 'Operador 1',
              cargo: 'Operador',
              foto: '',
              telefone: '(67) 99999-0000',
              status: 'presente',
              equipeId: v.equipe2_codigo || 'EQ-02',
              equipeNumero: 2,
              posicaoVeiculo: 'tras_esq',
            },
            trasDir: {
              id: `${v.id}-td`,
              nome: 'Operador 2',
              cargo: 'Operador',
              foto: '',
              telefone: '(67) 99999-0000',
              status: 'presente',
              equipeId: v.equipe2_codigo || 'EQ-02',
              equipeNumero: 2,
              posicaoVeiculo: 'tras_dir',
            },
          },
        }));
        setVeiculos(mapeados);
      }

      const { data: reservasDb, error: errReservas } = await supabase
        .from('colaboradores')
        .select('*')
        .eq('equipe_id', 'reserva');

      if (!errReservas && Array.isArray(reservasDb) && reservasDb.length > 0) {
        setColaboradoresReserva(
          reservasDb.map((c) => ({
            id: c.id,
            nome: c.nome,
            cargo: c.cargo || 'Operador Florestal',
            matricula: c.matricula,
            foto: c.foto || '',
            telefone: c.telefone || '(67) 99999-0000',
            status: c.status || 'presente',
            motivoFalta: c.motivo_falta,
            observacao: c.observacao,
            substitutoId: c.substituto_id,
            substitutoNome: c.substituto_nome,
            equipeId: 'reserva',
            equipeNumero: 1,
            posicaoVeiculo: 'motorista',
            unidade: c.unidade,
            dataAdmissao: c.data_admissao,
          }))
        );
      }
    } catch (e) {
      console.warn('Falha silenciosa ao sincronizar Supabase, mantendo dados locais:', e);
    } finally {
      setSincronizando(false);
    }
  }, []);

  useEffect(() => {
    carregarDadosDoBanco();
  }, [carregarDadosDoBanco]);

  // Alteração de presença de colaborador em assento do veículo
  const handleUpdateStatus = useCallback(
    (
      veiculoId: string,
      posicao: 'motorista' | 'frenteDir' | 'trasEsq' | 'trasDir',
      novoStatus: StatusPresenca,
      motivo?: MotivoFalta,
      obs?: string,
      substituto?: Colaborador
    ) => {
      setVeiculos((prev) =>
        (prev || []).map((v) => {
          if (!v || v.id !== veiculoId) return v;
          const assentoAtual = v.assentos?.[posicao];
          if (!assentoAtual) return v;

          const assentoAtualizado: Colaborador = {
            ...assentoAtual,
            status: novoStatus,
            motivoFalta: motivo,
            observacao: obs,
            substitutoId: substituto?.id,
            substitutoNome: substituto?.nome,
          };

          return {
            ...v,
            assentos: {
              ...v.assentos,
              [posicao]: assentoAtualizado,
            },
          };
        })
      );
    },
    []
  );

  // Cadastro de nova equipe
  const handleCriarEquipe = useCallback((payload: NovaEquipePayload) => {
    const novoVeiculo: Veiculo = {
      id: `v-${Date.now()}`,
      prefixo: payload.veiculoPrefixo,
      placa: payload.veiculoPlaca,
      modelo: payload.veiculoModelo || 'Toyota Hilux 4x4',
      ano: new Date().getFullYear(),
      regional: payload.regional,
      statusOperacional: 'ativo',
      equipe1Codigo: payload.codigo,
      equipe2Codigo: `${payload.codigo}-B`,
      assentos: {
        motorista: payload.motorista,
        frenteDir: payload.frenteDir,
        trasEsq:
          payload.trasEsq || {
            id: `colab-te-${Date.now()}`,
            nome: 'Operador Traseiro 1',
            cargo: 'Ajudante Florestal',
            foto: '',
            telefone: '(67) 99999-0000',
            status: 'presente',
            equipeId: `${payload.codigo}-B`,
            equipeNumero: 2,
            posicaoVeiculo: 'tras_esq',
            unidade: payload.regional === 'agua_clara' ? 'Água Clara' : 'Ribas do Rio Pardo',
          },
        trasDir:
          payload.trasDir || {
            id: `colab-td-${Date.now()}`,
            nome: 'Operador Traseiro 2',
            cargo: 'Ajudante Florestal',
            foto: '',
            telefone: '(67) 99999-0000',
            status: 'presente',
            equipeId: `${payload.codigo}-B`,
            equipeNumero: 2,
            posicaoVeiculo: 'tras_dir',
            unidade: payload.regional === 'agua_clara' ? 'Água Clara' : 'Ribas do Rio Pardo',
          },
      },
    };

    setVeiculos((prev) => [novoVeiculo, ...(prev || [])]);
  }, []);

  // Importar novos colaboradores para a reserva operacional
  const handleImportarColaboradores = useCallback((novos: ColaboradorCompleto[]) => {
    if (!Array.isArray(novos) || novos.length === 0) return;

    const adaptados: Colaborador[] = novos.map((n) => ({
      id: n.id,
      nome: n.nome,
      cargo: n.cargo,
      matricula: n.matricula,
      foto: n.foto,
      telefone: n.telefone,
      status: n.status || 'presente',
      motivoFalta: n.motivoFalta,
      observacao: n.observacao,
      substitutoNome: n.substitutoNome,
      equipeId: 'reserva',
      equipeNumero: 1,
      posicaoVeiculo: 'motorista',
      unidade: n.unidade,
      dataAdmissao: n.dataAdmissao,
    }));

    setColaboradoresReserva((prev) => [...adaptados, ...(prev || [])]);
  }, []);

  const handleAdicionarColaborador = useCallback((novo: ColaboradorCompleto) => {
    const colab: Colaborador = {
      id: novo.id,
      nome: novo.nome,
      cargo: novo.cargo,
      matricula: novo.matricula,
      foto: novo.foto,
      telefone: novo.telefone,
      status: novo.status || 'presente',
      motivoFalta: novo.motivoFalta,
      observacao: novo.observacao,
      substitutoNome: novo.substitutoNome,
      equipeId: 'reserva',
      equipeNumero: 1,
      posicaoVeiculo: 'motorista',
      unidade: novo.unidade,
      dataAdmissao: novo.dataAdmissao,
    };
    setColaboradoresReserva((prev) => [colab, ...(prev || [])]);
  }, []);

  return (
    <div className="min-h-screen bg-background text-foreground flex flex-col font-sans selection:bg-emerald-500/20 selection:text-emerald-300">
      {/* Barra de Navegação Superior */}
      <Navbar
        activeTab={activeTab}
        onTabChange={setActiveTab}
        selectedRegional={selectedRegional}
        onRegionalChange={setSelectedRegional}
        selectedDate={selectedDate}
        onDateChange={setSelectedDate}
        onNovaEquipeClick={() => setIsNewTeamModalOpen(true)}
      />

      {/* Conteúdo Principal */}
      <main className="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-6 space-y-6">
        {/* Painel de Métricas e Composição Geral */}
        <MetricsHeader
          veiculos={veiculos}
          selectedRegional={selectedRegional}
          selectedDate={selectedDate}
          onFiltroRegionalChange={(reg) => setSelectedRegional(reg)}
          onNovaEquipe={() => setIsNewTeamModalOpen(true)}
        />

        {/* Visualização de Veículos e Escala de Campo */}
        {activeTab === 'veiculos' && (
          <div className="space-y-4 animate-in fade-in-50 duration-200">
            <VehicleCardGrid
              veiculos={veiculos}
              colaboradoresReserva={colaboradoresReserva}
              selectedRegional={selectedRegional}
              onUpdateStatus={handleUpdateStatus}
            />
          </div>
        )}

        {/* Visualização de Gestão de Colaboradores e Importação */}
        {activeTab === 'colaboradores' && (
          <div className="animate-in fade-in-50 duration-200">
            <CollaboratorsManagement
              veiculos={veiculos}
              colaboradoresReserva={colaboradoresReserva}
              selectedRegional={selectedRegional}
              onImportarColaboradores={handleImportarColaboradores}
              onAdicionarColaborador={handleAdicionarColaborador}
            />
          </div>
        )}

        {/* Visualização de Gestão de Equipes */}
        {activeTab === 'equipes' && (
          <div className="animate-in fade-in-50 duration-200">
            <TeamsManagement
              veiculos={veiculos}
              colaboradoresReserva={colaboradoresReserva}
              selectedRegional={selectedRegional}
              onNovaEquipeClick={() => setIsNewTeamModalOpen(true)}
            />
          </div>
        )}

        {/* Visualização de Relatórios, Histórico Mensal e Exportação */}
        {activeTab === 'relatorios' && (
          <div className="animate-in fade-in-50 duration-200">
            <ExportReports
              veiculos={veiculos}
              colaboradoresReserva={colaboradoresReserva}
              selectedRegional={selectedRegional}
              selectedDate={selectedDate}
            />
          </div>
        )}
      </main>

      {/* Modal de Cadastro de Nova Equipe */}
      <NewTeamModal
        isOpen={isNewTeamModalOpen}
        onClose={() => setIsNewTeamModalOpen(false)}
        colaboradoresReserva={colaboradoresReserva}
        onCriarEquipe={handleCriarEquipe}
      />
    </div>
  );
}

export default App;

