import React, { useState, useMemo, useRef } from 'react';
import {
  Users,
  Search,
  Phone,
  Building2,
  Briefcase,
  FileSpreadsheet,
  Download,
  CheckCircle2,
  AlertCircle,
  X,
  Plus,
  Trash2,
  FileCheck,
  Eye,
  FileUp,
  Loader2,
  CalendarDays,
} from 'lucide-react';
import { Card, CardContent } from './ui/card';
import { Badge } from './ui/badge';
import { Input } from './ui/input';
import { Button } from './ui/button';
import { cn } from '@/lib/utils';
import { Colaborador, Veiculo, StatusPresenca, MotivoFalta, Regional } from '../types';

export interface ColaboradorCompleto {
  id: string;
  nome: string;
  cargo: string;
  matricula?: string;
  foto: string;
  telefone: string;
  status: StatusPresenca;
  motivoFalta?: MotivoFalta;
  observacao?: string;
  substitutoNome?: string;
  equipeId: string;
  equipeNumero: 1 | 2;
  posicaoVeiculo: 'motorista' | 'frente_dir' | 'tras_esq' | 'tras_dir';
  veiculoPrefixo: string;
  veiculoPlaca: string;
  regional: 'ribas' | 'agua_clara';
  unidade?: string;
  dataAdmissao?: string;
}

export interface CollaboratorsManagementProps {
  veiculos?: Veiculo[];
  colaboradoresReserva?: Colaborador[];
  selectedRegional?: Regional;
  onUpdateColaboradorStatus?: (
    colabId: string,
    novoStatus: StatusPresenca,
    motivo?: MotivoFalta,
    obs?: string
  ) => void;
  onImportarColaboradores?: (novosColaboradores: ColaboradorCompleto[]) => void;
  onAdicionarColaborador?: (novoColaborador: ColaboradorCompleto) => void;
}

const statusConfig: Record<StatusPresenca, { label: string; className: string }> = {
  presente: { label: 'Presente', className: 'bg-emerald-500/20 text-emerald-400 border-emerald-500/30' },
  falta: { label: 'Falta', className: 'bg-rose-500/20 text-rose-400 border-rose-500/30' },
  substituto: { label: 'Substituto', className: 'bg-amber-500/20 text-amber-400 border-amber-500/30' },
};

const regionalLabel: Record<string, string> = {
  ribas: 'Ribas do Rio Pardo',
  agua_clara: 'Água Clara',
};

const getIniciais = (nome?: string) => {
  if (!nome) return 'CO';
  const partes = nome.trim().split(' ');
  if (partes.length === 1) return partes[0].substring(0, 2).toUpperCase();
  return (partes[0][0] + (partes[partes.length - 1]?.[0] || '')).toUpperCase();
};

export const CollaboratorsManagement: React.FC<CollaboratorsManagementProps> = ({
  veiculos = [],
  colaboradoresReserva = [],
  selectedRegional = 'todas',
  onImportarColaboradores,
  onAdicionarColaborador,
}) => {
  const [search, setSearch] = useState('');
  const [filterStatus, setFilterStatus] = useState<StatusPresenca | 'todos'>('todos');
  const [filterRegional, setFilterRegional] = useState<Regional | 'todas'>(selectedRegional);
  const [fotoModalAberta, setFotoModalAberta] = useState<{ url: string; nome: string; cargo: string } | null>(null);

  // Modal de cadastro manual
  const [modalNovoAberto, setModalNovoAberto] = useState(false);
  const [novoNome, setNovoNome] = useState('');
  const [novoCargo, setNovoCargo] = useState('');
  const [novoTelefone, setNovoTelefone] = useState('');
  const [novaFoto, setNovaFoto] = useState<string>('');
  const [novaUnidade, setNovaUnidade] = useState<'ribas' | 'agua_clara'>('ribas');
  const [novaDataAdmissao, setNovaDataAdmissao] = useState('15/01/2023');

  // Modal de Importação Excel / CSV
  const [modalExcelAberto, setModalExcelAberto] = useState(false);
  const [isProcessandoExcel, setIsProcessandoExcel] = useState(false);
  const [excelPreview, setExcelPreview] = useState<ColaboradorCompleto[]>([]);
  const [excelErro, setExcelErro] = useState<string | null>(null);
  const [excelArquivoNome, setExcelArquivoNome] = useState<string>('');
  const [excelImportSucesso, setExcelImportSucesso] = useState(false);
  const excelInputRef = useRef<HTMLInputElement>(null);

  const colaboradoresBase: ColaboradorCompleto[] = useMemo(() => {
    const lista: ColaboradorCompleto[] = [];
    (veiculos || []).forEach((v) => {
      if (!v || !v.assentos) return;
      const assentos: Array<{ colab?: Colaborador; pos: ColaboradorCompleto['posicaoVeiculo'] }> = [
        { colab: v.assentos.motorista, pos: 'motorista' },
        { colab: v.assentos.frenteDir, pos: 'frente_dir' },
        { colab: v.assentos.trasEsq, pos: 'tras_esq' },
        { colab: v.assentos.trasDir, pos: 'tras_dir' },
      ];
      assentos.forEach(({ colab, pos }) => {
        if (!colab) return;
        lista.push({
          id: colab.id,
          nome: colab.nome || 'Sem Nome',
          cargo: colab.cargo || 'Operador',
          matricula: '',
          foto: colab.foto ?? '',
          telefone: colab.telefone ?? '',
          status: colab.status || 'presente',
          motivoFalta: colab.motivoFalta,
          observacao: colab.observacao,
          substitutoNome: colab.substitutoNome,
          equipeId: colab.equipeId || '',
          equipeNumero: colab.equipeNumero || 1,
          posicaoVeiculo: pos,
          veiculoPrefixo: v.prefixo || '',
          veiculoPlaca: v.placa || '',
          regional: v.regional || 'ribas',
          unidade: colab.unidade || (v.regional === 'agua_clara' ? 'Água Clara' : 'Ribas do Rio Pardo'),
          dataAdmissao: colab.dataAdmissao || '10/02/2023',
        });
      });
    });

    (colaboradoresReserva || []).forEach((r, idx) => {
      if (!r) return;
      lista.push({
        id: r.id || `res-${idx}`,
        nome: r.nome || 'Colaborador Reserva',
        cargo: r.cargo || 'Reserva Operacional',
        matricula: '',
        foto: r.foto || '',
        telefone: r.telefone || '',
        status: r.status || 'presente',
        motivoFalta: r.motivoFalta,
        observacao: r.observacao,
        substitutoNome: r.substitutoNome,
        equipeId: 'reserva',
        equipeNumero: 1,
        posicaoVeiculo: 'motorista',
        veiculoPrefixo: 'Banco de Reserva',
        veiculoPlaca: '-',
        regional: 'ribas',
        unidade: r.unidade || 'Ribas do Rio Pardo',
        dataAdmissao: r.dataAdmissao || '05/06/2023',
      });
    });

    return lista;
  }, [veiculos, colaboradoresReserva]);

  const [colaboradoresAdicionados, setColaboradoresAdicionados] = useState<ColaboradorCompleto[]>([]);

  const todosColaboradores = useMemo(() => {
    return [...colaboradoresBase, ...colaboradoresAdicionados];
  }, [colaboradoresBase, colaboradoresAdicionados]);

  const colaboradoresFiltrados = useMemo(() => {
    return todosColaboradores.filter((c) => {
      if (!c) return false;
      const matchSearch =
        !search ||
        (c.nome || '').toLowerCase().includes(search.toLowerCase()) ||
        (c.cargo || '').toLowerCase().includes(search.toLowerCase()) ||
        (c.veiculoPlaca || '').toLowerCase().includes(search.toLowerCase()) ||
        (c.veiculoPrefixo || '').toLowerCase().includes(search.toLowerCase()) ||
        (c.unidade || '').toLowerCase().includes(search.toLowerCase());

      const matchStatus = filterStatus === 'todos' || c.status === filterStatus;
      const matchRegional = filterRegional === 'todas' || c.regional === filterRegional;

      return matchSearch && matchStatus && matchRegional;
    });
  }, [todosColaboradores, search, filterStatus, filterRegional]);

  const handleFotoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      if (event.target?.result) {
        setNovaFoto(event.target.result as string);
      }
    };
    reader.readAsDataURL(file);
  };

  const handleCadastrarColaborador = (e: React.FormEvent) => {
    e.preventDefault();
    if (!novoNome.trim()) return;

    const novo: ColaboradorCompleto = {
      id: `colab-custom-${Date.now()}`,
      nome: novoNome.trim(),
      cargo: novoCargo.trim() || 'Operador Florestal',
      matricula: '',
      foto: novaFoto,
      telefone: novoTelefone.trim() || '(67) 99999-0000',
      status: 'presente',
      equipeId: 'reserva',
      equipeNumero: 1,
      posicaoVeiculo: 'motorista',
      veiculoPrefixo: 'Banco de Reserva',
      veiculoPlaca: '-',
      regional: novaUnidade,
      unidade: novaUnidade === 'ribas' ? 'Ribas do Rio Pardo' : 'Água Clara',
      dataAdmissao: novaDataAdmissao || '15/01/2023',
    };

    setColaboradoresAdicionados((prev) => [novo, ...prev]);
    onAdicionarColaborador?.(novo);

    setNovoNome('');
    setNovoCargo('');
    setNovoTelefone('');
    setNovaFoto('');
    setModalNovoAberto(false);
  };

  const processarTextoCSV = (texto: string) => {
    const linhas = texto.split(/\r?\n/).filter((l) => l.trim().length > 0);
    if (linhas.length < 2) {
      throw new Error('A planilha está vazia ou sem cabeçalho.');
    }

    const separador = linhas[0].includes(';') ? ';' : ',';
    const cabecalho = linhas[0]
      .split(separador)
      .map((c) => c.replace(/"/g, '').trim().toLowerCase());

    const idxNome = cabecalho.findIndex((c) => c.includes('nome') || c.includes('colaborador'));
    const idxCargo = cabecalho.findIndex((c) => c.includes('cargo') || c.includes('função') || c.includes('funcao'));
    const idxUnidade = cabecalho.findIndex((c) => c.includes('unidade') || c.includes('regional') || c.includes('polo'));
    const idxDataAdm = cabecalho.findIndex((c) => c.includes('admiss') || c.includes('data'));
    const idxTelefone = cabecalho.findIndex((c) => c.includes('telefone') || c.includes('contato') || c.includes('celular'));

    if (idxNome === -1) {
      throw new Error('Coluna de "Nome" do colaborador não foi encontrada no cabeçalho da planilha.');
    }

    const colaboradoresImportados: ColaboradorCompleto[] = [];

    for (let i = 1; i < linhas.length; i++) {
      const valores = linhas[i].split(separador).map((v) => v.replace(/"/g, '').trim());
      const nomeVal = valores[idxNome];
      if (!nomeVal) continue;

      const cargoVal = (idxCargo !== -1 && valores[idxCargo]) ? valores[idxCargo] : 'Operador Florestal';
      const unidadeVal = (idxUnidade !== -1 && valores[idxUnidade]) ? valores[idxUnidade] : 'Ribas do Rio Pardo';
      const regionalKey: 'ribas' | 'agua_clara' = unidadeVal.toLowerCase().includes('clara') ? 'agua_clara' : 'ribas';
      const dataVal = (idxDataAdm !== -1 && valores[idxDataAdm]) ? valores[idxDataAdm] : '10/02/2023';
      const telVal = (idxTelefone !== -1 && valores[idxTelefone]) ? valores[idxTelefone] : '(67) 99999-0000';

      colaboradoresImportados.push({
        id: `import-${Date.now()}-${i}`,
        nome: nomeVal,
        cargo: cargoVal,
        matricula: '',
        foto: '',
        telefone: telVal,
        status: 'presente',
        equipeId: 'reserva',
        equipeNumero: 1,
        posicaoVeiculo: 'motorista',
        veiculoPrefixo: 'Importado da Planilha',
        veiculoPlaca: '-',
        regional: regionalKey,
        unidade: regionalKey === 'agua_clara' ? 'Água Clara' : 'Ribas do Rio Pardo',
        dataAdmissao: dataVal,
      });
    }

    if (colaboradoresImportados.length === 0) {
      throw new Error('Nenhum registro válido pôde ser extraído da planilha.');
    }

    return colaboradoresImportados;
  };

  const handleUploadExcelArquivo = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setExcelArquivoNome(file.name);
    setExcelErro(null);
    setExcelImportSucesso(false);
    setIsProcessandoExcel(true);

    try {
      const text = await file.text();
      const resultado = processarTextoCSV(text);
      setExcelPreview(resultado);
    } catch (err: any) {
      setExcelErro(err.message || 'Falha ao interpretar a planilha enviada.');
      setExcelPreview([]);
    } finally {
      setIsProcessandoExcel(false);
    }
  };

  const handleConfirmarImportacao = () => {
    if (excelPreview.length === 0) return;
    setColaboradoresAdicionados((prev) => [...excelPreview, ...prev]);
    onImportarColaboradores?.(excelPreview);
    setExcelImportSucesso(true);
    setTimeout(() => {
      setModalExcelAberto(false);
      setExcelPreview([]);
      setExcelArquivoNome('');
      setExcelImportSucesso(false);
    }, 1200);
  };

  const baixarModeloExcel = () => {
    const modeloContent =
      '\uFEFFNome;Função;Unidade;Data de Admissão;Telefone\r\n' +
      'Carlos Eduardo Silva;Operador de Motosserra;Ribas do Rio Pardo;15/03/2022;(67) 99876-1122\r\n' +
      'Roberto Alves Santos;Operador de Carregadeira;Água Clara;20/07/2021;(67) 99123-4455\r\n' +
      'Lucas Gabriel Costa;Motorista de Apoio;Água Clara;10/01/2023;(67) 99988-7766\r\n' +
      'Marcos Souza;Ajudante Geral;Ribas do Rio Pardo;05/08/2022;(67) 99765-4321';

    const blob = new Blob([modeloContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', 'Modelo_Importacao_Colaboradores.csv');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  return (
    <div className="w-full space-y-5 animate-in fade-in duration-300">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 p-5 rounded-2xl border border-border/60 bg-card/60 backdrop-blur-md shadow-xl">
        <div className="space-y-1">
          <div className="flex items-center gap-2">
            <div className="p-2 rounded-xl bg-emerald-500/15 border border-emerald-500/30 text-emerald-400">
              <Users className="w-5 h-5" />
            </div>
            <h2 className="text-xl font-bold tracking-tight text-foreground">
              Gestão de Colaboradores
            </h2>
          </div>
          <p className="text-xs text-muted-foreground">
            Monitoramento de equipe florestal, importação em lote por planilha e cadastro rápido.
          </p>
        </div>

        <div className="flex items-center gap-2.5 flex-wrap">
          <Button
            onClick={() => setModalExcelAberto(true)}
            className="gap-2 bg-emerald-700 hover:bg-emerald-600 text-white font-semibold shadow-md"
          >
            <FileSpreadsheet className="w-4 h-4" />
            <span>Subir Planilha Excel</span>
          </Button>

          <Button
            onClick={() => setModalNovoAberto(true)}
            className="gap-2 bg-emerald-600 hover:bg-emerald-500 text-white font-semibold shadow-md"
          >
            <Plus className="w-4 h-4" />
            <span>Novo Colaborador</span>
          </Button>
        </div>
      </div>

      <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3">
        <div className="relative flex-1 max-w-md">
          <Search className="w-4 h-4 text-muted-foreground absolute left-3 top-1/2 -translate-y-1/2" />
          <Input
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder="Buscar por nome, função, unidade ou placa..."
            className="pl-9 h-10 rounded-xl bg-card/50"
          />
        </div>

        <div className="flex items-center gap-2 flex-wrap">
          <div className="flex items-center gap-1 bg-muted/40 p-1 rounded-xl border border-border/50">
            <button
              onClick={() => setFilterStatus('todos')}
              className={cn(
                'px-2.5 py-1 rounded-lg text-xs font-semibold transition-all',
                filterStatus === 'todos' ? 'bg-primary text-primary-foreground shadow-sm' : 'text-muted-foreground hover:text-foreground'
              )}
            >
              Todos ({todosColaboradores.length})
            </button>
            <button
              onClick={() => setFilterStatus('presente')}
              className={cn(
                'px-2.5 py-1 rounded-lg text-xs font-semibold transition-all',
                filterStatus === 'presente' ? 'bg-emerald-600 text-white shadow-sm' : 'text-muted-foreground hover:text-foreground'
              )}
            >
              Presentes
            </button>
            <button
              onClick={() => setFilterStatus('falta')}
              className={cn(
                'px-2.5 py-1 rounded-lg text-xs font-semibold transition-all',
                filterStatus === 'falta' ? 'bg-rose-600 text-white shadow-sm' : 'text-muted-foreground hover:text-foreground'
              )}
            >
              Faltas
            </button>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {colaboradoresFiltrados.map((c) => {
          const cfg = statusConfig[c.status] || statusConfig.presente;
          return (
            <Card
              key={c.id}
              className="border-border/60 bg-card/50 hover:border-emerald-500/40 transition-all shadow-md group"
            >
              <CardContent className="p-4 space-y-3">
                <div className="flex items-start gap-3">
                  <div
                    onClick={() => {
                      if (c.foto) {
                        setFotoModalAberta({ url: c.foto, nome: c.nome, cargo: c.cargo });
                      }
                    }}
                    className={cn(
                      'w-14 h-14 rounded-xl border-2 overflow-hidden flex items-center justify-center shrink-0 cursor-pointer shadow-sm transition-transform group-hover:scale-105',
                      c.status === 'presente' ? 'border-emerald-500/40 bg-emerald-950/20' : 'border-rose-500/40 bg-rose-950/20'
                    )}
                  >
                    {c.foto ? (
                      <img src={c.foto} alt={c.nome} className="w-full h-full object-cover" />
                    ) : (
                      <span className="text-base font-black text-muted-foreground tracking-wider">
                        {getIniciais(c.nome)}
                      </span>
                    )}
                  </div>

                  <div className="flex-1 min-w-0">
                    <div className="flex items-center justify-between gap-1">
                      <h4 className="font-bold text-sm text-foreground truncate">{c.nome}</h4>
                      <Badge className={cn('text-[10px] px-1.5 py-0 font-bold uppercase', cfg.className)}>
                        {cfg.label}
                      </Badge>
                    </div>

                    <p className="text-xs text-muted-foreground font-medium truncate flex items-center gap-1 mt-0.5">
                      <Briefcase className="w-3 h-3 text-emerald-400 shrink-0" />
                      {c.cargo}
                    </p>

                    <p className="text-[11px] text-muted-foreground truncate flex items-center gap-1 mt-0.5">
                      <Building2 className="w-3 h-3 text-teal-400 shrink-0" />
                      {c.unidade}
                    </p>
                  </div>
                </div>

                <div className="pt-2 border-t border-border/40 flex items-center justify-between text-[11px] text-muted-foreground">
                  <span className="flex items-center gap-1 tabular-nums">
                    <CalendarDays className="w-3 h-3 text-muted-foreground" />
                    Adm: {c.dataAdmissao || '10/02/2023'}
                  </span>
                  <span className="font-semibold text-foreground truncate max-w-[140px]">
                    {c.veiculoPrefixo}
                  </span>
                </div>
              </CardContent>
            </Card>
          );
        })}
      </div>

      {modalNovoAberto && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/75 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="relative w-full max-w-md rounded-2xl border border-border bg-card p-6 shadow-2xl space-y-4">
            <div className="flex items-center justify-between border-b border-border/50 pb-3">
              <div className="flex items-center gap-2">
                <div className="w-8 h-8 rounded-lg bg-emerald-500/15 border border-emerald-500/30 flex items-center justify-center">
                  <Plus className="w-4 h-4 text-emerald-400" />
                </div>
                <div>
                  <h3 className="text-base font-bold text-foreground">Cadastrar Colaborador</h3>
                  <p className="text-xs text-muted-foreground">Adicione um novo membro à equipe</p>
                </div>
              </div>
              <button
                onClick={() => setModalNovoAberto(false)}
                className="rounded-lg p-1 text-muted-foreground hover:bg-muted"
              >
                <X className="w-5 h-5" />
              </button>
            </div>

            <form onSubmit={handleCadastrarColaborador} className="space-y-3 text-xs">
              <div>
                <label className="block font-medium text-foreground mb-1">Nome Completo</label>
                <Input
                  required
                  placeholder="Ex: João Ferreira da Silva"
                  value={novoNome}
                  onChange={(e) => setNovoNome(e.target.value)}
                />
              </div>

              <div className="grid grid-cols-2 gap-2">
                <div>
                  <label className="block font-medium text-foreground mb-1">Função / Cargo</label>
                  <Input
                    placeholder="Ex: Operador Florestal"
                    value={novoCargo}
                    onChange={(e) => setNovoCargo(e.target.value)}
                  />
                </div>
                <div>
                  <label className="block font-medium text-foreground mb-1">Unidade</label>
                  <select
                    value={novaUnidade}
                    onChange={(e) => setNovaUnidade(e.target.value as any)}
                    className="w-full h-10 px-3 rounded-xl border border-input bg-card/50 text-xs text-foreground focus:outline-none"
                  >
                    <option value="ribas">Ribas do Rio Pardo</option>
                    <option value="agua_clara">Água Clara</option>
                  </select>
                </div>
              </div>

              <div className="grid grid-cols-2 gap-2">
                <div>
                  <label className="block font-medium text-foreground mb-1">Data de Admissão</label>
                  <Input
                    placeholder="Ex: 15/01/2023"
                    value={novaDataAdmissao}
                    onChange={(e) => setNovaDataAdmissao(e.target.value)}
                  />
                </div>
                <div>
                  <label className="block font-medium text-foreground mb-1">Telefone</label>
                  <Input
                    placeholder="(67) 99999-0000"
                    value={novoTelefone}
                    onChange={(e) => setNovoTelefone(e.target.value)}
                  />
                </div>
              </div>

              <div>
                <label className="block font-medium text-foreground mb-1">Foto do Colaborador (opcional)</label>
                <input
                  type="file"
                  accept="image/*"
                  onChange={handleFotoUpload}
                  className="w-full text-xs text-muted-foreground file:mr-2 file:py-1 file:px-3 file:rounded-lg file:border-0 file:bg-emerald-600 file:text-white hover:file:bg-emerald-500 cursor-pointer"
                />
              </div>

              <div className="flex justify-end gap-2 pt-3 border-t border-border/40">
                <Button type="button" variant="outline" onClick={() => setModalNovoAberto(false)}>
                  Cancelar
                </Button>
                <Button type="submit" className="bg-emerald-600 hover:bg-emerald-500 text-white font-semibold">
                  Cadastrar
                </Button>
              </div>
            </form>
          </div>
        </div>
      )}

      {modalExcelAberto && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/75 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="relative w-full max-w-xl rounded-2xl border border-border bg-card p-6 shadow-2xl space-y-4">
            <div className="flex items-center justify-between border-b border-border/50 pb-3">
              <div className="flex items-center gap-2">
                <div className="w-8 h-8 rounded-lg bg-emerald-500/15 border border-emerald-500/30 flex items-center justify-center">
                  <FileSpreadsheet className="w-4 h-4 text-emerald-400" />
                </div>
                <div>
                  <h3 className="text-base font-bold text-foreground">Importar Planilha de Colaboradores</h3>
                  <p className="text-xs text-muted-foreground">Suba um arquivo Excel (.csv / .xlsx) com os dados</p>
                </div>
              </div>
              <button
                onClick={() => setModalExcelAberto(false)}
                className="rounded-lg p-1 text-muted-foreground hover:bg-muted"
              >
                <X className="w-5 h-5" />
              </button>
            </div>

            <div className="space-y-4">
              <div className="p-3 rounded-xl border border-dashed border-emerald-500/40 bg-emerald-500/5 flex flex-col items-center justify-center text-center p-6 space-y-3">
                <FileUp className="w-8 h-8 text-emerald-400" />
                <div>
                  <p className="text-xs font-semibold text-foreground">
                    Clique abaixo para selecionar a planilha
                  </p>
                  <p className="text-[11px] text-muted-foreground mt-0.5">
                    Colunas aceitas: Nome, Função/Cargo, Unidade, Data de Admissão, Telefone
                  </p>
                </div>
                <input
                  ref={excelInputRef}
                  type="file"
                  accept=".csv,.txt,.xlsx"
                  onChange={handleUploadExcelArquivo}
                  className="hidden"
                />
                <Button
                  type="button"
                  onClick={() => excelInputRef.current?.click()}
                  className="bg-emerald-600 hover:bg-emerald-500 text-white font-semibold text-xs"
                >
                  Selecionar Arquivo do Computador
                </Button>
                {excelArquivoNome && (
                  <span className="text-xs text-emerald-400 font-semibold">{excelArquivoNome}</span>
                )}
              </div>

              {isProcessandoExcel && (
                <div className="flex items-center justify-center gap-2 p-3 text-xs text-muted-foreground">
                  <Loader2 className="w-4 h-4 animate-spin text-emerald-400" />
                  <span>Processando linhas da planilha...</span>
                </div>
              )}

              {excelErro && (
                <div className="p-3 rounded-xl border border-rose-500/30 bg-rose-500/10 text-rose-300 text-xs flex items-center gap-2">
                  <AlertCircle className="w-4 h-4 shrink-0 text-rose-400" />
                  <span>{excelErro}</span>
                </div>
              )}

              {excelPreview.length > 0 && (
                <div className="space-y-2">
                  <div className="flex items-center justify-between text-xs">
                    <span className="font-semibold text-foreground">
                      Prévia dos Colaboradores ({excelPreview.length} encontrados):
                    </span>
                    <Badge variant="outline" className="border-emerald-500/40 text-emerald-400 bg-emerald-500/10">
                      Pronto para salvar
                    </Badge>
                  </div>
                  <div className="max-h-48 overflow-y-auto rounded-xl border border-border/50 divide-y divide-border/30 bg-muted/20 text-xs">
                    {excelPreview.slice(0, 10).map((p, i) => (
                      <div key={i} className="p-2 flex items-center justify-between">
                        <div>
                          <span className="font-bold text-foreground">{p.nome}</span>
                          <span className="text-muted-foreground ml-2">({p.cargo})</span>
                        </div>
                        <span className="text-muted-foreground text-[11px]">{p.unidade}</span>
                      </div>
                    ))}
                    {excelPreview.length > 10 && (
                      <div className="p-2 text-center text-[11px] text-muted-foreground font-medium">
                        + {excelPreview.length - 10} outros colaboradores...
                      </div>
                    )}
                  </div>
                </div>
              )}

              {excelImportSucesso && (
                <div className="p-3 rounded-xl border border-emerald-500/30 bg-emerald-500/10 text-emerald-300 text-xs flex items-center gap-2">
                  <CheckCircle2 className="w-4 h-4 shrink-0 text-emerald-400" />
                  <span>Colaboradores importados com sucesso para o banco de dados!</span>
                </div>
              )}

              <div className="flex items-center justify-between pt-3 border-t border-border/40">
                <Button
                  type="button"
                  variant="ghost"
                  size="sm"
                  onClick={baixarModeloExcel}
                  className="text-xs text-muted-foreground hover:text-foreground"
                >
                  <Download className="w-3.5 h-3.5 mr-1" />
                  Baixar Modelo de Exemplo (.csv)
                </Button>

                <div className="flex gap-2">
                  <Button type="button" variant="outline" onClick={() => setModalExcelAberto(false)}>
                    Fechar
                  </Button>
                  <Button
                    type="button"
                    onClick={handleConfirmarImportacao}
                    disabled={excelPreview.length === 0 || excelImportSucesso}
                    className="bg-emerald-600 hover:bg-emerald-500 text-white font-semibold text-xs"
                  >
                    Confirmar e Importar
                  </Button>
                </div>
              </div>
            </div>
          </div>
        </div>
      )}

      {fotoModalAberta && (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/80 backdrop-blur-md animate-in fade-in"
          onClick={() => setFotoModalAberta(null)}
        >
          <div className="relative max-w-sm w-full bg-card rounded-2xl p-4 border border-border/80 shadow-2xl text-center space-y-3" onClick={(e) => e.stopPropagation()}>
            <img
              src={fotoModalAberta.url}
              alt={fotoModalAberta.nome}
              className="w-48 h-48 rounded-2xl object-cover mx-auto border-2 border-emerald-500/40 shadow-lg"
            />
            <div>
              <h3 className="font-bold text-foreground text-base">{fotoModalAberta.nome}</h3>
              <p className="text-xs text-muted-foreground">{fotoModalAberta.cargo}</p>
            </div>
            <Button
              variant="outline"
              size="sm"
              onClick={() => setFotoModalAberta(null)}
              className="w-full"
            >
              Fechar
            </Button>
          </div>
        </div>
      )}
    </div>
  );
};

