import React, { useState, useEffect } from 'react';
import { Navbar } from './components/Navbar';
import { MetricsHeader } from './components/MetricsHeader';
import { VehicleCardGrid } from './components/VehicleCardGrid';
import { CollaboratorsManagement } from './components/CollaboratorsManagement';
import { TeamsManagement } from './components/TeamsManagement';
import { ExportReports } from './components/ExportReports';
import { NewTeamModal, NovaEquipePayload } from './components/NewTeamModal';
import { supabase } from './lib/supabase';
import { VEICULOS_INICIAIS, COLABORADORES_RESERVA } from './data/mockData';
import { Veiculo, Colaborador, Regional, StatusPresenca, MotivoFalta } from './types';

export const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'veiculos' | 'colaboradores' | 'equipes' | 'relatorios'>('veiculos');
  const [selectedRegional, setSelectedRegional] = useState<Regional>('todas');
  const [selectedDate, setSelectedDate] = useState<Date>(new Date());
  const [isNewTeamModalOpen, setIsNewTeamModalOpen] = useState(false);

  const [veiculos, setVeiculos] = useState<Veiculo[]>(() => {
    try {
      const salvo = localStorage.getItem('gestao_veiculos_florestal');
      return salvo ? JSON.parse(salvo) : VEICULOS_INICIAIS;
    } catch {
      return VEICULOS_INICIAIS;
    }
  });

  const [colaboradoresReserva, setColaboradoresReserva] = useState<Colaborador[]>(() => {
    try {
      const salvo = localStorage.getItem('gestao_reserva_florestal');
      return salvo ? JSON.parse(salvo) : COLABORADORES_RESERVA;
    } catch {
      return COLABORADORES_RESERVA;
    }
  });

  useEffect(() => {
    try {
      localStorage.setItem('gestao_veiculos_florestal', JSON.stringify(veiculos));
    } catch (e) {
      console.warn('Erro ao salvar veículos no LocalStorage:', e);
    }
  }, [veiculos]);

  useEffect(() => {
    try {
      localStorage.setItem('gestao_reserva_florestal', JSON.stringify(colaboradoresReserva));
    } catch (e) {
      console.warn('Erro ao salvar reserva no LocalStorage:', e);
    }
  }, [colaboradoresReserva]);

  useEffect(() => {
    let authSub: { unsubscribe: () => void } | null = null;
    try {
      const { data } = supabase.auth.onAuthStateChange((_event: any, _session: any) => {
        // Listener seguro de autenticação
      });
      authSub = data?.subscription ?? null;
    } catch (e) {
      console.warn('Supabase auth listener omitido:', e);
    }

    return () => {
      authSub?.unsubscribe?.();
    };
  }, []);

  const handleUpdateColaboradorStatus = (
    colaboradorId: string,
    novoStatus: StatusPresenca,
    motivo?: MotivoFalta,
    observacao?: string,
    substitutoId?: string
  ) => {
    let nomeSubstituto: string | undefined = undefined;
    if (substitutoId) {
      const colabSub = colaboradoresReserva.find((c) => c?.id === substitutoId);
      if (colabSub) {
        nomeSubstituto = colabSub.nome;
      }
    }

    setVeiculos((prev) =>
      prev.map((v) => {
        if (!v || !v.assentos) return v;
        const novosAssentos = { ...v.assentos };
        let mudou = false;

        (['motorista', 'frenteDir', 'trasEsq', 'trasDir'] as const).forEach((pos) => {
          const colab = novosAssentos[pos];
          if (colab && colab.id === colaboradorId) {
            novosAssentos[pos] = {
              ...colab,
              status: novoStatus,
              motivoFalta: novoStatus === 'falta' ? motivo : undefined,
              observacao: novoStatus === 'falta' ? observacao : undefined,
              substitutoId: novoStatus === 'substituto' ? substitutoId : undefined,
              substitutoNome: novoStatus === 'substituto' ? nomeSubstituto : undefined,
            };
            mudou = true;
          }
        });

        return mudou ? { ...v, assentos: novosAssentos } : v;
      })
    );
  };

  const handleCriarEquipe = (payload: NovaEquipePayload) => {
    const novoVeiculo: Veiculo = {
      id: `veic-${Date.now()}`,
      prefixo: payload.veiculoPrefixo,
      placa: payload.veiculoPlaca,
      modelo: payload.veiculoModelo || 'Toyota Hilux 4x4',
      ano: new Date().getFullYear(),
      regional: payload.regional,
      statusOperacional: 'ativo',
      equipe1Codigo: payload.codigo,
      equipe2Codigo: `${payload.codigo}-B`,
      assentos: {
        motorista: payload.motorista,
        frenteDir: payload.frenteDir,
        trasEsq: payload.trasEsq || {
          id: `colab-tras1-${Date.now()}`,
          nome: 'Operador Traseiro 1',
          cargo: 'Operador Florestal',
          foto: '',
          telefone: '(67) 99999-0000',
          status: 'presente',
          equipeId: payload.codigo,
          equipeNumero: 2,
          posicaoVeiculo: 'tras_esq',
          unidade: payload.regional === 'ribas' ? 'Ribas do Rio Pardo' : 'Água Clara',
          dataAdmissao: '01/02/2023',
        },
        trasDir: payload.trasDir || {
          id: `colab-tras2-${Date.now()}`,
          nome: 'Operador Traseiro 2',
          cargo: 'Operador Florestal',
          foto: '',
          telefone: '(67) 99999-0000',
          status: 'presente',
          equipeId: payload.codigo,
          equipeNumero: 2,
          posicaoVeiculo: 'tras_dir',
          unidade: payload.regional === 'ribas' ? 'Ribas do Rio Pardo' : 'Água Clara',
          dataAdmissao: '01/02/2023',
        },
      },
    };

    setVeiculos((prev) => [novoVeiculo, ...prev]);
  };

  return (
    <div className="min-h-screen bg-background text-foreground flex flex-col antialiased selection:bg-emerald-500/20 selection:text-emerald-300">
      <Navbar
        activeTab={activeTab}
        onTabChange={setActiveTab}
        selectedRegional={selectedRegional}
        onRegionalChange={setSelectedRegional}
        selectedDate={selectedDate}
        onDateChange={setSelectedDate}
        onNovaEquipeClick={() => setIsNewTeamModalOpen(true)}
      />

      <main className="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-6 space-y-6">
        <MetricsHeader
          veiculos={veiculos}
          selectedRegional={selectedRegional}
          selectedDate={selectedDate}
          onFiltroRegionalChange={setSelectedRegional}
          onNovaEquipe={() => setIsNewTeamModalOpen(true)}
        />

        {activeTab === 'veiculos' && (
          <VehicleCardGrid
            veiculos={veiculos}
            colaboradoresReserva={colaboradoresReserva}
            selectedRegional={selectedRegional}
            selectedDate={selectedDate}
            onUpdateColaboradorStatus={handleUpdateColaboradorStatus}
          />
        )}

        {activeTab === 'colaboradores' && (
          <CollaboratorsManagement
            veiculos={veiculos}
            colaboradoresReserva={colaboradoresReserva}
            selectedRegional={selectedRegional}
            onUpdateColaboradorStatus={handleUpdateColaboradorStatus}
          />
        )}

        {activeTab === 'equipes' && (
          <TeamsManagement
            veiculos={veiculos}
            selectedRegional={selectedRegional}
            onNovaEquipeClick={() => setIsNewTeamModalOpen(true)}
          />
        )}

        {activeTab === 'relatorios' && (
          <ExportReports
            veiculos={veiculos}
            colaboradoresReserva={colaboradoresReserva}
            selectedRegional={selectedRegional}
            selectedDate={selectedDate}
          />
        )}
      </main>

      <NewTeamModal
        isOpen={isNewTeamModalOpen}
        onClose={() => setIsNewTeamModalOpen(false)}
        colaboradoresReserva={colaboradoresReserva}
        onCriarEquipe={handleCriarEquipe}
      />
    </div>
  );
};

export default App;

