import React, { useState } from 'react';
import {
  Car,
  Users,
  CheckCircle2,
  XCircle,
  UserCheck2,
  AlertCircle,
  Phone,
  Search,
  Sparkles,
  MapPin,
  Clock,
  ShieldAlert,
} from 'lucide-react';
import { Veiculo, Colaborador, StatusPresenca, MotivoFalta, Regional } from '../types';
import { Card, CardContent } from './ui/card';
import { Badge } from './ui/badge';
import { Button } from './ui/button';
import { Input } from './ui/input';
import { AttendanceModal } from './AttendanceModal';
import { cn } from '@/lib/utils';

export interface VehicleCardGridProps {
  veiculos?: Veiculo[];
  colaboradoresReserva?: Colaborador[];
  selectedRegional?: Regional;
  onUpdateColaboradorStatus?: (
    colaboradorId: string,
    novoStatus: StatusPresenca,
    motivo?: MotivoFalta,
    observacao?: string,
    substitutoId?: string
  ) => void;
  onNovaEquipeClick?: () => void;
}

const statusBadgeConfig: Record<StatusPresenca, { label: string; className: string; icon: React.ComponentType<{ className?: string }> }> = {
  presente: {
    label: 'Presente',
    className: 'bg-emerald-500/15 text-emerald-400 border-emerald-500/30',
    icon: CheckCircle2,
  },
  falta: {
    label: 'Falta',
    className: 'bg-rose-500/15 text-rose-400 border-rose-500/30',
    icon: XCircle,
  },
  substituto: {
    label: 'Substituto',
    className: 'bg-amber-500/15 text-amber-400 border-amber-500/30',
    icon: UserCheck2,
  },
};

export const VehicleCardGrid: React.FC<VehicleCardGridProps> = ({
  veiculos = [],
  colaboradoresReserva = [],
  selectedRegional = 'todas',
  onUpdateColaboradorStatus,
  onNovaEquipeClick,
}) => {
  const [busca, setBusca] = useState('');
  const [modalColaborador, setModalColaborador] = useState<Colaborador | null>(null);
  const [modalVeiculo, setModalVeiculo] = useState<Veiculo | null>(null);

  const veiculosFiltrados = (veiculos || []).filter((v) => {
    if (!v) return false;
    const matchRegional = selectedRegional === 'todas' || v.regional === selectedRegional;
    if (!matchRegional) return false;

    if (!busca.trim()) return true;
    const termo = busca.toLowerCase();
    const assentos = [
      v.assentos?.motorista?.nome,
      v.assentos?.frenteDir?.nome,
      v.assentos?.trasEsq?.nome,
      v.assentos?.trasDir?.nome,
    ]
      .filter(Boolean)
      .join(' ')
      .toLowerCase();

    return (
      (v.prefixo || '').toLowerCase().includes(termo) ||
      (v.placa || '').toLowerCase().includes(termo) ||
      (v.modelo || '').toLowerCase().includes(termo) ||
      (v.equipe1Codigo || '').toLowerCase().includes(termo) ||
      (v.equipe2Codigo || '').toLowerCase().includes(termo) ||
      assentos.includes(termo)
    );
  });

  const handleOpenAttendance = (colab: Colaborador, veiculo: Veiculo) => {
    setModalColaborador(colab);
    setModalVeiculo(veiculo);
  };

  const handleCloseAttendance = () => {
    setModalColaborador(null);
    setModalVeiculo(null);
  };

  const getIniciais = (nome?: string) => {
    if (!nome) return 'OP';
    const partes = nome.trim().split(' ');
    if (partes.length === 1) return partes[0].slice(0, 2).toUpperCase();
    return (partes[0][0] + (partes[partes.length - 1]?.[0] || '')).toUpperCase();
  };

  return (
    <div className="w-full space-y-4">
      {/* Search and Filters Bar */}
      <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3 bg-card/60 backdrop-blur-md p-3 rounded-2xl border border-border/60">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-2.5 w-4 h-4 text-muted-foreground" />
          <Input
            type="text"
            placeholder="Buscar por prefixo, placa, equipe ou nome do operador..."
            value={busca}
            onChange={(e) => setBusca(e.target.value)}
            className="pl-9 h-10 border-border/60 bg-background/50"
          />
        </div>
        <div className="flex items-center gap-2">
          <Badge variant="outline" className="h-9 px-3 text-xs font-semibold tabular-nums border-border/80">
            {veiculosFiltrados.length} {veiculosFiltrados.length === 1 ? 'veículo' : 'veículos'}
          </Badge>
          {onNovaEquipeClick && (
            <Button
              type="button"
              onClick={onNovaEquipeClick}
              size="sm"
              className="h-9 px-3 gap-1.5 bg-emerald-600 hover:bg-emerald-500 text-white font-medium"
            >
              <Sparkles className="w-3.5 h-3.5" />
              <span>Nova Equipe</span>
            </Button>
          )}
        </div>
      </div>

      {/* Grid of Vehicles */}
      {veiculosFiltrados.length === 0 ? (
        <Card className="p-8 text-center border-dashed border-border/60">
          <div className="max-w-sm mx-auto space-y-3">
            <Car className="w-10 h-10 mx-auto text-muted-foreground/60" />
            <h4 className="text-sm font-bold text-foreground">Nenhum veículo localizado</h4>
            <p className="text-xs text-muted-foreground">
              Tente ajustar sua busca ou selecionar outra regional no topo.
            </p>
          </div>
        </Card>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {veiculosFiltrados.map((veiculo) => {
            const assentos: Array<{
              colab: Colaborador;
              posicaoTexto: string;
              equipeNumero: 1 | 2;
            }> = [
              { colab: veiculo.assentos?.motorista, posicaoTexto: 'Motorista', equipeNumero: 1 },
              { colab: veiculo.assentos?.frenteDir, posicaoTexto: 'Dianteiro Dir.', equipeNumero: 1 },
              { colab: veiculo.assentos?.trasEsq, posicaoTexto: 'Traseiro Esq.', equipeNumero: 2 },
              { colab: veiculo.assentos?.trasDir, posicaoTexto: 'Traseiro Dir.', equipeNumero: 2 },
            ].filter((item): item is { colab: Colaborador; posicaoTexto: string; equipeNumero: 1 | 2 } => Boolean(item.colab));

            const totalPresentes = assentos.filter(
              (a) => a.colab.status === 'presente' || a.colab.status === 'substituto'
            ).length;
            const temFalta = assentos.some((a) => a.colab.status === 'falta');

            return (
              <Card
                key={veiculo.id}
                className={cn(
                  'rounded-2xl border transition-all duration-200 overflow-hidden flex flex-col',
                  temFalta
                    ? 'border-rose-500/30 bg-gradient-to-b from-rose-500/5 to-card/60 shadow-lg'
                    : 'border-border/60 bg-card/60 shadow-md hover:border-border'
                )}
              >
                {/* Vehicle Header */}
                <div className="p-4 border-b border-border/40 bg-muted/20 flex items-center justify-between gap-2">
                  <div className="flex items-center gap-2.5">
                    <div className="w-9 h-9 rounded-xl bg-emerald-500/15 border border-emerald-500/30 flex items-center justify-center shrink-0">
                      <Car className="w-4 h-4 text-emerald-400" />
                    </div>
                    <div>
                      <div className="flex items-center gap-1.5">
                        <span className="font-extrabold text-sm text-foreground tracking-tight">
                          {veiculo.prefixo}
                        </span>
                        <span className="text-[10px] text-muted-foreground uppercase font-mono px-1.5 py-0.5 rounded bg-muted">
                          {veiculo.placa}
                        </span>
                      </div>
                      <p className="text-[11px] text-muted-foreground">
                        {veiculo.modelo} · {veiculo.regional === 'agua_clara' ? 'Água Clara' : 'Ribas'}
                      </p>
                    </div>
                  </div>

                  <Badge
                    variant="outline"
                    className={cn(
                      'text-[10px] font-bold tabular-nums',
                      temFalta
                        ? 'border-rose-500/40 text-rose-300 bg-rose-500/10'
                        : 'border-emerald-500/40 text-emerald-300 bg-emerald-500/10'
                    )}
                  >
                    {totalPresentes}/4 ativos
                  </Badge>
                </div>

                {/* Team Badges */}
                <div className="px-4 py-2 border-b border-border/40 bg-muted/10 flex items-center justify-between text-[11px] text-muted-foreground">
                  <div className="flex items-center gap-1">
                    <span className="font-semibold text-foreground">Equipe 1:</span>
                    <span>{veiculo.equipe1Codigo || 'EQ-1'}</span>
                  </div>
                  <div className="flex items-center gap-1">
                    <span className="font-semibold text-foreground">Equipe 2:</span>
                    <span>{veiculo.equipe2Codigo || 'EQ-2'}</span>
                  </div>
                </div>

                {/* Operadores dos 4 Assentos */}
                <div className="p-3 space-y-2 flex-1">
                  {assentos.map(({ colab, posicaoTexto, equipeNumero }) => {
                    const cfg = statusBadgeConfig[colab.status || 'presente'];
                    const IconeStatus = cfg.icon;

                    return (
                      <div
                        key={colab.id}
                        onClick={() => handleOpenAttendance(colab, veiculo)}
                        className={cn(
                          'p-2.5 rounded-xl border flex items-center justify-between gap-2.5 transition-all cursor-pointer group',
                          colab.status === 'presente'
                            ? 'border-border/50 bg-card/40 hover:bg-muted/40 hover:border-emerald-500/40'
                            : colab.status === 'falta'
                            ? 'border-rose-500/30 bg-rose-500/10 hover:border-rose-500/50'
                            : 'border-amber-500/30 bg-amber-500/10 hover:border-amber-500/50'
                        )}
                      >
                        <div className="flex items-center gap-2.5 min-w-0">
                          {colab.foto ? (
                            <img
                              src={colaboradorFoto(colab.foto)}
                              alt={colab.nome}
                              className="w-9 h-9 rounded-lg object-cover border border-border/50 shrink-0"
                            />
                          ) : (
                            <div className="w-9 h-9 rounded-lg bg-muted text-muted-foreground font-bold text-xs flex items-center justify-center shrink-0">
                              {getIniciais(colab.nome)}
                            </div>
                          )}

                          <div className="min-w-0">
                            <p className="text-xs font-semibold text-foreground truncate group-hover:text-primary transition-colors">
                              {colab.nome}
                            </p>
                            <p className="text-[10px] text-muted-foreground truncate">
                              {posicaoTexto} · Eq. {equipeNumero}
                            </p>
                            {colab.status === 'substituto' && colab.substitutoNome && (
                              <p className="text-[10px] text-amber-300 font-medium truncate">
                                Sub: {colab.substitutoNome}
                              </p>
                            )}
                            {colab.status === 'falta' && colab.motivoFalta && (
                              <p className="text-[10px] text-rose-300 truncate">
                                {colab.motivoFalta}
                              </p>
                            )}
                          </div>
                        </div>

                        <Badge
                          variant="outline"
                          className={cn('text-[10px] px-2 py-0.5 shrink-0 gap-1 font-semibold', cfg.className)}
                        >
                          <IconeStatus className="w-3 h-3" />
                          <span>{cfg.label}</span>
                        </Badge>
                      </div>
                    );
                  })}
                </div>
              </Card>
            );
          })}
        </div>
      )}

      {/* Attendance Modal */}
      {modalColaborador && (
        <AttendanceModal
          isOpen={Boolean(modalColaborador)}
          onClose={handleCloseAttendance}
          colaborador={modalColaborador}
          veiculo={modalVeiculo}
          colaboradoresReserva={colaboradoresReserva}
          onSalvar={(colabId, status, motivo, obs, subId) => {
            onUpdateColaboradorStatus?.(colabId, status, motivo, obs, subId);
            handleCloseAttendance();
          }}
        />
      )}
    </div>
  );
};

function colaboradorFoto(url?: string): string {
  return url || '';
}

