  agua_clara: 'Água Clara',
};

const getIniciais = (nome?: string) => {
  if (!nome) return 'CO';
  const partes = nome.trim().split(' ');
  if (partes.length === 1) return partes[0].substring(0, 2).toUpperCase();
  return (partes[0][0] + (partes[partes.length - 1]?.[0] || '')).toUpperCase();
};

export const CollaboratorsManagement: React.FC<CollaboratorsManagementProps> = ({
  veiculos = [],
  colaboradoresReserva = [],
  selectedRegional = 'todas',
  onImportarColaboradores,
  onAdicionarColaborador,
}) => {
  const [search, setSearch] = useState('');
  const [filterStatus, setFilterStatus] = useState<StatusPresenca | 'todos'>('todos');
  const [filterRegional, setFilterRegional] = useState<Regional | 'todas'>(selectedRegional);
  const [fotoModalAberta, setFotoModalAberta] = useState<{ url: string; nome: string; cargo: string } | null>(null);

  // Modal de cadastro manual
  const [modalNovoAberto, setModalNovoAberto] = useState(false);
  const [novoNome, setNovoNome] = useState('');
  const [novoCargo, setNovoCargo] = useState('');
  const [novoTelefone, setNovoTelefone] = useState('');
  const [novaFoto, setNovaFoto] = useState<string>('');
  const [novaUnidade, setNovaUnidade] = useState<'ribas' | 'agua_clara'>('ribas');
  const [novaDataAdmissao, setNovaDataAdmissao] = useState('15/01/2023');

  // Modal de Importação de Planilha
  const [modalExcelAberto, setModalExcelAberto] = useState(false);
  const [isProcessandoExcel, setIsProcessandoExcel] = useState(false);
  const [excelPreview, setExcelPreview] = useState<ColaboradorCompleto[]>([]);
  const [excelErro, setExcelErro] = useState<string | null>(null);
  const [excelArquivoNome, setExcelArquivoNome] = useState<string>('');
  const [excelImportSucesso, setExcelImportSucesso] = useState(false);
  const excelInputRef = useRef<HTMLInputElement>(null);

  const colaboradoresBase: ColaboradorCompleto[] = useMemo(() => {
    const lista: ColaboradorCompleto[] = [];
    (veiculos || []).forEach((v) => {
      if (!v || !v.assentos) return;
      const assentos: Array<{ colab?: Colaborador; pos: ColaboradorCompleto['posicaoVeiculo'] }> = [
        { colab: v.assentos.motorista, pos: 'motorista' },
        { colab: v.assentos.frenteDir, pos: 'frente_dir' },
        { colab: v.assentos.trasEsq, pos: 'tras_esq' },
        { colab: v.assentos.trasDir, pos: 'tras_dir' },
      ];
      assentos.forEach(({ colab, pos }) => {
        if (!colab) return;
        lista.push({
          id: colab.id,
          nome: colab.nome || 'Sem Nome',
          cargo: colab.cargo || 'Operador',
          matricula: '',
          foto: colab.foto ?? '',
          telefone: colab.telefone ?? '',
          status: colab.status || 'presente',
          motivoFalta: colab.motivoFalta,
          observacao: colab.observacao,
          substitutoNome: colab.substitutoNome,
          equipeId: colab.equipeId || '',
          equipeNumero: colab.equipeNumero || 1,
          posicaoVeiculo: pos,
          veiculoPrefixo: v.prefixo || '',
          veiculoPlaca: v.placa || '',
          regional: v.regional || 'ribas',
          unidade: colab.unidade || (v.regional === 'agua_clara' ? 'Água Clara' : 'Ribas do Rio Pardo'),
          dataAdmissao: colab.dataAdmissao || '10/02/2023',
        });
      });
    });

    (colaboradoresReserva || []).forEach((r, idx) => {
      if (!r) return;
      lista.push({
        id: r.id || `res-${idx}`,
        nome: r.nome || 'Colaborador Reserva',
        cargo: r.cargo || 'Reserva Operacional',
        matricula: '',
        foto: r.foto || '',
        telefone: r.telefone || '',
        status: r.status || 'presente',
        motivoFalta: r.motivoFalta,
        observacao: r.observacao,
        substitutoNome: r.substitutoNome,
        equipeId: 'reserva',
        equipeNumero: 1,
        posicaoVeiculo: 'motorista',
        veiculoPrefixo: 'Banco de Reserva',
        veiculoPlaca: '-',
        regional: 'ribas',
        unidade: r.unidade || 'Ribas do Rio Pardo',
        dataAdmissao: r.dataAdmissao || '05/06/2023',
      });
    });

    return lista;
  }, [veiculos, colaboradoresReserva]);

  const [colaboradoresAdicionados, setColaboradoresAdicionados] = useState<ColaboradorCompleto[]>([]);

  const todosColaboradores = useMemo(() => {
    return [...colaboradoresBase, ...colaboradoresAdicionados];
  }, [colaboradoresBase, colaboradoresAdicionados]);

  const colaboradoresFiltrados = useMemo(() => {
    return todosColaboradores.filter((c) => {
      if (!c) return false;
      const matchSearch =
        !search ||
        (c.nome || '').toLowerCase().includes(search.toLowerCase()) ||
        (c.cargo || '').toLowerCase().includes(search.toLowerCase()) ||
        (c.veiculoPlaca || '').toLowerCase().includes(search.toLowerCase()) ||
        (c.veiculoPrefixo || '').toLowerCase().includes(search.toLowerCase()) ||
        (c.unidade || '').toLowerCase().includes(search.toLowerCase());

      const matchStatus = filterStatus === 'todos' || c.status === filterStatus;
      const matchRegional = filterRegional === 'todas' || c.regional === filterRegional;

      return matchSearch && matchStatus && matchRegional;
    });
  }, [todosColaboradores, search, filterStatus, filterRegional]);

  const handleFotoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      if (event.target?.result) {
        setNovaFoto(event.target.result as string);
      }
    };
    reader.readAsDataURL(file);
  };

  const handleCadastrarColaborador = (e: React.FormEvent) => {
    e.preventDefault();
    if (!novoNome.trim()) return;

    const novo: ColaboradorCompleto = {
      id: `colab-custom-${Date.now()}`,
      nome: novoNome.trim(),
      cargo: novoCargo.trim() || 'Operador Florestal',
      matricula: '',
      foto: novaFoto,
      telefone: novoTelefone.trim() || '(67) 99999-0000',
      status: 'presente',
      equipeId: 'reserva',
      equipeNumero: 1,
      posicaoVeiculo: 'motorista',
      veiculoPrefixo: 'Banco de Reserva',
      veiculoPlaca: '-',
      regional: novaUnidade,
      unidade: novaUnidade === 'agua_clara' ? 'Água Clara' : 'Ribas do Rio Pardo',
      dataAdmissao: novaDataAdmissao || '15/01/2023',
    };

    setColaboradoresAdicionados((prev) => [novo, ...prev]);
    onAdicionarColaborador?.(novo);

    setNovoNome('');
    setNovoCargo('');
    setNovoTelefone('');
    setNovaFoto('');
    setModalNovoAberto(false);
  };

  // Parser universal nativo de CSV / Texto de planilhas (sem travar o Vite)
  const handleProcessarArquivoPlanilha = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsProcessandoExcel(true);
    setExcelErro(null);
    setExcelArquivoNome(file.name);

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const text = (event.target?.result as string) || '';
        const lines = text.split(/\r\n|\n/).filter((l) => l.trim().length > 0);

        if (lines.length < 2) {
          throw new Error('A planilha deve conter pelo menos o cabeçalho e 1 linha de colaboradores.');
        }

        // Detectar delimitador (ponto e vírgula, vírgula ou tab)
        const firstLine = lines[0];
        let delimiter = ';';
        if (firstLine.includes(';') && (firstLine.match(/;/g) || []).length >= 1) {
          delimiter = ';';
        } else if (firstLine.includes('\t')) {
          delimiter = '\t';
        } else if (firstLine.includes(',')) {
          delimiter = ',';
        }

        const parseLine = (line: string) => {
          return line
            .split(delimiter)
            .map((col) => col.replace(/^["']|["']$/g, '').trim());
        };

        const headers = parseLine(lines[0]).map((h) => h.toLowerCase());
        const nomeIdx = headers.findIndex((h) => h.includes('nome'));
        const cargoIdx = headers.findIndex((h) => h.includes('cargo') || h.includes('função') || h.includes('funcao'));
        const unidadeIdx = headers.findIndex((h) => h.includes('unidade') || h.includes('regional'));
        const admissaoIdx = headers.findIndex((h) => h.includes('admiss') || h.includes('data'));
        const telefoneIdx = headers.findIndex((h) => h.includes('tel') || h.includes('contato'));

        const parsed: ColaboradorCompleto[] = [];

        for (let i = 1; i < lines.length; i++) {
          const cols = parseLine(lines[i]);
          const rawNome = nomeIdx !== -1 ? cols[nomeIdx] : cols[0];
          if (!rawNome) continue;

          const rawCargo = cargoIdx !== -1 ? cols[cargoIdx] : cols[1] || 'Operador Florestal';
          const rawUnidade = unidadeIdx !== -1 ? cols[unidadeIdx] : cols[2] || 'Ribas do Rio Pardo';
          const rawAdmissao = admissaoIdx !== -1 ? cols[admissaoIdx] : cols[3] || '10/01/2023';
          const rawTelefone = telefoneIdx !== -1 ? cols[telefoneIdx] : cols[4] || '(67) 99999-0000';

          const isAguaClara = rawUnidade.toLowerCase().includes('clara');

          parsed.push({
            id: `planilha-colab-${Date.now()}-${i}`,
            nome: rawNome,
            cargo: rawCargo,
            matricula: '',
            foto: '',
            telefone: rawTelefone,
            status: 'presente',
            equipeId: 'reserva',
            equipeNumero: 1,
            posicaoVeiculo: 'motorista',
            veiculoPrefixo: 'Banco de Reserva',
            veiculoPlaca: '-',
            regional: isAguaClara ? 'agua_clara' : 'ribas',
            unidade: isAguaClara ? 'Água Clara' : 'Ribas do Rio Pardo',
            dataAdmissao: rawAdmissao,
          });
        }

        if (parsed.length === 0) {
          throw new Error('Nenhum colaborador foi identificado nas linhas da planilha.');
        }

        setExcelPreview(parsed);
      } catch (err: any) {
        setExcelErro(err?.message || 'Erro ao processar arquivo. Verifique o formato CSV.');
      } finally {
        setIsProcessandoExcel(false);
      }
    };

    reader.onerror = () => {
      setExcelErro('Falha ao ler o arquivo selecionado.');
      setIsProcessandoExcel(false);
    };

    reader.readAsText(file);
  };

  const handleConfirmarImportacaoExcel = () => {
    if (excelPreview.length === 0) return;
    setColaboradoresAdicionados((prev) => [...excelPreview, ...prev]);
    onImportarColaboradores?.(excelPreview);
    setExcelImportSucesso(true);
    setTimeout(() => {
      setModalExcelAberto(false);
      setExcelPreview([]);
      setExcelImportSucesso(false);
      setExcelArquivoNome('');
    }, 1200);
  };

  const handleBaixarModeloPlanilha = () => {
    const modelo = [
      ['Nome', 'Função', 'Unidade', 'Data de Admissão', 'Telefone'],
      ['João da Silva', 'Operador de Máquinas', 'Ribas do Rio Pardo', '12/03/2022', '(67) 99888-1122'],
      ['Pedro Henrique Souza', 'Ajudante Geral', 'Água Clara', '05/08/2021', '(67) 99777-3344'],
      ['Carlos Eduardo Santos', 'Mecânico Florestal', 'Ribas do Rio Pardo', '19/01/2023', '(67) 99666-5566'],
    ];

    const csvContent = '\uFEFF' + modelo.map((row) => row.map((c) => `"${c}"`).join(';')).join('\r\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', 'modelo-importacao-colaboradores.csv');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  return (
    <div className="w-full space-y-6">
      {/* Barra de Ações Superior */}
      <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3 bg-card/60 backdrop-blur-md p-4 rounded-2xl border border-border/80 shadow-sm">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-xl bg-emerald-500/15 border border-emerald-500/30 flex items-center justify-center shrink-0">
            <Users className="w-5 h-5 text-emerald-400" />
          </div>
          <div>
            <h2 className="text-lg font-bold text-foreground">Gestão de Colaboradores</h2>
            <p className="text-xs text-muted-foreground">
              Total de <span className="text-foreground font-semibold tabular-nums">{todosColaboradores.length}</span> colaboradores cadastrados
            </p>
          </div>
        </div>

        <div className="flex items-center gap-2 flex-wrap">
          <Button
            type="button"
            variant="outline"
            onClick={() => setModalExcelAberto(true)}
            className="gap-2 border-emerald-500/30 bg-emerald-500/10 text-emerald-300 hover:bg-emerald-500/20 text-xs font-semibold"
          >
            <FileSpreadsheet className="w-4 h-4 text-emerald-400" />
            <span>Importar Planilha</span>
          </Button>

          <Button
            type="button"
            onClick={() => setModalNovoAberto(true)}
            className="gap-2 bg-emerald-600 hover:bg-emerald-500 text-white shadow-md text-xs font-semibold"
          >
            <Plus className="w-4 h-4" />
            <span>Cadastrar Colaborador</span>
          </Button>
        </div>
      </div>

      {/* Filtros e Busca */}
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
        <div className="relative sm:col-span-1">
          <Search className="w-4 h-4 absolute left-3 top-3 text-muted-foreground" />
          <Input
            placeholder="Buscar por nome, cargo ou placa..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="pl-9 text-xs"
          />
        </div>

        <div>
          <select
            value={filterStatus}
            onChange={(e) => setFilterStatus(e.target.value as any)}
            className="w-full h-10 px-3 rounded-xl border border-input bg-card/50 text-xs text-foreground focus:outline-none focus:ring-2 focus:ring-emerald-500/30"
          >
            <option value="todos">Todos os Status</option>
            <option value="presente">Apenas Presentes</option>
            <option value="falta">Apenas Faltas</option>
            <option value="substituto">Apenas Substitutos</option>
          </select>
        </div>

        <div>
          <select
            value={filterRegional}
            onChange={(e) => setFilterRegional(e.target.value as any)}
            className="w-full h-10 px-3 rounded-xl border border-input bg-card/50 text-xs text-foreground focus:outline-none focus:ring-2 focus:ring-emerald-500/30"
          >
            <option value="todas">Todas as Unidades</option>
            <option value="ribas">Ribas do Rio Pardo</option>
            <option value="agua_clara">Água Clara</option>
          </select>
        </div>
      </div>

      {/* Grid de Cards dos Colaboradores */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-3.5">
        {colaboradoresFiltrados.map((colab) => (
          <Card key={colab.id} className="border-border/70 hover:border-border transition-all">
            <CardContent className="p-4 space-y-3">
              <div className="flex items-start justify-between gap-2">
                <div className="flex items-center gap-3">
                  {colab.foto ? (
                    <img
                      src={colab.foto}
                      alt={colab.nome}
                      className="w-11 h-11 rounded-xl object-cover border border-border/80 cursor-pointer shadow-sm"
                      onClick={() => setFotoModalAberta({ url: colab.foto, nome: colab.nome, cargo: colab.cargo })}
                    />
                  ) : (
                    <div className="w-11 h-11 rounded-xl bg-muted/80 border border-border flex items-center justify-center font-black text-xs text-muted-foreground shadow-inner">
                      {getIniciais(colab.nome)}
                    </div>
                  )}
                  <div>
                    <h3 className="font-bold text-sm text-foreground leading-snug">{colab.nome}</h3>
                    <p className="text-xs text-muted-foreground">{colab.cargo}</p>
                  </div>
                </div>
                <Badge
                  variant="outline"
                  className={cn('text-[10px] font-semibold capitalize', statusConfig[colab.status]?.className)}
                >
                  {statusConfig[colab.status]?.label || colab.status}
                </Badge>
              </div>

              <div className="grid grid-cols-2 gap-2 text-[11px] pt-1 border-t border-border/40">
                <div className="flex items-center gap-1.5 text-muted-foreground">
                  <Building2 className="w-3.5 h-3.5 text-emerald-400 shrink-0" />
                  <span className="truncate">{colab.unidade || regionalLabel[colab.regional]}</span>
                </div>
                <div className="flex items-center gap-1.5 text-muted-foreground">
                  <CalendarDays className="w-3.5 h-3.5 text-teal-400 shrink-0" />
                  <span className="truncate tabular-nums">Adm: {colab.dataAdmissao || '10/02/2023'}</span>
                </div>
                <div className="flex items-center gap-1.5 text-muted-foreground">
                  <Phone className="w-3.5 h-3.5 text-muted-foreground shrink-0" />
                  <span className="truncate tabular-nums">{colab.telefone || '(67) 99999-0000'}</span>
                </div>
                <div className="flex items-center gap-1.5 text-muted-foreground">
                  <Briefcase className="w-3.5 h-3.5 text-muted-foreground shrink-0" />
                  <span className="truncate">{colab.veiculoPrefixo || 'Reserva'}</span>
                </div>
              </div>
            </CardContent>
          </Card>
        ))}
      </div>

      {/* Modal de Importação de Planilha Excel / CSV */}
      {modalExcelAberto && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/75 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="relative w-full max-w-2xl rounded-2xl border border-border/80 bg-card p-6 shadow-2xl space-y-4">
            <div className="flex items-center justify-between border-b border-border/40 pb-3">
              <div className="flex items-center gap-2.5">
                <div className="w-9 h-9 rounded-xl bg-emerald-500/15 border border-emerald-500/30 flex items-center justify-center">
                  <FileSpreadsheet className="w-5 h-5 text-emerald-400" />
                </div>
                <div>
                  <h3 className="text-base font-bold text-foreground">Importar Planilha de Colaboradores</h3>
                  <p className="text-xs text-muted-foreground">Envie sua planilha Excel (.csv com colunas Nome, Função, Unidade, Admissão)</p>
                </div>
              </div>
              <button
                type="button"
                onClick={() => setModalExcelAberto(false)}
                className="p-1.5 rounded-lg text-muted-foreground hover:bg-muted transition-colors"
              >
                <X className="w-5 h-5" />
              </button>
            </div>

            <div className="space-y-4">
              <div
                onClick={() => excelInputRef.current?.click()}
                className="border-2 border-dashed border-emerald-500/40 hover:border-emerald-500 rounded-2xl p-6 text-center cursor-pointer transition-colors bg-emerald-500/5 hover:bg-emerald-500/10 space-y-2"
              >
                <input
                  ref={excelInputRef}
                  type="file"
                  accept=".csv,.txt,.xlsx,.xls"
                  onChange={handleProcessarArquivoPlanilha}
                  className="hidden"
                />
                <FileUp className="w-8 h-8 text-emerald-400 mx-auto" />
                <p className="text-sm font-semibold text-foreground">
                  {excelArquivoNome || 'Clique para escolher ou arraste o arquivo da planilha'}
                </p>
                <p className="text-xs text-muted-foreground">
                  Suporta arquivos CSV com separador vírgula ou ponto e vírgula
                </p>
              </div>

              <div className="flex items-center justify-between text-xs text-muted-foreground bg-muted/40 p-3 rounded-xl border border-border/50">
                <span>Precisa do modelo padrão para preenchimento?</span>
                <Button
                  type="button"
                  variant="ghost"
                  size="sm"
                  onClick={handleBaixarModeloPlanilha}
                  className="text-emerald-400 hover:text-emerald-300 gap-1 text-xs"
                >
                  <Download className="w-3.5 h-3.5" />
                  <span>Baixar Modelo CSV</span>
                </Button>
              </div>

              {isProcessandoExcel && (
                <div className="flex items-center justify-center gap-2 py-4 text-emerald-400 text-xs">
                  <Loader2 className="w-4 h-4 animate-spin" />
                  <span>Processando arquivo e identificando colaboradores...</span>
                </div>
              )}

              {excelErro && (
                <div className="flex items-center gap-2 p-3 rounded-xl bg-rose-500/10 border border-rose-500/30 text-rose-300 text-xs">
                  <AlertCircle className="w-4 h-4 shrink-0" />
                  <span>{excelErro}</span>
                </div>
              )}

              {excelPreview.length > 0 && (
                <div className="space-y-2">
                  <div className="flex items-center justify-between text-xs font-semibold text-foreground">
                    <span>Prévia dos registros identificados ({excelPreview.length} colaboradores):</span>
                    <Badge variant="outline" className="text-emerald-400 border-emerald-500/30">
                      Pronto para importar
                    </Badge>
                  </div>
                  <div className="max-h-48 overflow-y-auto rounded-xl border border-border/60 divide-y divide-border/40 text-xs">
                    {excelPreview.map((item, idx) => (
                      <div key={idx} className="p-2.5 flex items-center justify-between bg-card/40">
                        <div>
                          <p className="font-bold text-foreground">{item.nome}</p>
                          <p className="text-[11px] text-muted-foreground">
                            {item.cargo} • {item.unidade}
                          </p>
                        </div>
                        <span className="text-[11px] text-muted-foreground tabular-nums">
                          Adm: {item.dataAdmissao}
                        </span>
                      </div>
                    ))}
                  </div>
                </div>
              )}

              {excelImportSucesso && (
                <div className="flex items-center gap-2 p-3 rounded-xl bg-emerald-500/10 border border-emerald-500/30 text-emerald-300 text-xs font-semibold">
                  <CheckCircle2 className="w-4 h-4" />
                  <span>Colaboradores importados com sucesso para a base!</span>
                </div>
              )}

              <div className="flex items-center justify-end gap-2 pt-2 border-t border-border/40">
                <Button
                  type="button"
                  variant="outline"
                  onClick={() => setModalExcelAberto(false)}
                >
                  Cancelar
                </Button>
                <Button
                  type="button"
                  disabled={excelPreview.length === 0 || isProcessandoExcel}
                  onClick={handleConfirmarImportacaoExcel}
                  className="bg-emerald-600 hover:bg-emerald-500 text-white"
                >
                  Confirmar Importação ({excelPreview.length})
                </Button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Modal de Cadastro Manual */}
      {modalNovoAberto && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/75 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="relative w-full max-w-md rounded-2xl border border-border/80 bg-card p-6 shadow-2xl space-y-4">
            <div className="flex items-center justify-between border-b border-border/40 pb-3">
              <h3 className="text-base font-bold text-foreground">Novo Colaborador</h3>
              <button
                type="button"
                onClick={() => setModalNovoAberto(false)}
                className="p-1 rounded-lg text-muted-foreground hover:bg-muted"
              >
                <X className="w-5 h-5" />
              </button>
            </div>

            <form onSubmit={handleCadastrarColaborador} className="space-y-3 text-xs">
              <div>
                <label className="block font-medium text-foreground mb-1">Nome Completo</label>
                <Input
                  required
                  placeholder="Ex: João da Silva"
                  value={novoNome}
                  onChange={(e) => setNovoNome(e.target.value)}
                />
              </div>

              <div>
                <label className="block font-medium text-foreground mb-1">Cargo / Função</label>
                <Input
                  placeholder="Ex: Operador Florestal"
                  value={novoCargo}
                  onChange={(e) => setNovoCargo(e.target.value)}
                />
              </div>

              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="block font-medium text-foreground mb-1">Unidade</label>
                  <select
                    value={novaUnidade}
                    onChange={(e) => setNovaUnidade(e.target.value as any)}
                    className="w-full h-10 px-3 rounded-xl border border-input bg-background text-xs"
                  >
                    <option value="ribas">Ribas do Rio Pardo</option>
                    <option value="agua_clara">Água Clara</option>
                  </select>
                </div>
                <div>
                  <label className="block font-medium text-foreground mb-1">Data de Admissão</label>
                  <Input
                    placeholder="DD/MM/AAAA"
                    value={novaDataAdmissao}
                    onChange={(e) => setNovaDataAdmissao(e.target.value)}
                  />
                </div>
              </div>

              <div>
                <label className="block font-medium text-foreground mb-1">Telefone</label>
                <Input
                  placeholder="(67) 99999-0000"
                  value={novoTelefone}
                  onChange={(e) => setNovoTelefone(e.target.value)}
                />
              </div>

              <div className="flex items-center justify-end gap-2 pt-3 border-t border-border/40">
                <Button type="button" variant="outline" onClick={() => setModalNovoAberto(false)}>
                  Cancelar
                </Button>
                <Button type="submit" className="bg-emerald-600 hover:bg-emerald-500 text-white">
                  Salvar
                </Button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Modal de Foto Ampliada */}
      {fotoModalAberta && (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm"
          onClick={() => setFotoModalAberta(null)}
        >
          <div className="bg-card p-4 rounded-2xl border border-border/80 max-w-sm w-full text-center space-y-3">
            <img
              src={fotoModalAberta.url}
              alt={fotoModalAberta.nome}
              className="w-48 h-48 mx-auto rounded-xl object-cover border border-border"
            />
            <h4 className="font-bold text-foreground text-sm">{fotoModalAberta.nome}</h4>
            <p className="text-xs text-muted-foreground">{fotoModalAberta.cargo}</p>
          </div>
        </div>
      )}
    </div>
  );
};

